INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного Внутренний устав называет причинами для увольнения?', '[{"id":"HO6vGTSk","text":"не отработка выговора более чем 7 дней"},{"id":"9AgpLtru","text":"наличие трёх непогашенных выговоров"},{"id":"aLUrU01","text":"наличие двух непогашенных предупреждений"},{"id":"nPLws3Xk","text":"по решению суда или предписанию Прокуратуры, СК"},{"id":"A8yU1UmV","text":"отказ от участия в поставке вооружения"}]', '["HO6vGTSk","9AgpLtru","nPLws3Xk"]', '', 2, 20010, '{"meta":{"article":"ВУ, п. 2.3","explanation":"ВУ, п. 2.3: «г) не отработка выговора более чем 7 дней;» «д) наличие трёх непогашенных дисциплинарных взысканий в виде выговоров;» «ж) по решению суда или предписанию органов Прокуратуры, Следственного комитета;»","quote":"«г) не отработка выговора более чем 7 дней;» … «д) наличие трёх непогашенных дисциплинарных взысканий в виде выговоров;» … «ж) по решению суда или предписанию органов Прокуратуры, Следственного комитета;»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-007~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 2.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе выбрать любое взыскание вплоть до увольнения в отношении срочника в звании от рядового до старшего сержанта?', '[{"id":"gKKTbHn","text":"Командир бригады"},{"id":"lyrHVvB","text":"заместители Командира бригады"},{"id":"TlNg5QvI","text":"Военный комендант"},{"id":"3lyLCZZR","text":"Командир батальона военной полиции"},{"id":"PXvfPMT","text":"командир взвода военной полиции"},{"id":"bKGMAg2s","text":"старший наряда по контрольно-пропускному пункту"}]', '["gKKTbHn","lyrHVvB","TlNg5QvI","3lyLCZZR"]', '', 3, 20020, '{"meta":{"article":"ВУ, п. 2.4","explanation":"ВУ, п. 2.4: «Командир бригады, его заместители, Военный комендант, Командир батальона военной полиции вправе выбрать любое дисциплинарное взыскание вплоть до увольнения со службы»","quote":"«Командир бригады, его заместители, Военный комендант, Командир батальона военной полиции вправе выбрать любое дисциплинарное взыскание вплоть до увольнения со службы»","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-008~v2', NULL, 'vp', 3, 'vu', 'ВУ, п. 2.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-008~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие цвета элементов одежды и аксессуаров Внутренний устав прямо называет допустимыми (в примечании о внешнем виде)?', '[{"id":"8HQdmFVs","text":"Белый"},{"id":"hdKLbRfj","text":"Чёрный"},{"id":"GwsKrDnN","text":"Синий"},{"id":"xFyytJ1m","text":"Зелёный"},{"id":"sbdk20h5","text":"Красный"}]', '["8HQdmFVs","hdKLbRfj"]', '', 2, 20030, '{"meta":{"article":"ВУ, п. 3.7","explanation":"ВУ, п. 3.7: «Цвета Белый и Черный допустимы для использования.»","quote":"«Цвета Белый и Черный допустимы для использования.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-015~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 3.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-015~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Выберите верные утверждения о растительности на лице.', '[{"id":"vVhmz4","text":"Со звания младший лейтенант разрешены опрятные усы"},{"id":"fDTwmhg6","text":"Бороды разрешены со звания майор при опрятном виде"},{"id":"gGKbNj3Q","text":"Бороды, бородки и щетина запрещены независимо от звания"},{"id":"VclhRYH","text":"Усы разрешены всем, включая рядовых, если они опрятные"}]', '["vVhmz4","gGKbNj3Q"]', '', 1, 20040, '{"meta":{"article":"ВУ, п. 3.9","explanation":"ВУ, п. 3.9: «Военнослужащим со звания Младший Лейтенант разрешено иметь усы опрятного вида.» «Бороды, бородки, щетины запрещены независимо от звания, должности и положения военнослужащего.»","quote":"«Военнослужащим со звания Младший Лейтенант разрешено иметь усы опрятного вида.» … «Бороды, бородки, щетины запрещены независимо от звания, должности и положения военнослужащего.»","difficulty":"1"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-019~v2', NULL, 'simple', 1, 'vu', 'ВУ, п. 3.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-019~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Выберите верные правила увольнительной.', '[{"id":"eguR6Aw","text":"Право — со звания ефрейтор"},{"id":"Ouv25Xji","text":"Раз в сутки, 60 минут"},{"id":"gOb7EP","text":"Можно разбить на две части по 30 минут"},{"id":"7VZ42CSg","text":"Нельзя брать во время начала вечерней поверки и за 30 минут до и после неё"},{"id":"KFzGuwLu","text":"Можно разбить на четыре части по 15 минут"}]', '["eguR6Aw","Ouv25Xji","gOb7EP","7VZ42CSg"]', '', 2, 20050, '{"meta":{"article":"ВУ, п. 4.6","explanation":"ВУ, п. 4.6: «Военнослужащие с звания Ефрейтор имеют право на увольнительную раз в сутки длительностью 60 минут, за исключением времени начала вечерней поверки, а также за 30 минут до и после неё. Увольнительную допускается разбить на две части по 30 минут.»","quote":"«Военнослужащие с звания Ефрейтор имеют право на увольнительную раз в сутки длительностью 60 минут, за исключением времени начала вечерней поверки, а также за 30 минут до и после неё. Увольнительную допускается разбить на две части по 30 минут.»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-026~v2', NULL, 'vp', 2, 'vu', 'ВУ, п. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-026~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Где предоставляется перерыв для отдыха и питания (60 минут)?', '[{"id":"ahMcaGM","text":"казарма"},{"id":"NklCcGS","text":"раздевалка"},{"id":"hEuP7jMH","text":"военный госпиталь"},{"id":"z78mpT0P","text":"строевой плац"},{"id":"7tIy2QYa","text":"КПП №1 у шлагбаума"}]', '["ahMcaGM","NklCcGS","hEuP7jMH"]', '', 1, 20060, '{"meta":{"article":"ВУ, п. 4.10","explanation":"ВУ, п. 4.10: «Перерыв предоставляется в специально отведенных местах: казарма, раздевалка, военный госпиталь.»","quote":"«Перерыв предоставляется в специально отведенных местах: казарма, раздевалка, военный госпиталь.»","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-032~v2', NULL, 'full', 1, 'vu', 'ВУ, п. 4.10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-032~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие полномочия Внутренний устав прямо закрепляет за ГУ ВП в дисциплинарной практике?', '[{"id":"hEaXkDJ","text":"привлечение военнослужащих к дисциплинарной ответственности"},{"id":"dPY0CNSn","text":"внесение отметок в личные дела"},{"id":"EGaazd5s","text":"возбуждение и проведение расследований"},{"id":"P2O0J4O","text":"формирование материалов дела для отправки в судебные органы"},{"id":"UVUapMYg","text":"присвоение внеочередных воинских званий за раскрытие дел"}]', '["hEaXkDJ","dPY0CNSn","EGaazd5s","P2O0J4O"]', '', 2, 20070, '{"meta":{"article":"ВУ, п. 5.2","explanation":"ВУ, п. 5.2: «на привлечение военнослужащих к дисциплинарной ответственности, внесение определенных отметок в личные дела военнослужащих, возбуждение и проведение расследований, формирование контрольного дела, формирование материалов дела для последующей их отправки в судебные органы.»","quote":"«на привлечение военнослужащих к дисциплинарной ответственности, внесение определенных отметок в личные дела военнослужащих, возбуждение и проведение расследований, формирование контрольного дела, формирование материалов дела для последующей их отправки в судебные органы.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-036~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-036~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры обеспечения производства по материалам о дисциплинарном проступке перечислены во Внутреннем уставе?', '[{"id":"Y8umFMzr","text":"задержание"},{"id":"AN5znhf","text":"доставление"},{"id":"9hMKn2Ds","text":"личный досмотр, досмотр вещей и транспорта"},{"id":"rXbNoNVm","text":"временное отстранение от обязанностей"},{"id":"LLo1E0YV","text":"казарменное положение на время служебной проверки"},{"id":"r2UkRnyc","text":"лишение премии и надбавок на время служебной проверки"}]', '["Y8umFMzr","AN5znhf","9hMKn2Ds","rXbNoNVm","LLo1E0YV"]', '', 2, 20080, '{"meta":{"article":"ВУ, п. 5.4","explanation":"ВУ, п. 5.4: «а) задержание;» «б) доставление;» «г) личный досмотр, досмотр вещей, находящихся при военнослужащем, досмотр личного и служебного транспортного средства военнослужащего;» «д) временное отстранение от исполнения служебных и должностных обязанностей;» «(далее — казарменное положение)»","quote":"«а) задержание;» … «б) доставление;» … «г) личный досмотр, досмотр вещей, находящихся при военнослужащем, досмотр личного и служебного транспортного средства военнослужащего;» … «д) временное отстранение от исполнения служебных и должностных обязанностей;» … «(далее — казарменное положение)»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-037~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-037~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Командир роты применил к подчинённому задержание как меру обеспечения производства по дисциплинарному проступку. Что он обязан сделать?', '[{"id":"gqMBc3CH","text":"Ничего — это право командира в пределах его полномочий"},{"id":"1zDQqm6E","text":"Письменно доложить об этом Военному коменданту"},{"id":"f2vJo4Tl","text":"Получить на это разрешение командира бригады"},{"id":"QCyVVVj9","text":"Устно сообщить об этом дежурному по части в рацию"}]', '["1zDQqm6E"]', '', 3, 20090, '{"meta":{"article":"ВУ, п. 5.5","explanation":"ВУ, п. 5.5: «з) командиры (начальники) подразделений, рот, батальонов, соединений, письменно доложив об этом Военному коменданту.»","quote":"«з) командиры (начальники) подразделений, рот, батальонов, соединений, письменно доложив об этом Военному коменданту.»","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-039~v2', NULL, 'medium', 3, 'vu', 'ВУ, п. 5.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-039~v2');
