INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие подразделения входят в ГУ ВП?', '[{"id":"poD4YUA7","text":"Военная комендатура"},{"id":"AatGCRT1","text":"Батальон военной полиции"},{"id":"s9MV6Ryf","text":"Силы специальных операций"},{"id":"nwIvdmzk","text":"Рота охраны и обеспечения"}]', '["poD4YUA7","AatGCRT1"]', '', 1, 20110, '{"meta":{"article":"ВУ, п. 6.50","explanation":"ВУ, п. 6.50: «контролирует работу входящих в него подразделений — Военной комендатуры и Батальона военной полиции.»","quote":"«контролирует работу входящих в него подразделений — Военной комендатуры и Батальона военной полиции.»","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-048~v2', NULL, 'medium', 1, 'vu', 'ВУ, п. 6.50', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-048~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто, помимо Командира бригады и его заместителей, имеет исключительное право на составление, выдачу, исполнение и контроль дисциплинарных взысканий в отношении всех военнослужащих бригады?', '[{"id":"QH8DIKDs","text":"Командиры подразделений в отношении своего личного состава"},{"id":"DLvRue3","text":"ГУ ВП в лице Военной комендатуры и Батальона военной полиции"},{"id":"f1USjBKh","text":"Отдел кадровой работы совместно с начальником штаба"},{"id":"XPJA2SX5","text":"Начальник штаба бригады и дежурный по части"}]', '["DLvRue3"]', '', 2, 20120, '{"meta":{"article":"ВУ, п. 6.52","explanation":"ВУ, п. 6.52: «Главное управление военной полиции в лице Военной комендатуры и Батальона военной полиции имеет исключительное право (помимо Командира бригады и его заместителей) на составление, выдачу, исполнение и контроль дисциплинарных взысканий»","quote":"«Главное управление военной полиции в лице Военной комендатуры и Батальона военной полиции имеет исключительное право (помимо Командира бригады и его заместителей) на составление, выдачу, исполнение и контроль дисциплинарных взысканий»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-049~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 6.52', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-049~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем могут быть скорректированы решения и действия ГУ ВП?', '[{"id":"0dKdYyL3","text":"Любым офицером штаба бригады по рапорту"},{"id":"fsYID9NA","text":"Никем, кроме Командира бригады и его заместителей"},{"id":"1SFkKuj","text":"Командиром подразделения, в котором служит нарушитель"},{"id":"0aTSgsZJ","text":"Военным комиссаром или начальником штаба бригады"}]', '["fsYID9NA"]', '', 2, 20130, '{"meta":{"article":"ВУ, п. 6.53","explanation":"ВУ, п. 6.53: «его решения и действия не могут быть скорректированы никем, кроме Командира бригады и его заместителей.»","quote":"«его решения и действия не могут быть скорректированы никем, кроме Командира бригады и его заместителей.»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-050~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 6.53', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-050~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'За что отвечает Военная комендатура?', '[{"id":"oxIY56dU","text":"рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП"},{"id":"dRE5nWla","text":"рассмотрение рапортов на снятие дисциплинарных взысканий"},{"id":"WPrnsxDV","text":"содержание на гауптвахте военнослужащих, подвергнутых аресту"},{"id":"olkxMeY","text":"выдача повесток гражданам о явке в военный комиссариат"},{"id":"a5ubsBKL","text":"проведение лекций и аттестаций для курсантов Военной академии"}]', '["oxIY56dU","dRE5nWla","WPrnsxDV"]', '', 2, 20140, '{"meta":{"article":"ВУ, п. 6.55","explanation":"ВУ, п. 6.45: «в) рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП;\n\nг) рассмотрение рапортов на снятие дисциплинарных взысканий;» «е) содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту;»","quote":"«в) рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП; … г) рассмотрение рапортов на снятие дисциплинарных взысканий;» … «е) содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту;»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-vu-051~v2', NULL, 'vp', 2, 'vu', 'ВУ, п. 6.55', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-051~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое подразделение является органом дознания бригады?', '[{"id":"OFd0KLwR","text":"Военная комендатура"},{"id":"GSdRLUm6","text":"Батальон военной полиции"},{"id":"tNnjtKEY","text":"Силы специальных операций"},{"id":"FNdSa9NA","text":"Штаб бригады"}]', '["GSdRLUm6"]', '', 2, 20150, '{"meta":{"article":"ВУ, п. 6.57","explanation":"ВУ, п. 6.57: «Батальон военной полиции является органом дознания 1-й Московской мотострелковой бригады»","quote":"«Батальон военной полиции является органом дознания 1-й Московской мотострелковой бригады»","difficulty":"2"}}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-052~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 6.57', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-052~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте должностное лицо и подразделение, работу которого оно непосредственно курирует.', '[]', '[]', '', 2, 20160, '{"meta":{"article":"ВУ, п. 6.14; 6.21; 6.28; 6.35","explanation":"ВУ, п. 6.14; 6.21; 6.28: «Первый заместитель командира бригады непосредственно курирует работу Сил специальных операций и Главного управления военной полиции» «непосредственно курирует работу Военного комиссариата и входящих в него отделов.» «Зам.Ком.Бриг. по МТО непосредственно курирует работу Роты охраны и обеспечения.»","quote":"«Первый заместитель командира бригады непосредственно курирует работу Сил специальных операций.» … «Заместитель Командира бригады по работе с личным составом непосредственно курирует работу Главного управления военной полиции и входящих в него отделов.» … «непосредственно курирует работу Военного комиссариата и входящих в него отделов.» … «Зам.Ком.Бриг. по МТО непосредственно курирует работу Роты охраны и обеспечения.»","difficulty":"2"},"pairs":[{"l":{"id":"oxKKdly6","text":"Первый заместитель командира бригады"},"r":{"id":"r1F32PHx","text":"Силы специальных операций"}},{"l":{"id":"tQrl1n9y","text":"Зам.Ком.Бриг. по работе с личным составом"},"r":{"id":"DzjeXKb","text":"Главное управление военной полиции и его отделы"}},{"l":{"id":"FxQa7Puz","text":"Начальник штаба"},"r":{"id":"ob5RiAZp","text":"Военный комиссариат и входящие в него отделы"}},{"l":{"id":"8inJbx8","text":"Зам.Ком.Бриг. по МТО"},"r":{"id":"tj58YGmt","text":"Рота охраны и обеспечения"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-053~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 6.14; 6.21; 6.28; 6.35', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-053~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Командир подразделения временно убыл, штатного заместителя нет. Кто принимает командование?', '[{"id":"aNKLx2os","text":"Самый опытный военнослужащий подразделения по выслуге лет"},{"id":"V1B4H0h","text":"Старший по должности, при равных должностях — старший по званию"},{"id":"B0L3V9","text":"Сотрудник ВП, назначенный Военным комендантом на время отсутствия"},{"id":"ZbwYk3","text":"Никто: подразделение подчиняется напрямую начальнику штаба"}]', '["V1B4H0h"]', '', 2, 20170, '{"meta":{"article":"ВУ, п. 6.45","explanation":"ВУ, п. 6.45: «При отсутствии штатного заместителя или если заместитель не был утвержден, командование принимает старший по должности, а при равных должностях — старший по воинскому званию.»","quote":"«При отсутствии штатного заместителя или если заместитель не был утвержден, командование принимает старший по должности, а при равных должностях — старший по воинскому званию.»","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-vu-054~v2', NULL, 'full', 2, 'vu', 'ВУ, п. 6.45', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-054~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях тег в рации не используется?', '[{"id":"ggs2FSM1","text":"Полковники и вышестоящие тегов не имеют"},{"id":"bBE2L6kU","text":"Доклад в наряде не требует тега"},{"id":"kLWzjUrV","text":"Рядовые Военной академии тегов не используют"},{"id":"AGfJojct","text":"В ночное время теги в рации не нужны"}]', '["ggs2FSM1","bBE2L6kU"]', '', 2, 20180, '{"meta":{"article":"ВУ, п. 8.10","explanation":"ВУ, п. 8.10: «Примечание: Полковники и вышестоящие тэгов не имеют.» «Примечание II: Доклад в наряде не требует тега.»","quote":"«Примечание: Полковники и вышестоящие тэгов не имеют.» … «Примечание II: Доклад в наряде не требует тега.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-057~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 8.10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-057~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте действия военной полиции при объявлении военного положения в порядке, установленном Внутренним уставом.', '[]', '[]', '', 2, 20190, '{"meta":{"article":"ВУ, п. 10.7","explanation":"ВУ, п. 10.7: «а) назначить оперативного дежурного, который будет оставаться на территории части и будет оперативно доставлять информацию об изменениях;» «б) остальные военнослужащие из состава ВП выдвигаются в патрулирование в близлежащих районах войсковой части, стратегических объектов;» «в) ожидать дальнейших инструкций от начальника подразделения.»","quote":"«а) назначить оперативного дежурного, который будет оставаться на территории части и будет оперативно доставлять информацию об изменениях;» … «б) остальные военнослужащие из состава ВП выдвигаются в патрулирование в близлежащих районах войсковой части, стратегических объектов;» … «в) ожидать дальнейших инструкций от начальника подразделения.»","difficulty":"2"},"items":[{"id":"QvoGfte","text":"назначить оперативного дежурного, который остаётся на территории части"},{"id":"OCllwtxS","text":"остальные военнослужащие ВП выдвигаются в патрулирование близлежащих районов и стратегических объектов"},{"id":"Ij9EQlkv","text":"ожидать дальнейших инструкций от начальника подразделения"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-062~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 10.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-062~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Сержант в 22:15 в будний день пытается выехать за территорию части, ссылаясь на то, что «рабочий день закончился». Согласования высшего офицерского состава нет.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Командир роты задержал подчинённого, подозреваемого в выносе имущества со склада, и сам объявил ему «казарменное положение» на время служебной проверки. Коменданту он ничего не сообщил.
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: Гражданин с татуировкой на шее и непогашенной судимостью пришёл на призыв. Сотрудник призыва готов принять его, «раз он хочет служить».
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие прямые основания для увольнения как дисциплинарной меры называет Дисциплинарный устав?', '[{"id":"GziYQvNa","text":"грубый проступок, предусмотренный Уставом"},{"id":"N0jgMpEh","text":"два действующих выговора за один месяц"},{"id":"NAKuOEWb","text":"достижение трёх действующих выговоров"},{"id":"IG1T2Ud3","text":"иное основание, прямо предусмотренное законом"},{"id":"qtyqA3N","text":"любое повторное предупреждение за опоздание"}]', '["GziYQvNa","NAKuOEWb","IG1T2Ud3"]', '', 2, 20230, '{"meta":{"article":"ДУ, п. 2.6","explanation":"ДУ, п. 2.6: «грубый проступок, предусмотренный настоящим Уставом, либо достижение трех действующих выговоров, либо иное основание, прямо предусмотренное законодательством.»","quote":"«грубый проступок, предусмотренный настоящим Уставом, либо достижение трех действующих выговоров, либо иное основание, прямо предусмотренное законодательством.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-008~v2', NULL, 'medium', 2, 'du', 'ДУ, п. 2.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-008~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте нарушение и меру «первично» по таблице главы VI.', '[]', '[]', '', 2, 20240, '{"meta":{"article":"ДУ, п. 6.1; 6.2; 6.11; 6.21","explanation":"ДУ, п. 6.1; 6.2; 6.11; 6.21: «Оскорбление других военнослужащих, сотрудников государственных структур, а также всех гражданских лиц без исключений.\n\nВзыскание (таблица гл. VI):\n▸ Первично — Предупреждение» «Хранение, употребление, распространение запрещенных законодательством наркотических или психотропных веществ.» «Сон и отдых вне специально предназначенных для этого мест» «Самовольное оставление части (СОЧ) в рабочее время без одобренного рапорта на отгул или отпуск.» «▸ Первично — Выговор»","quote":"«Оскорбление других военнослужащих, сотрудников государственных структур, а также всех гражданских лиц без исключений. … Взыскание (таблица гл. VI): … ▸ Первично — Предупреждение» … «Хранение, употребление, распространение запрещенных законодательством наркотических или психотропных веществ.» … «Сон и отдых вне специально предназначенных для этого мест» … «Самовольное оставление части (СОЧ) в рабочее время без одобренного рапорта на отгул или отпуск.» … «▸ Первично — Выговор»","difficulty":"2"},"pairs":[{"l":{"id":"H3nf8maK","text":"Оскорбление военнослужащих, сотрудников госструктур, гражданских"},"r":{"id":"keS3wXp","text":"Предупреждение"}},{"l":{"id":"xqT8Cx2L","text":"Хранение/употребление/распространение наркотических веществ"},"r":{"id":"A55Hc4Se","text":"Выговор"}},{"l":{"id":"mZ9HvWk","text":"Сон и отдых вне отведённых мест / на посту"},"r":{"id":"A55Hc4Se","text":"Выговор"}},{"l":{"id":"t0IgxHB","text":"Самовольное оставление части (СОЧ)"},"r":{"id":"A55Hc4Se","text":"Выговор"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-du-023~v2',