INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько минут увольнительного времени в сутки имеют военнослужащие до звания сержант (включительно) согласно примечанию Дисциплинарного устава к самовольному оставлению части?', '[]', '[]', '', 2, 20280, '{"meta":{"article":"ДУ, п. 6.21","explanation":"ДУ, п. 6.21: «имеют право только на увольнительное время (60 минут 1 раз в сутки)»","quote":"«имеют право только на увольнительное время (60 минут 1 раз в сутки)»","difficulty":"2"},"answer":60,"tolerance":0,"unit":""}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-030~v2', NULL, 'simple', 2, 'du', 'ДУ, п. 6.21', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-030~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько минут даётся военнослужащему на покидание территории части (или прибытие в часть), чтобы не нарушить запрет Дисциплинарного устава о гражданской одежде?', '[]', '[]', '', 1, 20290, '{"meta":{"article":"ДУ, п. 6.33","explanation":"ДУ, п. 6.33: «Военнослужащему даётся 5 минут на покидание территории воинской части, а равно и на прибытие в часть.»","quote":"«Военнослужащему даётся 5 минут на покидание территории воинской части, а равно и на прибытие в часть.»","difficulty":"1"},"answer":5,"tolerance":0,"unit":""}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-du-031~v2', NULL, 'simple', 1, 'du', 'ДУ, п. 6.33', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-031~v2');
