INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Выберите верные правила накопления взысканий.', '[{"id":"jH5unr5","text":"Три действующих предупреждения заменяются одним выговором"},{"id":"n2w99p9Q","text":"Два действующих выговора — основание для увольнения со службы"},{"id":"rBrgrTLH","text":"Три действующих выговора — основание для увольнения по инициативе командования"},{"id":"4RNMXPJn","text":"Пять действующих предупреждений приравниваются к дисциплинарному аресту"}]', '["jH5unr5","rBrgrTLH"]', '', 1, 20320, '{"meta":{"article":"ДУ, п. 7.1; 7.2","explanation":"ДУ, п. 7.1; 7.2: «Три действующих предупреждения (замечания) заменяются одним выговором.» «Достижение трех действующих выговоров является основанием для увольнения по инициативе командования»","quote":"«Три действующих предупреждения (замечания) заменяются одним выговором.» … «Достижение трех действующих выговоров является основанием для увольнения по инициативе командования»","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-du-036~v2', NULL, 'medium', 1, 'du', 'ДУ, п. 7.1; 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-036~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие правила рассмотрения отработки установлены Приложением №1?', '[{"id":"oN7h8lyZ","text":"На всех фото/видео проделанной работы должна быть включена бодикамера"},{"id":"vm3anatq","text":"У ВП есть 24 часа на рассмотрение рапорта об отработке и решение о снятии взыскания"},{"id":"1QMPFast","text":"У ВП есть 48 часов на рассмотрение рапорта и 24 часа на снятие взыскания"},{"id":"bOSGw0Sr","text":"Фиксация работы не требуется, если отработку подтвердил командир"}]', '["oN7h8lyZ","vm3anatq"]', '', 2, 20330, '{"meta":{"article":"ДУ, п. П1.3; П1.4","explanation":"ДУ, п. П1.3; П1.4: «На всех фото - видео фиксациях проделанной работе, у военнослужащего должна быть включена бодикамера.» «У ВП на рассмотрение рапорта о отработке и принятие решения о снятии дисциплинарного взыскания есть 24 часа.»","quote":"«На всех фото - видео фиксациях проделанной работе, у военнослужащего должна быть включена бодикамера.» … «У ВП на рассмотрение рапорта о отработке и принятие решения о снятии дисциплинарного взыскания есть 24 часа.»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-du-041~v2', NULL, 'vp', 2, 'du', 'ДУ, п. П1.3; П1.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-041~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте подразделение и один из вариантов отработки ВЫГОВОРА по Приложению №1.', '[]', '[]', '', 3, 20340, '{"meta":{"article":"ДУ, п. П1.6","explanation":"ДУ, п. П1.6: «3. Вывоз военнослужащего за территорию ВЧ 2 раза;» «3. Участие в 1 КРАЗе.» «2. Пост КПП 1 - 60 минут;» «1. Организация 8 ПМП;»","quote":"«3. Вывоз военнослужащего за территорию ВЧ 2 раза;» … «3. Участие в 1 КРАЗе.» … «2. Пост КПП 1 - 60 минут;» … «1. Организация 8 ПМП;»","difficulty":"3"},"pairs":[{"l":{"id":"TysLsadC","text":"Военная комендатура, Батальон ВП"},"r":{"id":"hR5usLY","text":"Вывоз военнослужащего за территорию ВЧ 2 раза"}},{"l":{"id":"6NfpmgLY","text":"Силы специальных операций"},"r":{"id":"VOWgMN0E","text":"Участие в 1 КРАЗе"}},{"l":{"id":"98UBStDm","text":"Рота охраны и обеспечения"},"r":{"id":"FTJf9RI4","text":"Пост КПП 1 - 60 минут"}},{"l":{"id":"nJZKAfYC","text":"Медицинская рота"},"r":{"id":"IgKPLc8","text":"Организация 8 ПМП"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-du-042~v2', NULL, 'vp', 3, 'du', 'ДУ, п. П1.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-du-042~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что определяет Устав караульно-постовой службы?', '[{"id":"VBBxoyQV","text":"предназначение, порядок организации и несения караульной службы"},{"id":"ukARLJNu","text":"права и обязанности военнослужащих, несущих караульную службу"},{"id":"xE2dO8U","text":"порядок несения постовой службы"},{"id":"DGqco2lK","text":"виды дисциплинарных взысканий для нарушителей и порядок их снятия"},{"id":"N0EA0jA","text":"порядок присвоения воинских званий постовым"}]', '["VBBxoyQV","ukARLJNu","xE2dO8U"]', '', 1, 20350, '{"meta":{"article":"КПС, п. 1","explanation":"КПС, п. 1: «Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также регламентирует порядок несения постовой службы.»","quote":"«Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также регламентирует порядок несения постовой службы.»","difficulty":"1"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-kps-001~v2', NULL, 'simple', 1, 'kps', 'КПС, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-001~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Для чего предназначена караульная служба?', '[{"id":"8zF92al4","text":"охрана и оборона боевых знамён"},{"id":"WWzxDKVn","text":"охрана и оборона хранилищ (складов) с вооружением, военной техникой, другим военным имуществом"},{"id":"ZuJF2zTK","text":"охрана военнослужащих, содержащихся на гауптвахте и в дисциплинарной части"},{"id":"uVaPcB48","text":"проведение призывных мероприятий и отбор кандидатов на контрактную службу"},{"id":"ODFUS49B","text":"сопровождение поставок вооружения в адрес других государственных структур"}]', '["8zF92al4","WWzxDKVn","ZuJF2zTK"]', '', 2, 20360, '{"meta":{"article":"КПС, п. 3","explanation":"КПС, п. 3: «Караульная служба предназначена для надежной охраны и обороны боевых знамен, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом» «а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.»","quote":"«Караульная служба предназначена для надежной охраны и обороны боевых знамен, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом» … «а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-kps-002~v2', NULL, 'simple', 2, 'kps', 'КПС, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-002~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чем, согласно Уставу караульно-постовой службы, постоянные караулы отличаются от временных?', '[{"id":"XsJv7PXM","text":"Постоянные караулы несутся только в дневное время, временные — круглосуточно"},{"id":"PXuqU75","text":"Служба на них идёт непрерывно, без сопроводительных документов и распоряжений на организацию"},{"id":"KP73bCKF","text":"Постоянные караулы требуют ежедневного приказа Командира бригады на организацию"},{"id":"0WClY4Vv","text":"Постоянные караулы выставляются только в военное время или при объявлении кода"}]', '["PXuqU75"]', '', 2, 20370, '{"meta":{"article":"КПС, п. 13 (разд. 2)","explanation":"КПС, п. 13 (разд. 2): «караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и(или) устных распоряжений на организацию и осуществление караулов.»","quote":"«караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и(или) устных распоряжений на организацию и осуществление караулов.»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-008~v2', NULL, 'medium', 2, 'kps', 'КПС, п. 13 (разд. 2)', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-008~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кем могут создаваться временные караулы?', '[{"id":"4ULRba9x","text":"приказами командиров воинских частей (формирований)"},{"id":"186PtDCl","text":"приказом (указом) Министра обороны Российской Федерации"},{"id":"Zbq2LnaD","text":"Премьер-министром"},{"id":"9YCQh34","text":"решением любого постового, заступившего на пост"},{"id":"JTMcepyQ","text":"распоряжением старшего наряда по КПП"}]', '["4ULRba9x","186PtDCl","Zbq2LnaD"]', '', 2, 20380, '{"meta":{"article":"КПС, п. 14","explanation":"КПС, п. 14: «Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами»","quote":"«Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-kps-009~v2', NULL, 'vp', 2, 'kps', 'КПС, п. 14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-009~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что входит в перечень постоянных караулов на территории Московской области?', '[{"id":"QokYoE4o","text":"воинская часть №12132"},{"id":"tcnSCSxp","text":"склады с вооружением, стоянки военной техники, объекты стратегического значения"},{"id":"th2cifo","text":"военный комиссариат Московской области, пункты отбора"},{"id":"iXKm0314","text":"государственные объекты материального снабжения"},{"id":"XSwaHzZ","text":"казино, ломбарды и иные частные объекты с охраной"}]', '["QokYoE4o","tcnSCSxp","th2cifo","iXKm0314"]', '', 2, 20390, '{"meta":{"article":"КПС, п. 15","explanation":"КПС, п. 15: «воинская часть №12132;» «территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения;» «военный комиссариат Московской области, пункты отборы;» «государственные объекты материального снабжения.»","quote":"«воинская часть №12132;» … «территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения;» … «военный комиссариат Московской области, пункты отборы;» … «государственные объекты материального снабжения.»","difficulty":"2"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-kps-010~v2', NULL, 'simple', 2, 'kps', 'КПС, п. 15', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие территории закрыты для свободного посещения и нахождения?', '[{"id":"nPGMkaUz","text":"военные склады материального снабжения, склады с вооружением"},{"id":"2Eh65PcJ","text":"стоянки военной техники"},{"id":"ausNEbyI","text":"объекты стратегического (военного) значения"},{"id":"7heK8K8","text":"территории воинских частей"},{"id":"5nCpSjcV","text":"городские парки, прилегающие к военным объектам"}]', '["nPGMkaUz","2Eh65PcJ","ausNEbyI","7heK8K8"]', '', 2, 20400, '{"meta":{"article":"КПС, п. 18.1","explanation":"КПС, п. 18.1: «Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения.»","quote":"«Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения.»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-012~v2', NULL, 'medium', 2, 'kps', 'КПС, п. 18.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие дежурства входят в перечень постов караула на территории в/ч №12132 (текущая редакция)?', '[{"id":"vVjMxpj","text":"дежурный по части (не более 1 дежурного и 1 помощника)"},{"id":"VN8ki0fn","text":"дежурный по штабу (не более 1 дежурного)"},{"id":"QSqaoxpU","text":"дежурный водитель при штабе (не более 1 дежурного на автомобиле)"},{"id":"Hla4LxLC","text":"дежурный по столовой (не более 2 дежурных в смену)"}]', '["vVjMxpj","VN8ki0fn","QSqaoxpU"]', '', 2, 20410, '{"meta":{"article":"КПС, п. 22","explanation":"КПС, п. 22: «дежурный по части, не более 1 дежурного, и 1 помощника;» «дежурный по штабу, не более 1 дежурного.» «дежурный водитель при штабе, не более 1 дежурного на автомобиле»","quote":"«дежурный по части, не более 1 дежурного, и 1 помощника;» … «дежурный по штабу, не более 1 дежурного.» … «дежурный водитель при штабе, не более 1 дежурного на автомобиле»","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-017~v2', NULL, 'medium', 2, 'kps', 'КПС, п. 22', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-017~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что обязан надеть и иметь при себе военнослужащий, заступающий на пост?', '[{"id":"5TR3l6hK","text":"тяжёлое защитное обмундирование"},{"id":"9VHv3QgG","text":"табельное оружие и дополнительные боеприпасы к нему"},{"id":"7zsl9pfz","text":"средства радиосвязи"},{"id":"DHCRARrs","text":"специальные средства в соответствии с занимаемой должностью"},{"id":"8JdLDQBF","text":"личный мобильный телефон для связи с дежурным"}]', '["5TR3l6hK","9VHv3QgG","7zsl9pfz","DHCRARrs"]', '', 1, 20420, '{"meta":{"article":"КПС, п. 27","explanation":"КПС, п. 27: «обязан надевать тяжёлое защитное обмундирование и иметь при себе:\n\nтабельное оружие и дополнительные боеприпасы к нему;\n\nсредства радиосвязи;\n\nспециальные средства в соответствии с занимаемой должностью.»","quote":"«обязан надевать тяжёлое защитное обмундирование и иметь при себе: … табельное оружие и дополнительные боеприпасы к нему; … средства радиосвязи; … специальные средства в соответствии с занимаемой должностью.»","difficulty":"1"},"partial":false}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-kps-021~v2', NULL, 'simple', 1, 'kps', 'КПС, п. 27', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-021~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что запрещено при несении постовой службы?', '[{"id":"kGjn6kNR","text":"отвлекаться на телефон, иные электронные средства, на разговоры"},{"id":"dLGSfpST","text":"оставлять вооружение без контроля, убирать его из рук"},{"id":"OAwIsxB1","text":"игнорировать запросы о состоянии поста в рацию"},{"id":"OpzUVnu2","text":"бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции"},{"id":"Wx7Q5VpJ","text":"докладывать о состоянии поста по запросу дежурного по части в рацию"}]', '["kGjn6kNR","dLGSfpST","OAwIsxB1","OpzUVnu2"]', '', 2, 20430, '{"meta":{"article":"КПС, п. 29","explanation":"КПС, п. 29: «терять концентрацию, отвлекаться на телефон, иные электронные средства, на разговоры;» «оставлять вооружение без контроля, убирать его из рук;» «игнорировать запросы о состоянии поста в рацию;» «бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции;»","quote":"«терять концентрацию, отвлекаться на телефон, иные электронные средства, на разговоры;» … «оставлять вооружение без контроля, убирать его из рук;» … «игнорировать запросы о состоянии поста в рацию;» … «бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции;»","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-kps-023~v2', NULL, 'vp', 2, 'kps', 'КПС, п. 29', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-023~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кого постовой КПП №2 обязан знать в лицо по Уставу караульно-постовой службы?', '[{"id":"si6nRFX","text":"Только командира своего подразделения и его заместителя по службе"},{"id":"YCAHIzjg","text":"Старший состав: командиров, их заместителей, начальников и их заместителей"},{"id":"qC9zfYi","text":"Всех военнослужащих части, включая рядовой и сержантский состав"},{"id":"okjKEcS6","text":"Только сотрудников военной полиции и Военной комендатуры части"}]', '["YCAHIzjg"]', '', 2, 20440, '{"meta":{"article":"КПС, п. 32","explanation":"КПС, п. 32: «Знать в лицо старший состав ( это командиров, зам.командиров, начальников и зам.начальников )» «знать в лицо командира бригады и заместителей командира бригады.»","quote":"«Знать в лицо старший состав ( это командиров, зам.командиров, начальников и зам.начальников )» … «знать в лицо командира бригады и заместителей командира бригады.»","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-032~v2', NULL, 'medium', 2, 'kps', 'КПС, п. 32', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-032~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте понятие и его определение по ПК.', '[]', '[]', '', 2, 20450, '{"meta":{"article":"Статья 3, пп. 1, 7, 8, 9","explanation":"Определения даны в ст. 3 ПК.","quote":"алиби - наличие объективных обстоятельств, свидетельствующих о непричастности обвиняемого или подозреваемого к преступлению","difficulty":"2"},"pairs":[{"l":{"id":"0ZCPET6","text":"Алиби"},"r":{"id":"NoFbgaBI","text":"наличие объективных обстоятельств, свидетельствующих о непричастности обвиняемого или подозреваемого к преступлению"}},{"l":{"id":"i8zpkol","text":"Розыскные меры"},"r":{"id":"9VTQRur2","text":"меры, принимаемые дознавателем, следователем, органом дознания для установления лица, подозреваемого в совершении преступления"}},{"l":{"id":"z7YRD1sp","text":"Делопроизводство"},"r":{"id":"qLVNhk9f","text":"досудебное следствие по делу, проводимое органами следствия или правоохранительными органами"}},{"l":{"id":"VoMo3Vem","text":"Судопроизводство"},"r":{"id":"2NCpod2o","text":"деятельность суда по рассмотрению уголовного дела, гражданского дела или дела об административном правонарушении"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q002~v2', NULL, 'medium', 2, 'pk', 'Статья 3, пп. 1, 7, 8, 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q002~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицу за преступление назначен штраф, санкция статьи предусматривает также лишение свободы. Лицо отказывается платить. Как поступить по ПК?', '[{"id":"7mSZNXrE","text":"Дополнительно вменить отказ от уплаты как отдельное преступление"},{"id":"qUpCDRa4","text":"Удвоить сумму штрафа и повторно предложить его оплатить"},{"id":"931cBFxz","text":"Избрать иную меру наказания, отдельно отказ не квалифицировать"},{"id":"Zc6XHvID","text":"Освободить лицо, так как штраф ему уже был предложен"}]', '["931cBFxz"]', '', 3, 20460, '{"meta":{"article":"Статья 4, ч. 4.7","explanation":"Если в санкции есть иные меры, отказ от уплаты не квалифицируется отдельно — избирается иная мера наказания. Отдельно отказ квалифицируется только когда санкция предусматривает исключительно штраф.","quote":"Отказ от предложения уплаты штрафа, в случае если штраф избирается как одна из допустимых мер наказания, не квалифицируется как отдельное деяние, в таком случае избирается иная мера наказания.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q005~v2', NULL, 'vp', 3, 'pk', 'Статья 4, ч. 4.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q005~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кому ПК предоставляет право предварительного задержания? Выберите все верные.', '[{"id":"DwXF1Me8","text":"Госслужащему, который не является сотрудником правоохранительного органа"},{"id":"cWxXliE1","text":"Сотруднику госоргана, не обладающему правом задержания по иным причинам"},{"id":"4oH8XCM9","text":"Только сотрудникам СК России и органов прокуратуры"},{"id":"h46dve9F","text":"Любому гражданину, ставшему очевидцем правонарушения с лишением свободы"}]', '["DwXF1Me8","cWxXliE1"]', '', 2, 20470, '{"meta":{"article":"Статья 6, ч. 6.4","explanation":"Предварительное задержание проводит сотрудник государственного органа (госслужащий), не являющийся сотрудником правоохранительного органа или не обладающий правом задержания по иным причинам.","quote":"Право осуществления предварительного задержания предоставляется сотрудникам государственного органа или государственному служащему, только в случае если он не является сотрудником правоохранительного органа или не обладает правом проведения задержания по иным причинам.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q008', NULL, 'medium', 2, 'pk', 'Статья 6, ч. 6.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'В течение скольких секунд после передачи (попытки передачи) протокола лицо должно оплатить штраф, чтобы не возникло основание для задержания по УК?', '[]', '[]', '', 2, 20480, '{"meta":{"article":"Статья 7, ч. 7.1, п. 6","explanation":"П. 6 ч. 7.1 — 35 секунд.","quote":"не оплатило наложенный на него административный штраф в течение 35 секунд после непосредственной передачи или попытки передачи протокола (постановления) сотрудником","difficulty":"2"},"answer":35,"tolerance":0,"unit":"секунд"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q010~v2', NULL, 'full', 2, 'pk', 'Статья 7, ч. 7.1, п. 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного является основанием для задержания по ПК (при санкции в виде ареста или лишения свободы там, где это требуется)?', '[{"id":"rBSib2FH","text":"Отказ лица назвать место работы"},{"id":"zx3vQBc","text":"Видеофиксация правонарушения, предоставленная очевидцем или потерпевшим"},{"id":"aVFgoKzF","text":"Наличие у лица крупной суммы наличных денег"},{"id":"gx7OJ7bK","text":"Указание на лицо одного очевидца"},{"id":"iNzAe4ZV","text":"Нахождение лица в розыске"},{"id":"qsLdK5m","text":"Наличие ориентировки на лицо или его транспортное средство, размещённой по рации государственных структур"}]', '["zx3vQBc","iNzAe4ZV","qsLdK5m"]', '', 2, 20490, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"Основания: застигнут при совершении/сразу после; 3+ очевидца; явные следы; привод; установление личности; ст. 67 УК; розыск; видеофиксация от очевидца/потерпевшего; ориентировка; установление оснований для действий, требующих спецразрешения; основание для ФСО.","quote":"в случае наличия ориентировки на данное лицо или на транспортное средство, размещенная посредством рации государственных структур или иным законным образом","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q011~v2', NULL, 'full', 2, 'pk', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q011~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо задержано для установления личности (скрывало лицо и отказалось предъявить документ). Личность установлена, в преступлении, предусматривающем лишение свободы, лицо не подозревается. Что обязан сделать сотрудник?', '[{"id":"6vmalVo","text":"Составить административный протокол, вынести наказание и отпустить лицо"},{"id":"aRZV8L7","text":"Доставить лицо в КПЗ и удерживать до выяснения всех обстоятельств"},{"id":"erenJxge","text":"Произвести арест за помеху деятельности сотрудника госвласти"},{"id":"ijlJqcvW","text":"Передать лицо сотрудникам ФСБ России для проверки личности"}]', '["6vmalVo"]', '', 2, 20500, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2: составить административный протокол и вынести наказание по закону; если лицо не подозревается в преступлении с лишением свободы — отпустить.","quote":"в случае если лицо не подозревается в совершении преступления предусматривающих лишение свободы, сотрудник обязан отпустить задержанное лицо","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q012', NULL, 'full', 2, 'pk', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какими правами обладает задержанный по ПК?', '[{"id":"0LyOYah","text":"Один телефонный звонок любому лицу не более 2 минут"},{"id":"cg7T2Z1U","text":"Требовать немедленного освобождения до принятия решения"},{"id":"yqm9Op0u","text":"Не свидетельствовать против себя самого"},{"id":"bE77rl1F","text":"Два телефонных звонка по 5 минут"},{"id":"EusJfzxd","text":"Требовать присутствия родственников на месте задержания"},{"id":"7XzjYAX","text":"Требовать предоставления государственного адвоката, если он на рабочем месте"}]', '["0LyOYah","yqm9Op0u","7XzjYAX"]', '', 1, 20510, '{"meta":{"article":"Статья 8, ч. 8.1","explanation":"Пять прав: не свидетельствовать против себя; государственный адвокат (если на рабочем месте); присутствие адвоката в СИЗО/КПЗ/ИУ; конфиденциальная беседа до 5 минут; один звонок до 2 минут.","quote":"требовать предоставить возможность провести один (1) телефонный звонок любому лицу на выбор задержанного, не превышающий двух (2) минут.","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q014~v2', NULL, 'medium', 1, 'pk', 'Статья 8, ч. 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q014~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где, по ПК, реализуются права задержанного (кроме права не свидетельствовать против себя)?', '[{"id":"aCiS2ZMo","text":"На месте фактического задержания, до доставления"},{"id":"nF2qOVd","text":"В СИЗО, исправительном учреждении, КПЗ и КПС"},{"id":"pBIl47Ln","text":"Только в здании суда после вынесения решения"},{"id":"qImU1Md5","text":"В служебном автомобиле сразу после задержания"}]', '["nF2qOVd"]', '', 2, 20520, '{"meta":{"article":"Статья 9, ч. 9.1","explanation":"Ч. 9.1: в камерах предварительного заключения.","quote":"Все права задержанного реализуются в помещениях следственного изолятора, исправительного учреждения, камерах предварительного заключения, камерах предварительного содержания, за исключением права не свидетельствовать против себя самого, оно предоставляется постоянно.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q018~v2', NULL, 'full', 2, 'pk', 'Статья 9, ч. 9.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q018~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие действия ПК относит к обязательным при задержании?', '[{"id":"BmxYGshf","text":"Уведомить родственников задержанного"},{"id":"RNQESQ8","text":"Взять письменные объяснения у очевидцев"},{"id":"tjgeqELC","text":"Произвести личный обыск"},{"id":"uZAEBVNL","text":"Огласить перечень статей, инкриминируемых задержанному"},{"id":"8RnHFvnw","text":"Получить письменное согласие прокурора"},{"id":"rFd7E4qz","text":"Идентифицировать себя"}]', '["tjgeqELC","uZAEBVNL","rFd7E4qz"]', '', 2, 20530, '{"meta":{"article":"Статья 10, ч. 10.1","explanation":"Обязательные действия: применить спецсредства, идентифицировать себя, огласить инкриминируемые статьи, произвести личный обыск, доставить в орган следствия/дознания или правоохранительный орган.","quote":"Сотрудник правоохранительного органа проводит задержание в свободном порядке, задержание предусматривает следующие обязательные действия:","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q024~v2', NULL, 'full', 2, 'pk', 'Статья 10, ч. 10.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q024~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто относится к субъектам процессуальных действий, имеющим свободный проход на место задержания?', '[{"id":"jQb2NYFe","text":"Не более одного представителя органов прокуратуры"},{"id":"sVCSIguE","text":"Один адвокат, прибывший по вызову сотрудника или задержанного"},{"id":"qmQSTL8y","text":"Корреспондент государственного СМИ с удостоверением"},{"id":"e1Xc3nb","text":"Представитель руководства организации задержанного госработника"},{"id":"JJmV7SxP","text":"Второй адвокат задержанного, прибывший по его звонку"},{"id":"iAdBeZco","text":"Родственники задержанного, если он об этом попросил"}]', '["jQb2NYFe","sVCSIguE","e1Xc3nb"]', '', 3, 20540, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Перечень ч. 11.1: сотрудники/оперативная группа, задержанный, один адвокат, СК/ФСБ/прокуратура при задержании госслужащего, не более одного представителя прокуратуры, не более одного представителя СК, представитель руководства задержанного госработника, не более одного сотрудника 1-й ОСС ФСБ, передавший задержание сотрудник, сотрудник для аннулирования лицензии на оружие.","quote":"один адвокат, прибывший по вызову сотрудника или задержанного;","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q029~v2', NULL, 'medium', 3, 'pk', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q029~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Может ли одно и то же лицо на месте задержания одновременно выступать как представитель руководства задержанного и как адвокат?', '[{"id":"DdeyVo3s","text":"Нет — одно лицо осуществляет полномочия только одного вида субъектов"},{"id":"EJw455pP","text":"Да, если задержанный письменно согласен на такое совмещение"},{"id":"h05fj5kD","text":"Да, если устав организации задержанного прямо это позволяет"},{"id":"YPxD42RX","text":"Да, если представитель прокуратуры на месте не возражает"}]', '["DdeyVo3s"]', '', 3, 20550, '{"meta":{"article":"Статья 11, ч. 11.4","explanation":"Ч. 11.4: одно лицо осуществляет полномочия только одного вида субъектов.","quote":"Одно и то же лицо может осуществлять полномочия только одного вида субъектов процессуальных действий.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q030', NULL, 'vp', 3, 'pk', 'Статья 11, ч. 11.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто обладает правом задержания госслужащего при исполнении должностных обязанностей за преступления из специального перечня ПК? Выберите все верные.', '[{"id":"B6pc2FET","text":"Сотрудники СК России"},{"id":"rdbTSjw","text":"Сотрудники ФСБ России"},{"id":"HOZdmauQ","text":"Сотрудники прокуратуры"},{"id":"kfuWzqtV","text":"Сотрудники правоохранительных органов по решению прокурора"},{"id":"x4kaLA1h","text":"Любой сотрудник правоохранительного органа по своему решению"},{"id":"D4KrD7qm","text":"Только непосредственный командир (начальник) госслужащего"}]', '["B6pc2FET","rdbTSjw","HOZdmauQ","kfuWzqtV"]', '', 3, 20560, '{"meta":{"article":"Статья 12, ч. 12.1","explanation":"Ч. 12.1: СК, ФСБ, прокуратура, а сотрудники правоохранительных органов — по решению прокурора.","quote":"обладают сотрудники СК России, ФСБ России, сотрудники прокуратуры, сотрудники правоохранительных органов по решению прокурора","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q031', NULL, 'full', 3, 'pk', 'Статья 12, ч. 12.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник ВП выявил кражу, совершённую госслужащим при исполнении обязанностей; кража не входит в перечень преступлений, за которые такого госслужащего задерживают СК, ФСБ или прокуратура. Как он обязан поступить?', '[{"id":"f5QUzpg7","text":"Передать материалы руководству госслужащего для дисциплинарного взыскания и служебной проверки"},{"id":"ns0JX4Yp","text":"Наложить штраф на месте и сообщить руководству госслужащего"},{"id":"OC9A8T57","text":"Задержать госслужащего и арестовать его самостоятельно"},{"id":"1DqASx4j","text":"Составить рапорт с доказательствами прокурору субъекта или руководителю СО СК либо подать иск"}]', '["1DqASx4j"]', '', 3, 20570, '{"meta":{"article":"Статья 12, ч. 12.2.1","explanation":"Ч. 12.2.1: в иных случаях — рапорт с доказательствами прокурору субъекта, руководителю СО СК по субъекту или исковое заявление по подследственности.","quote":"В иных случаях сотрудник правоохранительного органа, выявивший преступления обязан составить рапорт с приложением доказательств на имя прокурора субъекта Российской Федерации, руководителя следственного органа СК России по субъекту или обратиться с исковым заявлением согласно подследственности.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q032', NULL, 'vp', 3, 'pk', 'Статья 12, ч. 12.2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях сотрудник правоохранительного органа вправе сам задержать сотрудника государственного органа при исполнении служебных обязанностей (с дальнейшей передачей СК, ФСБ или прокуратуре)?', '[{"id":"cpPeRHq6","text":"Публично оскорбил представителя власти"},{"id":"zHExocyY","text":"Совершил неисполнение приказа"},{"id":"uU36sO98","text":"Совершил хулиганство"},{"id":"Eov5KYe1","text":"Применил специальные средства без законных оснований"},{"id":"aa1Hudjv","text":"Совершил кражу"},{"id":"9PCjf26Z","text":"Открыл огонь по гражданам без веской причины"}]', '["zHExocyY","Eov5KYe1","9PCjf26Z"]', '', 3, 20580, '{"meta":{"article":"Статья 12, ч. 12.3","explanation":"Ч. 12.3: открыл огонь без веской причины; применил спецсредства без законных оснований; совершил преступление по ст. 37, 55 или 78 УК.","quote":"если он открыл огонь по гражданами или иным лицам без веской на то причины, применил специальные средства без законных на то оснований или в случае совершения им хотя бы одного из преступлений, предусмотренных статьями 37, 55, 78 Уголовного Кодекса Российской Федерации","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q033~v2', NULL, 'medium', 3, 'pk', 'Статья 12, ч. 12.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q033~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что ПК признаёт подтверждением статуса госслужащего при задержании? Выберите все верные.', '[{"id":"Z7BkQWBs","text":"Наличие жетона или служебного удостоверения"},{"id":"ryrz5Wgi","text":"Доступ в рацию на общей частоте госструктур"},{"id":"j7MOa8h","text":"Устное заявление задержанного о своей должности"},{"id":"ueEV5i7Y","text":"Ношение камуфляжной или иной форменной одежды"}]', '["Z7BkQWBs","ryrz5Wgi"]', '', 2, 20590, '{"meta":{"article":"Статья 12, ч. 12.4","explanation":"Ч. 12.4: наличие жетона или служебного удостоверения, доступа в рацию на общей частоте госструктур.","quote":"(наличие жетона или служебного удостоверения, доступа в рацию на общей частоте государственных структур)","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q034', NULL, 'full', 2, 'pk', 'Статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Работник государственного органа совершил преступление, не входящее в перечень ПК. Допускается ли его увольнение по этому основанию?', '[{"id":"E1pkaie","text":"Допускается всегда"},{"id":"nENBdPaQ","text":"Допускается по решению командира"},{"id":"uJdeJXhD","text":"Допускается, если наказание — штраф"},{"id":"FKYJ6ERn","text":"Не допускается"}]', '["FKYJ6ERn"]', '', 3, 20600, '{"meta":{"article":"Статья 12, ч. 12.6","explanation":"Ч. 12.6: увольнение не допускается.","quote":"не попадающее под перечень указанный в части 5 настоящей статьи, увольнение (для адвокатов - прекращение статуса адвоката) не допускается.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q035~v2', NULL, 'vp', 3, 'pk', 'Статья 12, ч. 12.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q035~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто выносит решение в отношении задержанного государственного служащего?', '[{"id":"rwwekWyn","text":"Представитель руководства организации задержанного"},{"id":"lxKagDuI","text":"Только суд после передачи материалов дела"},{"id":"p2jsPqK","text":"Сотрудник СК России, а при его отсутствии — сотрудник прокуратуры"},{"id":"iibSkJwb","text":"Сотрудник, инициировавший задержание, по итогам проверки"}]', '["p2jsPqK"]', '', 3, 20610, '{"meta":{"article":"Статья 12, ч. 12.9","explanation":"Ч. 12.9: сотрудник СК (прокуратура — при отсутствии СК); при присутствии прокурора решение вступает в силу после его утверждения.","quote":"В отношении адвоката, государственного служащего, работника государственного органа выносит решение сотрудник органов СК России (сотрудник органов прокуратуры в отсутствии представителя органов СК России).","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q037', NULL, 'medium', 3, 'pk', 'Статья 12, ч. 12.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком порядке допускается увольнение по основаниям ПК судьи или прокурора субъекта РФ?', '[{"id":"Uc5JCmaT","text":"По рапорту сотрудника, проводившего задержание"},{"id":"yntu3jA","text":"По решению Генерального прокурора без суда"},{"id":"eidYdHss","text":"По решению сотрудника СК России"},{"id":"W4yqxLAT","text":"Не иначе как в судебном порядке"}]', '["W4yqxLAT"]', '', 3, 20620, '{"meta":{"article":"Статья 12, чч. 12.10–12.11","explanation":"Ч. 12.10 запрещает увольнение этих лиц по ч. 12.5; ч. 12.11 — только в судебном порядке.","quote":"Увольнение лиц указанных в части 10 настоящей статьи допускается не иначе как в судебном порядке, если иное не предусмотрено законом.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q038~v2', NULL, 'vp', 3, 'pk', 'Статья 12, чч. 12.10–12.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q038~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что происходит, если сотрудник прокуратуры отказал в утверждении решения сотрудника СК в отношении задержанного госслужащего?', '[{"id":"WqYf3T6","text":"Задержанный подлежит аресту, а решение о наказании самостоятельно исполняет сотрудник ВП"},{"id":"4NMXlOdU","text":"Решение СК вступает в силу без утверждения прокурора"},{"id":"1tcuLNgL","text":"Дело передаётся в ФСБ России для повторного рассмотрения"},{"id":"vXdB08l","text":"Задержание прекращается, сотрудник СК принимает материалы к собственному производству"}]', '["vXdB08l"]', '', 3, 20630, '{"meta":{"article":"Статья 12, ч. 12.12","explanation":"Ч. 12.12: задержание прекращается, сотрудник СК принимает материалы к собственному производству.","quote":"задержание прекращается, сотрудник органов СК России принимавший решение принимает материалы к собственному производству","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q039', NULL, 'vp', 3, 'pk', 'Статья 12, ч. 12.12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q039');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'По каким статьям УК задержание и арест (без судебного решения) вправе производить сотрудники любого правоохранительного органа, включая ВП?', '[{"id":"eSjDVybL","text":"Разглашение государственной тайны"},{"id":"5CP7owOn","text":"Незаконное проникновение на закрытый объект"},{"id":"M7yuffKt","text":"Неисполнение приказа"},{"id":"lcu21Nd","text":"Кража"},{"id":"1yG6omtp","text":"Террористический акт"},{"id":"HZhj49tJ","text":"Посягательство на жизнь сотрудника правоохранительного органа"}]', '["5CP7owOn","lcu21Nd","HZhj49tJ"]', '', 3, 20640, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2: ст. 37–49, 54, 56–68, 70, 86, 87, 89, 90–98 УК. Ст. 53, 74, 78 — задержание с передачей ФСБ (ч. 13.3).","quote":"Задержание и арест производится сотрудниками любого правоохранительного органа (без судебного решения) по уголовным делам о преступлениях, предусмотренных статьями 37 - 49, 54, 56 - 68, 70, 86, 87, 89, 90 - 98 Уголовного Кодекса Российской Федерации.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q040~v2', NULL, 'vp', 3, 'pk', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q040~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'По каким статьям УК задержание производится с дальнейшей передачей задержанного сотрудникам ФСБ России?', '[{"id":"YQBH1qr0","text":"Незаконное проникновение на закрытый объект"},{"id":"V2Lc6jIb","text":"Неисполнение приказа"},{"id":"uz6JIbo","text":"Захват заложника"},{"id":"Cl77j8QT","text":"Посягательство на жизнь сотрудника правоохранительного органа"},{"id":"IAHX6Dyv","text":"Незаконный оборот огнестрельного оружия"},{"id":"mxBE9AX","text":"Разглашение государственной тайны"}]', '["V2Lc6jIb","uz6JIbo","mxBE9AX"]', '', 3, 20650, '{"meta":{"article":"Статья 13, ч. 13.3","explanation":"Ч. 13.3: ст. 53, 55, 72, 73, 74, 75, 78 УК.","quote":"производится по уголовным делам о преступлениях, предусмотренных статьями 53, 55, 72, 73, 74, 75, 78 Уголовного Кодекса Российской Федерации.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q041~v2', NULL, 'full', 3, 'pk', 'Статья 13, ч. 13.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q041~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько минут сотрудник ждёт прибытия сотрудников ФСБ (после их ответа) при передаче задержанного по ПК?', '[]', '[]', '', 2, 20660, '{"meta":{"article":"Статья 13, ч. 13.4","explanation":"Ч. 13.4: ответ — 5 минут, прибытие — 5 минут; затем вправе продолжить с передачей дела в ФСБ.","quote":"Время ожидания ответа составляет пять (5) минут, время ожидания прибытия составляет пять (5) минут.","difficulty":"2"},"answer":5,"tolerance":0,"unit":"минут"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q042~v2', NULL, 'vp', 2, 'pk', 'Статья 13, ч. 13.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q042~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе постановлением предоставить сотрудникам СК, прокуратуры, ФСБ право проникновения на закрытую территорию для задержания? Выберите все верные.', '[{"id":"VuPCUq9w","text":"Начальник управления ФСБ по региону"},{"id":"WcW74kmn","text":"Руководитель следственного органа СК России"},{"id":"sAvYfnuD","text":"Прокурор"},{"id":"DrhodMID","text":"Командир воинской части"},{"id":"3YAjAUmJ","text":"Губернатор Федерального округа"},{"id":"AHfLZ6dH","text":"Министр обороны"}]', '["VuPCUq9w","WcW74kmn","sAvYfnuD"]', '', 3, 20670, '{"meta":{"article":"Статья 13, ч. 13.9","explanation":"Ч. 13.9: начальник управления ФСБ по региону, руководитель следственного органа СК, прокурор.","quote":"Начальник управления Федеральной службой безопасности по региону, руководитель следственного органа Следственного комитета России, прокурор вправе предоставить право на проникновение на закрытую территорию","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q046', NULL, 'full', 3, 'pk', 'Статья 13, ч. 13.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q046');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для окончания задержания и освобождения?', '[{"id":"A80qEinc","text":"Просьба родственников задержанного о его освобождении"},{"id":"1iirGVGw","text":"Отказ задержанного от права на телефонный звонок"},{"id":"aisR3gAj","text":"Задержанный оказался действующим военнослужащим"},{"id":"DYZ2A0gI","text":"Отсутствие оснований для задержания, предусмотренных ПК"},{"id":"0EwlBiTU","text":"Истечение максимально допустимого срока задержания"},{"id":"UyTgM8H6","text":"Недостаточно доказательств для установления факта вины"}]', '["DYZ2A0gI","0EwlBiTU","UyTgM8H6"]', '', 2, 20680, '{"meta":{"article":"Статья 14, ч. 14.1","explanation":"Ч. 14.1: недостаточно доказательств; нет наказания в виде лишения свободы; истёк срок; нет оснований для задержания; привод/отсутствие следователя.","quote":"недостаточно доказательств для установления факта вины лица;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q047~v2', NULL, 'full', 2, 'pk', 'Статья 14, ч. 14.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q047~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'По какой из перечисленных статей УК сотрудники Управления «К» ФСБ при сокрытии причастности к ФСБ вправе проводить задержание и арест?', '[{"id":"rh6QtIh7","text":"Кража"},{"id":"VYw3BW54","text":"Незаконный оборот огнестрельного оружия"},{"id":"183JbEHT","text":"Неисполнение приказа"},{"id":"sUkNRxO","text":"Разглашение государственной тайны"}]', '["VYw3BW54"]', '', 3, 20690, '{"meta":{"article":"Статья 16, ч. 16.2","explanation":"Ч. 16.2: ст. 37, 38, 39, 63, 64, 64-1, 89, 90 УК.","quote":"статьями 37, 38, 39, 63, 64, 64-1, 89, 90 Уголовного Кодекса Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q051~v2', NULL, 'full', 3, 'pk', 'Статья 16, ч. 16.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q051~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'При наличии признаков каких преступлений лицо со статусом неприкосновенности может быть задержано?', '[{"id":"m0GrjJB","text":"Убийство"},{"id":"nwNt6EpP","text":"Применение насилия в отношении представителя власти"},{"id":"TrxZySbi","text":"Незаконное проникновение на закрытый объект"},{"id":"0wJC5U8W","text":"Незаконный оборот огнестрельного оружия"},{"id":"uGAoIGNX","text":"Угроза убийством"},{"id":"3XUdm17","text":"Посягательство на жизнь сотрудника правоохранительного органа"}]', '["m0GrjJB","nwNt6EpP","3XUdm17"]', '', 3, 20700, '{"meta":{"article":"Статья 17, ч. 17.1","explanation":"Ч. 17.1: ст. 37, 38, 70, 71, 73, 89, 90 УК.","quote":"если отсутствуют признаки совершения им преступления, предусмотренного статьями 37, 38, 70, 71, 73, 89, 90 Уголовного Кодекса Российской Федерации.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q052~v2', NULL, 'vp', 3, 'pk', 'Статья 17, ч. 17.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q052~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо со статусом неприкосновенности совершило преступление, при котором ПК не разрешает его задерживать. Что обязан сделать сотрудник?', '[{"id":"Kn5j6vg1","text":"Зафиксировать деяние и направить видеофиксацию рапортом руководителю СО СК, прокурору субъекта или обратиться с иском"},{"id":"0CIxZohh","text":"Задержать лицо на 60 минут, провести личный обыск и сообщить о задержании прокурору субъекта и в СК"},{"id":"AoT4VWH","text":"Составить протокол, наложить штраф на месте, затем сообщить о деянии руководителю СО СК и прокурору субъекта"},{"id":"n45r4AFl","text":"Произвести личный обыск и доставить лицо в СК для решения вопроса"}]', '["Kn5j6vg1"]', '', 3, 20710, '{"meta":{"article":"Статья 17, ч. 17.2","explanation":"Ч. 17.2: меры принуждения не применяются; сотрудник фиксирует деяние и направляет видеофиксацию рапортом руководителю СО СК, прокурору субъекта или обращается с иском.","quote":"сотрудник обязан зафиксировать данное деяние и предоставить полную видеофиксацию с персональной служебной камеры сотрудника","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q053', NULL, 'vp', 3, 'pk', 'Статья 17, ч. 17.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q053');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия порядка проведения ареста по ПК.', '[]', '[]', '', 2, 20720, '{"meta":{"article":"Статья 18, ч. 18.2","explanation":"Ч. 18.2: уведомить и разъяснить причину (назвать статьи); личный обыск; арест на срок с заполнением личного дела.","quote":"произвести арест лица на срок, установленный за соответствующее преступление настоящим Кодексом, заполнив данные в личном деле.","difficulty":"2"},"items":[{"id":"VkDWmt","text":"Уведомить лицо и иных субъектов задержания, назвать статьи и кратко их описать"},{"id":"B6urVRBp","text":"Произвести личный обыск с целью обнаружения и конфискации нелегальных предметов"},{"id":"738mWs10","text":"Произвести арест на установленный срок, заполнив данные в личном деле"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q054~v2', NULL, 'full', 2, 'pk', 'Статья 18, ч. 18.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q054~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязательно должен содержать протокол ареста (личное дело)?', '[{"id":"k04nt1SK","text":"Перечень изъятых предметов, их оценочную стоимость и подпись задержанного"},{"id":"4KqSQPPn","text":"Статьи или части статей, по которым лицо привлечено, с указанием Кодекса"},{"id":"vUQSunu","text":"Только фамилию задержанного и время начала задержания"},{"id":"nKCFVVkL","text":"Подпись прокурора, утвердившего арест задержанного"}]', '["4KqSQPPn"]', '', 2, 20730, '{"meta":{"article":"Статья 18, ч. 18.3","explanation":"Ч. 18.3: статьи или части статей с указанием Кодекса.","quote":"Протокол ареста (личное дело) должен содержать статьи или части статьи, по которым лицо было подвергнуто уголовной или административной ответственности с указанием Кодекса.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q055', NULL, 'vp', 2, 'pk', 'Статья 18, ч. 18.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q055');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин на КПП закрытой территории отказывается от добровольного личного обыска. Как вправе поступить сотрудник?', '[{"id":"hxmlPjns","text":"Отказать в допуске к закрытой территории"},{"id":"IIj5r5bi","text":"Задержать его за помеху деятельности сотрудника"},{"id":"w1Pk4H3","text":"Провести обыск принудительно с применением силы"},{"id":"VmdDZbME","text":"Пропустить без обыска, сделав запись в журнале"}]', '["hxmlPjns"]', '', 2, 20740, '{"meta":{"article":"Статья 19, ч. 19.3","explanation":"Ч. 19.3: при отказе от добровольного обыска лицу вправе отказать в допуске на закрытую территорию.","quote":"При отказе от такого добровольного личного обыска лицу вправе отказать в допуске к закрытой территории.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q058', NULL, 'medium', 2, 'pk', 'Статья 19, ч. 19.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q058');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На основании чего по общему правилу допускается обыск жилища?', '[{"id":"oeWvvER","text":"Устного приказа командира подразделения"},{"id":"STTSDOYt","text":"Рапорта сотрудника ВП, согласованного с дежурным по части и командиром роты"},{"id":"TI3H8NTC","text":"Письменного согласия соседей или управляющего"},{"id":"wxJpPlR","text":"Ордера за подписью следователя в рамках делопроизводства или ордера суда"}]', '["wxJpPlR"]', '', 2, 20750, '{"meta":{"article":"Статья 20, ч. 20.1","explanation":"Ч. 20.1: ордер за подписью следователя в рамках делопроизводства или ордер суда.","quote":"допускается при наличии ордера о проведении обыска жилища или обыска транспортного средства за подписью следователя в рамках делопроизводства или при наличии ордера суда","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q059', NULL, 'full', 2, 'pk', 'Статья 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q059');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях обыск транспортного средства допускается без ордера?', '[{"id":"6wA1Waa7","text":"Остановка транспортного средства в ночное время суток"},{"id":"YYGdJWbg","text":"Нахождение гражданина в зоне, где введено военное положение"},{"id":"tqFBSti","text":"Совершение нарушения правил дорожного движения"},{"id":"m4MV19Yu","text":"Просьба потерпевшего, указавшего на транспортное средство"},{"id":"dGYu2AR","text":"Устное указание дежурного по части проверить автомобиль"},{"id":"fPbxgW9x","text":"Проезд на территорию, подлежащую государственной охране"}]', '["YYGdJWbg","tqFBSti","fPbxgW9x"]', '', 2, 20760, '{"meta":{"article":"Статья 20, ч. 20.2","explanation":"Ч. 20.2: ЧП/военное положение/КТО; нарушение ПДД; ТС в зоне преступления; оперативные мероприятия ГИБДД или ФСБ при надлежащих подписях; проезд на территорию, подлежащую государственной охране.","quote":"в случае проезда на территорию подлежащую государственной охране.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q060~v2', NULL, 'full', 2, 'pk', 'Статья 20, ч. 20.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q060~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать сотрудник в форме со знаками различия перед выдвижением законного требования?', '[{"id":"Uj0RL7xS","text":"Сообщить личный номер жетона и свой позывной в рации"},{"id":"ArTPjjeZ","text":"Ничего — форма со знаками различия говорит сама за себя"},{"id":"51j9ujNy","text":"Обозначить принадлежность к госоргану с указанием его наименования"},{"id":"sHUvnGJX","text":"Предъявить приказ о заступлении на службу и удостоверение"}]', '["51j9ujNy"]', '', 1, 20770, '{"meta":{"article":"Статья 21, ч. 21.1","explanation":"Ч. 21.1: обозначить принадлежность к госоргану с указанием его наименования.","quote":"Обозначение должно содержать наименование государственного органа к которому он относится.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q061', NULL, 'medium', 1, 'pk', 'Статья 21, ч. 21.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q061');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что такое законное требование по ПК?', '[{"id":"4tDqzw","text":"Только письменное предписание руководителя госоргана, зарегистрированное в журнале"},{"id":"Ewk9aNxj","text":"Любое требование сотрудника, находящегося в форме"},{"id":"TYcLF1yv","text":"Требование, предварительно согласованное с прокурором"},{"id":"0MDT4jW2","text":"Требование, основанное на нормативных правовых актах, в устной или письменной форме"}]', '["0MDT4jW2"]', '', 1, 20780, '{"meta":{"article":"Статья 21, ч. 21.2","explanation":"Ч. 21.2.","quote":"Законное требование или распоряжение - это требование, основанное на нормативных правовых актах, выраженное в устной или письменной форме.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q062', NULL, 'full', 1, 'pk', 'Статья 21, ч. 21.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q062');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник ВП по объективным причинам не может продолжать задержание. Что он обязан сделать?', '[{"id":"5DIPozIr","text":"Отпустить задержанного, составив рапорт о причинах прекращения задержания на имя командира"},{"id":"N0hHrivQ","text":"Передать задержание уполномоченному сотруднику с изложением обстоятельств и видеоматериалами"},{"id":"AxVzbVN2","text":"Передать задержанного любому гражданину до прибытия сотрудников"},{"id":"5C0fKVNC","text":"Доставить задержанного в часть и оставить у дежурного по части"}]', '["N0hHrivQ"]', '', 2, 20790, '{"meta":{"article":"Статья 22","explanation":"Ст. 22: передать задержание уполномоченному сотруднику с изложением обстоятельств и передачей видеоматериалов.","quote":"он обязан передать его уполномоченному сотруднику с подробным изложением всех известных ему обстоятельств, передачей видеоматериалов по нарушению задерживаемого.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q063', NULL, 'full', 2, 'pk', 'Статья 22', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q063');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто, по ПК, производит отстранение работника государственной организации от занимаемой должности? Выберите все верные.', '[{"id":"HV2jDsb","text":"Сотрудник СК России в рамках делопроизводства"},{"id":"erHfnIA4","text":"Сотрудник органов прокуратуры"},{"id":"4JaHpPAI","text":"Суд"},{"id":"OEwR6NqA","text":"Командир бригады самостоятельно"},{"id":"gFyi03O","text":"Сотрудник, проводивший задержание"}]', '["HV2jDsb","erHfnIA4","4JaHpPAI"]', '', 2, 20800, '{"meta":{"article":"Статья 23","explanation":"Ст. 23: сотрудник СК в рамках делопроизводства, сотрудник прокуратуры или суд.","quote":"Отстранение работника государственной организации от занимаемой должности производит сотрудник органов СК России в рамках ведения делопроизводства, сотрудник органов прокуратуры или суд.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q064', NULL, 'vp', 2, 'pk', 'Статья 23', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q064');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При задержании преступника у сотрудника нет специальных средств и оружия. Что он вправе использовать?', '[{"id":"0L0OmfA","text":"Любые подручные средства и иное не состоящее на вооружении оружие"},{"id":"fht0sSH","text":"Ничего — задержание без спецсредств и оружия запрещено"},{"id":"TqiXVhlz","text":"Только физическую силу и приёмы рукопашного боя"},{"id":"8UEdLqq0","text":"Только служебный транспорт для блокирования лица"}]', '["0L0OmfA"]', '', 3, 20810, '{"meta":{"article":"Статья 24, ч. 24.3","explanation":"Ч. 24.3: любые подручные средства и иное не состоящее на вооружении оружие.","quote":"вправе использовать любые подручные средства, а также применять иное не состоящее на вооружении правоохранительного органа оружие","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q065', NULL, 'medium', 3, 'pk', 'Статья 24, ч. 24.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q065');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать сотрудник после применения огнестрельного оружия?', '[{"id":"GLOmZeW","text":"Ничего, если применение оружия было законным"},{"id":"OhsAErd3","text":"Вызвать скорую медицинскую помощь или по возможности оказать помощь самому"},{"id":"A8o3lG6","text":"Сдать оружие дежурному, написать объяснительную и ждать служебной проверки"},{"id":"0bHoYJVb","text":"Немедленно доложить о применении в ФСБ России"}]', '["OhsAErd3"]', '', 2, 20820, '{"meta":{"article":"Статья 25, ч. 25.1","explanation":"Ч. 25.1: вызвать скорую или по возможности оказать помощь сам.","quote":"В случае применения огнестрельного оружия сотрудник, применивший его, обязан вызвать бригаду скорой медицинской помощи для оказания необходимой медицинской помощи или по возможности оказать её самому.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q067', NULL, 'medium', 2, 'pk', 'Статья 25, ч. 25.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q067');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие утверждения о применении огнестрельного оружия против вооружённого преступника верны по ПК?', '[{"id":"clHxPUl8","text":"Требуется письменное разрешение командира подразделения"},{"id":"PyWktRsu","text":"Необходимо сделать предупредительный выстрел в воздух"},{"id":"rSYisFAz","text":"Необходимо предупредить о намерении открыть огонь на поражение"},{"id":"jyHCwAxu","text":"Обязательно сделать три предупредительных выстрела подряд"},{"id":"tAW6Fshm","text":"При явной угрозе жизни человека разрешено применение без предупреждения"},{"id":"WE7zwlh","text":"Огонь допускается только после безуспешного применения тайзера"}]', '["PyWktRsu","rSYisFAz","tAW6Fshm"]', '', 3, 20830, '{"meta":{"article":"Статья 25, ч. 25.2","explanation":"Сотрудник вправе применить оружие для сдерживания; обязан предупредить о намерении открыть огонь на поражение и сделать предупредительный выстрел в воздух; при явной угрозе жизни — без предупреждения.","quote":"Сотрудник обязан предупредить о намерении открыть огонь на поражение и сделать предупредительный выстрел в воздух.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q069~v2', NULL, 'full', 3, 'pk', 'Статья 25, ч. 25.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q069~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие категории прямо названы в ПК как имеющие право на ношение и хранение огнестрельного оружия при исполнении служебных обязанностей?', '[{"id":"1D4p9ZOX","text":"Военнослужащие Вооружённых Сил РФ"},{"id":"eYadRD3","text":"Сотрудники Министерства юстиции"},{"id":"Qv4sY8C","text":"Сотрудники ФСИН"},{"id":"AGUMFnye","text":"Адвокаты"},{"id":"PLDWOR4e","text":"Сотрудники органов прокуратуры"},{"id":"XHfRiiXn","text":"Работники государственных СМИ"}]', '["1D4p9ZOX","Qv4sY8C","PLDWOR4e"]', '', 1, 20840, '{"meta":{"article":"Статья 26","explanation":"Ст. 26 называет полицию, ФСИН, Росгвардию, ФСБ, ФСО, Вооружённые Силы, прокуратуру, СК и иных лиц по законодательству.","quote":"Федеральной службы охраны, Вооруженных Сил Российской Федерации, сотрудники органов прокуратуры Российской Федерации","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q071~v2', NULL, 'full', 1, 'pk', 'Статья 26', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q071~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько причин остановки транспортных средств перечислено в ПК?', '[]', '[]', '', 1, 20850, '{"meta":{"article":"Статья 56","explanation":"Нарушение уголовного/административного законодательства, нарушение ПДД, проверка документов.","quote":"нарушение уголовного или административного законодательства, в любом его проявлении;","difficulty":"1"},"answer":3,"tolerance":0,"unit":"причины"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q072~v2', NULL, 'medium', 1, 'pk', 'Статья 56', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q072~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите процессуальные действия сотрудника ГИБДД при остановке ТС в общем порядке, установленном ПК.', '[]', '[]', '', 2, 20860, '{"meta":{"article":"Статья 58, ч. 58.2","explanation":"Пп. 1–5 ч. 58.2.","quote":"запросить документы, разрешающие управление транспортным средством;","difficulty":"2"},"items":[{"id":"YqWWo7M5","text":"Подойти к ТС, назвать должность, звание, фамилию"},{"id":"kmPIDQZc","text":"Донести требование выйти из ТС"},{"id":"jfIo1UZ7","text":"Показать удостоверение, сообщить причину остановки"},{"id":"oB24KAzg","text":"Запросить документы, разрешающие управление ТС"},{"id":"0OaACKl","text":"Подтвердить владение автомобилем или право им управлять"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q075~v2', NULL, 'vp', 2, 'pk', 'Статья 58, ч. 58.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q075~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Можно ли эвакуировать спецтранспорт с включёнными синими проблесковыми маячками?', '[{"id":"qm3vUF6u","text":"Нельзя, кроме блокировки въезда на территорию учреждений или угрозы БДД"},{"id":"xktN3MsX","text":"Нельзя ни при каких условиях, даже при прямой угрозе БДД"},{"id":"vJrD8cpW","text":"Можно всегда, если транспорт припаркован с нарушением правил"},{"id":"Bsfhx5Nj","text":"Можно только по письменному решению прокурора или суда"}]', '["qm3vUF6u"]', '', 2, 20870, '{"meta":{"article":"Статья 60, ч. 60.3","explanation":"Ч. 60.3: нельзя, кроме случаев блокировки въезда на территорию учреждений или непосредственной угрозы безопасности движения.","quote":"Не допускается задержание специального транспорта со включёнными проблесковыми маячками синего или красно-синего цвета","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q077', NULL, 'full', 2, 'pk', 'Статья 60, ч. 60.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q077');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае протокол об административном правонарушении НЕ составляется?', '[{"id":"CiYLlkhX","text":"Когда нарушитель просит не составлять протокол и оплачивает штраф"},{"id":"3yeudygI","text":"Когда штраф оплачен на месте до окончания составления протокола"},{"id":"FYCJXvRG","text":"Когда дело рассматривается в суде, прокуратуре или Министерстве юстиции"},{"id":"GTy6VaNe","text":"Когда нарушитель — военнослужащий, проходящий службу по контракту"}]', '["FYCJXvRG"]', '', 2, 20880, '{"meta":{"article":"Статья 62, ч. 62.1","explanation":"Ч. 62.1: когда дело рассматривается в суде, прокуратуре или Минюсте.","quote":"О совершении административного правонарушения составляется протокол, за исключением случаев, когда дело рассматривается в суде, в прокуратуре или Министерстве юстиции.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-pk-q079', NULL, 'full', 2, 'pk', 'Статья 62, ч. 62.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q079');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо находится под защитой государственной тайны и подозревается в административном правонарушении. Что оно обязано предоставить сотруднику?', '[{"id":"0ZvgPg4C","text":"Паспорт и служебное удостоверение с печатью"},{"id":"FH2lt5vB","text":"Ничего не обязано предоставлять"},{"id":"xrZLxx5Z","text":"Исключительно жетон государственного служащего"},{"id":"Zn97FQZm","text":"Справку из ФСБ о допуске к гостайне"}]', '["xrZLxx5Z"]', '', 3, 20890, '{"meta":{"article":"Статья 63, ч. 63.2","explanation":"Ч. 63.2: исключительно жетон госслужащего, без раскрытия иных данных.","quote":"оно обязано предоставить исключительно жетон государственного служащего, подтверждающий его личность и принадлежность к государственной организации","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-q080', NULL, 'vp', 3, 'pk', 'Статья 63, ч. 63.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q080');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие утверждения об использовании алкотестеров верны по ПК?', '[{"id":"FOC4Qki","text":"Использование допускается частными охранными организациями"},{"id":"z7nPdQmb","text":"Выданные на службе алкотестеры являются государственной собственностью"},{"id":"JnfrjcSk","text":"Анализ может проводиться при задержании сотрудниками правоохранительных органов"},{"id":"Cat2KHhH","text":"Алкотестер может применять любой работодатель в отношении работников"},{"id":"phKW2dk","text":"Использование допускается только сотрудниками правоохранительных или медицинских органов"},{"id":"qc8iIxSk","text":"Алкотестер разрешено использовать в личных целях вне службы"}]', '["z7nPdQmb","JnfrjcSk","phKW2dk"]', '', 1, 20900, '{"meta":{"article":"Статья 64","explanation":"Используются только сотрудниками правоохранительных или медицинских органов; являются госсобственностью и используются только для должностных обязанностей; причины — медосмотр, задержание или иное процессуальное действие.","quote":"использование алкотестеров допускается только сотрудниками правоохранительных или медицинских органов;","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-pk-q081~v2', NULL, 'medium', 1, 'pk', 'Статья 64', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-q081~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой уголовный закон имеет обратную силу?', '[{"id":"7738EAD1","text":"Закон, устраняющий преступность деяния, смягчающий наказание или иначе улучшающий положение лица"},{"id":"QlUn9sbV","text":"Закон, усиливающий наказание, если деяние ещё не было рассмотрено судом по существу дела"},{"id":"EgLuQIr","text":"Никакой уголовный закон обратной силы не имеет"},{"id":"gb13Wuh7","text":"Любой новый уголовный закон"}]', '["7738EAD1"]', '', 2, 20910, '{"meta":{"article":"Статья 8, ч. 8.2","explanation":"Ч. 8.2: обратную силу имеет закон, устраняющий преступность, смягчающий наказание или иначе улучшающий положение лица.","quote":"Уголовный закон, устраняющий преступность деяния, смягчающий наказание или иным образом улучшающий положение лица, совершившего преступление, имеет обратную силу","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q003', NULL, 'full', 2, 'uk', 'Статья 8, ч. 8.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что признаётся временем совершения преступления?', '[{"id":"K7EWaQ22","text":"Время задержания лица"},{"id":"rHuoDwBy","text":"Время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий"},{"id":"UGtzKRJN","text":"Время возбуждения уголовного дела в отношении лица, совершившего действие"},{"id":"ySfMw6DQ","text":"Время наступления общественно опасных последствий независимо от времени совершения самого действия"}]', '["rHuoDwBy"]', '', 2, 20920, '{"meta":{"article":"Статья 8, ч. 8.4","explanation":"Ч. 8.4: время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий.","quote":"Временем совершения преступления признается время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q004', NULL, 'full', 2, 'uk', 'Статья 8, ч. 8.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кем по УК может устанавливаться малозначительность деяния?', '[{"id":"GqxOuvUi","text":"Судом"},{"id":"torB3FJo","text":"Адвокатом"},{"id":"zVp4b91t","text":"Командиром воинской части"},{"id":"iA77Iwwf","text":"Прокурором"},{"id":"vTxb9lF1","text":"Следователем Следственного комитета"},{"id":"YM8WW4qV","text":"Сотрудником ВП, проводящим задержание"}]', '["GqxOuvUi","iA77Iwwf","vTxb9lF1"]', '', 2, 20930, '{"meta":{"article":"Статья 10, ч. 10.2","explanation":"Ч. 10.2: судом, прокурором, следователем Следственного комитета.","quote":"Малозначительность может устанавливается судом, прокурором, следователем Следственного комитета.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q005~v2', NULL, 'vp', 2, 'uk', 'Статья 10, ч. 10.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q005~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каков предел наказания за покушение на преступление?', '[{"id":"c6QRT18","text":"Равен наказанию за оконченное преступление того же состава"},{"id":"NyVjpSw","text":"Не более трёх четвертей максимального срока или размера наказания"},{"id":"rMTWkVVc","text":"Не более одной трети максимального срока наиболее строгого наказания"},{"id":"OYi1tzxI","text":"Не более половины максимального срока или размера наиболее строгого вида наказания"}]', '["OYi1tzxI"]', '', 3, 20940, '{"meta":{"article":"Статья 10, ч. 10.3","explanation":"Ч. 10.3: не более половины максимального срока или размера наиболее строгого вида наказания за оконченное преступление.","quote":"Срок или размер наказания за покушение на преступление не может превышать половины максимального срока или размера наиболее строгого вида наказания","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q006', NULL, 'vp', 3, 'uk', 'Статья 10, ч. 10.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте категорию преступления и максимальное наказание по УК.', '[]', '[]', '', 2, 20950, '{"meta":{"article":"Статья 12","explanation":"Ст. 12: небольшой тяжести — до 2 лет; средней — 3–5 лет; тяжкие — 6–10 лет; особо тяжкие — от 11 лет.","quote":"Тяжкими преступлениями признаются деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, составляет от шести до десяти лет лишения свободы включительно.","difficulty":"2"},"pairs":[{"l":{"id":"bDEMx9P5","text":"Небольшой тяжести"},"r":{"id":"rioyYhtV","text":"до двух лет лишения свободы включительно"}},{"l":{"id":"QegryAQu","text":"Средней тяжести"},"r":{"id":"8WWjp7Xn","text":"от трёх до пяти лет включительно"}},{"l":{"id":"6PCP9rTk","text":"Тяжкие"},"r":{"id":"tOvzqeeF","text":"от шести до десяти лет включительно"}},{"l":{"id":"KsyWUoZ","text":"Особо тяжкие"},"r":{"id":"XUGxX97O","text":"от одиннадцати и более лет"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q012~v2', NULL, 'full', 2, 'uk', 'Статья 12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид соучастника и его определение по УК.', '[]', '[]', '', 2, 20960, '{"meta":{"article":"Статья 15","explanation":"Чч. 15.2–15.5.","quote":"Подстрекателем признается лицо, склонившее другое лицо к совершению преступления путем уговора, подкупа, угрозы или другим способом.","difficulty":"2"},"pairs":[{"l":{"id":"Z7p0BKkF","text":"Исполнитель"},"r":{"id":"O5cPNsxr","text":"непосредственно совершил преступление или участвовал в нём совместно с другими лицами"}},{"l":{"id":"5xvqynZ","text":"Организатор"},"r":{"id":"zhrwVmaD","text":"организовал совершение преступления или руководил его исполнением"}},{"l":{"id":"HzavTUM","text":"Подстрекатель"},"r":{"id":"d7Zd1vWE","text":"склонил другое лицо к совершению преступления уговором, подкупом, угрозой или иным способом"}},{"l":{"id":"zsWAa2z","text":"Пособник"},"r":{"id":"tvT5qEJ","text":"содействовал советами, указаниями, предоставлением информации, средств или орудий либо устранением препятствий"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q015~v2', NULL, 'vp', 2, 'uk', 'Статья 15', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q015~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо, не являющееся специальным субъектом (например, не должностное лицо), участвовало в превышении должностных полномочий вместе с должностным лицом. Как оно отвечает?', '[{"id":"WorrQu8l","text":"Как соисполнитель"},{"id":"9k40XfwY","text":"Только как исполнитель преступления наравне с должностным лицом"},{"id":"H8NOXr1","text":"Не несёт ответственности"},{"id":"koVXsJ71","text":"В качестве организатора, подстрекателя либо пособника"}]', '["koVXsJ71"]', '', 3, 20970, '{"meta":{"article":"Статья 16, ч. 16.4","explanation":"Ч. 16.4: в качестве организатора, подстрекателя либо пособника.","quote":"несет уголовную ответственность за данное преступление в качестве его организатора, подстрекателя либо пособника","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q016', NULL, 'full', 3, 'uk', 'Статья 16, ч. 16.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда причинение любого вреда посягающему является необходимой обороной без учёта соразмерности?', '[{"id":"yvk24jzW","text":"Только если обороняется сотрудник правоохранительного органа"},{"id":"Jo85myY6","text":"Всегда, когда защищается имущество, жилище или иные охраняемые законом интересы граждан и государства"},{"id":"0oG8WFmP","text":"Если посягательство сопряжено с насилием, опасным для жизни, или с непосредственной угрозой такого насилия"},{"id":"mUSyfiUI","text":"Только при посягательстве группы лиц, если обороняющийся находился один"}]', '["0oG8WFmP"]', '', 2, 20980, '{"meta":{"article":"Статья 17, ч. 17.1","explanation":"Ч. 17.1: если посягательство сопряжено с насилием, опасным для жизни, или с непосредственной угрозой такого насилия.","quote":"если это посягательство было сопряжено с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q018', NULL, 'vp', 2, 'uk', 'Статья 17, ч. 17.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии причинение вреда лицу, совершившему преступление, при его задержании не является преступлением?', '[{"id":"Su6qquHW","text":"Только если вред причинён по неосторожности и без применения оружия"},{"id":"ip4Vv98u","text":"Только если задерживаемый вооружён и оказывает активное сопротивление сотрудникам"},{"id":"LNUS1JD","text":"Всегда при задержании"},{"id":"ft0qm1Q","text":"Если иными средствами задержать было невозможно и не допущено превышения необходимых мер"}]', '["ft0qm1Q"]', '', 2, 20990, '{"meta":{"article":"Статья 18, ч. 18.1","explanation":"Ч. 18.1: если иными средствами задержать не представлялось возможным и не допущено превышения необходимых мер.","quote":"если иными средствами задержать такое лицо не представлялось возможным и при этом не было допущено превышения необходимых для этого мер","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q021', NULL, 'full', 2, 'uk', 'Статья 18, ч. 18.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае превышение мер, необходимых для задержания лица, совершившего преступление, влечёт уголовную ответственность?', '[{"id":"nMLakFC5","text":"Только при причинении смерти"},{"id":"zsqw2d9","text":"Только в случаях умышленного причинения вреда"},{"id":"08IXC1n9","text":"В любом случае, в том числе при неосторожности"},{"id":"hXaZT0ef","text":"Только если задержание проводил гражданский"}]', '["zsqw2d9"]', '', 3, 21000, '{"meta":{"article":"Статья 18, ч. 18.2","explanation":"Ч. 18.2: только в случаях умышленного причинения вреда.","quote":"Такое превышение влечет за собой уголовную ответственность только в случаях умышленного причинения вреда.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q022', NULL, 'vp', 3, 'uk', 'Статья 18, ч. 18.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий, исполняя обязательный для него приказ, причинил вред охраняемым интересам. Кто несёт ответственность?', '[{"id":"LOzj3LGf","text":"Никто"},{"id":"E5ps78C5","text":"Исполнитель и отдавший приказ в равной мере"},{"id":"2C24I8yp","text":"Лицо, отдавшее незаконный приказ или распоряжение"},{"id":"5RcKjx5l","text":"Исполнитель приказа, если не обжаловал приказ"}]', '["2C24I8yp"]', '', 2, 21010, '{"meta":{"article":"Статья 19, ч. 19.1","explanation":"Ч. 19.1: не преступление для исполнителя; отвечает лицо, отдавшее незаконный приказ.","quote":"Уголовную ответственность за причинение такого вреда несет лицо, отдавшее незаконные приказ или распоряжение.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q023', NULL, 'full', 2, 'uk', 'Статья 19, ч. 19.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как оценивается неисполнение заведомо незаконного приказа?', '[{"id":"HBwxutN9","text":"Как преступление — неисполнение приказа"},{"id":"SnQzrTTL","text":"Как дисциплинарный проступок с лишением звания"},{"id":"KbYIrUFm","text":"Как халатность военнослужащего"},{"id":"quyKdTF","text":"Исключает уголовную ответственность"}]', '["quyKdTF"]', '', 3, 21020, '{"meta":{"article":"Статья 19, ч. 19.2","explanation":"Ч. 19.2: неисполнение заведомо незаконного приказа исключает уголовную ответственность; исполнитель такого приказа, совершивший умышленное преступление, отвечает на общих основаниях.","quote":"Неисполнение заведомо незаконных приказа или распоряжения исключает уголовную ответственность.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q024~v2', NULL, 'full', 3, 'uk', 'Статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q024~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие виды наказаний предусмотрены УК?', '[{"id":"XFIAFEu","text":"Лишение специального, воинского или почётного звания, классного чина и госнаград"},{"id":"lrPrP3BU","text":"Обязательные работы"},{"id":"T1ItACr","text":"Ограничение свободы"},{"id":"F8Twao5P","text":"Штраф"},{"id":"tb6AUlu5","text":"Арест (лишение свободы на определённый срок)"},{"id":"VDjhyvh4","text":"Исправительные работы"}]', '["XFIAFEu","F8Twao5P","tb6AUlu5"]', '', 1, 21030, '{"meta":{"article":"Статья 21","explanation":"Ст. 21: штраф; лишение права занимать должности/заниматься деятельностью; лишение звания, классного чина и госнаград; арест (лишение свободы).","quote":"в) лишение специального, воинского или почетного звания, классного чина и государственных наград;","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q026~v2', NULL, 'full', 1, 'uk', 'Статья 21', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q026~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо уклоняется от уплаты штрафа, назначенного как основное наказание. Как поступают?', '[{"id":"MpYcZNQi","text":"Лицо освобождается от наказания"},{"id":"kgkE1IvY","text":"Назначается условное лишение свободы в пределах санкции соответствующей статьи"},{"id":"GACkpluN","text":"Штраф заменяется наказанием в пределах санкции статьи, условным оно быть не может"},{"id":"9ouVWMWt","text":"Штраф удваивается"}]', '["GACkpluN"]', '', 2, 21040, '{"meta":{"article":"Статья 22, ч. 22.5","explanation":"Ч. 22.5: штраф заменяется наказанием в пределах санкции статьи; назначенное наказание не может быть условным.","quote":"штраф заменяется наказанием в пределах санкции, предусмотренной инкриминируемой статьей Особенной части настоящего Кодекса по которому назначено наказание","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q027', NULL, 'vp', 2, 'uk', 'Статья 22, ч. 22.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе лишить осуждённого за тяжкое преступление воинского звания и кто — государственных наград?', '[{"id":"oTXNn450","text":"Воинского звания — только суд; наград — уполномоченное лицо"},{"id":"DCwrKFPH","text":"Воинского звания — уполномоченное должностное лицо; госнаград — только суд"},{"id":"rHHKBF4","text":"И воинского звания, и государственных наград лишает только суд"},{"id":"6HjKiGq","text":"И того, и другого лишает командир воинской части"}]', '["DCwrKFPH"]', '', 3, 21050, '{"meta":{"article":"Статья 24","explanation":"Ст. 24: воинского звания — уполномоченное должностное лицо; госнаград и почётного звания — только суд.","quote":"Лишение государственных наград или почетного звания осуществляется только судом.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q029', NULL, 'full', 3, 'uk', 'Статья 24', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'К лицам, совершившим какие преступления, сроки давности по УК НЕ применяются? Выберите все верные.', '[{"id":"uD7d4nS","text":"Террористический акт"},{"id":"ryCEj3iB","text":"Умышленное причинение тяжкого вреда здоровью"},{"id":"abX9dnr","text":"Посягательство на жизнь сотрудника правоохранительного органа"},{"id":"fIxZTTKr","text":"Убийство"},{"id":"OAo9UrI","text":"Государственная измена"},{"id":"7LIKw1Z0","text":"Разглашение государственной тайны"}]', '["uD7d4nS","ryCEj3iB","OAo9UrI"]', '', 3, 21060, '{"meta":{"article":"Статья 32, ч. 32.3","explanation":"Ч. 32.3: ст. 38, 53, 55, 69, 71.","quote":"К лицам, совершившим преступление, предусмотренного статьями 38, 53, 55, 69, 71 настоящего Кодекса, сроки давности не применяются.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q036~v2', NULL, 'full', 3, 'uk', 'Статья 32, ч. 32.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q036~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что происходит с течением срока давности, если лицо уклоняется от следствия или суда?', '[{"id":"sewtg1QJ","text":"Срок удваивается"},{"id":"4Zc5D1v","text":"Срок начинается заново с момента уклонения"},{"id":"Ahlz12i4","text":"Течение приостанавливается до задержания лица или его явки с повинной"},{"id":"Ry5XphhF","text":"Срок продолжает течь, но при задержании наказание назначается строже"}]', '["Ahlz12i4"]', '', 3, 21070, '{"meta":{"article":"Статья 32, ч. 32.4","explanation":"Ч. 32.4: течение приостанавливается и возобновляется с момента задержания или явки с повинной.","quote":"Течение сроков давности приостанавливается, если лицо, совершившее преступление, уклоняется от следствия или суда.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q037', NULL, 'vp', 3, 'uk', 'Статья 32, ч. 32.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кого суд может освободить от уголовной ответственности с назначением судебного штрафа?', '[{"id":"cfRcXmbj","text":"Впервые совершившее преступление небольшой или средней тяжести и загладившее вред"},{"id":"jtdvEECh","text":"Любое лицо по ходатайству командира воинской части или руководителя"},{"id":"OOVAnZD","text":"Впервые совершившее тяжкое преступление, признавшее вину и загладившее вред"},{"id":"nOR8V2MN","text":"Только несовершеннолетних"}]', '["cfRcXmbj"]', '', 2, 21080, '{"meta":{"article":"Статья 31, ч. 31.1","explanation":"Ч. 31.1: лицо, впервые совершившее преступление небольшой или средней тяжести и возместившее ущерб (загладившее вред).","quote":"Лицо, впервые совершившее преступление небольшой или средней тяжести, может быть освобождено судом от уголовной ответственности с назначением судебного штрафа","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q038', NULL, 'full', 2, 'uk', 'Статья 31, ч. 31.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q038');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чьим актом осуществляется помилование и снимается ли с помилованного судимость?', '[{"id":"B9mFB2en","text":"Приказом Министра юстиции после проверки уголовного дела; судимость с помилованного не снимается"},{"id":"LVe6gHkZ","text":"Указом Губернаторов Федерального округа при отсутствии возражений Генпрокурора; судимость не снимается"},{"id":"OUOdRREA","text":"Указом Президента по представлению суда и Генпрокурора; судимость с помилованного снимается"},{"id":"jRdY6ZMf","text":"Решением суда; судимость снимается"}]', '["LVe6gHkZ"]', '', 2, 21090, '{"meta":{"article":"Статья 33-1","explanation":"Ст. 33-1: Указом Губернаторов ФО при отсутствии возражений Генпрокурора; судимость не снимается.","quote":"С помилованного лица судимость не снимается.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q041', NULL, 'full', 2, 'uk', 'Статья 33-1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q041');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какое имущество подлежит конфискации по УК?', '[{"id":"itxoTw4M","text":"Орудия совершения преступления, принадлежащие обвиняемому"},{"id":"xJ2Ou93x","text":"Деньги и ценности, полученные в результате совершения преступлений"},{"id":"3qSI1SE6","text":"Оборудование или иные средства совершения преступления, принадлежащие обвиняемому"},{"id":"iFbLHRJt","text":"Заработная плата обвиняемого за последний год службы или работы"},{"id":"3r8X3OfB","text":"Единственное жильё обвиняемого вне связи с преступлением"},{"id":"ZFbzPONP","text":"Всё имущество родственников обвиняемого, проживающих с ним совместно"}]', '["itxoTw4M","xJ2Ou93x","3qSI1SE6"]', '', 2, 21100, '{"meta":{"article":"Статья 36, ч. 36.1","explanation":"Ч. 36.1: деньги, ценности и иное имущество, полученные преступным путём; орудия, оборудование и иные средства совершения преступления, принадлежащие обвиняемому.","quote":"орудий, оборудования или иных средств совершения преступления, принадлежащих обвиняемому.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q042~v2', NULL, 'vp', 2, 'uk', 'Статья 36, ч. 36.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q042~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой срок (в годах) наказывается убийство без квалифицирующих признаков?', '[]', '[]', '', 1, 21110, '{"meta":{"article":"Статья 37, ч. 37.1","explanation":"Ч. 37.1: 7 лет, СПРП ★★★★.","quote":"наказывается лишением свободы на срок семи лет (СПРП «★★★★»).","difficulty":"1"},"answer":7,"tolerance":0,"unit":"лет"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q043~v2', NULL, 'full', 1, 'uk', 'Статья 37, ч. 37.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q043~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что понимается под тяжким вредом здоровью в УК (RMRP)?', '[{"id":"Vy9XPifX","text":"Утрата трудоспособности более чем на 3 дня"},{"id":"h1mLMsTm","text":"Любое ранение огнестрельным оружием, требующее госпитализации в больницу"},{"id":"P3xjG333","text":"Состояние, при котором человек без медицинской помощи не может прийти в сознание"},{"id":"KDAynL5","text":"Любой вред, зафиксированный врачом"}]', '["h1mLMsTm"]', '', 2, 21120, '{"meta":{"article":"Статья 68, примечание","explanation":"Примечание к ст. 68 распространяет определение на другие статьи Кодекса.","quote":"Под тяжким вредом здоровью понимается состояние человека в настоящей статье и других статьях настоящего Кодекса, при котором он без медицинской помощи не может прийти в сознание.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q045', NULL, 'vp', 2, 'uk', 'Статья 68, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q045');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое условие обязательно для квалификации угрозы убийством по УК?', '[{"id":"ECzYPayn","text":"У угрожающего было огнестрельное оружие"},{"id":"vb5WU371","text":"Угроза высказана при двух и более свидетелях"},{"id":"kHiD5FQ","text":"Угроза высказана письменно или по телефону"},{"id":"x8UqgL08","text":"Имелись основания опасаться осуществления угрозы"}]', '["x8UqgL08"]', '', 2, 21130, '{"meta":{"article":"Статья 39","explanation":"Ст. 39: если имелись основания опасаться осуществления угрозы.","quote":"Угроза убийством или причинением тяжкого вреда здоровью, если имелись основания опасаться осуществления этой угрозы","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q046', NULL, 'full', 2, 'uk', 'Статья 39', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q046');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите составы в порядке возрастания срока лишения свободы.', '[]', '[]', '', 2, 21140, '{"meta":{"article":"Статьи 44, 46, 47","explanation":"Кража (ст. 44) — 3 года; грабёж (ч. 46.1) — 4 года; разбой (ч. 47.2) — 6 лет; разбой с тяжким вредом (ч. 47.3) — 7 лет.","quote":"Разбой, совершенный группой лиц по предварительному сговору, а равно с применением оружия или предметов, используемых в качестве оружия","difficulty":"2"},"items":[{"id":"I5gIw","text":"Кража"},{"id":"bMpvCltb","text":"Грабёж"},{"id":"uPzPgj0s","text":"Разбой с применением оружия"},{"id":"xLePFXct","text":"Разбой с причинением тяжкого вреда здоровью"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q047~v2', NULL, 'full', 2, 'uk', 'Статьи 44, 46, 47', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q047~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'С какой суммы (в рублях) стоимость имущества признаётся значительным ущербом по примечанию к УК?', '[]', '[]', '', 2, 21150, '{"meta":{"article":"Статья 48, примечание","explanation":"Примечание к ст. 48: от 500 000 рублей.","quote":"Под значительным ущербом в настоящей статье и в дальнейшем понимается стоимость имущества в размере от пятисот тысяч (500.000) рублей.","difficulty":"2"},"answer":500000,"tolerance":0,"unit":"рублей"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q048~v2', NULL, 'full', 2, 'uk', 'Статья 48, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q048~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военный водитель по неосторожности в ДТП повредил служебный автомобиль (госсобственность). Подпадает ли это под УК?', '[{"id":"UwfhCTJc","text":"Нет, не подпадает и квалифицируется по иным нормам"},{"id":"JYPoZqZW","text":"Да, если ущерб свыше 500 000 рублей"},{"id":"HD97lyf","text":"Да, но наказание смягчается вдвое как за неосторожное"},{"id":"QnxRB3D","text":"Да, всегда"}]', '["UwfhCTJc"]', '', 3, 21160, '{"meta":{"article":"Статья 48-1, примечание 3","explanation":"Примечание 3: деяния по неосторожности, в т.ч. в ДТП, не подпадают под ст. 48-1.","quote":"Деяния, повлекшие повреждение государственной собственности по неосторожности (в том числе в результате дорожно‑транспортного происшествия), не подпадают под действие настоящей статьи","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q049', NULL, 'full', 3, 'uk', 'Статья 48-1, примечание 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q049');
