INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе хранить и использовать «Армейское Обезболивающее»?', '[{"id":"LMMRuOUb","text":"Любой гражданин при наличии рецепта от врача государственной больницы"},{"id":"EAH7Qrl","text":"Никто — это запрещённое вещество"},{"id":"0bwOXyC","text":"Сотрудники гос. (силовых) структур при исполнении должностных обязанностей"},{"id":"xEboyCrT","text":"Только врачи гражданских больниц"}]', '["0bwOXyC"]', '', 2, 21200, '{"meta":{"article":"Статья 64, примечание 2","explanation":"Примечание 2 к ст. 64: сотрудники гос. (силовых) структур при исполнении обязанностей; иначе порядок устанавливает устав организации.","quote":"могут храниться и использоваться сотрудниками гос. (силовых) структур при исполнении ими своих должностных обязанностей","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q058', NULL, 'full', 2, 'uk', 'Статья 64, примечание 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q058');
