INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто из перечисленных признаётся государственным или общественным деятелем по примечанию к УК?', '[{"id":"7mKVJVjA","text":"Начальник военной полиции гарнизона"},{"id":"zmGeeQlp","text":"Главный врач больницы"},{"id":"8dLlKCCS","text":"Прокурор субъекта РФ"},{"id":"NWfUpYg7","text":"Командир мотострелковой бригады"}]', '["8dLlKCCS"]', '', 2, 21230, '{"meta":{"article":"Статья 70, примечание","explanation":"Примечание к ст. 70 содержит закрытый перечень: Губернатор и вице-губернатор ФО, руководство и депутаты ЗС, министры ФО, судьи, Президент адвокатской палаты, руководство СК и прокуратуры, сенаторы и др.","quote":"прокурор субъекта Российской Федерации и его заместители","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q064~v2', NULL, 'full', 2, 'uk', 'Статья 70, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q064~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое условие обязательно для состава разглашения государственной тайны по УК?', '[{"id":"Jer9oCzG","text":"Сведения переданы иностранному государству"},{"id":"8FJdjEQ","text":"Лицо получило за это вознаграждение"},{"id":"KADHJHD","text":"Сведения стали достоянием других лиц"},{"id":"z0WEXQAA","text":"Сведения опубликованы в СМИ"}]', '["KADHJHD"]', '', 2, 21240, '{"meta":{"article":"Статья 74","explanation":"Ст. 74: сведения стали достоянием других лиц.","quote":"если эти сведения стали достоянием других лиц","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q065~v2', NULL, 'vp', 2, 'uk', 'Статья 74', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q065~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто признаётся должностным лицом в статьях главы XVIII УК?', '[{"id":"dvq9pKU","text":"Только руководители органов власти"},{"id":"UF8iCrgI","text":"Любые работники коммерческих организаций"},{"id":"s00uAM9L","text":"Лица, постоянно, временно или по специальному полномочию осуществляющие функции представителя власти либо организационно-распорядительные, административно-хозяйственные функции в госорганах"},{"id":"I0FnnV6V","text":"Только лица, имеющие специальное или воинское звание и постоянно занимающие должность в органах государственной власти, органах местного самоуправления и государственных учреждениях"}]', '["s00uAM9L"]', '', 2, 21250, '{"meta":{"article":"Статья 76, примечание 1","explanation":"Примечание 1 к ст. 76.","quote":"Должностными лицами в статьях настоящей главы признаются лица, постоянно, временно или по специальному полномочию осуществляющие функции представителя власти","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q066', NULL, 'vp', 2, 'uk', 'Статья 76, примечание 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q066');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие признаки являются квалифицирующими для превышения должностных полномочий?', '[{"id":"GBlUIoj","text":"В отношении иностранного гражданина"},{"id":"pXjayMpk","text":"В выходной день"},{"id":"ZrwdCKkh","text":"С причинением тяжких последствий"},{"id":"3sP6kl40","text":"В ночное время суток"},{"id":"1VEdRGRy","text":"С применением оружия или специальных средств"},{"id":"nux7bmeC","text":"Из корыстной или иной личной заинтересованности"}]', '["ZrwdCKkh","1VEdRGRy","nux7bmeC"]', '', 3, 21260, '{"meta":{"article":"Статья 77, ч. 77.3","explanation":"Ч. 77.3: насилие или угроза; оружие или спецсредства; тяжкие последствия; группа по сговору/организованная группа; корыстная или иная личная заинтересованность.","quote":"с применением оружия или специальных средств;","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q067~v2', NULL, 'full', 3, 'uk', 'Статья 77, ч. 77.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q067~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой приказ должен быть умышленно не исполнен, чтобы наступила ответственность по УК?', '[{"id":"ccVlikLJ","text":"Отданный в установленном порядке и не противоречащий закону"},{"id":"gmq5uCdI","text":"Любой приказ, даже противоречащий закону, если он отдан старшим"},{"id":"zZhquiUl","text":"Только письменный приказ Министра обороны"},{"id":"dd2ClUGA","text":"Только приказ, отданный в боевой обстановке"}]', '["ccVlikLJ"]', '', 2, 21270, '{"meta":{"article":"Статья 78","explanation":"Ст. 78: приказ начальника/уполномоченного лица, отданный в установленном порядке и не противоречащий закону.","quote":"отданного в установленном порядке и не противоречащего закону","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q070', NULL, 'full', 2, 'uk', 'Статья 78', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q070');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии лицо, давшее взятку, освобождается от уголовной ответственности?', '[{"id":"cX3EeIY","text":"Если взятка не была принята"},{"id":"k4wJECV","text":"Не освобождается ни при каких условиях"},{"id":"zgc6JfTB","text":"Если сумма взятки меньше 50 000 руб. и лицо до возбуждения уголовного дела добровольно вернуло полученную выгоду и сообщило о ней"},{"id":"ORnNjupi","text":"Если активно способствовало раскрытию и (или) расследованию и было вымогательство либо оно добровольно сообщило о даче взятки"}]', '["ORnNjupi"]', '', 3, 21280, '{"meta":{"article":"Статья 79, примечание","explanation":"Примечание к ст. 79: активно способствовало раскрытию/расследованию и либо имело место вымогательство, либо лицо добровольно сообщило о даче взятки.","quote":"Лицо, давшее взятку, освобождается от уголовной ответственности, если оно активно способствовало раскрытию и (или) расследованию преступления","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q071', NULL, 'vp', 3, 'uk', 'Статья 79, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q071');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид халатности по УК и санкцию.', '[]', '[]', '', 3, 21290, '{"meta":{"article":"Статья 80","explanation":"Чч. 80.1–80.4.","quote":"наказывается штрафом в размере одного миллиона двухсот пятидесяти тысяч (1.250.000) рублей или лишением свободы на срок в три года (СПРП «★★»).","difficulty":"3"},"pairs":[{"l":{"id":"UC4Qz0ub","text":"Ненадлежащее исполнение обязанностей"},"r":{"id":"ukN6kTv","text":"штраф 800 000 руб. или 2 года"}},{"l":{"id":"Rc1c5xjO","text":"Неисполнение обязанностей"},"r":{"id":"YGId2KH6","text":"6 лет лишения свободы"}},{"l":{"id":"Tp7LCOoV","text":"Нарушение процессуальных норм при задержании и аресте"},"r":{"id":"CBlThcYd","text":"штраф 1 000 000 руб. или 3 года"}},{"l":{"id":"RghmV0R","text":"Отказ от реализации прав задержанного или ненадлежащая реализация"},"r":{"id":"ycwZUS4i","text":"штраф 1 250 000 руб. или 3 года"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q072~v2', NULL, 'vp', 3, 'uk', 'Статья 80', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q072~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Подлежит ли ответственности свидетель за отказ от дачи показаний против своего близкого родственника?', '[{"id":"GZ0cPru","text":"Да, как за отказ от дачи показаний"},{"id":"iGljOabc","text":"Только штраф"},{"id":"VopG9Di5","text":"Нет, не подлежит"},{"id":"aKiJ5Dj7","text":"Да, как за ложные показания"}]', '["VopG9Di5"]', '', 2, 21300, '{"meta":{"article":"Статья 86-2, примечание","explanation":"Примечание к ст. 86-2: не подлежит.","quote":"Лицо не подлежит уголовной ответственности за отказ от дачи показаний против себя самого, своего супруга или своих близких родственников.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q074~v2', NULL, 'full', 2, 'uk', 'Статья 86-2, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q074~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Охватывает ли УК посягательство на жизнь военнослужащего?', '[{"id":"c8dej330","text":"Да, военнослужащего и его близких"},{"id":"pErnuWMp","text":"Нет, только сотрудников полиции"},{"id":"aS9Evfy","text":"Нет, это квалифицируется как убийство"},{"id":"Noapi11W","text":"Только если военнослужащий на боевом дежурстве"}]', '["c8dej330"]', '', 2, 21310, '{"meta":{"article":"Статья 89","explanation":"Ст. 89: сотрудника правоохранительного органа, военнослужащего, а равно их близких — 6 лет.","quote":"Посягательство на жизнь сотрудника правоохранительного органа, военнослужащего, а равно их близких","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q076~v2', NULL, 'vp', 2, 'uk', 'Статья 89', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q076~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто признаётся представителем власти в УК?', '[{"id":"QBThfWN","text":"Только сотрудник полиции"},{"id":"98QeKyS5","text":"Любой госслужащий"},{"id":"g4TA3QNp","text":"Любой военнослужащий"},{"id":"OPU6gWlp","text":"Должностное лицо правоохранительного или контролирующего органа, а также иное должностное лицо с распорядительными полномочиями в отношении лиц, не находящихся от него в служебной зависимости"},{"id":"ufIjtMq","text":"Любое лицо, постоянно или временно состоящее на государственной службе, а также военнослужащий, исполняющий обязанности по охране объекта или сопровождению груза, независимо от должности"}]', '["OPU6gWlp"]', '', 1, 21320, '{"meta":{"article":"Статья 90, примечание","explanation":"Примечание к ст. 90.","quote":"Представителем власти в настоящей статье и других статьях настоящего Кодекса признается должностное лицо правоохранительного или контролирующего органа","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q077', NULL, 'full', 1, 'uk', 'Статья 90, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q077');
