INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда помеха в деятельности сотрудника госвласти становится преступлением по УК?', '[{"id":"B3kYcM2","text":"После вынесения сотрудником предупреждения о недопустимости помех"},{"id":"ylyd9C2C","text":"Только при применении насилия к сотруднику или его имуществу"},{"id":"kLAUkYtd","text":"При любом разговоре с сотрудником"},{"id":"gvVaykG8","text":"Только в здании суда"}]', '["B3kYcM2"]', '', 2, 21340, '{"meta":{"article":"Статья 93","explanation":"Ст. 93: намеренные попытки отвлечь после вынесения сотрудником предупреждения о недопустимости помех.","quote":"выражающееся в намеренных попытках отвлечь после вынесения сотрудником государственной власти предупреждения о недопустимости осуществления помех","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-q079', NULL, 'full', 2, 'uk', 'Статья 93', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q079');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите преступления против личности, госсимволов и государства по возрастанию срока лишения свободы.', '[]', '[]', '', 3, 21350, '{"meta":{"article":"Статьи 39, 69, 71, 95, 98","explanation":"Ч. 98.1 — 1 год; ст. 95 — 2 года; ст. 39 — 4 года; ст. 71 — 10 лет; ст. 69 — 15 лет.","quote":"наказывается лишением свободы на срок пятнадцати лет (СПРП «★★★★★★»).","difficulty":"3"},"items":[{"id":"7LmWs23","text":"Надругательство над телами умерших"},{"id":"nitbIgzf","text":"Надругательство над Государственным флагом"},{"id":"Ucf7MQvd","text":"Угроза убийством"},{"id":"U15asuZ","text":"Вооружённый мятеж"},{"id":"8y3uHj7O","text":"Государственная измена"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-uk-q083~v2', NULL, 'vp', 3, 'uk', 'Статьи 39, 69, 71, 95, 98', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-q083~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Освобождает ли незнание закона от административной ответственности?', '[{"id":"ofvsvN0E","text":"Нет, незнание закона не освобождает лицо от ответственности"},{"id":"m0LRrYjH","text":"Да, для иностранных граждан, если закон не опубликован на их языке"},{"id":"EquEINqq","text":"Да, если правонарушение малозначительное"},{"id":"24sjyO67","text":"Да, если лицо впервые совершило правонарушение"}]', '["ofvsvN0E"]', '', 1, 21360, '{"meta":{"article":"Статья 1.3","explanation":"Ст. 1.3, последнее предложение.","quote":"Незнание закона не освобождает лицо от ответственности.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q001', NULL, 'medium', 1, 'koap', 'Статья 1.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие положения входят в презумпцию невиновности по КоАП? Выберите все верные.', '[{"id":"FgXiyVcc","text":"Лицо считается невиновным, пока вина не доказана и не установлена вступившим в силу постановлением"},{"id":"3Rq03wzH","text":"Неустранимые сомнения в виновности толкуются в пользу лица"},{"id":"efT4GOQB","text":"Лицо обязано самостоятельно доказывать свою невиновность при составлении протокола"},{"id":"scf0rFVb","text":"Лицо отвечает только за правонарушения, в отношении которых установлена его вина"},{"id":"hoxn8lT8","text":"Сомнения толкуются в пользу сотрудника, составившего протокол"},{"id":"B0JDUvy","text":"Вина презюмируется при отказе от объяснений"}]', '["FgXiyVcc","3Rq03wzH","scf0rFVb"]', '', 2, 21370, '{"meta":{"article":"Статья 1.4","explanation":"Ч. 1.4.1–1.4.3.","quote":"1.4.3. Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, толкуются в пользу этого лица.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q002~v2', NULL, 'full', 2, 'koap', 'Статья 1.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q002~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте форму вины по КоАП с её признаками.', '[]', '[]', '', 2, 21380, '{"meta":{"article":"Статья 2.2","explanation":"Ч. 2.2.1, 2.2.2.","quote":"но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.","difficulty":"2"},"pairs":[{"l":{"id":"TlFJrRqz","text":"Умысел"},"r":{"id":"sZMn3tfR","text":"Осознавало противоправность, предвидело последствия и желало их, сознательно допускало либо относилось безразлично"}},{"l":{"id":"jAf3Xy81","text":"Неосторожность (самонадеянность)"},"r":{"id":"Zlk00Fhp","text":"Предвидело возможность последствий, но без достаточных оснований рассчитывало их предотвратить"}},{"l":{"id":"OWYGPxP1","text":"Неосторожность (небрежность)"},"r":{"id":"9xD1YtZE","text":"Не предвидело возможности последствий, хотя должно было и могло их предвидеть"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q004~v2', NULL, 'vp', 2, 'koap', 'Статья 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q004~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае должностное лицо подлежит административной ответственности по КоАП?', '[{"id":"H6hGG5Z3","text":"Только по решению вышестоящего начальника после проведения служебной проверки по факту совершённого нарушения"},{"id":"Iu1Sra0G","text":"Только при причинении имущественного ущерба"},{"id":"flLocdZ","text":"При любом правонарушении в рабочее время"},{"id":"SiiC4mjJ","text":"При совершении правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей"}]', '["SiiC4mjJ"]', '', 2, 21390, '{"meta":{"article":"Статья 2.4","explanation":"Ст. 2.4.","quote":"Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q005', NULL, 'vp', 2, 'koap', 'Статья 2.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия сотрудника (военнослужащего) при предупреждении в порядке, установленном КоАП.', '[]', '[]', '', 2, 21400, '{"meta":{"article":"Статья 3.3","explanation":"Ст. 3.3: неисполнение требований предупреждения может приравниваться к неподчинению.","quote":"После, если результатов оно не повлекло, то есть лицо не направило свои действия на устранение нарушения или отказалось в их пресечении со своей стороны, применяются иные виды административных наказаний.","difficulty":"2"},"items":[{"id":"WIpj1BC","text":"Вынести предупреждение (устно или письменно) с просьбой прекратить проступок"},{"id":"DtjV2WSn","text":"Убедиться, что лицо не устранило нарушение или отказалось его пресечь"},{"id":"GzfCtsHy","text":"Применить иные виды административных наказаний"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q007~v2', NULL, 'full', 2, 'koap', 'Статья 3.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое соотношение игрового и реального времени установлено для административного ареста?', '[{"id":"LdG24ARf","text":"1 игровой день — 1 реальный час"},{"id":"KjKHB4d","text":"1 игровой день — 1 реальная минута"},{"id":"HeIQ4H0R","text":"1 игровые сутки — 5 реальных минут"},{"id":"1fuOC848","text":"1 игровой день — 10 реальных минут"}]', '["KjKHB4d"]', '', 2, 21410, '{"meta":{"article":"Статья 3.6","explanation":"Ст. 3.6.","quote":"((1 игровой день - 1 реальная минута))","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q009~v2', NULL, 'vp', 2, 'koap', 'Статья 3.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q009~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является конфискацией орудия совершения или предмета административного правонарушения?', '[{"id":"Vp00DgDN","text":"Временное изъятие вещей до уплаты штрафа"},{"id":"1M79po40","text":"Уничтожение вещей на месте"},{"id":"LL4xj0x2","text":"Продажа вещей с торгов с передачей вырученных средств потерпевшему"},{"id":"dz2c8SuI","text":"Принудительное безвозмездное обращение вещей в федеральную собственность"}]', '["dz2c8SuI"]', '', 1, 21420, '{"meta":{"article":"Статья 3.7","explanation":"Ст. 3.7.","quote":"Конфискацией орудия совершения или предмета административного правонарушения является принудительное безвозмездное обращение в федеральную собственность вещей.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q010', NULL, 'full', 1, 'koap', 'Статья 3.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие наказания КоАП относит к основным?', '[{"id":"ga9yzYn","text":"Административный арест"},{"id":"e4ljAkUa","text":"Административный штраф"},{"id":"ZwK290dt","text":"Предупреждение"},{"id":"2TE1HBwi","text":"Лишение права на управление ТС"},{"id":"wa0beGq","text":"Дисквалификация"},{"id":"ikzRq8Mu","text":"Конфискация орудия совершения правонарушения"},{"id":"pPD0SfYL","text":"Обязательные работы"}]', '["ga9yzYn","e4ljAkUa","ZwK290dt","2TE1HBwi"]', '', 2, 21430, '{"meta":{"article":"Статья 4.1, ч. 4.1.2","explanation":"Конфискация — дополнительное наказание; основное может назначаться только одно.","quote":"Основными наказания являются: предупреждение, лишение права на управление транспортным средством, административный штраф, административный арест.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q011~v2', NULL, 'medium', 2, 'koap', 'Статья 4.1, ч. 4.1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q011~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что признаётся смягчающими обстоятельствами по КоАП? Выберите все верные.', '[{"id":"GXYkFkJP","text":"Добровольное прекращение противоправного поведения"},{"id":"VNwkkAtz","text":"Совершение правонарушения в состоянии опьянения"},{"id":"pPBsUmtT","text":"Раскаяние лица"},{"id":"2iu240xo","text":"Добровольное сообщение о совершённом правонарушении в уполномоченный орган"},{"id":"xncNWLp0","text":"Совершение правонарушения впервые и при отсутствии судимости"},{"id":"JPZjO4P","text":"Содействие органу в установлении обстоятельств дела"},{"id":"b0hMielG","text":"Наличие государственной службы или воинского звания"}]', '["GXYkFkJP","pPBsUmtT","2iu240xo","JPZjO4P"]', '', 2, 21440, '{"meta":{"article":"Статья 4.2","explanation":"Ч. 4.2.1, пп. 1–4; судья может признать и иные (ч. 4.2.2).","quote":"1) раскаяние лица, совершившего административное правонарушение; 2) добровольное прекращение противоправного поведения лицом, совершившим административное правонарушение;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q013~v2', NULL, 'full', 2, 'koap', 'Статья 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q013~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что признаётся отягчающими обстоятельствами по КоАП? Выберите все верные.', '[{"id":"xCs5cZ9T","text":"Совершение в условиях стихийного бедствия или при других чрезвычайных обстоятельствах"},{"id":"ufEq9Pbo","text":"Раскаяние лица"},{"id":"NRXIAC","text":"Совершение правонарушения военнослужащим, проходящим службу по контракту"},{"id":"9WFpwX5q","text":"Совершение правонарушения группой лиц"},{"id":"gu9hWkyd","text":"Совершение в состоянии опьянения либо отказ от медосвидетельствования"},{"id":"Lo6Y0P5e","text":"Продолжение противоправного поведения несмотря на требование уполномоченных лиц прекратить его"},{"id":"5cf0LHsC","text":"Совершение правонарушения в ночное время или в выходной день"}]', '["xCs5cZ9T","9WFpwX5q","gu9hWkyd","Lo6Y0P5e"]', '', 2, 21450, '{"meta":{"article":"Статья 4.3","explanation":"Ч. 4.3.1, пп. 1, 3, 4, 5 (п. 2 — повторность).","quote":"1) продолжение противоправного поведения, несмотря на требование уполномоченных на то лиц прекратить его;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q014~v2', NULL, 'full', 2, 'koap', 'Статья 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q014~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда отягчающее обстоятельство, перечисленное в КоАП, не может учитываться как отягчающее?', '[{"id":"MmI2kKOL","text":"Если лицо раскаялось"},{"id":"iq3VQwRB","text":"Если правонарушение совершено государственным служащим при исполнении служебных обязанностей"},{"id":"IiwzQW","text":"Если протокол составлен военнослужащим"},{"id":"orMkO9vu","text":"Если оно предусмотрено в качестве квалифицирующего признака соответствующего правонарушения"}]', '["orMkO9vu"]', '', 3, 21460, '{"meta":{"article":"Статья 4.3, ч. 4.3.2","explanation":"Ч. 4.3.2 (пример — опьянение в ст. 9.42).","quote":"4.3.2. Обстоятельства, предусмотренные частью 1 настоящей статьи, не могут учитываться как отягчающие в случае, если указанные обстоятельства предусмотрены в качестве квалифицирующего признака административного правонарушения","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q015', NULL, 'full', 3, 'koap', 'Статья 4.3, ч. 4.3.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Вправе ли сотрудник суммировать штраф за нарушения одной и той же нормы КоАП?', '[{"id":"aFphQwns","text":"Нет; но если после оформления протокола лицо повторно нарушает ту же норму, его можно привлечь повторно"},{"id":"vFzT90j0","text":"Да, за каждый эпизод до составления протокола, но не более трёх раз за одно задержание одного и того же лица"},{"id":"7qDJfSq","text":"Да, но не более трёх раз"},{"id":"uqHrycvG","text":"Нет, и повторное привлечение после протокола тоже запрещено"}]', '["aFphQwns"]', '', 2, 21470, '{"meta":{"article":"Статья 4.5","explanation":"Ст. 4.5.","quote":"Сотрудник правоохранительных органов не вправе суммировать штраф за нарушения одного и того же пункта настоящего Кодекса. Если после оформления протокола лицо повторно совершает нарушение пункта, по которому уже было наказано, то оно может быть повторно привлечено к ответственности.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q017', NULL, 'medium', 2, 'koap', 'Статья 4.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо отказывается уплатить штраф по статье, санкция которой предусматривает и арест. Что обязан сделать сотрудник?', '[{"id":"nG4DDY67","text":"Удвоить сумму штрафа"},{"id":"HhcPQpYc","text":"Передать дело в суд без задержания лица и без ареста"},{"id":"KUPINOz","text":"Применить меру пресечения в виде административного ареста"},{"id":"jhqzIQ8b","text":"Ограничиться предупреждением"}]', '["KUPINOz"]', '', 3, 21480, '{"meta":{"article":"Статья 4.6, ч. 4.6.1","explanation":"Ч. 4.6.1.","quote":"сотрудник правоохранительных органов обязан применить меру пресечения в виде административного ареста.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q018', NULL, 'vp', 3, 'koap', 'Статья 4.6, ч. 4.6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать сотрудник при наличии отягчающих обстоятельств?', '[{"id":"P6nk0122","text":"Применить минимальный штраф и предупреждение, а при повторном нарушении той же нормы — административный арест"},{"id":"WsV8kbkI","text":"Передать материалы в прокуратуру"},{"id":"mttuOPV9","text":"Применить максимальную меру наказания по санкции статьи или административный арест, если он предусмотрен"},{"id":"KmfgYqUs","text":"Назначить два основных наказания"}]', '["mttuOPV9"]', '', 3, 21490, '{"meta":{"article":"Статья 4.6, ч. 4.6.2","explanation":"Ч. 4.6.2.","quote":"4.6.2. В случае наличия отягчающих обстоятельств сотрудник правоохранительных органов обязан применить максимальную меру административного наказания предусмотренную санкцией статьи или меру пресечения в виде административного ареста, если такая имеется.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q019', NULL, 'medium', 3, 'koap', 'Статья 4.6, ч. 4.6.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как соотносятся штраф и административный арест по КоАП?', '[{"id":"qGoxiGY","text":"Арест допускается только с согласия лица"},{"id":"xsG14J84","text":"Считаются равнозначными"},{"id":"I0pNcYh","text":"Штраф применяется только после ареста"},{"id":"o7EsjBuP","text":"Арест всегда строже штрафа"}]', '["xsG14J84"]', '', 2, 21500, '{"meta":{"article":"Статья 4.6, ч. 4.6.3","explanation":"Ч. 4.6.3.","quote":"4.6.3. Административное наказание в виде административного штрафа и административного ареста считается равнозначным.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q020~v2', NULL, 'full', 2, 'koap', 'Статья 4.6, ч. 4.6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q020~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий вне службы превысил скорость. Как назначается ему штраф по КоАП?', '[{"id":"ZINHBuaa","text":"Штраф заменяется дисциплинарным взысканием по месту службы военнослужащего"},{"id":"nDvMUzdD","text":"В двойном размере — вне зависимости от того, при исполнении он или нет"},{"id":"WCoBXMRm","text":"В обычном размере, т.к. он не при исполнении"},{"id":"tSGkn3ev","text":"В тройном размере"}]', '["nDvMUzdD"]', '', 2, 21510, '{"meta":{"article":"Статья 4.7","explanation":"Ст. 4.7 касается правонарушений главы IX (дорожное движение).","quote":"государственным служащим вне зависимости от того находится ли государственный служащий при исполнении служебных обязанностей или нет, в случае избрания административного наказания в виде административного штрафа, административный штраф накладывается в двойном размере.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q021', NULL, 'full', 2, 'koap', 'Статья 4.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Военнослужащий проигнорировал требование ГИБДД об остановке; выбран штраф. Какой размер штрафа (руб.) с учётом правил КоАП о штрафах для военнослужащих?', '[]', '[]', '', 3, 21520, '{"meta":{"article":"Статья 4.7; Статья 9.8","explanation":"Ст. 9.8 — 30 000 руб.; ст. 4.7 — двойной размер для госслужащих за гл. IX.","quote":"влечет наложение административного штрафа в размере тридцати тысяч (30.000) рублей либо административного ареста на срок четырнадцати суток (СПРП «★★»).","difficulty":"3"},"answer":60000,"tolerance":0,"unit":"рублей"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q022~v2', NULL, 'vp', 3, 'koap', 'Статья 4.7; Статья 9.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q022~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Неповиновение законному требованию какого лица образует состав КоАП?', '[{"id":"tlFs3b48","text":"Сотрудника правоохранительных органов или военнослужащего"},{"id":"EHbKqyp4","text":"Только сотрудника полиции или судебного пристава при исполнении"},{"id":"dczs4vr","text":"Любого гражданина"},{"id":"ECcwKTEG","text":"Только судьи"}]', '["tlFs3b48"]', '', 1, 21530, '{"meta":{"article":"Статья 8.7","explanation":"Ст. 8.7 прямо называет военнослужащего.","quote":"Неповиновение законному распоряжению или требованию сотрудника правоохранительных органов или военнослужащего","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q023', NULL, 'medium', 1, 'koap', 'Статья 8.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В чём должен быть уверен сотрудник (военнослужащий) перед применением наказания за неповиновение законному требованию?', '[{"id":"raFK6YIh","text":"Что лицо ранее уже привлекалось к ответственности за неповиновение требованию"},{"id":"vXecKNcl","text":"Что требование было дано в письменном виде и под подпись"},{"id":"sqanrVM1","text":"Что присутствуют двое понятых"},{"id":"jrsGw9bH","text":"Что требование было верно воспринято именно тем лицом, к которому адресовалось"}]', '["jrsGw9bH"]', '', 2, 21540, '{"meta":{"article":"Статья 8.7","explanation":"Ст. 8.7, скобки.","quote":"перед применением меры наказания сотрудник должен быть уверен, что выдвинутое требование было верно воспринято именно тем лицом, к которому оно адресовалось","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q024', NULL, 'full', 2, 'koap', 'Статья 8.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой срок (суток) налагается административный арест за неповиновение законному требованию сотрудника или военнослужащего?', '[]', '[]', '', 1, 21550, '{"meta":{"article":"Статья 8.7","explanation":"Либо штраф 15 000–30 000 руб.","quote":"влечет наложение административного штрафа в размере от пятнадцати тысяч (15.000) до тридцати тысяч (30.000) рублей, либо административного ареста на срок четырнадцати суток (СПРП «★★»).","difficulty":"1"},"answer":14,"tolerance":0,"unit":"суток"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q025~v2', NULL, 'medium', 1, 'koap', 'Статья 8.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q025~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что ещё, помимо неповиновения законному требованию, охватывает этот состав КоАП?', '[{"id":"1Z3Yg2c","text":"Ложный вызов"},{"id":"TFNNgyaH","text":"Воспрепятствование исполнению сотрудником (военнослужащим) служебных обязанностей"},{"id":"tDC4iLrg","text":"Клевету на сотрудника"},{"id":"9BCq3Ely","text":"Публичное оскорбление сотрудника при исполнении им служебных обязанностей"}]', '["TFNNgyaH"]', '', 2, 21560, '{"meta":{"article":"Статья 8.7","explanation":"Ст. 8.7: «а равно воспрепятствование…».","quote":"а равно воспрепятствование исполнению ими служебных обязанностей","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q026', NULL, 'vp', 2, 'koap', 'Статья 8.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Каков максимальный размер штрафа (руб.) за нарушение правил поведения на охраняемых территориях?', '[]', '[]', '', 2, 21570, '{"meta":{"article":"Статья 8.11","explanation":"Ст. 8.11: от 10 000 до 20 000 руб.","quote":"правил поведения на охраняемых территориях в соответствии с законодательством о закрытых и охраняемых территориях, - влечет наложение административного штрафа в размере от десяти тысяч (10.000) до двадцати тысяч (20.000) рублей.","difficulty":"2"},"answer":20000,"tolerance":0,"unit":"рублей"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q027~v2', NULL, 'full', 2, 'koap', 'Статья 8.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q027~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что образует состав КоАП?', '[{"id":"dsaMfUdB","text":"Скрытое ношение огнестрельного оружия без лицензии"},{"id":"bQ6zEqb","text":"Ношение бронежилета 3-го класса"},{"id":"ZDyezZcr","text":"Открытое ношение холодного оружия в общественных местах"},{"id":"zHMJ0cWX","text":"Хранение патронов без лицензии"}]', '["ZDyezZcr"]', '', 2, 21580, '{"meta":{"article":"Статья 8.13","explanation":"Ст. 8.13; штраф 15 000–20 000 руб.","quote":"Нарушение требований законодательства об оружии, выражающееся в открытом ношении холодного оружия в общественных местах, -","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q028~v2', NULL, 'full', 2, 'koap', 'Статья 8.13', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q028~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Ношение каких масок в общественном месте НЕ образует состав КоАП о сокрытии лица?', '[{"id":"bTG053Mg","text":"Любых масок в ночное время"},{"id":"EYKx2xO","text":"Масок, скрывающих лицо, при морозе"},{"id":"NdN30BZr","text":"Балаклав и иных масок у военнослужащих вне службы, если они следуют к месту прохождения службы или обратно домой из части"},{"id":"BlvJKLfn","text":"Медицинских масок из специализированного магазина и декоративных масок на мероприятиях, санкционированных Правительством РФ"}]', '["BlvJKLfn"]', '', 2, 21590, '{"meta":{"article":"Статья 8.12","explanation":"Ст. 8.12.","quote":"кроме медицинских масок, купленных в специализированном магазине, а также за исключением ношения декоративных масок на мероприятиях, санкционированных Правительством Российской Федерации","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q029', NULL, 'medium', 2, 'koap', 'Статья 8.12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что понимается под общественным местом в КоАП?', '[{"id":"Gv3QAVoW","text":"Любое место за пределами жилища и В/Ч"},{"id":"B0oxSt59","text":"Только улицы и площади"},{"id":"hHe2hFeX","text":"Только места проведения массовых мероприятий"},{"id":"FzWPsFi","text":"Территория или помещение, доступные неограниченному кругу лиц либо предназначенные для коллективного пользования (улицы, площади, парки, транспорт, учреждения и предприятия)"},{"id":"2wt2Pu8x","text":"Территория, на которой в данный момент находятся не менее трёх посторонних граждан, а также любое помещение, принадлежащее государственной организации или воинской части, кроме жилых"}]', '["FzWPsFi"]', '', 3, 21600, '{"meta":{"article":"Статья 8.12, пояснение","explanation":"Пояснение к ст. 8.12.","quote":"Пояснение: Под общественным местом в настоящем Кодексе понимается территория или помещение, доступное для посещения неограниченным кругом лиц либо предназначенное для коллективного пользования","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q030', NULL, 'vp', 3, 'koap', 'Статья 8.12, пояснение', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q030');
