INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий не предоставил следователю документы, значимые для проверки сообщения о преступлении. По какой норме он отвечает?', '[{"id":"kjndpfo","text":"По Уголовному кодексу РФ, а не по КоАП"},{"id":"uouFfhRN","text":"По КоАП — штраф в размере десяти окладов"},{"id":"MNrOeA5H","text":"По КоАП как неповиновение требованию"},{"id":"pKTjfrWb","text":"Только в дисциплинарном порядке"}]', '["kjndpfo"]', '', 3, 21630, '{"meta":{"article":"Статья 8.9, примечание","explanation":"Примечание к ст. 8.9.","quote":"то лицо несет ответственность в соответствии с Уголовным Кодексом Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q034', NULL, 'full', 3, 'koap', 'Статья 8.9, примечание', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q034');
