INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите составы превышения скорости по КоАП по возрастанию штрафа.', '[]', '[]', '', 3, 21670, '{"meta":{"article":"Статья 9.45","explanation":"Ч. 9.45.1–9.45.4.","quote":"9.45.4. Превышение установленной скорости движения транспортного средства на величину более 80 километров в час -","difficulty":"3"},"items":[{"id":"hpo7ByUS","text":"Превышение не более чем на 20 км/ч"},{"id":"fo0Vj5c","text":"Превышение более чем на 20, но не более чем на 40 км/ч"},{"id":"6E3WhtN3","text":"Превышение более чем на 40, но не более чем на 80 км/ч"},{"id":"PL0wAf","text":"Превышение более чем на 80 км/ч"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-koap-q044~v2', NULL, 'vp', 3, 'koap', 'Статья 9.45', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q044~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая санкция за управление ТС в состоянии опьянения или передачу управления лицу в опьянении?', '[{"id":"5pTcxScX","text":"Штраф 15 000 руб. и арест на 7 суток без лишения права"},{"id":"oS5MV342","text":"Арест на 14 суток"},{"id":"AicCWJ9","text":"Штраф 30 000 руб. или лишение права на управление ТС"},{"id":"fPvHAPQ","text":"Штраф 50 000 руб. и конфискация ТС"}]', '["AicCWJ9"]', '', 2, 21680, '{"meta":{"article":"Статья 9.42","explanation":"Ст. 9.42.","quote":"Управление транспортным средством в состоянии опьянения или передача управления транспортным средством лицу, находящемуся в состоянии опьянения (см. статья 2.4 ПДД);","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q045', NULL, 'full', 2, 'koap', 'Статья 9.42', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q045');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что из перечисленного прямо названо в составе мелкого хулиганства?', '[{"id":"gl9CsS5t","text":"Попрошайничество и навязчивое предложение услуг"},{"id":"LMmkBGqB","text":"Ношение маски, скрывающей лицо"},{"id":"xYE51EId","text":"Непристойное или оскорбительное приставание к гражданам"},{"id":"YshEFpy","text":"Уничтожение или повреждение чужого имущества"},{"id":"LfDMki13","text":"Курение в общественном месте вне специально отведённых мест"},{"id":"78pWTMdW","text":"Нахождение в общественных местах в нижнем белье (кроме водоёмов, бассейнов, спортзалов)"},{"id":"ZK7C7IY","text":"Нецензурная лексика в общественных местах"}]', '["xYE51EId","YshEFpy","78pWTMdW","ZK7C7IY"]', '', 2, 21690, '{"meta":{"article":"Статья 8.1","explanation":"Ст. 8.1; курение — 8.14, маски — 8.12, попрошайничество — 8.4.","quote":"сопровождающееся нецензурной лексикой в общественных местах, непристойным или оскорбительным приставанием к гражданам","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-koap-q047~v2', NULL, 'medium', 2, 'koap', 'Статья 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q047~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой штраф за оскорбление?', '[{"id":"H90thmaQ","text":"От 10 000 до 20 000 руб."},{"id":"HnBqaGvB","text":"Арест на 7 суток"},{"id":"ApYhWaiD","text":"От 5 000 до 15 000 руб."},{"id":"piRU1lw","text":"От 20 000 до 50 000 руб."}]', '["H90thmaQ"]', '', 2, 21700, '{"meta":{"article":"Статья 5.2","explanation":"Ст. 5.2.","quote":"влечет наложение административного штрафа в размере от десяти тысяч (10.000) до двадцати тысяч (20.000) рублей.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-koap-q048~v2', NULL, 'full', 2, 'koap', 'Статья 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-koap-q048~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в часах) разрешено отстранять работника на основании оперативно-розыскных и иных следственных мероприятий?', '[]', '[]', '', 2, 21710, '{"meta":{"article":"Статья 15, ч. 15.5","explanation":"По основанию п. «б» ч. 15.3 срок отстранения — не более трёх часов.","quote":"На основании пункта \"б\" части 3 настоящей статьи разрешено отстранять работника на срок не более трех часов.","difficulty":"2"},"answer":3,"tolerance":0,"unit":"часа"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q003~v2', NULL, 'full', 2, 'tk', 'Статья 15, ч. 15.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q003~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто из перечисленных в государственных организациях вправе отстранить работника от выполняемой им работы?', '[{"id":"tSFd65AX","text":"Командир роты военной полиции"},{"id":"vazaGXwH","text":"Руководитель оперативно-следственной службы ФСБ на основаниях, предусмотренных ТК"},{"id":"5SQTt9p1","text":"Любой старший по званию военнослужащий"},{"id":"DneYZyP","text":"Потерпевший гражданин"},{"id":"f26Twjk","text":"Начальник кадровой службы по собственному усмотрению и без согласования с руководителем"}]', '["vazaGXwH"]', '', 3, 21720, '{"meta":{"article":"Статья 15, ч. 15.2","explanation":"В госорганизациях отстраняют Губернатор ФО, министры ФО (в отношении возглавляемых органов), руководитель ОСС ФСБ; также прокуратура, СК и суд.","quote":"В государственных организациях отстранить работника от выполняемой им работы могут Губернатор Федерального округа Российской Федерации, министры федеральных округов, в отношении возглавляемых федеральных органов государственной власти, руководитель оперативно-следственной службы Федеральной службы безопасности Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q005', NULL, 'full', 3, 'tk', 'Статья 15, ч. 15.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае допускается отстранение работника по основанию «досудебное разбирательство»?', '[{"id":"hwqntId2","text":"При наличии двух выговоров"},{"id":"ghphAX6j","text":"Только при совершении (подозрении на совершение) преступлений, прямо перечисленных в ТК, либо преступлений против основ конституционного строя и безопасности государства"},{"id":"iTkM2yKp","text":"При любом административном правонарушении"},{"id":"An9UvrP","text":"При любом дисциплинарном проступке, если работник имеет непогашенное взыскание и ранее уже отстранялся от работы по решению своего непосредственного руководителя организации"},{"id":"ugqumH3d","text":"По устному распоряжению непосредственного начальника"}]', '["ghphAX6j"]', '', 3, 21730, '{"meta":{"article":"Статья 15, ч. 15.4","explanation":"Ч. 15.4 ограничивает это основание перечнем статей УК и преступлениями против основ конституционного строя и безопасности государства.","quote":"На основании пункта \"а\" части 3 настоящей статьи разрешено отстранять работника, только в случае совершения (подозрения на совершение) работником преступлений, предусмотренных статьями 38, 39, 41, 42, 64, 77, 78, 79, частью 2 статьи 80, 89, 90 Уголовного Кодекса Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q007', NULL, 'vp', 3, 'tk', 'Статья 15, ч. 15.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях работодатель может привлечь работника к сверхурочной работе без его согласия?', '[{"id":"L8x9d","text":"При нехватке личного состава в мирное время"},{"id":"R9cIUcFz","text":"При производстве работ, необходимость которых обусловлена введением чрезвычайного или военного положения"},{"id":"OzIA76uV","text":"Для выполнения плана подразделения в обычном режиме по приказу начальника, если работник не занят"},{"id":"2Cv5XT7y","text":"При нехватке личного состава в мирное время, если об этом издан письменный приказ руководителя организации"},{"id":"yKCDJQlp","text":"В любой выходной день"},{"id":"WdOXBHvu","text":"При производстве неотложных работ в условиях чрезвычайных обстоятельств (бедствие или угроза бедствия)"}]', '["R9cIUcFz","WdOXBHvu"]', '', 2, 21740, '{"meta":{"article":"Статья 19, ч. 19.2","explanation":"Ч. 19.2 содержит только два случая (пп. «а», «б») и случаи, предусмотренные ТК.","quote":"Привлечение работника по инициативе работодателя к сверхурочной работе допускается без его согласия в следующих случаях: а) при производстве работ, необходимость которых обусловлена введением чрезвычайного или военного положения;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q010~v2', NULL, 'full', 2, 'tk', 'Статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Работник подал заявление на увольнение, но у него есть непогашенное дисциплинарное взыскание. Как вправе поступить работодатель?', '[{"id":"uXpHpIGf","text":"Наложить дисциплинарный арест"},{"id":"mo5JpB6w","text":"Оставить заявление без рассмотрения на неопределённый срок, пока работник не отработает смену"},{"id":"MpXxBPC","text":"Уволить работника по статье за нарушение дисциплины"},{"id":"1SOTK3ge","text":"Отказать в расторжении трудового договора до момента погашения (отработки) взыскания"},{"id":"AijiniwA","text":"Обязан уволить в течение 24 часов без права отказа"}]', '["1SOTK3ge"]', '', 2, 21750, '{"meta":{"article":"Статья 16, ч. 16.3","explanation":"Ч. 16.3: заявление рассматривается в течение 24 часов; при непогашенных взысканиях работодатель вправе отказать до погашения.","quote":"В случае наличия у работника непогашенных дисциплинарных взысканий работодатель вправе отказать в расторжении трудового договора до момента погашения (отработки) дисциплинарного взыскания.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q024', NULL, 'vp', 2, 'tk', 'Статья 16, ч. 16.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для наложения запрета на работу в госорганизациях БЕЗ судебного решения?', '[{"id":"VJoqzdoD","text":"Систематическое (три и более в течение недели) неисполнение законного требования сотрудника прокуратуры"},{"id":"trqpxwqj","text":"Совершение преступления небольшой тяжести"},{"id":"MzonJQY","text":"Кража государственного имущества работником государственной организации"},{"id":"fKesKy5i","text":"Кража денежных средств работником государственной организации"},{"id":"nGvBKa5v","text":"Не отработка семи дней на руководящих должностях / провал работы на руководящих должностях"},{"id":"ciCvVhXN","text":"Получение одного выговора и одного устного замечания за неделю"},{"id":"OIPdZjR","text":"Увольнение по собственному желанию до окончания срока испытания на должности"}]', '["VJoqzdoD","MzonJQY","fKesKy5i","nGvBKa5v"]', '', 2, 21760, '{"meta":{"article":"Статья 16-1, ч. 16-1.8","explanation":"Ч. 16-1.8, пп. «а»–«г».","quote":"а) кража государственного имущества работником государственной организации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q027~v2', NULL, 'full', 2, 'tk', 'Статья 16-1, ч. 16-1.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q027~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На какой максимальный срок (в днях) Губернатор ФО может без судебного решения внести гражданина в реестр уволенных по отрицательным мотивам по основаниям, которые ТК допускает для запрета на работу без суда?', '[]', '[]', '', 3, 21770, '{"meta":{"article":"Статья 16-1, ч. 16-1.8","explanation":"Губернатор — не более 5 дней, Генеральный прокурор — не более 7 дней.","quote":"принимает Губернатор Федерального округа Российской Федерации на срок не более пяти (5) дней или Генеральный прокурор Российской Федерации на срок не более семи (7) дней.","difficulty":"3"},"answer":5,"tolerance":0,"unit":"дней"}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q028~v2', NULL, 'full', 3, 'tk', 'Статья 16-1, ч. 16-1.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q028~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто принимает решение о внесении в реестр по основанию «систематическое неисполнение законного требования сотрудника прокуратуры»?', '[{"id":"Y038GtgU","text":"Губернатор ФО на срок не более 5 дней"},{"id":"qzpKo6Ym","text":"Суд на срок от 6 до 12 дней"},{"id":"VCywdDA","text":"Прокурор субъекта по представлению руководителя на срок до 24 дней"},{"id":"UnOrSGIR","text":"Командир воинской части"},{"id":"6M4TPPrB","text":"Исключительно Генеральный прокурор РФ, на срок не более 7 дней"}]', '["6M4TPPrB"]', '', 3, 21780, '{"meta":{"article":"Статья 16-1, ч. 16-1.8","explanation":"Последний абзац ч. 16-1.8.","quote":"Решение о внесении граждан в реестр лиц уволенных по отрицательным мотивам на основании п. г части восемь настоящей статьи принимает исключительно Генеральный прокурор Российской Федерации на срок не более семи (7) дней.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q029', NULL, 'full', 3, 'tk', 'Статья 16-1, ч. 16-1.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Считается ли принудительным трудом выполнение приказа начальника, отданного в установленном законом порядке, на государственной службе?', '[{"id":"zsUohxZz","text":"Нет, такие приказы не могут быть расценены как принудительный труд"},{"id":"pS14zFc","text":"Да, если приказ отдан в выходной день или в ночное время суток"},{"id":"05yCz6EA","text":"Да, всегда, кроме военного положения"},{"id":"E8s2xLyI","text":"Да, если работник не согласен с приказом"}]', '["zsUohxZz"]', '', 2, 21790, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"П. «а» ч. 4.3.","quote":"Приказы начальства и иных уполномоченных лиц, отданных в установленном законом порядке, не могут быть расценены как принудительный труд.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q031', NULL, 'full', 2, 'tk', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для получения какого порядкового звания (если аттестация предусмотрена уставом) аттестация в госорганизациях является обязательным условием?', '[{"id":"7EvYxVl","text":"Первого порядкового звания"},{"id":"g5HqUUBN","text":"Каждого следующего звания после окончания испытательного срока"},{"id":"VKUDCmXi","text":"Пятого порядкового звания"},{"id":"NOkslYo7","text":"Третьего порядкового звания и (или) третьей по счёту должности"}]', '["NOkslYo7"]', '', 3, 21800, '{"meta":{"article":"Статья 14, ч. 14.5","explanation":"Ч. 14.5; аттестация как требование к дальнейшему повышению не допускается, кроме руководящего/старшего состава.","quote":"В государственных организациях аттестация является обязательным условием для получения третьего порядкового звания и(или) замещаемой должности, третьей по счету, начиная с наименьшей в случае, если аттестация предусмотрена уставом организации.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q033', NULL, 'vp', 3, 'tk', 'Статья 14, ч. 14.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как применяются нормы локального нормативного акта, ухудшающие положение работников по сравнению с трудовым законодательством?', '[{"id":"ZDPQwD5","text":"Не подлежат применению; применяется трудовое законодательство"},{"id":"oNbQIN6","text":"Применяются только к новым работникам"},{"id":"TmR2tz1J","text":"Применяются, если акт утверждён руководителем и согласован с работниками"},{"id":"dB1zCzOf","text":"Применяются до отмены их судом"}]', '["ZDPQwD5"]', '', 2, 21810, '{"meta":{"article":"Статья 6, ч. 6.4","explanation":"Ч. 6.4.","quote":"Нормы локальных нормативных актов, ухудшающие положение работников по сравнению с установленным трудовым законодательством и иными нормативными правовыми актами, содержащими нормы трудового права, коллективным договором, соглашениями не подлежат применению.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-tk-q038', NULL, 'full', 2, 'tk', 'Статья 6, ч. 6.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q038');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Работники каких государственных организаций (по ТК) могут иметь непогашенную судимость по статьям ПК?', '[{"id":"XMULaNwJ","text":"Органов внутренних дел и прокуратуры"},{"id":"TqR8eq4h","text":"Органов прокуратуры"},{"id":"LjKH3jWS","text":"Вооружённых Сил РФ"},{"id":"qLHMofT","text":"Государственных организаций здравоохранения"}]', '["qLHMofT"]', '', 2, 21820, '{"meta":{"article":"Статья 16, ч. 16.7","explanation":"Ч. 16.7: исключение — здравоохранение, государственные СМИ, казённые учреждения.","quote":"Работники: государственных организаций здравоохранения, государственных средств массовой информации, государственных казенных учреждений могут иметь непогашенную судимость.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-tk-q039', NULL, 'vp', 2, 'tk', 'Статья 16, ч. 16.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-tk-q039');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что понимается под обороной в Федеральном законе «Об обороне»?', '[{"id":"DTI81cVr","text":"Деятельность военной полиции по задержанию правонарушителей"},{"id":"PY2OppcR","text":"Совокупность мер по охране общественного порядка в городах и сельской местности, осуществляемых полицией, военной полицией и Росгвардией в мирное и военное время на территории РФ"},{"id":"8j4AqL5O","text":"Система политических, экономических, военных, социальных, правовых и иных мер по подготовке к вооружённой защите и вооружённая защита РФ, целостности и неприкосновенности её территории"},{"id":"ob1KUUd","text":"Исключительно деятельность Вооружённых Сил в военное время"}]', '["8j4AqL5O"]', '', 1, 21830, '{"meta":{"article":"Статья 1, ч. 1.1","explanation":"Ч. 1.1.","quote":"под обороной понимается система политических, экономических, военных, социальных, правовых и иных мер по подготовке к вооруженной защите и вооруженная защита Российской Федерации, целостности и неприкосновенности ее территории.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q001', NULL, 'full', 1, 'fz_oborona', 'Статья 1, ч. 1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как закон относится к формированиям, имеющим военную организацию или вооружение, не предусмотренным федеральными законами?', '[{"id":"xPDpw5qm","text":"Допускаются с разрешения командира бригады"},{"id":"jt0hMpMe","text":"Допускаются при регистрации в Министерстве обороны и согласовании с Губернатором"},{"id":"3Aim82C","text":"Разрешены, если не носят военную форму"},{"id":"K5j4pl2","text":"Их создание и существование запрещаются и преследуются по закону"}]', '["K5j4pl2"]', '', 2, 21840, '{"meta":{"article":"Статья 1, ч. 1.4","explanation":"Ч. 1.4.","quote":"Создание и существование формирований, имеющих военную организацию или вооружение и военную технику либо в которых предусматривается прохождение военной службы, не предусмотренных федеральными законами, запрещаются и преследуются по закону.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q002', NULL, 'vp', 2, 'fz_oborona', 'Статья 1, ч. 1.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где, согласно закону «Об обороне», ВС РФ организуют патрульно-постовую службу и блокпосты?', '[{"id":"lftCHA62","text":"На подведомственной территории ВС — на дорогах, идущих из городской части в областную"},{"id":"V2QdsCK","text":"На всех дорогах города и области в мирное время по решению командира бригады ВС"},{"id":"2bLjGW9z","text":"Исключительно на государственной границе"},{"id":"pzdF2oAH","text":"Только внутри военных городков"}]', '["lftCHA62"]', '', 3, 21850, '{"meta":{"article":"Статья 6, ч. 6.1 п. 5","explanation":"П. 5 ч. 6.1 — цель: безопасность гражданского населения и военнослужащих в области.","quote":"организация на подведомственной территории вооруженных сил Российской Федерации патрульно-постовой службы и блокпостов на дорогах идущих из городской части в областную с целью обеспечения безопасности гражданского населения и военнослужащих в области.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q008', NULL, 'vp', 3, 'fz_oborona', 'Статья 6, ч. 6.1 п. 5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На каком основании ВС РФ могут привлекаться к выполнению задач с использованием вооружения не по их предназначению?', '[{"id":"9QSI8ge","text":"По приказу командира бригады"},{"id":"7D08qV01","text":"По запросу начальника отдела полиции"},{"id":"Lpk5bSCp","text":"На основании решения Губернатора Федерального округа РФ"},{"id":"7DVkrzo","text":"По решению Министра обороны без согласования с органами власти"}]', '["Lpk5bSCp"]', '', 2, 21860, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"Ч. 7.1.","quote":"Вооруженные Силы Российской Федерации могут привлекаться к выполнению задач с использованием вооружения не по их предназначению на основании решения Губернатора Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q009', NULL, 'medium', 2, 'fz_oborona', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан предоставить обратившемуся сотрудник, исполняющий обязанности с засекречиванием своей личности?', '[{"id":"MN1ozuaw","text":"Предоставить жетон и назвать позывной и номер жетона"},{"id":"W1hxVGD9","text":"Ничего, так как его личность засекречена"},{"id":"Cs8stoUw","text":"Назвать только должность"},{"id":"lOCoUqqp","text":"Назвать фамилию и звание, предъявить удостоверение"}]', '["MN1ozuaw"]', '', 2, 21870, '{"meta":{"article":"Статья 9, ч. 9.2","explanation":"Ч. 9.2; образцы жетонов устанавливает Правительство ФО.","quote":"Сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности обязаны предоставить жетон и назвать позывной и номер жетона обратившемуся.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q012', NULL, 'full', 2, 'fz_oborona', 'Статья 9, ч. 9.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как осуществляется комплектование ВС РФ согласно закону «Об обороне»?', '[{"id":"lObg0Fiu","text":"Путём добровольного поступления граждан на военную службу по контракту"},{"id":"9vatlwoO","text":"Путём перевода сотрудников полиции и Росгвардии без их согласия по приказу Губернатора"},{"id":"Bxtlxj","text":"Только по призыву"},{"id":"gWOZFT88","text":"По жребию среди граждан"}]', '["lObg0Fiu"]', '', 1, 21880, '{"meta":{"article":"Статья 10, ч. 10.2","explanation":"Ч. 10.2.","quote":"Комплектование Вооруженных Сил Российской Федерации осуществляется в соответствии с законодательством Российской Федерации военнослужащими путем добровольного поступления граждан на военную службу по контракту.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q013', NULL, 'medium', 1, 'fz_oborona', 'Статья 10, ч. 10.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Обыск каких транспортных средств вправе производить ВС РФ?', '[{"id":"5Eb2M9ek","text":"Любых транспортных средств в городе"},{"id":"zSDxBX85","text":"Только транспорта иностранных граждан"},{"id":"UMZnR0Vu","text":"Транспортных средств, припаркованных у жилых домов военнослужащих и у зданий органов власти города"},{"id":"qYCsvlKG","text":"Транспортных средств, нарушивших правила, установленные на охраняемых вооружёнными силами объектах"}]', '["qYCsvlKG"]', '', 2, 21890, '{"meta":{"article":"Статья 12, ч. 12.1 п. 5","explanation":"П. 5 ч. 12.1.","quote":"5) производить обыск транспортных средств, нарушивших правила, установленные на охраняемых вооруженными силами объектах;","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q018', NULL, 'full', 2, 'fz_oborona', 'Статья 12, ч. 12.1 п. 5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где ВС РФ вправе производить личный обыск граждан?', '[{"id":"9gVCxZe6","text":"В пунктах пропуска на охраняемых важных государственных объектах в соответствии с законодательством о закрытых территориях"},{"id":"IEjSFx0Z","text":"На улицах города при патрулировании"},{"id":"SLL5bkfV","text":"В любом общественном месте при подозрении на хранение оружия или запрещённых веществ, а также в транспорте граждан"},{"id":"IkdZq5Z9","text":"Только в помещениях полиции"}]', '["9gVCxZe6"]', '', 2, 21900, '{"meta":{"article":"Статья 12, ч. 12.1 п. 6","explanation":"П. 6 ч. 12.1.","quote":"6) производить личный обыск граждан в пунктах пропуска на охраняемых важных государственных объектах в соответствии с законодательством о закрытых территориях;","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q019', NULL, 'vp', 2, 'fz_oborona', 'Статья 12, ч. 12.1 п. 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии ВС РФ вправе патрулировать городские и сельские местности с использованием тяжёлой бронированной техники?', '[{"id":"8GJo19GU","text":"При введении режима чрезвычайного и военного положения"},{"id":"TN7KnLaS","text":"При проведении учений в мирное время по плану Министерства обороны"},{"id":"CndxLWQd","text":"При задержании любого нарушителя ПДД"},{"id":"FNWLdspN","text":"В любое время по приказу командира роты"}]', '["8GJo19GU"]', '', 2, 21910, '{"meta":{"article":"Статья 12, ч. 12.1 п. 10","explanation":"П. 10 ч. 12.1.","quote":"10) патрулировать в городских и сельских местностях, с использованием тяжелой и (или) тяжелой бронированной техники при введении режима чрезвычайного и военного положения;","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q020', NULL, 'medium', 2, 'fz_oborona', 'Статья 12, ч. 12.1 п. 10', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где в мирное время ВС РФ вправе производить задержания граждан в предусмотренных законодательством случаях?', '[{"id":"SBRxBVO","text":"На подведомственной территории воинской части, с дальнейшей передачей задержанных правоохранительным органам"},{"id":"kNaGCuYq","text":"Только за пределами воинской части"},{"id":"m5gjfRA6","text":"Нигде — задержания в мирное время запрещены"},{"id":"u0IBC4rQ","text":"В любом месте Федерального округа с правом содержания задержанных в воинской части до вынесения решения судом"}]', '["SBRxBVO"]', '', 3, 21920, '{"meta":{"article":"Статья 12, ч. 12.1 п. 11","explanation":"П. 11 ч. 12.1.","quote":"11) производить задержания граждан в случаях, предусмотренных действующим законодательством на подведомственной территории воинской части Вооруженных Сил в период мирного времени с дальнейшей передачей задержанных правоохранительным органам.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q021', NULL, 'medium', 3, 'fz_oborona', 'Статья 12, ч. 12.1 п. 11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое право есть у ВС РФ в отношении места совершения предполагаемого преступления?', '[{"id":"aOmeJrtp","text":"Никаких — это компетенция только полиции"},{"id":"AZgfBTq","text":"Самостоятельно проводить следствие, возбуждать уголовное дело и опрашивать очевидцев"},{"id":"YPaxwBfy","text":"Уничтожать следы во избежание паники"},{"id":"fs17FvOR","text":"Принимать необходимые меры по охране места до прибытия правоохранительных органов"}]', '["fs17FvOR"]', '', 1, 21930, '{"meta":{"article":"Статья 12, ч. 12.1 п. 3","explanation":"П. 3 ч. 12.1.","quote":"3) принимать необходимые меры по охране места совершения предполагаемого преступления до прибытия правоохранительными органами;","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q022', NULL, 'full', 1, 'fz_oborona', 'Статья 12, ч. 12.1 п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'С какой целью ВС РФ вправе беспрепятственно входить в любое время суток на территории и в помещения охраняемых объектов и осматривать их?', '[{"id":"8q0ohsJp","text":"В целях изъятия личного имущества граждан"},{"id":"PqsIlX8Z","text":"Только для проверки пожарной безопасности"},{"id":"hYHt4Nu","text":"Для проведения оперативно-розыскных мероприятий против гражданских лиц, а также для изъятия у них имущества, документов и предметов, запрещённых к обороту"},{"id":"Cy5tbeJ","text":"В целях задержания лиц, незаконно проникших либо пытавшихся проникнуть на охраняемые объекты, с последующей передачей правоохранительным органам"}]', '["Cy5tbeJ"]', '', 2, 21940, '{"meta":{"article":"Статья 12, ч. 12.1 п. 7","explanation":"П. 7 ч. 12.1.","quote":"осматривать их в целях задержания лиц, незаконно проникших либо пытавшихся проникнуть на охраняемые объекты, с последующей передачей правоохранительным органам;","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q023', NULL, 'full', 2, 'fz_oborona', 'Статья 12, ч. 12.1 п. 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На основании чьих актов осуществляется приведение ВС РФ в высшие степени боевой готовности?', '[{"id":"PVi9YISO","text":"Председателя Правительства РФ, Министерства обороны РФ"},{"id":"TwvA3OMP","text":"Военного комиссариата"},{"id":"A5ryk5Rh","text":"Генерального прокурора РФ и Губернатора Федерального округа"},{"id":"GpBjJmlU","text":"Командира бригады"}]', '["PVi9YISO"]', '', 3, 21950, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2.","quote":"Приведение Вооруженных Сил Российской Федерации в высшие степени боевой готовности осуществляется на основании актов Председателя Правительства Российской Федерации, Министерства обороны Российской Федерации.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q024', NULL, 'vp', 3, 'fz_oborona', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q024');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто устанавливает порядок прохождения курса военной подготовки для выдачи военного билета?', '[{"id":"7wWLihoM","text":"Прокуратура РФ"},{"id":"Xj854yTt","text":"Губернатор Федерального округа единолично по представлению военкомата"},{"id":"eZ1LXeqg","text":"Военный комиссариат самостоятельно"},{"id":"h1X9NhAv","text":"Командир войсковой части с утверждением Министра обороны РФ"}]', '["h1X9NhAv"]', '', 2, 21960, '{"meta":{"article":"Статья 13, ч. 13.4–13.5","explanation":"Ч. 13.5.","quote":"Порядок прохождения курса военной подготовки для выдачи документа о прохождении военной службы (также — военного билета) устанавливается командиром войсковой части с утверждением Министра обороны Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q025', NULL, 'full', 2, 'fz_oborona', 'Статья 13, ч. 13.4–13.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе заключить с Министерством обороны договор об ускоренной военной подготовке?', '[{"id":"EbfYTd9U","text":"Только лица, уволенные с военной службы в запас, имеющие военный билет и не служившие в правоохранительных структурах более одного календарного года"},{"id":"yb9Jcx3","text":"Гражданин РФ, находящийся на службе в правоохранительных (силовых) структурах, годный к военной службе и отвечающий требованиям к поступающим по контракту"},{"id":"2wkhAsVa","text":"Любой гражданин старше 16 лет"},{"id":"u0omVwm7","text":"Только иностранные граждане"}]', '["yb9Jcx3"]', '', 2, 21970, '{"meta":{"article":"Статья 14","explanation":"Ст. 14.","quote":"Гражданин Российской Федерации, находящийся на службе в правоохранительных (силовых) структурах и годный к военной службе по состоянию здоровья","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oborona-q026', NULL, 'vp', 2, 'fz_oborona', 'Статья 14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда военнослужащие ВС РФ имеют право на хранение, применение и использование оружия, специальных средств и физической силы?', '[{"id":"lCw94q8i","text":"Только на территории воинской части и на охраняемых ею объектах в часы несения службы"},{"id":"MaKho8Bz","text":"Только при введении военного положения"},{"id":"jsGaEAdq","text":"Только во время боевых действий"},{"id":"gyXqMYOf","text":"При исполнении обязанностей военной службы, а при необходимости и во внеслужебное время"}]', '["gyXqMYOf"]', '', 2, 21980, '{"meta":{"article":"Статья 17","explanation":"Ст. 17; порядок применения устанавливается законодательством РФ.","quote":"Военнослужащие Вооруженных Сил Российской Федерации при исполнении обязанностей военной службы, а при необходимости и во внеслужебное время, имеют право на хранение, применение и использование оружия и специальных средств","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oborona-q031', NULL, 'medium', 2, 'fz_oborona', 'Статья 17', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Допускается ли блокирование военных городков и мест постоянной дислокации войск?', '[{"id":"ciFxCHS","text":"Не допускается — это препятствование ВС РФ в выполнении задач в области обороны"},{"id":"72gmsD3","text":"Допускается, если не применяется оружие"},{"id":"djRHpK8E","text":"Допускается в форме мирного собрания"},{"id":"Vwz16MY","text":"Допускается с уведомлением командира части, если не создаёт помех выезду техники"}]', '["ciFxCHS"]', '', 2, 21990, '{"meta":{"article":"Статья 20, ч. 20.1","explanation":"Ч. 20.1, ответственность — ч. 20.2.","quote":"в том числе путем блокирования военных городков, районов (позиций) несения боевого дежурства, районов сосредоточения войск, постоянного места дислокации войск, объектов военной инфраструктуры не допускается.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oborona-q034', NULL, 'full', 2, 'fz_oborona', 'Статья 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oborona-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что регулирует Федеральный закон «Об оружии» № 34-ФЗ?', '[{"id":"MLpkgEan","text":"Производство, продажу, передачу, владение, хранение и использование стрелкового оружия на территории РФ"},{"id":"0MIUoBnr","text":"Оборот всех видов вооружения, включая бронетехнику, авиацию и боеприпасы к ним, на всей территории РФ"},{"id":"bi1GzQFU","text":"Только порядок выдачи лицензий на гражданское оружие"},{"id":"sP7r7CHp","text":"Только применение оружия сотрудниками полиции"}]', '["MLpkgEan"]', '', 1, 22000, '{"meta":{"article":"Статья 1","explanation":"Ст. 1.","quote":"Настоящий закон регулирует производство, продажу, передачу, владение, хранение и использование стрелкового оружия на территории Российской Федерации.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q001', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как 34-ФЗ определяет понятие «оружие»?', '[{"id":"7iq2H3Vf","text":"Только огнестрельные устройства, использующие энергию порохового заряда для механического поражения цели"},{"id":"tkpHz1gw","text":"Устройства и предметы, конструктивно предназначенные для поражения живой или иной цели, подачи сигналов"},{"id":"B1Vk2KLu","text":"Устройства, внесённые в государственный реестр оружия"},{"id":"EbIcBOrd","text":"Любые предметы, которыми можно причинить вред здоровью"}]', '["tkpHz1gw"]', '', 1, 22010, '{"meta":{"article":"Статья 2, ч. 2.1, п. 1","explanation":"П. 1 ч. 2.1.","quote":"1) оружие — устройства и предметы, конструктивно предназначенные для поражения живой или иной цели, подачи сигналов;","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q002', NULL, 'full', 1, 'fz_oruzhie', 'Статья 2, ч. 2.1, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте термин закона «Об оружии» с его определением.', '[]', '[]', '', 2, 22020, '{"meta":{"article":"Статья 2, ч. 2.1, пп. 2, 3, 7, 9","explanation":"Пп. 2, 3, 7, 9 ч. 2.1.","quote":"3) холодное оружие — оружие, предназначенное для поражения цели при помощи мускульной силы человека при непосредственном контакте с объектом поражения.","difficulty":"2"},"pairs":[{"l":{"id":"OanzOe2n","text":"Огнестрельное оружие"},"r":{"id":"aMpfnrR","text":"Механическое поражение цели на расстоянии метаемым снаряжением за счёт энергии порохового или иного заряда"}},{"l":{"id":"IV70VxaR","text":"Холодное оружие"},"r":{"id":"Iw9Zz0j4","text":"Поражение цели при помощи мускульной силы человека при непосредственном контакте"}},{"l":{"id":"49dNOP1","text":"Предметы, используемые в качестве оружия"},"r":{"id":"HxzUJHs2","text":"Вещи, предметы, использовавшиеся в качестве орудия преступления или правонарушения"}},{"l":{"id":"Q8GvnOwj","text":"Патрон"},"r":{"id":"Yq53LP7s","text":"Устройство для выстрела, объединяющее гильзой средства инициирования, метательный заряд и метаемое снаряжение"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q003~v2', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 2, ч. 2.1, пп. 2, 3, 7, 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q003~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой федеральный орган исполнительной власти является уполномоченным в сфере оборота оружия по закону «Об оружии»?', '[{"id":"6NNzXCQ9","text":"Орган, осуществляющий функции в сфере деятельности войск национальной гвардии РФ, в сфере оборота оружия"},{"id":"RoABffMK","text":"Федеральная служба безопасности"},{"id":"IUjiPSfZ","text":"Министерство внутренних дел (полиция), осуществляющее лицензионно-разрешительную работу в сфере оружия"},{"id":"70HAVAoa","text":"Министерство обороны РФ"}]', '["6NNzXCQ9"]', '', 2, 22030, '{"meta":{"article":"Статья 2, ч. 2.1, п. 6","explanation":"П. 6 ч. 2.1 связывает уполномоченный орган со сферой деятельности войск национальной гвардии.","quote":"в сфере деятельности войск национальной гвардии Российской Федерации, в сфере оборота оружия;","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q005', NULL, 'full', 2, 'fz_oruzhie', 'Статья 2, ч. 2.1, п. 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Изделие сертифицировано как хозяйственно-бытовое и конструктивно сходно с огнестрельным оружием. При каком условии оно не относится к оружию?', '[{"id":"TDeeG0fI","text":"Если не содержит в своём составе основных частей огнестрельного оружия"},{"id":"PaV3sAle","text":"Если оно зарегистрировано в реестре лицензий как бытовое изделие"},{"id":"vBWxVDHf","text":"Если оно окрашено в яркий цвет"},{"id":"TR7MHZ1D","text":"Если его масса не превышает 1 кг"}]', '["TDeeG0fI"]', '', 3, 22040, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Ч. 2.2.","quote":"Конструктивно сходные с огнестрельным оружием изделия не должны содержать в своём составе основные части огнестрельного оружия.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q006', NULL, 'full', 3, 'fz_oruzhie', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Преступление совершено с использованием изделия, которое закон «Об оружии» не относит к оружию. Как его могут квалифицировать правоохранительные органы?', '[{"id":"1x6VQZYh","text":"Как преступление или правонарушение, совершённое с использованием оружия"},{"id":"aPbZ4vy","text":"Только как преступление без использования оружия"},{"id":"SsB1NIyT","text":"Только как административное правонарушение по КоАП без учёта изделия"},{"id":"E8yvPyzm","text":"Как деяние, не подлежащее ответственности"}]', '["1x6VQZYh"]', '', 3, 22050, '{"meta":{"article":"Статья 2, ч. 2.3","explanation":"Ч. 2.3.","quote":"2.3. Преступления, совершённые с использованием предметов, не являющихся оружием, согласно части второй настоящей статьи, могут квалифицироваться правоохранительными органами как преступления или правонарушения, совершённые с использованием оружия.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q007', NULL, 'vp', 3, 'fz_oruzhie', 'Статья 2, ч. 2.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'На какие виды подразделяется оружие по цели применения?', '[{"id":"PfuFKcQa","text":"Самозарядное"},{"id":"ZUzaMAkj","text":"Гражданское"},{"id":"PLVkJNv","text":"Спортивное"},{"id":"eWS61q7","text":"Коллекционное (или используемое в культурных целях)"},{"id":"gN7kQblN","text":"Служебное"},{"id":"ruWyOUlB","text":"Огнестрельное"},{"id":"xcp0IhBS","text":"Боевое ручное стрелковое"}]', '["ZUzaMAkj","eWS61q7","gN7kQblN","xcp0IhBS"]', '', 2, 22060, '{"meta":{"article":"Статья 3, п. 1","explanation":"П. 1 ст. 3; «огнестрельное» — это критерий функционального назначения, «самозарядное» — принципа действия.","quote":"1) По цели применения: гражданское, служебное, боевое ручное стрелковое, коллекционное (или используемое в культурных целях).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q008~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 3, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q008~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте критерий классификации оружия по закону «Об оружии» с примером вида.', '[]', '[]', '', 3, 22070, '{"meta":{"article":"Статья 3","explanation":"Пп. 1–4 ст. 3.","quote":"4) По принципу действия ударно-спускового механизма: автоматическое (многозарядное), самозарядное, самострельное, неавтоматическое (однозарядное).","difficulty":"3"},"pairs":[{"l":{"id":"szPAtTaw","text":"По функциональному назначению"},"r":{"id":"RmSE0YxS","text":"Огнестрельное, холодное"}},{"l":{"id":"8Haq4uzN","text":"По конструкции"},"r":{"id":"cWED30GN","text":"Пистолеты-пулемёты, высокоточные винтовки"}},{"l":{"id":"KwYjkPfu","text":"По принципу действия ударно-спускового механизма"},"r":{"id":"h88bkiHi","text":"Самозарядное, самострельное"}},{"l":{"id":"2Z52cosi","text":"По цели применения"},"r":{"id":"4aTAZ6Fi","text":"Служебное, боевое ручное стрелковое"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q009~v2', NULL, 'full', 3, 'fz_oruzhie', 'Статья 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q009~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое ограничение закон «Об оружии» устанавливает для гражданского огнестрельного оружия?', '[{"id":"UnO3Q9v8","text":"Его ёмкость магазина — не более 5 патронов"},{"id":"FvrtxNP2","text":"Оно должно храниться только в оружейном сейфе"},{"id":"NHrF6","text":"Оно должно быть только гладкоствольным"},{"id":"426Z7Btl","text":"Оно должно исключать ведение огня очередями"}]', '["426Z7Btl"]', '', 1, 22080, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1.","quote":"Гражданское огнестрельное оружие должно исключать ведение огня очередями.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q010~v2', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к оружию самообороны?', '[{"id":"62iGiBJd","text":"Копии старинного (антикварного) оружия"},{"id":"JMmiACv","text":"Холодное клинковое"},{"id":"VII6awa","text":"Списанное оружие"},{"id":"BsiWiciM","text":"Автоматы (в том числе укороченные)"},{"id":"tNiZuAy","text":"Гладкоствольное длинноствольное оружие (ружьё)"},{"id":"WH9dce2T","text":"Холодное оружие дробящего действия"}]', '["JMmiACv","tNiZuAy","WH9dce2T"]', '', 2, 22090, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"Ч. 4.3 также включает огнестрельное оружие ограниченного поражения; списанное оружие и копии — культурные/образовательные цели (ч. 4.4).","quote":"2) холодное клинковое; 3) гладкоствольное длинноствольное оружие (ружьё); 4) холодное оружие дробящего действия.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q011~v2', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q011~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к оружию, используемому в культурных и образовательных целях?', '[{"id":"p5ltbXbH","text":"Пистолеты-пулемёты"},{"id":"S7PM0YU","text":"Оружие, имеющее культурную ценность"},{"id":"ad5aECVD","text":"Списанное оружие"},{"id":"xVrNNBK","text":"Огнестрельное оружие ограниченного поражения"},{"id":"dyJ4qQa6","text":"Холодное оружие дробящего действия"},{"id":"GefZXAM6","text":"Копии старинного (антикварного) оружия"}]', '["S7PM0YU","ad5aECVD","GefZXAM6"]', '', 1, 22100, '{"meta":{"article":"Статья 4, ч. 4.4","explanation":"Ч. 4.4.","quote":"1) оружие, имеющее культурную ценность; 2) копии старинного (антикварного) оружия; 3) списанное оружие.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q012~v2', NULL, 'full', 1, 'fz_oruzhie', 'Статья 4, ч. 4.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для чего предназначено служебное оружие по закону «Об оружии»?', '[{"id":"nHJVgVq8","text":"Для использования должностными лицами госорганов при исполнении полномочий — для самообороны или исполнения обязанностей по защите жизни и здоровья граждан"},{"id":"2WeuBWDl","text":"Только для ведения боевых действий"},{"id":"MAMwtPKx","text":"Для использования гражданами в целях самообороны, спорта и охоты, а также в культурных, образовательных, учебных и иных законных целях на территории РФ"},{"id":"aySJe81d","text":"Для использования сотрудниками ЧОП на охраняемых объектах"}]', '["nHJVgVq8"]', '', 2, 22110, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1.","quote":"в целях самообороны или для исполнения возложенных на них законом обязанностей по защите жизни и здоровья граждан.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q013', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кому закон «Об оружии» предоставляет право на ношение, хранение и применение огнестрельного оружия при исполнении служебных обязанностей? Выберите все верные.', '[{"id":"Nr70fhri","text":"Служащим войск национальной гвардии"},{"id":"eo8stKER","text":"Сотрудникам органов Следственного комитета РФ"},{"id":"mfaUK2T","text":"Сотрудникам средств массовой информации"},{"id":"v1opxpHo","text":"Сотрудникам частных охранных предприятий"},{"id":"UEOnguY","text":"Служащим Вооружённых сил РФ"},{"id":"BYF9y7Br","text":"Сотрудникам государственных бюджетных учреждений здравоохранения"}]', '["Nr70fhri","eo8stKER","UEOnguY"]', '', 2, 22120, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Перечень ч. 5.3: полиция, ФСИН, Росгвардия, ФСБ, ФСО, ВС РФ, прокуратура, СК, сотрудники Правительства (определённые актами).","quote":"Вооружённых сил Российской Федерации, органов прокуратуры Российской Федерации, органов Следственного комитета Российской Федерации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q014~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q014~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях военнослужащий ВС РФ обязан сдать служебное оружие, бронежилет и иные полученные предметы?', '[{"id":"Hbg8tfo","text":"При выезде за пределы части по служебному заданию"},{"id":"VyvCyue0","text":"При заступлении в наряд"},{"id":"m6Da3LSN","text":"При переводе в другое подразделение той же части"},{"id":"9gBRotTM","text":"При уходе в увольнительную"},{"id":"dORNBObq","text":"При уходе в отгул или отпуск"},{"id":"0vtgPfQ5","text":"При окончании рабочей смены"}]', '["9gBRotTM","dORNBObq","0vtgPfQ5"]', '', 2, 22130, '{"meta":{"article":"Статья 5, ч. 5.4","explanation":"Ч. 5.4: окончание смены, увольнительная, отгул, отпуск, иные причины окончания служебных полномочий.","quote":"при окончании рабочей смены, при уходе в увольнительную, отгул, отпуск, а также по иным причинам окончания служебных полномочий сотрудника (служащего).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q015~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 5, ч. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q015~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудники каких органов вправе не сдавать служебное оружие в рамках проведения оперативных мероприятий?', '[{"id":"U8iwFQCC","text":"ФСБ и Следственного комитета РФ"},{"id":"5KaVJVCO","text":"ВС РФ и войск национальной гвардии"},{"id":"EChfh5q","text":"ФСО и прокуратуры"},{"id":"9IP8PhIz","text":"Полиции и ФСИН"}]', '["U8iwFQCC"]', '', 3, 22140, '{"meta":{"article":"Статья 5, ч. 5.4","explanation":"Последнее предложение ч. 5.4.","quote":"Сотрудники органов Федеральной службы безопасности, органов Следственного комитета Российской Федерации вправе не сдавать служебное оружие в рамках проведения оперативных мероприятий.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q016', NULL, 'medium', 3, 'fz_oruzhie', 'Статья 5, ч. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что запрещено законом «Об оружии»? Выберите все верные.', '[{"id":"Lq0ii0H2","text":"Хранение лёгкого бронежилета 2-го класса"},{"id":"NqubQHkx","text":"Хранение материалов для создания оружия в количестве до 100 единиц без лицензии"},{"id":"0AbIP5HI","text":"Ношение гражданами оружия при проведении митингов, шествий, демонстраций"},{"id":"rO2Ycx7J","text":"Ношение огнестрельного или холодного клинкового оружия в состоянии опьянения"},{"id":"Gr4OGs94","text":"Хранение патронов без лицензии"}]', '["0AbIP5HI","rO2Ycx7J"]', '', 3, 22150, '{"meta":{"article":"Статья 6, ч. 6.1, п. 2","explanation":"Хранение патронов без лицензии, лёгкий бронежилет и материалы до 100 ед. прямо разрешены (ч. 6.3, 6.4, ст. 7).","quote":"2) ношение гражданами оружия при проведении митингов, уличных шествий, демонстраций и других массовых публичных мероприятий, ношение огнестрельного или холодного клинкового оружия в состоянии опьянения;","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q017~v2', NULL, 'medium', 3, 'fz_oruzhie', 'Статья 6, ч. 6.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q017~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин с лицензией идёт по улице с пистолетом. Как это оценивается по закону «Об оружии»?', '[{"id":"Eko6X8mz","text":"Запрещено: ношение огнестрельного оружия гражданами в общественных местах не допускается"},{"id":"PCHnN4T5","text":"Разрешено при наличии действующей лицензии на хранение и ношение этого оружия"},{"id":"kkwB0CGG","text":"Разрешено, если оружие входит в перечень разрешённого гражданам"},{"id":"LvYbUhl6","text":"Разрешено только в дневное время и вне массовых мероприятий"}]', '["Eko6X8mz"]', '', 2, 22160, '{"meta":{"article":"Статья 6, ч. 6.1, п. 3","explanation":"П. 3 ч. 6.1.","quote":"3) ношение огнестрельного оружия гражданами в общественных местах, за исключением ношения огнестрельного оружия лицами, определёнными частью третьей статьи 5 настоящего Федерального закона при исполнении должностных обязанностей;","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q018', NULL, 'medium', 2, 'fz_oruzhie', 'Статья 6, ч. 6.1, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кому запрещено продавать или передавать патроны к гражданскому оружию?', '[{"id":"N5G07FcW","text":"Лицам без медицинской книжки"},{"id":"SDDncTm","text":"Военнослужащим срочной службы, курсантам военных училищ и кадетам"},{"id":"8xvKEyYn","text":"Лицам, не владеющим на законном основании таким гражданским оружием"},{"id":"WZXwBHXI","text":"Лицам младше 21 года"}]', '["8xvKEyYn"]', '', 2, 22170, '{"meta":{"article":"Статья 6, ч. 6.1, п. 4","explanation":"П. 4 ч. 6.1.","quote":"4) продажа или передача патронов к гражданскому оружию лицам, не владеющим на законном основании таким гражданским оружием.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q019', NULL, 'full', 2, 'fz_oruzhie', 'Статья 6, ч. 6.1, п. 4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Патроны с пулями какого действия запрещены к обороту в качестве гражданского и служебного оружия?', '[{"id":"N1zNhP9r","text":"Зажигательного"},{"id":"6GLaJyT","text":"Разрывного"},{"id":"XrZjxDOd","text":"Трассирующего"},{"id":"rYzJDXfS","text":"Экспансивного"},{"id":"gwAIBIAS","text":"Холостого"},{"id":"8LK5yfrt","text":"Бронебойного"},{"id":"SWIcEXtI","text":"Травматического"}]', '["N1zNhP9r","6GLaJyT","XrZjxDOd","8LK5yfrt"]', '', 2, 22180, '{"meta":{"article":"Статья 6, ч. 6.1, п. 1","explanation":"П. 1 ч. 6.1.","quote":"бронебойного, зажигательного, разрывного или трассирующего действия","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q020~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 6, ч. 6.1, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q020~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие образцы входят в допустимые для хранения гражданским лицом виды огнестрельного оружия?', '[{"id":"cxvNkKdD","text":"Desert Eagle"},{"id":"4lCHdP4k","text":"Мини Узи"},{"id":"mEncbvxi","text":"СВД"},{"id":"rwNcRLBF","text":"Heckler & Koch P2000"},{"id":"k4yhVA6q","text":"Mossberg 500 Тактический"},{"id":"udd4pFcO","text":"АК-74"},{"id":"QDpIEqgQ","text":"Taurus PT92"}]', '["4lCHdP4k","rwNcRLBF","k4yhVA6q","QDpIEqgQ"]', '', 2, 22190, '{"meta":{"article":"Статья 6, ч. 6.2","explanation":"Ч. 6.2: пистолеты HK P2000, HK P7-M10, Taurus PT92; дробовики — обрез, Mossberg 500 Тактический; ПП — TEC-9, Мини Узи, vz.61.","quote":"1) Пистолеты: Heckler & Koch P2000, Heckler & Koch P7-M10, Taurus PT92.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q021~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 6, ч. 6.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q021~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Нужна ли лицензия для хранения патронов и боеприпасов к оружию?', '[{"id":"pFg9QWOo","text":"Да, лицензия на приобретение оружия"},{"id":"ahsEs8m3","text":"Да, отдельное разрешение Росгвардии"},{"id":"k41Oicvv","text":"Нужна только для патронов к пистолетам-пулемётам и высокоточным винтовкам"},{"id":"w46i320z","text":"Нет, хранение всех видов патронов, боеприпасов разрешено, лицензия не требуется"}]', '["w46i320z"]', '', 2, 22200, '{"meta":{"article":"Статья 6, ч. 6.3","explanation":"Ч. 6.3.","quote":"6.3. Разрешено хранение всех видов патронов, боеприпасов к оружию. Наличие соответствующей лицензии для хранения всех видов патронов, боеприпасов к оружию не требуется.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q022', NULL, 'full', 2, 'fz_oruzhie', 'Статья 6, ч. 6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте бронежилет с режимом его ношения и хранения по закону «Об оружии».', '[]', '[]', '', 2, 22210, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"Ч. 7.1.","quote":"1) лёгкий бронежилет (2-го класса защиты) — разрешён для ношения и хранения всеми лицами;","difficulty":"2"},"pairs":[{"l":{"id":"W7IuH2","text":"Лёгкий (2-го класса защиты)"},"r":{"id":"UxU9eoxy","text":"Разрешён для ношения и хранения всеми лицами"}},{"l":{"id":"As6xrjr","text":"Средний (3-го класса защиты)"},"r":{"id":"to7CKZbG","text":"Запрещён, кроме ЧОП, СМИ (при условиях) и силовых структур"}},{"l":{"id":"FtYMt0x","text":"Тяжёлый (4-го класса) или в комплексе с аптечкой"},"r":{"id":"R2xKCcuH","text":"Запрещён, кроме силовых структур при исполнении"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q024~v2', NULL, 'medium', 2, 'fz_oruzhie', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q024~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданский носит бронежилет, идущий в комплексе с аптечкой и неотделимый от неё. Как это оценивается по закону «Об оружии»?', '[{"id":"eYFwUfjW","text":"Разрешено, если класс защиты 2-й"},{"id":"J1VXE6K","text":"Разрешено, так как бронежилет в комплексе с аптечкой считается медицинским изделием"},{"id":"gnKHU1g","text":"Запрещено: такой бронежилет приравнен к тяжёлому и разрешён только силовым структурам"},{"id":"UQZ8m8F6","text":"Разрешено при лицензии на оружие"}]', '["gnKHU1g"]', '', 3, 22220, '{"meta":{"article":"Статья 7, ч. 7.1, п. 3","explanation":"П. 3 ч. 7.1.","quote":"3) тяжёлый бронежилет (4-го класса защиты) или любой бронежилет идущий в комплексе с аптечкой и неотделимый от неё — запрещён для ношения и хранения любыми лицами, за исключением лиц, определённых частью второй настоящей статьи.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q026', NULL, 'vp', 3, 'fz_oruzhie', 'Статья 7, ч. 7.1, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каким правом пользуются военнослужащие (сотрудники силовых, военизированных структур) при исполнении должностных обязанностей по закону «Об оружии»?', '[{"id":"u4ctZlcj","text":"Правом на ношение СИЗ только при ЧП или военном положении"},{"id":"bkohlzKw","text":"Правом на ношение только лёгких и средних бронежилетов"},{"id":"O2fyvcNE","text":"Правом на ношение всех видов СИЗ"},{"id":"jiw82b9e","text":"Правом на ношение СИЗ только по приказу Губернатора"}]', '["O2fyvcNE"]', '', 2, 22230, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2.","quote":"7.2. Сотрудники силовых, военизированных, правоохранительных государственных структур, а также органы Правительства Российской Федерации и органы Правительств Федеральных округов Российской Федерации при исполнении должностных обязанностей имеют право на ношение всех видов средств индивидуальной защиты (СИЗ).","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q027~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q027~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии сотрудники иных государственных структур имеют право на ношение всех видов СИЗ по закону «Об оружии»?', '[{"id":"l0p8aux","text":"Всегда, включая нерабочее время"},{"id":"0cqARu9p","text":"Только при наличии лицензии на оружие"},{"id":"1uXV8JY","text":"При исполнении должностных обязанностей, если они сопряжены с риском для жизни"},{"id":"FQwuypM","text":"Только на территории своей организации и при наличии лицензии на оружие"}]', '["1uXV8JY"]', '', 3, 22240, '{"meta":{"article":"Статья 7, ч. 7.3","explanation":"Ч. 7.3.","quote":"7.3. Сотрудники государственных структур имеют право на ношение всех видов средств индивидуальной защиты (СИЗ) при исполнении должностных обязанностей, если таковые сопряжены с риском для жизни.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q028', NULL, 'full', 3, 'fz_oruzhie', 'Статья 7, ч. 7.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'После чего выдаётся лицензия на приобретение оружия гражданам?', '[{"id":"BC5HqlSS","text":"После 3 месяцев стажа службы в ВС РФ"},{"id":"HfaL4dgf","text":"Сразу после подачи паспорта"},{"id":"UanPki37","text":"После оплаты государственной пошлины и подачи заявления в ФСВНГ, без проверки знаний и навыков обращения с оружием"},{"id":"GONJ6dah","text":"После проверки знаний закона об оружии и подтверждения навыков безопасного обращения с оружием при отсутствии препятствий"}]', '["GONJ6dah"]', '', 2, 22250, '{"meta":{"article":"Статья 8, ч. 8.3","explanation":"Ч. 8.3.","quote":"8.3. Лицензия на приобретение оружия выдаётся гражданам после прохождения ими соответствующей проверки знаний закона об оружии и подтверждения навыков безопасного обращения с оружием","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q031', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 8, ч. 8.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кому лицензия на приобретение оружия не выдаётся?', '[{"id":"a4lRwEm","text":"Лицам, лишённым судом права на приобретение оружия на установленный срок"},{"id":"pv7XAjQL","text":"Лицам, не достигшим установленного возраста"},{"id":"x41CPT","text":"Лицам с погашенной судимостью за преступление небольшой тяжести без оружия"},{"id":"ma57vBRp","text":"Военнослужащим ВС РФ"},{"id":"VnjDqlIQ","text":"Лицам с непогашенной судимостью за умышленное преступление"},{"id":"0KP3zObF","text":"Лицам, ранее добровольно отказавшимся от лицензии"},{"id":"8giA1Is","text":"Лицам с погашенной судимостью за тяжкое преступление, совершённое с применением оружия"}]', '["a4lRwEm","pv7XAjQL","VnjDqlIQ","8giA1Is"]', '', 3, 22260, '{"meta":{"article":"Статья 8, ч. 8.4","explanation":"Ч. 8.4.","quote":"2) имеющим непогашенную судимость за преступление, совершённое умышленно, либо имеющим погашенную судимость за тяжкое преступление, совершённое с применением оружия;","difficulty":"3"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q032~v2', NULL, 'medium', 3, 'fz_oruzhie', 'Статья 8, ч. 8.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q032~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие сведения должны быть указаны в реестрах лицензий?', '[{"id":"3yqyEFKI","text":"Модель и серийный номер оружия"},{"id":"1pekesCZ","text":"Фамилия и имя гражданина, реквизиты документа, удостоверяющего личность"},{"id":"NGoxruk","text":"Дата аннулирования лицензии"},{"id":"4abseAYX","text":"Место службы гражданина"},{"id":"C688ZC7Y","text":"Наименование органа, выдавшего лицензию"},{"id":"IXgUsVd6","text":"Основание и дата выдачи, номер и срок действия лицензии"},{"id":"uAAslH3","text":"Адрес места хранения оружия"}]', '["1pekesCZ","NGoxruk","C688ZC7Y","IXgUsVd6"]', '', 2, 22270, '{"meta":{"article":"Статья 9, ч. 9.2","explanation":"Ч. 9.2.","quote":"1) фамилия и имя гражданина, которому выдана лицензия, наименование и реквизиты документа, удостоверяющего его личность;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q035~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 9, ч. 9.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q035~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите этапы получения лицензии на приобретение оружия и разрешения на хранение и ношение в порядке, установленном законом «Об оружии».', '[]', '[]', '', 1, 22280, '{"meta":{"article":"Статья 10, ч. 10.2","explanation":"Ч. 10.2.","quote":"1) сбор гражданином необходимых документов (паспорт, медицинская карта, военный билет); 2) подача соответствующего заявления в Федеральную службу войск национальной гвардии;","difficulty":"1"},"items":[{"id":"evbMW5FJ","text":"Сбор документов (паспорт, медицинская карта, военный билет)"},{"id":"TAFQiSuw","text":"Подача заявления в Федеральную службу войск национальной гвардии"},{"id":"EADsNEYR","text":"Запись на специальный экзамен и его сдача уполномоченному инструктору"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q036~v2', NULL, 'full', 1, 'fz_oruzhie', 'Статья 10, ч. 10.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q036~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем устанавливается порядок проведения специального экзамена на лицензию?', '[{"id":"dEjKFRsP","text":"Начальником Федеральной службы войск национальной гвардии"},{"id":"sDXVOiNW","text":"Министром обороны РФ"},{"id":"NwZje4u","text":"Директором ФСБ"},{"id":"pakFES9K","text":"Губернатором Федерального округа по представлению МВД"}]', '["dEjKFRsP"]', '', 2, 22290, '{"meta":{"article":"Статья 10, ч. 10.3","explanation":"Ч. 10.3.","quote":"10.3. Порядок проведения специального экзамена, включая состав вопросов и методику его проведения, устанавливается Начальником Федеральной службы войск национальной гвардии.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q037', NULL, 'medium', 2, 'fz_oruzhie', 'Статья 10, ч. 10.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q037');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях лицензия аннулируется органами, выдающими лицензии?', '[{"id":"8FwkfHUl","text":"Поступление на военную службу"},{"id":"33mYItJM","text":"Добровольный отказ от лицензии либо прекращение её действия"},{"id":"y0XHe3S","text":"Утрата военного билета или служебного удостоверения владельцем"},{"id":"jD8QaidT","text":"Установление факта нарушения законодательства в сфере оборота стрелкового оружия"},{"id":"iiQXe94q","text":"Смена места жительства без уведомления органа, выдавшего лицензию"},{"id":"IzoNBAm9","text":"Судебное решение о лишении гражданина соответствующего специального права"}]', '["33mYItJM","jD8QaidT","IzoNBAm9"]', '', 2, 22300, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Ч. 11.1.","quote":"3) установления факта нарушения гражданином законодательства Российской Федерации в сфере производства, продажи, передачи, владения, хранения и использования стрелкового оружия.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q038~v2', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q038~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой орган осуществляет контроль и надзор за оружейными магазинами?', '[{"id":"uBt8VV1","text":"ФСБ России"},{"id":"zDVs856h","text":"ГУ МВД"},{"id":"1HjpuxK","text":"Федеральная служба войск национальной гвардии РФ"},{"id":"eFjSt3m","text":"Министерство обороны РФ и органы МВД России"}]', '["1HjpuxK"]', '', 2, 22310, '{"meta":{"article":"Статья 12, ч. 12.2","explanation":"Ч. 12.2.","quote":"12.2. Органом государственной власти, осуществляющим контроль и надзор за оружейными магазинами, является Федеральная служба войск национальной гвардии Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q040', NULL, 'full', 2, 'fz_oruzhie', 'Статья 12, ч. 12.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q040');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицензия аннулирована за нарушение 34-ФЗ. Что обязаны сделать сотрудники правоохранительных органов?', '[{"id":"HNI8iJIp","text":"Только уведомить нарушителя об аннулировании лицензии и предложить ему добровольно сдать оружие в органы ФСВНГ в течение месяца"},{"id":"BekzdHne","text":"Передать дело в военный суд"},{"id":"Wnf1HRNW","text":"Изъять оружие, боеприпасы и специальные средства, найденные при обыске личных вещей либо транспортного средства нарушителя"},{"id":"thKKtnQS","text":"Опечатать жилище нарушителя"}]', '["Wnf1HRNW"]', '', 2, 22320, '{"meta":{"article":"Статья 12, ч. 12.4","explanation":"Ч. 12.4.","quote":"сотрудники правоохранительных органов обязаны изъять оружие, боеприпасы и специальные средства, найденные при обыске личных вещей либо транспортного средства нарушителя.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q041', NULL, 'full', 2, 'fz_oruzhie', 'Статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q041');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие документы необходимо иметь при себе для пользования лицензией на оружие?', '[{"id":"Fpjgo7X","text":"Медицинская книжка"},{"id":"7xtXP0Qb","text":"Военный билет"},{"id":"oeHDTBp","text":"Свидетельство о регистрации ТС"},{"id":"qo558sRF","text":"Паспорт и/или удостоверение, выданное органом государственной власти"},{"id":"gUmehbaq","text":"Справка о прохождении медосмотра у врача-нарколога"},{"id":"FnRCkvFl","text":"Справка об отсутствии судимости"}]', '["Fpjgo7X","qo558sRF","gUmehbaq"]', '', 1, 22330, '{"meta":{"article":"Статья 12, ч. 12.5","explanation":"Ч. 12.5.","quote":"1) паспорт и/или удостоверение, выданное органом государственной власти; 2) медицинская книжка; 3) справка о прохождении медицинского осмотра у врача-нарколога.","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_oruzhie-q042~v2', NULL, 'medium', 1, 'fz_oruzhie', 'Статья 12, ч. 12.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q042~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'От предоставления какого документа освобождаются сотрудники правоохранительных структур при подаче заявления на лицензию?', '[{"id":"FA5JH6wY","text":"Справки врача-нарколога"},{"id":"3U2pRDNF","text":"Военного билета"},{"id":"7AByBPK3","text":"Паспорта"},{"id":"mFiPrVF","text":"Удостоверения сотрудника"}]', '["3U2pRDNF"]', '', 2, 22340, '{"meta":{"article":"Статья 13, ч. 13.1","explanation":"Ч. 13.1: основание — удостоверение сотрудника действующего состава.","quote":"освобождаются от обязанности предоставления военного билета при подаче заявления на получение лицензии на приобретение, хранение и ношение оружия.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_oruzhie-q043~v2', NULL, 'full', 2, 'fz_oruzhie', 'Статья 13, ч. 13.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q043~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что обязаны предоставить сотрудники в рамках упрощённой процедуры получения лицензии?', '[{"id":"9RKUx2aD","text":"Справку о прохождении медосмотра (врач-нарколог)"},{"id":"L17ONE4o","text":"Удостоверение сотрудника, выданное соответствующим органом"},{"id":"JvjxPjfe","text":"Характеристику от непосредственного командира с места службы"},{"id":"anidFXfv","text":"Военный билет"},{"id":"UF13gmdC","text":"Медицинскую карту"}]', '["9RKUx2aD","L17ONE4o"]', '', 2, 22350, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2.","quote":"1) удостоверение сотрудника, выданное соответствующим органом; 2) справку о прохождении медицинского осмотра (врач-нарколог).","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q044~v2', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q044~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какую лицензию обязан иметь при себе каждый сотрудник правоохранительной структуры, имеющий право на ношение оружия?', '[{"id":"oUcZqxW","text":"Лицензию, выданную командиром части"},{"id":"yLwI6HEY","text":"Лицензию ФСБ"},{"id":"Nc1FXNj3","text":"Никакую — для сотрудника достаточно служебного удостоверения и жетона"},{"id":"fdHcqE","text":"Действующую лицензию на хранение и ношение оружия, выданную органами ФСВНГ"}]', '["fdHcqE"]', '', 2, 22360, '{"meta":{"article":"Статья 14, ч. 14.1","explanation":"Ч. 14.1.","quote":"обязан иметь при себе действующую лицензию на хранение и ношение оружия, выданную органами Федеральной службы войск национальной гвардии.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q045', NULL, 'vp', 2, 'fz_oruzhie', 'Статья 14, ч. 14.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q045');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что может повлечь отсутствие действующей лицензии у сотрудника, использующего оружие в служебной деятельности?', '[{"id":"CBn0mW0N","text":"Немедленное увольнение со службы"},{"id":"cGdAvrLT","text":"Служебную проверку и меры дисциплинарного взыскания, вплоть до временного отстранения от обязанностей, связанных с применением оружия"},{"id":"hH0XmmK","text":"Уголовную ответственность в любом случае, вне зависимости от обстоятельств, а также немедленное увольнение со службы без проверки"},{"id":"tnhxW8mM","text":"Только административный штраф по КоАП"}]', '["cGdAvrLT"]', '', 3, 22370, '{"meta":{"article":"Статья 14, ч. 14.2","explanation":"Ч. 14.2.","quote":"14.2. Отсутствие действующей лицензии у сотрудника, использующего оружие в служебной деятельности, может повлечь служебную проверку и меры дисциплинарного взыскания, вплоть до временного отстранения от выполнения обязанностей, связанных с применением оружия.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_oruzhie-q046', NULL, 'vp', 3, 'fz_oruzhie', 'Статья 14, ч. 14.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_oruzhie-q046');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте понятие закона о закрытых и охраняемых территориях с определением.', '[]', '[]', '', 1, 22380, '{"meta":{"article":"Статья 1, ч. 1.1","explanation":"Пп. 1, 2, 4, 7 ч. 1.1.","quote":"2) закрытая территория - это место с закрытым доступом для гражданских лиц, а также с частично ограниченным доступом для государственных сотрудников.","difficulty":"1"},"pairs":[{"l":{"id":"nHdaFGTM","text":"Охраняемая территория"},"r":{"id":"MpDqv1lY","text":"Место под охраной структуры с ограниченным или запрещённым доступом гражданским лицам"}},{"l":{"id":"hFnQn1P","text":"Закрытая территория"},"r":{"id":"4kqy5OiT","text":"Место с закрытым доступом для гражданских и частично ограниченным для госсотрудников"}},{"l":{"id":"xbPNmxMy","text":"Зелёная зона"},"r":{"id":"LRj6RkRK","text":"Свободное передвижение граждан, зона общего порядка"}},{"l":{"id":"IGPHDzc4","text":"Доступ"},"r":{"id":"Ojwyclg1","text":"Право прохода, проезда и пролёта на территорию"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q001~v2', NULL, 'full', 1, 'fz_territorii', 'Статья 1, ч. 1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q001~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является государственной собственностью по закону о закрытых и охраняемых территориях?', '[{"id":"BaiSeSx2","text":"Земля и другие ресурсы и объекты, не находящиеся в собственности граждан, юридических лиц"},{"id":"MQGPeJKk","text":"Всё имущество на территории РФ, включая имущество граждан и юридических лиц, кроме иностранного"},{"id":"5IoHCxsT","text":"Только здания органов власти"},{"id":"VYXamwR7","text":"Только имущество войсковых частей"}]', '["BaiSeSx2"]', '', 1, 22390, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Ч. 2.2.","quote":"2.2. Земля и другие ресурсы и объекты, не находящиеся в собственности граждан, юридических лиц, являются государственной собственностью.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q004', NULL, 'medium', 1, 'fz_territorii', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто имеет доступ на все закрытые и охраняемые территории по общему правилу закона (кроме случаев, установленных законом)? Выберите все верные.', '[{"id":"PAzd3RQ","text":"Министры Федерального округа и их заместители по любым вопросам"},{"id":"HUSLMQ6q","text":"Любые сотрудники ФСО без сопровождения"},{"id":"PRErpto9","text":"Губернатор ФО, Председатель Совета Федерации, Председатель законодательного собрания ФО"},{"id":"kxZlQCUw","text":"Генеральный прокурор РФ, его заместители и их помощники"},{"id":"hAkGcV3","text":"Сотрудники ГБУЗ при любой цели визита"},{"id":"TGfHCD0t","text":"Прокуроры субъектов РФ и их заместители"},{"id":"BSmyva6","text":"Судьи РФ"}]', '["PRErpto9","kxZlQCUw","TGfHCD0t","BSmyva6"]', '', 3, 22400, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1; министры — только на закреплённые территории (ч. 4.2); ФСО — в сопровождении (ч. 4.5); медики — с целью медпомощи (ч. 4.6).","quote":"4.1. Губернатор Федерального округа Российской Федерации, Председатель Совета Федерации, Председатель законодательного собрания Федерального округа имеют доступ на все закрытые и охраняемые территории","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q007~v2', NULL, 'vp', 3, 'fz_territorii', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каким правом обладают министры Федерального округа?', '[{"id":"CY0y9sgZ","text":"Правом доступа только на территорию Московского Кремля и Правительства"},{"id":"c1rcVtvp","text":"Правом прохождения и проезда на закреплённые за ними территории"},{"id":"PSzBYDix","text":"Правом доступа на все закрытые территории"},{"id":"tvnV90Ku","text":"Правом выдавать пропуска в В/Ч"}]', '["c1rcVtvp"]', '', 2, 22410, '{"meta":{"article":"Статья 4, ч. 4.2","explanation":"Ч. 4.2.","quote":"4.2. Министры Федерального округа Российской Федерации обладают правом на прохождение и проезд на закрепленные за ними территории в соответствии с настоящим Федеральным законом.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q008', NULL, 'medium', 2, 'fz_territorii', 'Статья 4, ч. 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На каких условиях сотрудники ФСО получают доступ на закрытые территории?', '[{"id":"KrBoZW5","text":"В сопровождении лиц, наделённых таким правом в соответствии с законодательством"},{"id":"5BWYvObD","text":"Только при введении военного положения"},{"id":"wovAaiaG","text":"Без ограничений, как охрана первых лиц государства и Губернатора Федерального округа"},{"id":"EGkSosag","text":"Только по разовому пропуску"}]', '["KrBoZW5"]', '', 2, 22420, '{"meta":{"article":"Статья 4, ч. 4.5","explanation":"Ч. 4.5.","quote":"4.5. Сотрудники органов Федеральной службы охраны получают доступ на закрытые территории в сопровождении лиц, которые наделены таковым правом в соответствии с законодательством Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q010', NULL, 'full', 2, 'fz_territorii', 'Статья 4, ч. 4.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие условия установлены для доступа медработников ГБУЗ на закрытые территории?', '[{"id":"xnxy4k8b","text":"Письменное разрешение Губернатора"},{"id":"ZmzqdrV","text":"Обязательное сопровождение сотрудником ФСО"},{"id":"i9mJgStA","text":"Обязательная фиксация веской причины прохождения"},{"id":"SNERDZgn","text":"Покинуть территорию по первому требованию уполномоченного сотрудника"},{"id":"OCQ8wz2i","text":"Цель — оказание медицинской помощи"},{"id":"ei9KzqzU","text":"Наличие постоянного пропуска"}]', '["i9mJgStA","SNERDZgn","OCQ8wz2i"]', '', 2, 22430, '{"meta":{"article":"Статья 4, ч. 4.6","explanation":"Ч. 4.6.","quote":"4.6. Сотрудники государственных бюджетных учреждений здравоохранения получают доступ на закрытые территории с целью оказания медицинской помощи с обязательной фиксацией веской причины прохождения на закрытую территорию.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q011~v2', NULL, 'vp', 2, 'fz_territorii', 'Статья 4, ч. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q011~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каких случаях следователи получают доступ на закрытые территории организации?', '[{"id":"6FFLeSuY","text":"При осуществлении следственных действий или в целях задержания в отношении сотрудников этой организации"},{"id":"QYE9w3E","text":"В любое время по служебному удостоверению, без указания цели визита и без какого-либо сопровождения"},{"id":"u1MlyTT7","text":"Только в сопровождении прокурора"},{"id":"46m6DtBD","text":"Только по приглашению командира"}]', '["6FFLeSuY"]', '', 2, 22440, '{"meta":{"article":"Статья 4, ч. 4.7","explanation":"Ч. 4.7.","quote":"4.7. Следователи при осуществлении следственных действий или в целях задержания получают доступ на закрытые территории организации, в отношении сотрудников которой ведутся следственные действия","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q012', NULL, 'full', 2, 'fz_territorii', 'Статья 4, ч. 4.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник госорганизации прошёл на закрытую территорию по служебной необходимости. Что он обязан сделать по требованию сотрудника, который к нему обратился?', '[{"id":"dUYWn6I","text":"Ничего — служебная необходимость не раскрывается никому, кроме своего руководителя"},{"id":"n4VVMerW","text":"Озвучить служебную необходимость, если она не содержит государственной или служебной тайны"},{"id":"M4AxF4ev","text":"Немедленно покинуть территорию"},{"id":"vBxl7OPb","text":"Предъявить письменный приказ руководителя"}]', '["n4VVMerW"]', '', 2, 22450, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Ч. 5.3.","quote":"5.3. Сотрудник государственной организации, прошедший на закрытые и охраняемые территории по служебной необходимости, обязан ее озвучить по первому требованию сотрудника, который обратился, если она не содержит информации, составляющей государственную или служебную тайну.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q013', NULL, 'vp', 2, 'fz_territorii', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие объекты относятся к государственным территориям, допуск к которым определяется 86-ФЗ?', '[{"id":"ZDvvR18","text":"Частные охранные предприятия"},{"id":"RTF13dWA","text":"Государственные склады или складские помещения"},{"id":"kU0EjlCy","text":"Здания коммерческих банков"},{"id":"fTG3kF1","text":"Жилые дома граждан"},{"id":"i3BvSouK","text":"Здания и территории Судов РФ"},{"id":"grJ75YJ","text":"Войсковые части"},{"id":"0MiqB73n","text":"Московский Кремль"}]', '["RTF13dWA","i3BvSouK","grJ75YJ","0MiqB73n"]', '', 1, 22460, '{"meta":{"article":"Статья 6, ч. 6.3","explanation":"Ч. 6.3 (13 пунктов).","quote":"7) войсковые части; 8) государственные склады или складские помещения (объекты);","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q014~v2', NULL, 'full', 1, 'fz_territorii', 'Статья 6, ч. 6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q014~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является закрытым для общего пользования и посещения в Московском Кремле?', '[{"id":"6IVGp4OI","text":"Холл здания Управления ФСО"},{"id":"sSkRMGe","text":"КПП Московского Кремля"},{"id":"Div4qyHn","text":"Крыши зданий на территории Кремля и Красной площади"},{"id":"EqDXT4In","text":"Стены Московского Кремля"},{"id":"3TPh32Tz","text":"Комнаты совещания Судов РФ"},{"id":"CEPCIggV","text":"Общая территория Кремля"}]', '["Div4qyHn","EqDXT4In","3TPh32Tz"]', '', 2, 22470, '{"meta":{"article":"Статья 8, ч. 8.1","explanation":"Холл ФСО, КПП и общая территория — охраняемые (ч. 8.2).","quote":"2) крыши зданий на территории Московского Кремля и красной площади; 3) стены Московского Кремля; 4) комнаты совещания Судов Российской Федерации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q017~v2', NULL, 'vp', 2, 'fz_territorii', 'Статья 8, ч. 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q017~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вводит и отменяет ограничения на свободное посещение охраняемой территории Кремля?', '[{"id":"mGPb2fxO","text":"Начальник УВД по ЦАО"},{"id":"dwBQsPJi","text":"Губернатор ФО, Правительство ФО, а также комендант Московского Кремля (уполномоченное лицо ФСО) или его заместитель"},{"id":"qzFDlTqi","text":"Командир полка ВС РФ, охраняющего Кремль, по согласованию с начальником УВД по ЦАО и прокурором субъекта РФ"},{"id":"1jyu3tBh","text":"Только Председатель Совета Федерации"}]', '["dwBQsPJi"]', '', 2, 22480, '{"meta":{"article":"Статья 9, ч. 9.2","explanation":"Ч. 9.2.","quote":"9.2. Ограничение на свободное посещение на охраняемой территории Московского Кремля вводятся и отменяются Губернатором Федерального округа Российской Федерации, Правительством Федерального округа Российской Федерации, а также уполномоченным должностным лицом Федеральной службы охраны","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q019', NULL, 'medium', 2, 'fz_territorii', 'Статья 9, ч. 9.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Военнослужащий ВС РФ хочет пройти на закрытую территорию Московского Кремля. На каком основании это возможно?', '[{"id":"BYaqEnY","text":"Невозможно ни при каких условиях"},{"id":"q9Z8duMC","text":"По разовому пропуску КПП Кремля в любом случае"},{"id":"oyTrGpcS","text":"По военному билету"},{"id":"87zS5VTg","text":"По приглашению лиц, которым закон даёт такое право"}]', '["87zS5VTg"]', '', 3, 22490, '{"meta":{"article":"Статья 9, ч. 9.7","explanation":"Ч. 9.7.","quote":"9.7. Сотрудники государственных организаций и иные лица имеют право на вход на закрытые территории Московского Кремля по приглашению лиц, указанных в части 3 статьи 9 настоящего Федерального закона.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q020~v2', NULL, 'full', 3, 'fz_territorii', 'Статья 9, ч. 9.7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q020~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к охраняемым (а не закрытым) территориям Прокуратуры и СК?', '[{"id":"jFGJAUi","text":"Крыши на территориях Прокуратуры и СК"},{"id":"G5z67pgy","text":"Залы совещаний и конгресс-холл"},{"id":"ACvoPTDQ","text":"Все кабинеты в здании"},{"id":"uanBdzed","text":"Периметр территории за забором органа"},{"id":"XwwLaff","text":"Территория парковок и прилежащие к ним"},{"id":"VQTZuzr","text":"Холл, лестница, лифт и общее пространство на этажах"}]', '["uanBdzed","XwwLaff","VQTZuzr"]', '', 2, 22500, '{"meta":{"article":"Статья 9-1, ч. 9-1.1, 9-1.2","explanation":"Кабинеты, залы совещаний, конгресс-холл и крыши — закрытые (ч. 9-1.1).","quote":"1) Территория парковок и прилежащие к ним; 2) Периметр территории находящиеся за забором органа; 3) Холл, лестница, лифт и общее пространство на этажах.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q021~v2', NULL, 'full', 2, 'fz_territorii', 'Статья 9-1, ч. 9-1.1, 9-1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q021~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто имеет допуск к закрытой территории Государственной думы?', '[{"id":"Y7J6UXXw","text":"Сотрудники всех госорганизаций по служебному удостоверению или жетону, без ограничений"},{"id":"4Rktl5I9","text":"Сотрудники правительства ФО, депутаты Законодательного собрания и сенаторы Совета Федерации"},{"id":"hJwyLZAj","text":"Любые лица при соблюдении правил поведения"},{"id":"C6NlIp8F","text":"Только сотрудники ФСО"}]', '["4Rktl5I9"]', '', 2, 22510, '{"meta":{"article":"Статья 9-4, ч. 9-4.2","explanation":"Ч. 9-4.2.","quote":"9-4.2. Допуск к закрытой территории Государственной думы имеют сотрудники правительства Федерального округа, депутаты Законодательного собрания и сенаторы Совета Федерации а также иные лица в соответствии со статьей 4 настоящего Федерального закона.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q022', NULL, 'full', 2, 'fz_territorii', 'Статья 9-4, ч. 9-4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является охраняемой территорией Правительства по закону о закрытых и охраняемых территориях?', '[{"id":"UqsAWJfC","text":"Вся территория здания, включая кабинеты, крышу и подвальные помещения"},{"id":"yG9ZdsfJ","text":"Крыша Правительства"},{"id":"871XIcts","text":"Прилежащая территория к зданию, холл Правительства, коридоры и уборные"},{"id":"nnFn5uV","text":"Все кабинеты в здании"}]', '["871XIcts"]', '', 2, 22520, '{"meta":{"article":"Статья 9-5, ч. 9-5.2","explanation":"Ч. 9-5.2; кабинеты и крыша — закрытые (ч. 9-5.1).","quote":"2) холл Правительства, коридоры и уборные.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q023', NULL, 'full', 2, 'fz_territorii', 'Статья 9-5, ч. 9-5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является закрытым для общего пользования на территории УФСБ?', '[{"id":"ONSPo9Y","text":"Парковка у забора УФСБ"},{"id":"M71qmqdE","text":"Внутренний двор УФСБ"},{"id":"2yYrXQJ9","text":"Подъезд к внутреннему двору УФСБ"},{"id":"1FmUFnY","text":"Холл (вестибюль) УФСБ"},{"id":"as58Ubpp","text":"Все помещения и кабинеты, за исключением холла"},{"id":"EGeWNJiv","text":"Блоки камер предварительного содержания УФСБ"}]', '["M71qmqdE","as58Ubpp","EGeWNJiv"]', '', 2, 22530, '{"meta":{"article":"Статья 10, ч. 10.1","explanation":"Холл и подъезд — охраняемые (ч. 10.2).","quote":"1) внутренний двор УФСБ; 2) все помещения и кабинеты УФСБ, за исключением холла; 3) блоки камер предварительного содержания УФСБ.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q024~v2', NULL, 'medium', 2, 'fz_territorii', 'Статья 10, ч. 10.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q024~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является закрытым для общего пользования на территории органов МВД?', '[{"id":"SY46iBfD","text":"Внутренняя парковка УВД по ЦАО"},{"id":"BDW7Fqia","text":"Камера предварительного заключения УВД по ЦАО"},{"id":"AG0p8VH1","text":"Внешняя парковка УВД по ЦАО"},{"id":"sYPcJxL","text":"Холл УГИБДД"},{"id":"7gLDjrg","text":"Фронтальная зона и задний двор УВД по ЦАО"},{"id":"i0AbcQOI","text":"Подъездные участки к КПП УВД по ЦАО"}]', '["SY46iBfD","BDW7Fqia","7gLDjrg"]', '', 2, 22540, '{"meta":{"article":"Статья 14, ч. 14.1","explanation":"Внешняя парковка, холлы и подъезды к КПП — охраняемые (ч. 14.2).","quote":"1) фронтальная зона и задний двор УВД по ЦАО; 2) все помещения и кабинеты УВД по ЦАО, за исключением холла; 3) камера предварительного заключения УВД по ЦАО;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q026~v2', NULL, 'full', 2, 'fz_territorii', 'Статья 14, ч. 14.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q026~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является закрытым на территории ГКУ ЦОДД?', '[{"id":"tKa4m5P","text":"Только склад"},{"id":"wY3Ix5nm","text":"Прилегающая парковка, КПП и холл здания, а также крыша и пространство над зданием"},{"id":"41NftYW","text":"Внутренний двор с КПП и воротами, а также внутренние помещения здания, кроме холла"},{"id":"2XZpX7l","text":"Холл здания ГКУ ЦОДД"}]', '["41NftYW"]', '', 2, 22550, '{"meta":{"article":"Статья 19-1, ч. 19-1.1","explanation":"Ч. 19-1.1; холл, парковка и КПП — охраняемые (ч. 19-1.2).","quote":"1) внутренний двор огражденный забором, имеющий КПП с воротами, прилегающий к зданию ГКУ ЦОДД;","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q028', NULL, 'vp', 2, 'fz_territorii', 'Статья 19-1, ч. 19-1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является закрытым для общего пользования и посещения на территории войсковых частей?', '[{"id":"HGbgz3n","text":"Только КПП и парковки перед ними"},{"id":"0i5Jqw0Z","text":"Территории, огороженные сплошным периметром забора — вся территория, здания, крыши, иные объекты и пространство внутри, а также крыши охраняемых объектов"},{"id":"1LezajOg","text":"Только территория в радиусе 15 метров от забора, КПП и парковочные комплексы перед ними, а также здания штабов, склады вооружения, казармы и плац части"},{"id":"iGMItVDK","text":"Только здания штабов и склады вооружения"}]', '["0i5Jqw0Z"]', '', 2, 22560, '{"meta":{"article":"Статья 20, ч. 20.1","explanation":"Ч. 20.1.","quote":"20.1. Территории войсковых частей, огражденные сплошным периметром забора, то есть вся территория, здания, крыши, иные объекты и пространство в закрытой сплошным периметром забора территории","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q029', NULL, 'medium', 2, 'fz_territorii', 'Статья 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие территории ВС РФ являются охраняемыми?', '[{"id":"ZWjA8dtn","text":"Крыши зданий КПП и иных объектов внутри части"},{"id":"reSwnByJ","text":"КПП войсковых частей и парковочные комплексы перед ними"},{"id":"f3Kd6KRr","text":"Подъездной участок к КПП на территорию В/Ч №12132"},{"id":"PdBeP49q","text":"Плац и казармы внутри периметра части"},{"id":"JYOqru3w","text":"Военные комиссариаты"},{"id":"DkfFrGXO","text":"Склады вооружения"}]', '["reSwnByJ","f3Kd6KRr","JYOqru3w"]', '', 1, 22570, '{"meta":{"article":"Статья 20, ч. 20.2","explanation":"Ч. 20.2; крыши охраняемых объектов — закрытые (ч. 20.1).","quote":"1) контрольно-пропускные пункты войсковых частей и парковочные комплексы перед ними; 2) военные комиссариаты; 3) подъездной участок к КПП на территорию Войсковой части №12132.","difficulty":"1"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q030~v2', NULL, 'medium', 1, 'fz_territorii', 'Статья 20, ч. 20.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q030~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин забрался на крышу здания КПП войсковой части. На какой территории он находится?', '[{"id":"IffWiuvI","text":"На закрытой: крыши охраняемых объектов ВС РФ относятся к закрытой территории"},{"id":"50Vd6aRA","text":"На зелёной зоне — крыша КПП не входит в территорию воинской части и не охраняется"},{"id":"m7gukeaD","text":"На охраняемой — КПП относится к охраняемым территориям"},{"id":"PMfBY2US","text":"На территории общего пользования"}]', '["IffWiuvI"]', '', 3, 22580, '{"meta":{"article":"Статья 20, ч. 20.1","explanation":"Ч. 20.1 прямо относит крыши охраняемых объектов к закрытым.","quote":"а также крыши объектов, которые являются охраняемыми на основании статьи 20.2 настоящего федерального закона, являются закрытыми для общего пользования и посещения.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q031', NULL, 'medium', 3, 'fz_territorii', 'Статья 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе проходить на охраняемую территорию ВС РФ (например, к КПП)?', '[{"id":"ufc9gHKR","text":"Только сотрудники госорганизаций"},{"id":"vq5BJP1O","text":"Только лица с разовым пропуском"},{"id":"uZYcODf","text":"Только военнослужащие, члены их семей и сотрудники госорганизаций по удостоверению"},{"id":"kVB7ndk","text":"Любые лица при соблюдении правил поведения, установленных 86-ФЗ и ФОИВ в области обороны"}]', '["kVB7ndk"]', '', 2, 22590, '{"meta":{"article":"Статья 21, ч. 21.4","explanation":"Ч. 21.4.","quote":"21.4. На охраняемую территорию Вооруженных сил Российской Федерации вправе проходить любые лица при соблюдении определённых правил поведения, установленных настоящим Федеральным законом и федеральным органом исполнительной власти в области обеспечения обороны страны и безопасности государства.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q033', NULL, 'full', 2, 'fz_territorii', 'Статья 21, ч. 21.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии сотрудники госструктур допускаются на закрытую территорию ВС РФ с целью общего сбора для оказания снабжения?', '[{"id":"NTvym2yD","text":"Только в сопровождении сотрудника ФСО"},{"id":"5ZHAnzrx","text":"При наличии письменного приказа Министра обороны и сопровождающего"},{"id":"eu8fK8","text":"При предварительном озвучивании этого в рацию государственных структур"},{"id":"HSIHUYpA","text":"Без каких-либо условий"}]', '["eu8fK8"]', '', 3, 22600, '{"meta":{"article":"Статья 21, ч. 21.5","explanation":"Ч. 21.5.","quote":"21.5. Допуск к закрытой территории Вооруженных Сил Российской Федерации разрешается сотрудникам государственных структур с целью общего сбора для оказания снабжения по предварительному озвучиванию этого в рацию государственных структур.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q035', NULL, 'vp', 3, 'fz_territorii', 'Статья 21, ч. 21.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что влечёт нарушение установленных правил поведения на территории ВС РФ?', '[{"id":"cKwhtyIn","text":"Только устное замечание"},{"id":"Q6Vj8HY","text":"Обязательное уголовное преследование и задержание"},{"id":"RlyTg3OR","text":"Ответственность, предусмотренную законодательством"},{"id":"YfQGJWme","text":"Немедленное применение оружия"}]', '["RlyTg3OR"]', '', 2, 22610, '{"meta":{"article":"Статья 21, ч. 21.2","explanation":"Ч. 21.2.","quote":"21.2. Нарушение установленных правил поведения на территории Вооруженных Сил Российской Федерации влечет ответственность, предусмотренную законодательством.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q036', NULL, 'full', 2, 'fz_territorii', 'Статья 21, ч. 21.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На каком основании сотрудники госструктур входят на закрытые территории учреждений исполнения наказаний?', '[{"id":"etsjL1YK","text":"По постоянному пропуску"},{"id":"s4VYXWTb","text":"По разовому пропуску (кроме лиц, которым закон даёт доступ без него)"},{"id":"Hp2UQOFx","text":"По приглашению любого осуждённого или его родственников, без пропуска"},{"id":"pI81DgkN","text":"По служебному удостоверению"}]', '["s4VYXWTb"]', '', 2, 22620, '{"meta":{"article":"Статья 25, ч. 25.4","explanation":"Ч. 25.4.","quote":"25.4. Сотрудники государственных структур и иные лица имеют право на вход на закрытые территории учреждений исполнения уголовных наказаний по разовому пропуску.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_territorii-q038', NULL, 'vp', 2, 'fz_territorii', 'Статья 25, ч. 25.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q038');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия при проходе адвоката в учреждение исполнения наказаний в установленном законом порядке.', '[]', '[]', '', 2, 22630, '{"meta":{"article":"Статья 26","explanation":"Ст. 26.","quote":"Сотрудники уголовно-исполнительной системы обязаны сопроводить адвоката в комнату свиданий, затем доставить туда лицо, отбывающее наказание.","difficulty":"2"},"items":[{"id":"Hiu538K","text":"Адвокат предъявляет удостоверение адвоката и паспорт"},{"id":"2hhbJADU","text":"Адвокат называет имя и фамилию лица, к которому прибыл"},{"id":"2ZUdkfcr","text":"Сотрудники УИС сопровождают адвоката в комнату свиданий"},{"id":"2TN8evlu","text":"Сотрудники УИС доставляют туда лицо, отбывающее наказание"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q039~v2', NULL, 'full', 2, 'fz_territorii', 'Статья 26', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q039~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие объекты относятся к стратегически важным государственным объектам?', '[{"id":"MUEsWAcW","text":"Объект №7"},{"id":"AOJN7ZDj","text":"Военные комиссариаты"},{"id":"0gPIETTs","text":"Зарайский кремль"},{"id":"Pn0caSRg","text":"Государственные склады медицинского оборудования, военные склады"},{"id":"ipbanZjx","text":"Холл УФСБ"},{"id":"RO8UJIq","text":"Радиолокационная станция «Орбита»"},{"id":"GvZIDaKI","text":"КПП войсковых частей"}]', '["MUEsWAcW","0gPIETTs","Pn0caSRg","RO8UJIq"]', '', 3, 22640, '{"meta":{"article":"Статья 28, ч. 28.2","explanation":"Ч. 28.2 (7 пунктов).","quote":"4) Объект №7 5) Радиолокационная станция \"Орбита\" 6) Зарайский кремль","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q040~v2', NULL, 'full', 3, 'fz_territorii', 'Статья 28, ч. 28.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q040~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии возможно временное открытие Зарайского кремля для посещений?', '[{"id":"MixFw5YM","text":"Только при наличии специального разрешения Губернатора ФО и если посещение не нарушает режим безопасности и сохранности объекта"},{"id":"w399bYj0","text":"По разовому пропуску ФСО"},{"id":"VC5p0Fy","text":"В период финансовых поставок"},{"id":"jwlXx8z","text":"По решению командира охраняющего подразделения и коменданта Кремля, если посещение согласовано с ФСО не позднее чем за сутки"}]', '["MixFw5YM"]', '', 3, 22650, '{"meta":{"article":"Статья 28, ч. 28.3","explanation":"Ч. 28.3: закрыт постоянно, включая период финансовых поставок.","quote":"Временное открытие Зарайского кремля для посещений возможно только при наличии специального разрешения Губернатора Федерального округа и при условии, что такое посещение не нарушает режим безопасности и сохранности объекта.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q041', NULL, 'full', 3, 'fz_territorii', 'Статья 28, ч. 28.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q041');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какие органы осуществляют охрану и обеспечение правопорядка на стратегически важных объектах?', '[{"id":"uL6mmxQ","text":"Только ВС РФ"},{"id":"R1dG5qks","text":"Полиция и частные охранные предприятия по договору с Правительством Федерального округа"},{"id":"p7PwkLzJ","text":"Только Росгвардия"},{"id":"Us14nq2t","text":"ФСБ России и ФСО России; силовые подразделения иных органов оказывают содействие"}]', '["Us14nq2t"]', '', 2, 22660, '{"meta":{"article":"Статья 28, ч. 28.4","explanation":"Ч. 28.4.","quote":"28.4. Охрана и обеспечение правопорядка на территориях стратегически важных государственных объектов осуществляется органами ФСБ России и ФСО России.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q042', NULL, 'medium', 2, 'fz_territorii', 'Статья 28, ч. 28.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q042');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто имеет допуск к закрытой территории стратегически важных государственных объектов?', '[{"id":"XANTeLJ2","text":"Только Губернатор ФО"},{"id":"JhTovnsF","text":"Только сотрудники ФСБ и ФСО при исполнении"},{"id":"zHlHXwHK","text":"Сотрудники всех государственных организаций"},{"id":"6sYQi452","text":"Любые граждане"}]', '["zHlHXwHK"]', '', 1, 22670, '{"meta":{"article":"Статья 29, ч. 29.1","explanation":"Ч. 29.1.","quote":"29.1. Допуск к закрытой территории стратегически важных государственных объектов имеют сотрудники всех государственных организаций.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q043', NULL, 'full', 1, 'fz_territorii', 'Статья 29, ч. 29.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q043');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид пропуска с его назначением.', '[]', '[]', '', 2, 22680, '{"meta":{"article":"Статья 31, ч. 31.1","explanation":"Ч. 31.1.","quote":"4) разовый пропуск – документ, предоставляющий право однократного доступа на территорию объекта.","difficulty":"2"},"pairs":[{"l":{"id":"8zap2R2F","text":"Постоянный"},"r":{"id":"Up00M0B","text":"Многократный доступ на установленный срок лицам с постоянной трудовой/служебной деятельностью на объекте"}},{"l":{"id":"zFiGEsgX","text":"Временный"},"r":{"id":"hmWvhdtN","text":"Многократный доступ на период выполнения работ временного характера"}},{"l":{"id":"AvHgDZEA","text":"Разовый"},"r":{"id":"coiOMq8e","text":"Однократный доступ посетителям и представителям организаций"}},{"l":{"id":"k5IVIbFw","text":"Материальный"},"r":{"id":"vxchKy5G","text":"Перемещение материальных ценностей (ввоз, вывоз, внос, вынос)"}}],"distractors":[],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_territorii-q044~v2', NULL, 'medium', 2, 'fz_territorii', 'Статья 31, ч. 31.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q044~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Нужен ли пропуск высшим должностным лицам, которым закон о закрытых территориях даёт общий доступ (Губернатор, судьи, прокуроры и др.), для доступа на территории с пропускным режимом?', '[{"id":"Py6nHwxY","text":"Да, нужен служебный пропуск той организации, на территорию которой они проходят"},{"id":"D820v6b","text":"Да, постоянный пропуск"},{"id":"WxFCcPN","text":"Да, разовый пропуск в каждом случае"},{"id":"FZzTDhW2","text":"Нет, они имеют доступ без пропуска в порядке, установленном законом"}]', '["FZzTDhW2"]', '', 2, 22690, '{"meta":{"article":"Статья 30, ч. 30.2","explanation":"Ч. 30.2.","quote":"30.2. Лица, определенные статьей 4 настоящего Федерального закона, имеют доступ в порядке, определенном статьей 4, к территориям с пропускным режимом без пропуска.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q046~v2', NULL, 'full', 2, 'fz_territorii', 'Статья 30, ч. 30.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q046~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите полномочия сотрудников, охраняющих территорию с пропускным режимом, в порядке их применения к лицу.', '[]', '[]', '', 2, 22700, '{"meta":{"article":"Статья 31, ч. 31.3","explanation":"Ч. 31.3, пп. 1–3.","quote":"3) в случае отказа лица от осуществления в отношении него указанных процедур, сотрудники органов государственной власти с пропускным режимом имеют право отказать лицу в посещении таковой территории либо потребовать от него её покинуть.","difficulty":"2"},"items":[{"id":"EjUB2T3","text":"Проверка документов, удостоверяющих личность"},{"id":"Blc0hoNE","text":"Личный обыск и обыск транспортного средства лица"},{"id":"HnqzUHT0","text":"При отказе лица от процедур — отказ в посещении либо требование покинуть территорию"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_territorii-q047~v2', NULL, 'full', 2, 'fz_territorii', 'Статья 31, ч. 31.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_territorii-q047~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что такое носители сведений, составляющих государственную тайну?', '[{"id":"ZgsnIJ8V","text":"Только бумажные документы с грифом секретности, а также лица, допущенные к государственной тайне, органы её защиты, их печати, штампы и служебные удостоверения сотрудников"},{"id":"09S0u2O","text":"Материальные объекты, в том числе физические поля, в которых сведения находят отображение в виде символов, образов, сигналов, технических решений и процессов"},{"id":"4OX0LeBk","text":"Лица, допущенные к государственной тайне"},{"id":"2LFieYH","text":"Органы защиты государственной тайны"}]', '["09S0u2O"]', '', 2, 22710, '{"meta":{"article":"Статья 2, п. 2","explanation":"Ст. 2 п. 2.","quote":"носители сведений, составляющих государственную тайну, - материальные объекты, в том числе физические поля","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q002', NULL, 'full', 2, 'fz_gostayna', 'Статья 2, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что такое жетон государственного служащего?', '[{"id":"2fEZEZ6","text":"Пропуск на охраняемый объект"},{"id":"8kMOiAe","text":"Личный знак с номером, который позволяет идентифицировать государственного служащего"},{"id":"7Kv0GmjS","text":"Нагрудный знак за выслугу лет"},{"id":"YeXaNJxg","text":"Документ о допуске к сведениям особой важности, выдаваемый органами ФСБ России"}]', '["8kMOiAe"]', '', 1, 22720, '{"meta":{"article":"Статья 2, п. 8","explanation":"Ст. 2 п. 8.","quote":"жетон государственного служащего (работника государственной организации) — это личный знак с номером, который позволяет идентифицировать государственного служащего.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q004', NULL, 'medium', 1, 'fz_gostayna', 'Статья 2, п. 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какие сведения в военной области составляют государственную тайну?', '[{"id":"voyc8t9i","text":"О правилах ношения повседневной формы, о распорядке дня, о праздничных днях и о порядке подачи заявлений"},{"id":"KuSXnQ6","text":"О праздничных днях в части"},{"id":"uB8FkvE","text":"О порядке подачи заявления на отпуск"},{"id":"rxUp5jZ6","text":"О дислокации, действительных наименованиях, организационной структуре, вооружении, численности войск"}]', '["rxUp5jZ6"]', '', 1, 22730, '{"meta":{"article":"Статья 4, ч. 4.1 п. 4","explanation":"Ч. 4.1 п. 4.","quote":"4) о дислокации, действительных наименованиях, об организационной структуре, о вооружении, численности войск и состоянии их боевого обеспечения","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q006', NULL, 'full', 1, 'fz_gostayna', 'Статья 4, ч. 4.1 п. 4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что из перечисленного относится к гостайне в отношении режимных и особо важных объектов?', '[{"id":"ysoBCl9O","text":"Только названия объектов на картах города"},{"id":"TZqfEiOE","text":"Сведения о цене обедов в столовой объекта, о графике работы магазинов рядом с ним и о названиях и адресах объектов на картах города"},{"id":"jH5LPAiY","text":"Сведения о погоде в районе объекта"},{"id":"JNyrt0q","text":"Сведения о дислокации, назначении, степени готовности, защищённости объектов, их проектировании, строительстве и эксплуатации"}]', '["JNyrt0q"]', '', 2, 22740, '{"meta":{"article":"Статья 4, ч. 4.1 п. 3","explanation":"Ч. 4.1 п. 3.","quote":"3) о дислокации, назначении, степени готовности, защищенности режимных и особо важных объектов, об их проектировании, строительстве и эксплуатации","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q007', NULL, 'full', 2, 'fz_gostayna', 'Статья 4, ч. 4.1 п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какие сведения в сфере противодействия терроризму прямо отнесены законом «О государственной тайне» к гостайне?', '[{"id":"stzAamoO","text":"О ценах на услуги охранных предприятий"},{"id":"JrBoOYQK","text":"О количестве жителей Федерального округа"},{"id":"MZWdqWFL","text":"О мерах по обеспечению защищённости критически важных и потенциально опасных объектов инфраструктуры от террористических актов"},{"id":"bGIc2lEw","text":"О графике работы общественного транспорта и о схемах движения маршрутов вблизи критически важных объектов инфраструктуры"}]', '["MZWdqWFL"]', '', 3, 22750, '{"meta":{"article":"Статья 4, ч. 4.2 п. 9","explanation":"Ч. 4.2 п. 9.","quote":"9) о мерах по обеспечению защищенности критически важных объектов и потенциально опасных объектов инфраструктуры Российской Федерации от террористических актов.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q009', NULL, 'vp', 3, 'fz_gostayna', 'Статья 4, ч. 4.2 п. 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чему должна соответствовать степень секретности сведений?', '[{"id":"Gvs9wqgE","text":"Званию и должности лица, подписавшего документ, а также количеству страниц и экземпляров документа"},{"id":"Wl6z0bg","text":"Сроку службы исполнителя"},{"id":"S0LFYAd","text":"Степени тяжести ущерба, который может быть нанесён безопасности РФ вследствие распространения сведений"},{"id":"vtYUO5ve","text":"Количеству страниц документа"}]', '["S0LFYAd"]', '', 2, 22760, '{"meta":{"article":"Статья 6, ч. 6.1","explanation":"Ч. 6.1.","quote":"Степень секретности сведений, составляющих государственную тайну, должна соответствовать степени тяжести ущерба, который может быть нанесен безопасности Российской Федерации вследствие распространения указанных сведений.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q013', NULL, 'vp', 2, 'fz_gostayna', 'Статья 6, ч. 6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является основанием для засекречивания сведений, полученных в результате деятельности органов власти и организаций?', '[{"id":"Qp82gssY","text":"Их соответствие действующим в данных органах (организациях) перечням сведений, подлежащих засекречиванию"},{"id":"AK26zhRM","text":"Устное распоряжение любого начальника, если исполнитель документа считает сведения важными для службы"},{"id":"wZvqlCg","text":"Решение собрания трудового коллектива"},{"id":"Vo0dfCGU","text":"Желание исполнителя документа"}]', '["Qp82gssY"]', '', 3, 22770, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2; носителям присваивается соответствующий гриф.","quote":"является их соответствие действующим в данных органах, на данных предприятиях, в данных учреждениях и организациях перечням сведений, подлежащих засекречиванию.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q014', NULL, 'medium', 3, 'fz_gostayna', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие должности и подразделения включены в перечень, составляющий государственную тайну?', '[{"id":"6Lq0SSfS","text":"Любые военнослужащие военной полиции, несущие службу в составе патрульных нарядов и на КПП воинских частей"},{"id":"bIDAKQIQ","text":"Третья служба по защите конституционного строя и борьбе с экстремизмом и терроризмом ФСБ и её сотрудники"},{"id":"ffBJfGxr","text":"Все сотрудники Министерства юстиции"},{"id":"ENpPRkiZ","text":"Сотрудники Первой и Второй оперативно-следственных служб ФСБ, выполняющие ОРМ"},{"id":"16KXbd7p","text":"Военнослужащие Сил специальных операций в служебной форме спецподразделения с использованием средств сокрытия личности"},{"id":"GsVc9Bj","text":"Сотрудники патрульно-постовой службы полиции"}]', '["bIDAKQIQ","ENpPRkiZ","16KXbd7p"]', '', 2, 22780, '{"meta":{"article":"Статья 9","explanation":"Ст. 9, пп. 1, 2, 4.","quote":"4) военнослужащие подразделений Сил специальных операций, находящиеся в служебной форме специального подразделения с использованием средств сокрытия личности.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q016~v2', NULL, 'full', 2, 'fz_gostayna', 'Статья 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q016~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При каком условии сотрудники спецподразделений ОВД, Росгвардии, ФСО в форме спецподразделения с сокрытием личности обладают статусом секретности?', '[{"id":"vwcBW6tn","text":"Всегда, если на них балаклава"},{"id":"YwWCwyR","text":"По решению прокурора субъекта"},{"id":"hAGM0rE","text":"По приказу командира подразделения, согласованному с прокурором субъекта и ФСБ"},{"id":"v5hJlnnz","text":"По решению Губернатора ФО путём издания соответствующего нормативного правового акта"}]', '["v5hJlnnz"]', '', 3, 22790, '{"meta":{"article":"Статья 9, п. 3","explanation":"Ст. 9 п. 3: «В ином случае ... не обладают статусом секретности».","quote":"по решению Губернатора Федерального округа Российской Федерации путем издания соответствующего нормативного правового акта. В ином случае лица, указанные в настоящем пункте, не обладают статусом секретности;","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q017', NULL, 'vp', 3, 'fz_gostayna', 'Статья 9, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чьими актами определяется порядок допуска должностных лиц и граждан к гостайне?', '[{"id":"u9SRqdnD","text":"Актами Губернатора Федерального округа РФ"},{"id":"qNHk8Rrd","text":"Решениями судов"},{"id":"0fApHCNx","text":"Приказами командиров бригад"},{"id":"UdUvFqaU","text":"Актами Министерства юстиции и судов"}]', '["u9SRqdnD"]', '', 2, 22800, '{"meta":{"article":"Статья 11, ч. 11.4","explanation":"Ч. 11.4.","quote":"Порядок допуска должностных лиц и граждан к государственной тайне определяется актами Губернатора Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q023', NULL, 'medium', 2, 'fz_gostayna', 'Статья 11, ч. 11.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что отбирается у лиц, допущенных к гостайне в особом порядке (без проверочных мероприятий)?', '[{"id":"QTuONo9C","text":"Подписка о невыезде"},{"id":"QWosif6b","text":"Денежный залог"},{"id":"al3Ae6aY","text":"Расписка о предупреждении о неразглашении и об уголовной ответственности"},{"id":"UExiiyZz","text":"Отпечатки пальцев, образцы ДНК и подписка о невыезде с территории ФО"}]', '["al3Ae6aY"]', '', 2, 22810, '{"meta":{"article":"Статья 12, ч. 12.3","explanation":"Ч. 12.3.","quote":"о чем у них отбирается соответствующая расписка.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q025', NULL, 'full', 2, 'fz_gostayna', 'Статья 12, ч. 12.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Куда гражданин может обжаловать решение об отказе в допуске к государственной тайне?', '[{"id":"P6OenKNv","text":"Только в ФСБ"},{"id":"JwH9kOqI","text":"Решение не обжалуется"},{"id":"XWqZXSBD","text":"В вышестоящую организацию или в суд"},{"id":"gC8poFjB","text":"Только Губернатору или в ФСБ"}]', '["XWqZXSBD"]', '', 1, 22820, '{"meta":{"article":"Статья 13","explanation":"Ст. 13.","quote":"Гражданин имеет право обжаловать это решение в вышестоящую организацию или в суд.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gostayna-q026', NULL, 'medium', 1, 'fz_gostayna', 'Статья 13', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'По чьему решению может быть прекращён допуск должностного лица или гражданина к государственной тайне?', '[{"id":"7YWFCvOZ","text":"По решению Законодательного собрания или прокурора"},{"id":"P49yye","text":"По решению любого сослуживца"},{"id":"1oWWL2G1","text":"Только по приговору суда"},{"id":"LeA1uCYB","text":"По решению руководителя государственной организации"}]', '["LeA1uCYB"]', '', 2, 22830, '{"meta":{"article":"Статья 14","explanation":"Ст. 14; решение обжалуется в вышестоящую организацию или в суд (п. 5).","quote":"Допуск должностного лица или гражданина к государственной тайне может быть прекращен по решению руководителя государственной организации в случаях:","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q029', NULL, 'full', 2, 'fz_gostayna', 'Статья 14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На что основываются органы власти, решая вопрос об отнесении незаконно распространённых сведений к гостайне?', '[{"id":"wSSqLmD7","text":"На подготовленных в установленном порядке экспертных заключениях"},{"id":"l04c6wB","text":"На мнении свидетелей"},{"id":"kDHJu4kP","text":"На публикациях в СМИ"},{"id":"Xt8yPqM","text":"На личном убеждении командира, мнении свидетелей и публикациях в СМИ"}]', '["wSSqLmD7"]', '', 3, 22840, '{"meta":{"article":"Статья 15, ч. 15.2","explanation":"Ч. 15.2.","quote":"основываются на подготовленных в установленном порядке экспертных заключениях об отнесении незаконно распространенных сведений к сведениям, составляющим государственную тайну.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gostayna-q031', NULL, 'full', 3, 'fz_gostayna', 'Статья 15, ч. 15.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q031');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто осуществляет контроль за обеспечением защиты государственной тайны?', '[{"id":"I8ty3brb","text":"Командиры бригад"},{"id":"ZGlLzOyZ","text":"Министерство здравоохранения, средства массовой информации и командиры бригад"},{"id":"otIruEMJ","text":"Средства массовой информации"},{"id":"DMJTGrp4","text":"Губернатор Федерального округа РФ, Правительство Федерального округа РФ"}]', '["DMJTGrp4"]', '', 2, 22850, '{"meta":{"article":"Статья 16","explanation":"Ст. 16.","quote":"Контроль за обеспечением защиты государственной тайны осуществляют Губернатор Федерального округа Российской Федерации, Правительство Федерального округа Российской Федерации","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gostayna-q032', NULL, 'vp', 2, 'fz_gostayna', 'Статья 16', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gostayna-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что запрещено работнику государственной организации по правилам служебной этики? Выберите все верные.', '[{"id":"Ikblaltp","text":"Делать грубые и оскорбительные замечания, реплики либо жесты"},{"id":"mztVaZ5g","text":"Делать оскорбительные сравнения (например, с животными или неодушевлёнными предметами)"},{"id":"gJxRDdZw","text":"Использовать в адрес конкретного лица ненормативную лексику, нецензурные выражения"},{"id":"s2gTJnXJ","text":"Обращаться к гражданам на «Вы» и по имени-отчеству при исполнении служебных обязанностей"},{"id":"6kHNFQXm","text":"Носить классические наручные часы"},{"id":"VHE8KdFn","text":"Выдвигать инициативы руководству"}]', '["Ikblaltp","mztVaZ5g","gJxRDdZw"]', '', 1, 22860, '{"meta":{"article":"Статья 2, ч. 2.3","explanation":"Ч. 2.3, пп. 1–3.","quote":"3) делать оскорбительные сравнения (например, с животными или неодушевленными предметами).","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q002~v2', NULL, 'full', 1, 'fz_gossluzhba', 'Статья 2, ч. 2.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q002~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая обязанность руководства в вопросах служебной этики установлена законом о государственной службе?', '[{"id":"TyEkSbxq","text":"Согласовывать каждое решение по этике с прокуратурой субъекта РФ"},{"id":"mLPNeH9K","text":"Запрещать работникам выдвигать инициативы"},{"id":"VQGfES68","text":"Выслушивать инициативу работников и обращать на неё должное внимание"},{"id":"1bbCD4pQ","text":"Публиковать личные данные работников"}]', '["VQGfES68"]', '', 1, 22870, '{"meta":{"article":"Статья 3, ч. 3.2","explanation":"Ч. 3.2; по ч. 3.1 руководство отвечает за благоприятные условия для работы подчинённых.","quote":"Руководство обязано выслушивать инициативу работников и обращать на нее должное внимание.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q003', NULL, 'full', 1, 'fz_gossluzhba', 'Статья 3, ч. 3.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких органах исполняется военная служба по закону о государственной службе? Выберите все верные.', '[{"id":"N3FjanzB","text":"В Вооружённых Силах РФ"},{"id":"PDddRKNW","text":"В органах внутренних дел"},{"id":"eVXniaQ8","text":"В уголовно-исполнительной системе"},{"id":"WufeS5A","text":"В органах прокуратуры"},{"id":"9Lgh8Z8U","text":"В органах государственной охраны"},{"id":"yxED3B3H","text":"В органах федеральной службы безопасности"}]', '["N3FjanzB","9Lgh8Z8U","yxED3B3H"]', '', 2, 22880, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1: военная служба — особый вид федеральной госслужбы.","quote":"Военная служба - особый вид федеральной государственной службы, исполняемой в Вооруженных Силах Российской Федерации, в органах федеральной службы безопасности, органах государственной охраны.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q005~v2', NULL, 'vp', 2, 'fz_gossluzhba', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q005~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком порядке осуществляется прохождение военной службы гражданами?', '[{"id":"QM7Ggj5S","text":"По решению суда"},{"id":"7Y0f2yaS","text":"Только по призыву на срок, установленный приказом"},{"id":"nM1UCZJl","text":"По призыву и в добровольном порядке (по контракту)"},{"id":"D1Olek6h","text":"Только по контракту"}]', '["nM1UCZJl"]', '', 1, 22890, '{"meta":{"article":"Статья 5, ч. 5.2","explanation":"Ч. 5.2.","quote":"1) гражданами - по призыву; 2) гражданами в добровольном порядке (по контракту).","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q006', NULL, 'medium', 1, 'fz_gossluzhba', 'Статья 5, ч. 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как закон оценивает искажение воинских званий, употребление кличек, прозвищ и фамильярное обращение?', '[{"id":"fSrknsQK","text":"Не регулируются законом, только уставом"},{"id":"IxgkI9EU","text":"Несовместимы с понятием воинской чести и достоинством военнослужащего и влекут ответственность"},{"id":"ayKFszBS","text":"Допустимы во внеслужебное время в части"},{"id":"zQO11cnT","text":"Допустимы между военнослужащими одного звания во внеслужебное время, если это не слышат подчинённые"}]', '["IxgkI9EU"]', '', 2, 22900, '{"meta":{"article":"Статья 8, ч. 8.3 п. 3","explanation":"П. 3 ч. 8.3.","quote":"искажение воинских званий, употребление нецензурных слов, кличек и прозвищ, грубость и фамильярное обращение несовместимы с понятием воинской чести и достоинством военнослужащего, влечет за собой ответственность, предусмотренную законодательством.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q008', NULL, 'medium', 2, 'fz_gossluzhba', 'Статья 8, ч. 8.3 п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Начиная с какого воинского звания военнослужащие обязаны пройти военную выучку и иметь военный билет?', '[{"id":"SFBbZyz9","text":"С младшего лейтенанта и старше"},{"id":"8UZgLwg4","text":"С сержанта и старшины и старше"},{"id":"Y9XW633s","text":"С прапорщика"},{"id":"9U5OGy31","text":"С майора"}]', '["SFBbZyz9"]', '', 2, 22910, '{"meta":{"article":"Статья 9, ч. 9.4","explanation":"Ч. 9.4: запрещено повышение без военного билета до младшего лейтенанта и выше.","quote":"Военнослужащие, достигшие воинского звания младший лейтенант и старше, обязаны пройти военную выучку и иметь документ (также - военный билет), подтверждающий прохождение военной подготовки.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q014', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 9, ч. 9.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q014');
