INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто присваивает классные чины прокурорских работников до чина старшего советника юстиции включительно?', '[{"id":"dVLvP47z","text":"Председатель Следственного комитета и его заместители"},{"id":"CsU56RO","text":"Министр юстиции"},{"id":"3a1R65nD","text":"Только Президент РФ"},{"id":"i7lslWJ5","text":"Прокурор субъекта РФ, его первый заместитель и заместители"}]', '["i7lslWJ5"]', '', 3, 22940, '{"meta":{"article":"Статья 17, ч. 17.2","explanation":"Ч. 17.2.","quote":"Классные чины прокурорских работников до чина старшего советника юстиции включительно присваиваются прокурором субъекта Российской Федерации, его первым заместителем и заместителями.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q019', NULL, 'vp', 3, 'fz_gossluzhba', 'Статья 17, ч. 17.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто присваивает специальные звания сотрудникам органов юстиции (СК) до подполковника юстиции включительно?', '[{"id":"oqtWEmVg","text":"Прокурор субъекта РФ"},{"id":"2mK53hPb","text":"Руководитель следственного органа Следственного комитета РФ"},{"id":"BTHmcUol","text":"Министр обороны"},{"id":"fClSBEyC","text":"Губернатор Федерального округа или прокурор субъекта РФ"}]', '["2mK53hPb"]', '', 3, 22950, '{"meta":{"article":"Статья 23, ч. 23.3","explanation":"Ч. 23.3.","quote":"Специальные звания до звания подполковник юстиции включительно присваиваются руководителем следственного органа Следственного комитета Российской Федерации.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q021', NULL, 'medium', 3, 'fz_gossluzhba', 'Статья 23, ч. 23.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто, помимо Председателя Правительства РФ и Губернаторов, присваивает специальные звания уголовно-исполнительной системы?', '[{"id":"RVSfz49","text":"Директор ФСИН России и его заместители"},{"id":"GmFwlCnl","text":"Начальник колонии"},{"id":"nAGdy4Ha","text":"Министр обороны"},{"id":"ONTPqD3o","text":"Генеральный прокурор РФ и его заместители"}]', '["RVSfz49"]', '', 3, 22960, '{"meta":{"article":"Статья 21, ч. 21.4","explanation":"Ч. 21.4.","quote":"Специальные звания присваиваются Председателем Правительства Российской Федерации, Губернаторами Федеральных округов Российской Федерации, директором Федеральной службы исполнения наказаний Российской Федерации и его заместителями.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q022', NULL, 'vp', 3, 'fz_gossluzhba', 'Статья 21, ч. 21.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Может ли сотрудник силовой государственной организации носить форму другого подразделения?', '[{"id":"XQhCs0Yp","text":"Только при наличии акта непосредственного руководителя силовой организации либо акта уполномоченного ФОИВ"},{"id":"Fxx41Xtz","text":"Да, если подразделения относятся к одному министерству и форма имеет те же знаки различия, без каких-либо актов"},{"id":"3ZLoc3sl","text":"Нет, ни при каких условиях"},{"id":"6jtamZhr","text":"Да, всегда во внеслужебное время"}]', '["XQhCs0Yp"]', '', 2, 22970, '{"meta":{"article":"Статья 29, ч. 29.2","explanation":"Ч. 29.2.","quote":"Запрещается ношение формы других подразделений без соответствующего акта непосредственного руководителя государственной силовой организации либо акта уполномоченного федерального органа исполнительной власти.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q025', NULL, 'medium', 2, 'fz_gossluzhba', 'Статья 29, ч. 29.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудники каких организаций вправе пренебречь правилами внешнего вида, установленными законом о государственной службе?', '[{"id":"YvboXD8A","text":"Органов внутренних дел и Росгвардии во внеслужебное время, а также органов прокуратуры и СК"},{"id":"hxIhhPlu","text":"Государственных казённых учреждений, государственных компаний, учреждений здравоохранения"},{"id":"8UdMMq4A","text":"Органов прокуратуры"},{"id":"QP6LMmP","text":"Вооружённых Сил РФ"}]', '["hxIhhPlu"]', '', 2, 22980, '{"meta":{"article":"Статья 29, ч. 29.6","explanation":"Ч. 29.6.","quote":"Сотрудники государственных казенных учреждений, государственных компаний, учреждений здравоохранения имеют право пренебречь правилами внешнего вида и ношения униформы установленными в настоящей статье.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q026', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 29, ч. 29.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В какой форме проводятся процессуальные, следственные действия, кроме неотложных?', '[{"id":"yYehWWzl","text":"В любой одежде по усмотрению служащего, если при нём есть служебное удостоверение или жетон"},{"id":"qMJAPkyo","text":"Исключительно в служебной форме одежды со знаками различия и принадлежности к органу власти"},{"id":"9fYa5EN","text":"Только в гражданском костюме"},{"id":"WkTNzHA1","text":"В спортивной форме подразделения"}]', '["qMJAPkyo"]', '', 3, 22990, '{"meta":{"article":"Статья 30, ч. 30.1","explanation":"Ч. 30.1; исключение из ст. 31 для старших и высших составов не действует.","quote":"Проведение процессуальных, следственных действий, кроме неотложных, проводятся государственными служащими исключительно в служебной форме одежды с знаками различия и принадлежности к органу государственной власти.","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q029', NULL, 'full', 3, 'fz_gossluzhba', 'Статья 30, ч. 30.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q029');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Разрешено ли госслужащему использовать знаки отличия, не идентифицирующие подразделение, в котором он служит?', '[{"id":"4WzIaD72","text":"Разрешено с устного согласия сослуживцев и непосредственного начальника, если знаки отличия похожи на установленные образцы"},{"id":"1BCjttzn","text":"Разрешено только рядовому составу"},{"id":"w059ffvf","text":"Разрешено всегда"},{"id":"8RedHnY0","text":"Запрещено; специализированная форма допускается при оперативных мероприятиях в случаях, предусмотренных законодательством"}]', '["8RedHnY0"]', '', 2, 23000, '{"meta":{"article":"Статья 33","explanation":"Ст. 33.","quote":"Государственным служащим запрещается использовать форменную одежду, знаки отличия, которые не относятся (идентифицируют) подразделение, в котором они проходят службу.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q030', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 33', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является основанием для наложения запрета на работу в госорганизациях без судебного решения по 54-ФЗ?', '[{"id":"u9AF273N","text":"Кража денежных средств работником государственной организации"},{"id":"xw92eGKf","text":"Не отработка 7 дней на руководящих должностях, провал работы на руководящих должностях"},{"id":"IvTAoAg8","text":"Совершение любого административного правонарушения в рабочее время"},{"id":"lIgL1dR","text":"Увольнение по собственному желанию"},{"id":"FSblVUq","text":"Получение одного замечания"},{"id":"te7HSZ5","text":"Кража государственного имущества работником государственной организации"}]', '["u9AF273N","xw92eGKf","te7HSZ5"]', '', 2, 23010, '{"meta":{"article":"Статья 37, ч. 37.1","explanation":"Ч. 37.1.","quote":"2) кража денежных средств работником государственной организации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_gossluzhba-q031~v2', NULL, 'full', 2, 'fz_gossluzhba', 'Статья 37, ч. 37.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q031~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто по закону о государственной службе принимает решение о внесении граждан в реестр уволенных по отрицательным мотивам?', '[{"id":"pUmgtelq","text":"Министр обороны Федерального округа по представлению командиров"},{"id":"G5cIb5nq","text":"Командир воинской части"},{"id":"UDrcVIQ","text":"Председатель Правительства РФ, Губернаторы Федеральных округов РФ"},{"id":"p7zog9yI","text":"Отдел кадров организации"}]', '["UDrcVIQ"]', '', 3, 23020, '{"meta":{"article":"Статья 37, ч. 37.2","explanation":"Ч. 37.2 (ср. ТК ч. 16-1.8 — Губернатор / Генеральный прокурор).","quote":"Решение о внесении граждан в реестр лиц уволенных по отрицательным мотивам на основаниях, определенных настоящей статьей принимает Председатель Правительства Российской Федерации, Губернаторами Федеральных округов Российской Федерации.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q033', NULL, 'vp', 3, 'fz_gossluzhba', 'Статья 37, ч. 37.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязаны сделать ответственные сотрудники, если в госорганизации работает гражданин из реестра уволенных по отрицательным мотивам?', '[{"id":"ZmcjVzRc","text":"Уволить такого гражданина из государственной организации"},{"id":"pr3990W7","text":"Ничего, если он был принят на службу до внесения в реестр"},{"id":"i3zRgoE","text":"Перевести на нижестоящую должность"},{"id":"UZdVqz12","text":"Объявить ему выговор"}]', '["ZmcjVzRc"]', '', 2, 23030, '{"meta":{"article":"Статья 36, ч. 36.2","explanation":"Ч. 36.2.","quote":"В случае нахождения такого гражданина в государственной организации, ответственные сотрудники обязаны уволить такого гражданина из государственной организации.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_gossluzhba-q034', NULL, 'vp', 2, 'fz_gossluzhba', 'Статья 36, ч. 36.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q034');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На какие организации НЕ распространяется запрет работать в госорганизации лицам с непогашенной судимостью по статьям ПК?', '[{"id":"qi0rrEyQ","text":"Органы внутренних дел, Росгвардия и органы уголовно-исполнительной системы"},{"id":"IsLnBcKr","text":"Организации здравоохранения, телерадиовещания, государственные казённые учреждения"},{"id":"aGDIYzkb","text":"Вооружённые Силы и военная полиция"},{"id":"Ai6ODpd","text":"Органы прокуратуры и СК"}]', '["IsLnBcKr"]', '', 3, 23040, '{"meta":{"article":"Статья 36, ч. 36.4–36.5","explanation":"Ч. 36.5.","quote":"Положение части 4 настоящей статьи не распространяются на организации здравоохранения, телерадиовещания, государственные казенные учреждения.","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q035', NULL, 'medium', 3, 'fz_gossluzhba', 'Статья 36, ч. 36.4–36.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое ограничение установлено для ведомственных наград территориальных органов исполнительной власти Федерального округа?', '[{"id":"d5eLbDN","text":"Требуют утверждения прокуратурой"},{"id":"AGXytiz1","text":"Могут вручаться только посмертно"},{"id":"n2yiV3Uq","text":"Не могут вручаться военнослужащим и сотрудникам федеральных органов государственной власти, кроме посмертного награждения"},{"id":"0k7EJgfb","text":"Не могут по статусу и значению превышать соответствующие награды федеральных органов государственной власти"}]', '["0k7EJgfb"]', '', 2, 23050, '{"meta":{"article":"Статья 38, ч. 38.4","explanation":"Ч. 38.4.","quote":"Ведомственные награды территориальных органов исполнительной власти Федерального округа не могут по своему статусу и значению превышать соответствующие ведомственные награды федеральных органов государственной власти.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_gossluzhba-q036', NULL, 'medium', 2, 'fz_gossluzhba', 'Статья 38, ч. 38.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_gossluzhba-q036');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Перемещение каких материальных объектов прямо названо в определении использования воздушного пространства?', '[{"id":"MOHGrH83","text":"Парашютистов"},{"id":"tmlUFCkK","text":"Беспилотных аэростатов"},{"id":"wpiuj0Sa","text":"Воздушных судов"},{"id":"elcWjRb","text":"Наземного транспорта на автомагистралях"},{"id":"9Rf1fz26","text":"Ракет"}]', '["wpiuj0Sa","9Rf1fz26"]', '', 2, 23060, '{"meta":{"article":"Статья 1, ч. 1.2","explanation":"В ч. 1.2 перечислены воздушные суда, ракеты и «другие объекты», а также иная деятельность, связанная с безопасностью воздушного движения.","quote":"осуществляются перемещение в воздушном пространстве различных материальных объектов (воздушных судов, ракет и других объектов), а также другая деятельность, связанная с безопасностью воздушного движения.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q002~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 1, ч. 1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q002~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто является пользователями воздушного пространства?', '[{"id":"CQL4Micj","text":"Только сотрудники силовых структур и Правительства"},{"id":"fLgRiTWH","text":"Только пилоты, имеющие допуск Министерства транспорта"},{"id":"Hcmomp0","text":"Сотрудники государственных организаций, граждане РФ, наделённые правом на осуществление деятельности по использованию воздушного пространства"},{"id":"vGlDrM8P","text":"Любые лица, находящиеся на территории РФ, без ограничений, в том числе иностранные граждане и организации, если они уведомили диспетчера о полёте"}]', '["Hcmomp0"]', '', 1, 23070, '{"meta":{"article":"Статья 2, ч. 2.1","explanation":"Ч. 2.1 называет две группы: сотрудников госорганизаций и граждан РФ, наделённых соответствующим правом.","quote":"2.1. Пользователями воздушного пространства являются сотрудники государственных организаций, граждане Российской Федерации наделенные правом на осуществление деятельности по использованию воздушного пространства.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q003', NULL, 'full', 1, 'fz_vozduh', 'Статья 2, ч. 2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие категории пользователей воздушного пространства выделяет закон об использовании воздушного пространства?', '[{"id":"Hdwc6vr","text":"Журналисты аккредитованных СМИ"},{"id":"Of0VvhVM","text":"Сотрудники иных государственных организаций"},{"id":"VDVmhWpI","text":"Иностранные граждане и лица без гражданства"},{"id":"QqU75Otl","text":"Граждане Российской Федерации"},{"id":"OT2Tw9h","text":"Сотрудники частных охранных предприятий"},{"id":"BaUjBpEO","text":"Члены Правительства РФ, члены Правительства Федерального округа РФ"}]', '["Of0VvhVM","QqU75Otl","BaUjBpEO"]', '', 2, 23080, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Три категории: а) граждане РФ; б) члены Правительства РФ и Правительства ФО; в) сотрудники иных госорганизаций.","quote":"а) граждане Российской Федерации; б) члены Правительства Российской Федерации, члены Правительства Федерального округа Российской Федерации;; в) сотрудники иных государственных организаций.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q004~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q004~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько категорий пользователей воздушного пространства выделяет закон об использовании воздушного пространства?', '[]', '[]', '', 1, 23090, '{"meta":{"article":"Статья 2, ч. 2.2","explanation":"Пункты а), б), в).","quote":"2.2. Выделяются следующие категории пользователей воздушного пространства, требования к которым различны согласно настоящему Федеральному закону:","difficulty":"1"},"answer":3,"tolerance":0,"unit":"категории"}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q005~v2', NULL, 'medium', 1, 'fz_vozduh', 'Статья 2, ч. 2.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q005~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какое воздушное движение предусматривает обеспечить организация использования воздушного пространства?', '[{"id":"Ur28zene","text":"Круглосуточное"},{"id":"05xO4VBH","text":"Регулярное"},{"id":"io339wJa","text":"Скоростное"},{"id":"P8EKK1n","text":"Безопасное"},{"id":"miTeD8Uf","text":"Экономичное"},{"id":"BkdF5PC5","text":"Бесплатное"}]', '["05xO4VBH","P8EKK1n","miTeD8Uf"]', '', 1, 23100, '{"meta":{"article":"Статья 3, ч. 3.1","explanation":"Ч. 3.1: безопасного, экономичного и регулярного воздушного движения.","quote":"3.1. Организация использования воздушного пространства предусматривает обеспечение безопасного, экономичного и регулярного воздушного движения.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q006~v2', NULL, 'full', 1, 'fz_vozduh', 'Статья 3, ч. 3.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q006~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что включает в себя организация использования воздушного пространства?', '[{"id":"7T6vb8VZ","text":"Обслуживание (управление) воздушного движения сотрудниками государственных организаций и гражданами РФ"},{"id":"ZfpWoUOo","text":"Выдачу лицензий пилотам гражданских воздушных судов и их ежегодную аттестацию в Министерстве транспорта"},{"id":"VbxYrHqg","text":"Организацию потоков воздушного движения и безопасности запретных зон"},{"id":"EiMeTzw","text":"Сертификацию посадочных площадок жилых домов"},{"id":"81dDPddz","text":"Регистрацию и учёт частных вертолётов"}]', '["7T6vb8VZ","VbxYrHqg"]', '', 2, 23110, '{"meta":{"article":"Статья 3, ч. 3.2","explanation":"Ч. 3.2 содержит ровно два пункта: а) обслуживание (управление) движения; б) организация потоков и безопасности запретных зон.","quote":"а) обслуживание (управление) воздушного движения сотрудниками государственных организаций и гражданами Российской Федерации; б) организацию потоков воздушного движения и безопасности запретных зон.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q007~v2', NULL, 'vp', 2, 'fz_vozduh', 'Статья 3, ч. 3.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Куда закон об использовании воздушного пространства не допускает посадку воздушных судов (иначе как в порядке, предусмотренном законом)?', '[{"id":"wiwZCLy2","text":"На специализированные объекты взлёта и посадки"},{"id":"R2YD2Gju","text":"На жилые дома"},{"id":"LGzern","text":"На вертолётные площадки больниц"},{"id":"lcrUTJHL","text":"На автомобильные дороги"},{"id":"OjK6EpHV","text":"На автомагистрали"},{"id":"e5X5yfoD","text":"На посадочные площадки государственных организаций"}]', '["R2YD2Gju","lcrUTJHL","OjK6EpHV"]', '', 1, 23120, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Запрет ч. 4.1: автомагистрали, автомобильные дороги, жилые дома.","quote":"Не допускается посадка воздушных судов на автомагистрали, автомобильные дороги, жилые дома иначе как в порядке, предусмотренном настоящим Федеральным законом.","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q009~v2', NULL, 'full', 1, 'fz_vozduh', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q009~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях сотрудники госорганизаций вправе совершить посадку на любые территории и объекты?', '[{"id":"NH3jWl5","text":"Оказание экстренной или неотложной медицинской помощи"},{"id":"nUU3Wjvw","text":"Устное разрешение любого старшего по званию"},{"id":"w7oFJyN","text":"Отсутствие свободной площадки у своей организации"},{"id":"FwpZqqrr","text":"Сокращение времени в пути до места службы"},{"id":"Gvyd4rv6","text":"Вынужденная необходимость в проведении оперативных мероприятий"},{"id":"QPog9Oke","text":"Проведение спасательных операций"}]', '["NH3jWl5","Gvyd4rv6","QPog9Oke"]', '', 2, 23130, '{"meta":{"article":"Статья 4, ч. 4.2","explanation":"Ч. 4.2: оперативные мероприятия, экстренная/неотложная медпомощь, спасательные операции или иные мероприятия по перечню Правительства ФО.","quote":"посадка связана с вынужденной необходимостью в проведении оперативных мероприятий, оказания экстренной или неотложной медицинской помощи, проведении спасательных операций или иных мероприятий","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q010~v2', NULL, 'medium', 2, 'fz_vozduh', 'Статья 4, ч. 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кем устанавливается перечень «иных мероприятий», при которых сотрудник госорганизации вправе посадить воздушное судно на любую территорию?', '[{"id":"vUSTynV","text":"Командиром войсковой части"},{"id":"sriLtGIM","text":"Министерством обороны РФ"},{"id":"3xAbBzr","text":"Правительством Федерального округа Российской Федерации"},{"id":"rkF0UQFz","text":"Губернатором единолично указом о чрезвычайном положении"}]', '["3xAbBzr"]', '', 2, 23140, '{"meta":{"article":"Статья 4, ч. 4.2","explanation":"Конец ч. 4.2.","quote":"иных мероприятий, перечень которых устанавливается Правительством Федерального округа Российской Федерации","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q011', NULL, 'full', 2, 'fz_vozduh', 'Статья 4, ч. 4.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'С каких мест иные граждане РФ вправе осуществлять взлёт и посадку?', '[{"id":"qDwucJc7","text":"С дворовых территорий"},{"id":"QxydFWCb","text":"С посадочных площадок жилых домов"},{"id":"zWFz4Yv6","text":"Со специализированных объектов взлёта и посадки"},{"id":"tgI8jsI2","text":"С охраняемых территорий при наличии пропуска"},{"id":"B4V6uLL7","text":"С КПП войсковых частей"},{"id":"yienaXkY","text":"С автомобильных дорог при отсутствии движения"}]', '["qDwucJc7","QxydFWCb","zWFz4Yv6"]', '', 2, 23150, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"Ч. 4.3 — кроме охраняемых и закрытых территорий.","quote":"4.3. Иные граждане Российской Федерации вправе осуществлять взлет и посадку с посадочных площадок жилых домов, дворовых территорий, специализированных объектов взлета и посадки, кроме охраняемых и закрытых территорий","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q012~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин сажает свой частный вертолёт на крышу жилого дома (не на посадочную площадку). Как это оценивается по закону об использовании воздушного пространства?', '[{"id":"L8z2Rqp","text":"Разрешено при уведомлении в частоту государственных структур"},{"id":"KEceJiM1","text":"Запрещено: посадка воздушных судов в собственности физлиц на жилые дома запрещена"},{"id":"cCDCzo39","text":"Разрешено, если дом не является охраняемой территорией"},{"id":"MQz5lzB","text":"Разрешено, т.к. гражданские пилоты не обязаны уведомлять о посадке"}]', '["KEceJiM1"]', '', 3, 23160, '{"meta":{"article":"Статья 4, ч. 4.3","explanation":"Ч. 4.3 разрешает посадку на посадочные площадки жилых домов, но прямо запрещает посадку частных судов на жилые дома.","quote":"Запрещена посадка воздушных судов в собственности физических лиц на автомагистрали, автомобильные дороги, жилые дома.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q013~v2', NULL, 'vp', 3, 'fz_vozduh', 'Статья 4, ч. 4.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q013~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какие порядки использования воздушного пространства устанавливаются правилами?', '[{"id":"8mV0PJgD","text":"Лицензионный или свободный"},{"id":"QpSxDj","text":"Заявительный или регистрационный"},{"id":"UM1EaxlW","text":"Разрешительный или уведомительный"},{"id":"Ma2Dr3oZ","text":"Разрешительный или запретительный"}]', '["UM1EaxlW"]', '', 1, 23170, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1.","quote":"устанавливается разрешительный или уведомительный порядок использования воздушного пространства.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q014~v2', NULL, 'medium', 1, 'fz_vozduh', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q014~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе выдать разрешение на пролёт над закрытой и охраняемой территорией?', '[{"id":"4hON9Wfr","text":"Руководители территориальных подразделений органов государственной власти и их заместители"},{"id":"sJGtFFSJ","text":"Диспетчер гражданской авиации"},{"id":"uE844Kgh","text":"Губернатор Федерального округа РФ и Вице-губернаторы ФО"},{"id":"D6TbXutJ","text":"Председатель Государственной думы единолично или его заместители"},{"id":"pZBx23tp","text":"Руководители соответствующего федерального органа исполнительной власти"},{"id":"ncIv0lu","text":"Любой пилот госструктуры с допуском"}]', '["4hON9Wfr","uE844Kgh","pZBx23tp"]', '', 3, 23180, '{"meta":{"article":"Статья 5, ч. 5.4","explanation":"Перечень ч. 5.4 также включает уполномоченных руководителей (начальников) подразделений территориальных органов.","quote":"5.4. Разрешение на пролет над закрытой и охраняемой территорией выдается Губернатором Федерального округа Российской Федерации и Вице-губернаторами Федерального округа, руководителями соответствующего федерального органа исполнительной власти, руководителями территориальных подразделений органов государственной власти","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q018~v2', NULL, 'full', 3, 'fz_vozduh', 'Статья 5, ч. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q018~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лиц, которые по общему правилу выдают разрешение на пролёт над закрытой и охраняемой территорией, нет на месте. Кто вправе выдать такое разрешение?', '[{"id":"Hihc676t","text":"Сам пилот, уведомив частоту государственных структур и получив подтверждение от диспетчера"},{"id":"dMRpys8w","text":"Старший по должности сотрудник госорганизации, если это предусмотрено Уставом госорганизации"},{"id":"TJxZrcIT","text":"Никто — пролёт в этом случае запрещён"},{"id":"JQlXyr3D","text":"Любой сотрудник, несущий службу на КПП"}]', '["dMRpys8w"]', '', 2, 23190, '{"meta":{"article":"Статья 5, ч. 5.5","explanation":"Ч. 5.5.","quote":"5.5. В случае отсутствия лиц, указанных в настоящей статье разрешение на пролет над закрытой и охраняемой территорией вправе выдать старший по должности сотрудник государственной организации, если таковое предусмотрено Уставом государственной организации.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q019', NULL, 'full', 2, 'fz_vozduh', 'Статья 5, ч. 5.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите элементы запроса на разрешение о пролёте над запретной зоной в порядке, установленном формой запроса.', '[]', '[]', '', 2, 23200, '{"meta":{"article":"Статья 6, ч. 6.1","explanation":"Форма ч. 6.1.","quote":"[№-вертолета][Состав: “количество пассажиров”] Пилот “Должность/звание” “Имя Фамилия” запрашивает разрешение пролета над запретной зоной ... (Название зоны).","difficulty":"2"},"items":[{"id":"FR2Kk8um","text":"[№-вертолёта]"},{"id":"XeMm59uD","text":"[Состав: «количество пассажиров»]"},{"id":"35MowWLb","text":"Пилот «Должность/звание» «Имя Фамилия»"},{"id":"cPSAC2D","text":"запрашивает разрешение пролёта над запретной зоной … (Название зоны)"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q020~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 6, ч. 6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q020~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой элемент есть в форме запроса о взлёте, но отсутствует в форме запроса на пролёт над запретной зоной?', '[{"id":"O9pfUW55","text":"[№-вертолёта]"},{"id":"g4tdkGV2","text":"[Код доступа]"},{"id":"ag7DfGqq","text":"Имя и фамилия пилота"},{"id":"fSRCoPS8","text":"[Состав: «количество пассажиров»]"}]', '["g4tdkGV2"]', '', 3, 23210, '{"meta":{"article":"Статья 6, ч. 6.1, 6.3","explanation":"Форма 6.3: [№-вертолета]|[Состав][Код доступа] Пилот…; форма 6.1 кода доступа не содержит.","quote":"[№-вертолета]|[Состав: “количество пассажиров”][Код доступа] Пилот “Имя Фамилия” запрашивает разрешение на взлет (посадку) с посадочной площадки структуры … (Название структуры).","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q022~v2', NULL, 'vp', 3, 'fz_vozduh', 'Статья 6, ч. 6.1, 6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q022~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте вид сообщения пилота с ключевой формулировкой по установленной форме.', '[]', '[]', '', 2, 23220, '{"meta":{"article":"Статья 6, ч. 6.1, 6.3, 6.4","explanation":"Запрос — «запрашивает», уведомление — «осуществляет».","quote":"[№-вертолета]|[Состав: “количество пассажиров”][Код доступа] Пилот “Имя Фамилия” осуществляет взлет (посадку) с посадочной площадки структуры … (Название структуры).","difficulty":"2"},"pairs":[{"l":{"id":"Mjp5UQoW","text":"Запрос на пролёт над запретной зоной"},"r":{"id":"IUOuHSym","text":"«запрашивает разрешение пролета над запретной зоной»"}},{"l":{"id":"ypYCXFPv","text":"Запрос о взлёте (посадке)"},"r":{"id":"4ZSv2KhH","text":"«запрашивает разрешение на взлет (посадку) с посадочной площадки структуры»"}},{"l":{"id":"1p4Bg6kG","text":"Уведомление о взлёте и посадке"},"r":{"id":"4WVrBQj","text":"«осуществляет взлет (посадку) с посадочной площадки структуры»"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q023~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 6, ч. 6.1, 6.3, 6.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q023~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Пилот ВС РФ садится на посадочную площадку своей же войсковой части. Нужно ли запрашивать разрешение на посадку?', '[{"id":"D7vMPRS","text":"Требуется всегда, по установленной форме запроса, даже на своей площадке"},{"id":"MxBN7xLu","text":"Не требуется, если иное не установлено Уставом госорганизации"},{"id":"FNimebC","text":"Требуется только при наличии пассажиров"},{"id":"SYXKOfio","text":"Требуется письменное разрешение командира"}]', '["MxBN7xLu"]', '', 2, 23230, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2: при посадке на площадку своей организации разрешение не требуется, если Уставом не установлено иное.","quote":"В случае если посадка осуществляется на посадочную площадку государственной организации, в которой служит (работает) сотрудник разрешение запрашивать не требуется, если иное не установлено Уставом государственной организации.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q025', NULL, 'vp', 2, 'fz_vozduh', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q025');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать пилот госорганизации перед посадкой на посадочную площадку чужой структуры?', '[{"id":"qbkLRMZv","text":"Запросить разрешение на посадку по установленной законом форме"},{"id":"dzOezhKE","text":"Только уведомить о посадке без запроса"},{"id":"pL4AwLDb","text":"Получить разрешение Вице-губернатора"},{"id":"FeYkbUI","text":"Ничего, посадка на площадки госорганизаций свободная для всех"}]', '["qbkLRMZv"]', '', 2, 23240, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 7.2, первое предложение.","quote":"7.2. Перед посадкой на посадочную площадку обязан запросить разрешение на посадку согласно установленной настоящим Федеральным законом форме.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q026', NULL, 'medium', 2, 'fz_vozduh', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q026');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой номер вертолёта закреплён за ВС РФ (Армия) в законе об использовании воздушного пространства?', '[{"id":"oUxty8y9","text":"№-GRF/2209-13"},{"id":"ekC42MrP","text":"№-RNG/2703-41"},{"id":"mavKrJJ9","text":"№-RAF/4145-40"},{"id":"7XPOzDa2","text":"№-MOI/1001-42"}]', '["mavKrJJ9"]', '', 1, 23250, '{"meta":{"article":"Статья 8","explanation":"Таблица ст. 8.","quote":"| ВС РФ (Армия) | №-RAF/4145-40 | T/L **/ |","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q028~v2', NULL, 'full', 1, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q028~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте структуру с номером её вертолёта по закону об использовании воздушного пространства.', '[]', '[]', '', 2, 23260, '{"meta":{"article":"Статья 8","explanation":"Таблица ст. 8.","quote":"| ГУ МВД (Полиция) | №-MOI/1001-42 | T/L **/ |","difficulty":"2"},"pairs":[{"l":{"id":"37hnT0W5","text":"Правительство"},"r":{"id":"zF6XQlAX","text":"№-GRF/2209-13"}},{"l":{"id":"YVFVxbv","text":"ГУ МВД (Полиция)"},"r":{"id":"bH7tBwIk","text":"№-MOI/1001-42"}},{"l":{"id":"V9t0ltV","text":"ФСВНГ (Росгвардия)"},"r":{"id":"eXvjS4Xv","text":"№-RNG/2703-41"}},{"l":{"id":"jtNHffb6","text":"Москва-Live"},"r":{"id":"Nn791ERS","text":"№-MLV/0810-11"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q029~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q029~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько государственных структур перечислено в таблице номеров вертолётов и кодов доступа закона об использовании воздушного пространства?', '[]', '[]', '', 2, 23270, '{"meta":{"article":"Статья 8","explanation":"Правительство, ФСБ, ГУ МВД, ФСВНГ, ВС РФ, ОМС, Москва-Live.","quote":"Каждая государственная структура имеет свой вертолет и свои коды доступа на осуществления взлета и посадки.","difficulty":"2"},"answer":7,"tolerance":0,"unit":"структур"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q030~v2', NULL, 'vp', 2, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q030~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для какой структуры в законе об использовании воздушного пространства код доступа указан открыто как «T/L 8800/3g»?', '[{"id":"MyQGkxyW","text":"ВС РФ (Армия)"},{"id":"0mlyD4DF","text":"Москва-Live"},{"id":"UsLR7S6","text":"ФСБ"},{"id":"6Blv7A1v","text":"ОМС"}]', '["6Blv7A1v"]', '', 3, 23280, '{"meta":{"article":"Статья 8","explanation":"У ОМС — 8800/3g, у Москва-Live — 5535/2g; у остальных код скрыт (**/).","quote":"| ОМС | №RMS/2106-12 | T/L 8800/3g |","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fz_vozduh-q031~v2', NULL, 'medium', 3, 'fz_vozduh', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q031~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каким вертолётам запрещено находиться в воздушном пространстве РФ по закону об использовании воздушного пространства?', '[{"id":"7FoVAXjO","text":"Вертолётам без пассажиров на борту"},{"id":"Wr64G0d","text":"Вертолётам госструктур, не предупредившим в частоту «Государственные структуры» о взлёте или посадке"},{"id":"cBbzvWr","text":"Вертолётам, не имеющим кода доступа ОМС"},{"id":"jzF1kK8i","text":"Любым гражданским вертолётам, взлетевшим без уведомления в частоту «Государственные структуры»"}]', '["Wr64G0d"]', '', 2, 23290, '{"meta":{"article":"Статья 9","explanation":"Ст. 9.","quote":"В воздушном пространстве Российской Федерации запрещено находиться вертолетам государственных структур не предупредивших в частоту “Государственные структуры” о взлете или посадке.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q032', NULL, 'full', 2, 'fz_vozduh', 'Статья 9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q032');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Вертолёт госструктуры взлетел без уведомления. Расположите действия сотрудников силовых органов в порядке, установленном законом.', '[]', '[]', '', 2, 23300, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Ч. 11.1: сначала требование о посадке, огонь — только при неподчинении.","quote":"11.1. В случае, если уведомления на взлет не осуществлялось, сотрудники силовых государственных органов выдвигают требование о посадке воздушного судна, в случае неподчинения законным требованиям - разрешается открытие огня на поражение","difficulty":"2"},"items":[{"id":"5B0m7tcS","text":"Установить, что уведомление о взлёте не осуществлялось"},{"id":"hEaKbO2","text":"Выдвинуть требование о посадке воздушного судна"},{"id":"ucLkY5mw","text":"При неподчинении законным требованиям — открыть огонь на поражение"}],"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fz_vozduh-q034~v2', NULL, 'full', 2, 'fz_vozduh', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q034~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Несанкционированно взлетевший вертолёт находится над запретной территорией (В/Ч). Что вправе сделать сотрудники правоохранительных органов по закону об использовании воздушного пространства?', '[{"id":"hsCWlGTX","text":"Только сообщить в частоту и ждать посадки"},{"id":"9kaO1fZm","text":"Открыть огонь лишь после разрешения Губернатора"},{"id":"m1afxCm9","text":"Открыть огонь на поражение"},{"id":"8DsDpURG","text":"Только зафиксировать номер и составить протокол"}]', '["m1afxCm9"]', '', 3, 23310, '{"meta":{"article":"Статья 11, ч. 11.2","explanation":"Ч. 11.2 не содержит условия о предварительном требовании посадки (в отличие от ч. 11.1).","quote":"11.2. В случае, если несанкционированно взлетевший вертолет находится над запретной территорией, сотрудники правоохранительных государственных органов вправе открыть огонь на поражение.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fz_vozduh-q035~v2', NULL, 'vp', 3, 'fz_vozduh', 'Статья 11, ч. 11.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fz_vozduh-q035~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для чего вводится чрезвычайное положение по ФКЗ об особых правовых режимах?', '[{"id":"9QgUshvt","text":"Только для проведения выборов в особом порядке"},{"id":"fsyGyFUw","text":"Только для отражения агрессии против РФ и для мобилизации граждан на военную службу в случае непосредственной угрозы нападения"},{"id":"OeRNXT6M","text":"Для предотвращения незаконной деятельности, либо устранения результатов террористических актов, либо катастроф различного характера"},{"id":"kt5kxG1D","text":"Для мобилизации граждан на военную службу"}]', '["OeRNXT6M"]', '', 1, 23320, '{"meta":{"article":"Статья 1, ч. 1.1","explanation":"Ч. 1.1.","quote":"1.1. Чрезвычайное положение – положение, вводимое на территории всей Российской Федерации или в ее отдельных местностях для предотвращения незаконной деятельности, либо устранения результатов террористических актов, либо катастроф различного характера.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q001', NULL, 'medium', 1, 'fkz_rezhimy', 'Статья 1, ч. 1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие обстоятельства относятся к основаниям введения чрезвычайного положения?', '[{"id":"T2rY3bNO","text":"Попытка насильственного изменения конституционного строя, захвата власти, теракты"},{"id":"eFiIMMWW","text":"Ухудшение криминогенной обстановки"},{"id":"SkSC3wsd","text":"Агрессия против РФ или непосредственная угроза агрессии"},{"id":"lEk2za8m","text":"Участившиеся случаи хищения государственного имущества"},{"id":"re5KFuqy","text":"Похищение человека, захват заложника"},{"id":"IeRzIpC4","text":"Проведение рейда в отношении преступной группировки"},{"id":"IvgqaEjB","text":"ЧС природного и/или технического характера, требующие масштабных аварийно-спасательных работ"}]', '["T2rY3bNO","eFiIMMWW","lEk2za8m","IvgqaEjB"]', '', 2, 23330, '{"meta":{"article":"Статья 3","explanation":"Агрессия — основание военного положения (ч. 13.1), похищение и рейд — основания КТО (ч. 18.2).","quote":"1) ухудшение криминогенной обстановки на территории Российской Федерации или отдельных её субъектов; 2) участившиеся случаи хищения государственного имущества;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q007~v2', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На кого в период ЧП возлагается руководство действиями правоохранительных, военных и иных госструктур?', '[{"id":"QxB8Zp60","text":"На ФСБ с прямым подчинением Губернатору ФО"},{"id":"Gdu7uW","text":"На органы прокуратуры"},{"id":"LOp3HrL","text":"На коменданта Московского Кремля"},{"id":"KyNpAeK3","text":"На Министерство обороны и военных комендантов"}]', '["QxB8Zp60"]', '', 3, 23340, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1.","quote":"возлагается на Федеральную службу безопасности с прямым подчинением Губернатору Федерального округа Российской Федерации.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q008', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы исключены из-под руководства ФСБ в период ЧП?', '[{"id":"qBCD5aR","text":"Органы внутренних дел"},{"id":"vgh8ur8P","text":"Военные структуры"},{"id":"873vkZgm","text":"Органы Следственного Комитета"},{"id":"DzTaUG5","text":"Медицинские структуры"},{"id":"9S4OlnvL","text":"Органы прокуратуры"}]', '["873vkZgm","9S4OlnvL"]', '', 3, 23350, '{"meta":{"article":"Статья 4, ч. 4.1","explanation":"Ч. 4.1: «за исключением органов Следственного Комитета, органов прокуратуры».","quote":"руководство действиями всех правоохранительных, за исключением органов Следственного Комитета, органов прокуратуры, гражданских, медицинских, военных и иных государственных (федеральных) структур","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q009~v2', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 4, ч. 4.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q009~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Для чего при чрезвычайном положении применяются Вооружённые Силы РФ, другие войска, воинские формирования и органы?', '[{"id":"T2nziA","text":"Для отражения или предотвращения агрессии против суверенитета РФ"},{"id":"ep7R8eaI","text":"Для проведения следственных действий и охраны КПП органов внутренних дел"},{"id":"ZTMJDAWK","text":"Для сопровождения грузов частных организаций"},{"id":"lCvG8cDD","text":"Для охраны КПП органов внутренних дел"}]', '["T2nziA"]', '', 2, 23360, '{"meta":{"article":"Статья 5, ч. 5.1","explanation":"Ч. 5.1.","quote":"применяются для отражения или предотвращения агрессии против суверенитета Российской Федерации","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q011', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 5, ч. 5.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Силы и средства каких органов используются для обеспечения режима ЧП?', '[{"id":"0ZFDA5QB","text":"Федеральных органов безопасности"},{"id":"5u3u9d","text":"Политических партий"},{"id":"lKgGadya","text":"Вооружённых сил РФ"},{"id":"KeAZoUBG","text":"Органов внутренних дел"},{"id":"6n9f3yhA","text":"Частных охранных предприятий"},{"id":"LOfGf8yQ","text":"Средств массовой информации"},{"id":"YjGlRyuL","text":"Войск национальной гвардии"}]', '["0ZFDA5QB","lKgGadya","KeAZoUBG","YjGlRyuL"]', '', 2, 23370, '{"meta":{"article":"Статья 5, ч. 5.2","explanation":"Ч. 5.2 также называет силы и средства государственных медицинских учреждений.","quote":"5.2. Для обеспечения режима чрезвычайного положения используются силы и средства органов внутренних дел, федеральных органов безопасности, войск национальной гвардии Российской Федерации, вооруженные силы Российской Федерации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q012~v2', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 5, ч. 5.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Где госсиловые структуры вправе обыскивать личные вещи, транспорт и имущество граждан в период ЧП?', '[{"id":"jbjXEzs","text":"Везде без ограничений по территории"},{"id":"HzOSIDRQ","text":"Только на территории войсковых частей"},{"id":"L09DOfgB","text":"Только в жилищах граждан по решению суда и на территории войсковых частей"},{"id":"rfMB0nDB","text":"На КПП и в подконтрольных районах, объявленных указом Губернатора ФО"}]', '["rfMB0nDB"]', '', 2, 23380, '{"meta":{"article":"Статья 5, ч. 5.3","explanation":"Ч. 5.3.","quote":"на контрольно-пропускных пунктах и подконтрольных районов, объявленных указом Губернатора Федерального округа Российской Федерации.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q013', NULL, 'vp', 2, 'fkz_rezhimy', 'Статья 5, ч. 5.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В какой мере могут ограничиваться права граждан в период ЧП?', '[{"id":"xFzVPFb3","text":"Только по решению суда в каждом отдельном случае и не более чем на 48 часов, независимо от угрозы безопасности страны"},{"id":"R1MKKn4O","text":"Без каких-либо пределов"},{"id":"rxyK2ead","text":"Только в отношении иностранных граждан"},{"id":"Szdo3QxE","text":"В той мере, в какой это необходимо для обеспечения обороны страны и безопасности суверенитета государства"}]', '["Szdo3QxE"]', '', 3, 23390, '{"meta":{"article":"Статья 6","explanation":"Ст. 6; на граждан и организации могут возлагаться дополнительные обязанности.","quote":"могут в той мере, в какой это необходимо для обеспечения обороны страны и безопасности суверенитета государства, ограничиваться права и свобода граждан Российской Федерации","difficulty":"3"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q015', NULL, 'full', 3, 'fkz_rezhimy', 'Статья 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры может предусматривать указ о введении ЧП?', '[{"id":"FlmR2vRe","text":"Приостановление деятельности частных организаций"},{"id":"Ej9pqJAX","text":"Введение карантина"},{"id":"IFXg5Vpa","text":"Принудительное перемещение граждан на территории без ЧП"},{"id":"ACJNwHio","text":"Задержание и арест граждан за нарушение указов"},{"id":"3adPBbWY","text":"Ограничение движения транспортных средств и их обыск"},{"id":"4ilPcqEh","text":"Введение военной цензуры"},{"id":"AmAbq3Tv","text":"Проверка документов, личный обыск, обыск вещей, жилища и ТС"}]', '["FlmR2vRe","Ej9pqJAX","3adPBbWY","AmAbq3Tv"]', '', 2, 23400, '{"meta":{"article":"Статья 7","explanation":"Пп. 5, 6, 9, 11 ст. 7; перемещение граждан, военная цензура и задержание/арест — меры военного положения (пп. 7–9 ст. 14).","quote":"5) ограничение движения транспортных средств и осуществление их обыска; 6) приостановление деятельности частных организаций;","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q016~v2', NULL, 'medium', 2, 'fkz_rezhimy', 'Статья 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q016~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая мера в отношении СМИ предусмотрена ФКЗ при чрезвычайном положении?', '[{"id":"yjjT78dc","text":"Передача СМИ в управление ФСБ"},{"id":"iQ4CPHF","text":"Ограничение свободы печати путём предварительной цензуры, изъятие/арест печатной продукции, особый порядок аккредитации журналистов"},{"id":"SipIcrYh","text":"Введение военной цензуры, передача всех СМИ в управление ФСБ России и использование СМИ исключительно для нужд обороны государства"},{"id":"W7cEMGcv","text":"Полный запрет деятельности всех СМИ"}]', '["iQ4CPHF"]', '', 3, 23410, '{"meta":{"article":"Статья 7, п. 7","explanation":"П. 7 ст. 7; военная цензура — п. 9 ст. 14 (военное положение).","quote":"7) ограничение свободы печати и других средств массовой информации путем введения предварительной цензуры с указанием условий и порядка ее осуществления","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q017', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 7, п. 7', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Деятельность каких политических партий и общественных объединений может быть приостановлена при ЧП?', '[{"id":"CfeOG7x","text":"Только зарегистрированных менее года назад или не прошедших перерегистрацию в Минюсте"},{"id":"EThIFBd","text":"Которые препятствуют устранению обстоятельств, послуживших основанием для введения ЧП"},{"id":"gAVgoonQ","text":"Любых без исключения"},{"id":"fVKMM4oV","text":"Только ведущих агитацию в день голосования"}]', '["EThIFBd"]', '', 3, 23420, '{"meta":{"article":"Статья 7, п. 8","explanation":"П. 8 ст. 7.","quote":"8) приостановление деятельности политических партий и иных общественных объединений, которые препятствуют устранению обстоятельств, послуживших основанием для введения чрезвычайного положения;","difficulty":"3"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q018', NULL, 'medium', 3, 'fkz_rezhimy', 'Статья 7, п. 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае Губернатор вправе приостановить действие правовых актов органов госвласти на территории ЧП?', '[{"id":"Q80j1C1","text":"В любом случае по своему усмотрению"},{"id":"NQsXPD7B","text":"Только по представлению прокурора"},{"id":"DLLFOjT4","text":"Если они противоречат указу Губернатора о введении ЧП на данной территории"},{"id":"nUfkn4HW","text":"Только с согласия Законодательного собрания ФО и прокурора субъекта РФ"}]', '["DLLFOjT4"]', '', 2, 23430, '{"meta":{"article":"Статья 8","explanation":"Ст. 8.","quote":"в случае противоречия этих актов указу Губернатора Федерального округа Российской Федерации о введении на данной территории чрезвычайного положения","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q019', NULL, 'medium', 2, 'fkz_rezhimy', 'Статья 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие полномочия имеет комендант территории ЧП?', '[{"id":"UqbbW5x","text":"Издаёт приказы и распоряжения, обязательные для всех организаций, граждан и командиров силовых органов"},{"id":"gH1byG2","text":"Назначает судей на территории ЧП и утверждает приговоры по делам о нарушении режима ЧП"},{"id":"natxwKIh","text":"Продлевает ЧП свыше 48 часов"},{"id":"hSCnOPz","text":"Отменяет указ Губернатора о ЧП"},{"id":"ZMHzlQ7b","text":"Оповещает население через СМИ о порядке выполнения мер"},{"id":"9cLzMTNr","text":"Выдворяет за пределы территории лиц, нарушающих режим ЧП"},{"id":"ZZqDU0K5","text":"Определяет особый режим въезда и выезда"}]', '["UqbbW5x","ZMHzlQ7b","9cLzMTNr","ZZqDU0K5"]', '', 2, 23440, '{"meta":{"article":"Статья 10, ч. 10.2","explanation":"Ч. 10.2, пп. 1–4.","quote":"3) выдворяет в установленном порядке за пределы территории, на которой введено чрезвычайное положение, лиц, нарушающих режим чрезвычайного положения;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q020~v2', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 10, ч. 10.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q020~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кому подчиняется комендант территории ЧП и обязательно ли его назначение?', '[{"id":"wxnEXOHt","text":"Подчиняется руководителю УФСБ и Министру обороны; назначение коменданта обязательно в каждом случае введения ЧП"},{"id":"5jixFZqv","text":"Подчиняется Министру обороны; назначение обязательно"},{"id":"EOXLqhru","text":"Подчиняется Законодательному собранию; назначается им"},{"id":"NFJ09u7B","text":"Находится в прямом подчинении Губернатора ФО; Губернатор вправе не назначать коменданта и выполнять его функции сам"}]', '["NFJ09u7B"]', '', 2, 23450, '{"meta":{"article":"Статья 10, ч. 10.3, 10.4","explanation":"Ч. 10.3, 10.4.","quote":"10.4. Губернатор Федерального округа Российской Федерации вправе не назначать коменданта территории, на которой введено чрезвычайное положение, и выполнять его функции самостоятельно.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q021', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 10, ч. 10.3, 10.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В каком случае Губернатор ФО вводит военное положение по ФКЗ об особых правовых режимах?', '[{"id":"peVTooxg","text":"При ухудшении криминогенной обстановки или массовых беспорядках в ФО"},{"id":"MIXTFeOa","text":"В случае агрессии против РФ или непосредственной угрозы агрессии"},{"id":"m58Nu96x","text":"При ЧС природного характера"},{"id":"lpzaf4a","text":"При захвате заложника"}]', '["MIXTFeOa"]', '', 1, 23460, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"Ч. 11.1; иные причины — ч. 13.2.","quote":"Губернатором Федерального округа Российской Федерации в случае агрессии против Российской Федерации или непосредственной угрозы агрессии.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q022', NULL, 'full', 1, 'fkz_rezhimy', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какова цель введения военного положения?', '[{"id":"ZHWB4niE","text":"Создание условий для отражения или предотвращения агрессии против РФ"},{"id":"8ntEIFbj","text":"Пресечение террористического акта и минимизация его последствий"},{"id":"Zn7NGS4C","text":"Обеспечение проведения выборов"},{"id":"Ga70Qnw","text":"Устранение последствий катастроф"}]', '["ZHWB4niE"]', '', 1, 23470, '{"meta":{"article":"Статья 11, ч. 11.2","explanation":"Ч. 11.2.","quote":"11.2. Целью введения военного положения является создание условий для отражения или предотвращения агрессии против Российской Федерации.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q023', NULL, 'medium', 1, 'fkz_rezhimy', 'Статья 11, ч. 11.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q023');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Могут ли в период военного положения применяться меры и временные ограничения, предусмотренные для чрезвычайного положения?', '[{"id":"Eh1y8WRU","text":"Только после утверждения Генеральным прокурором"},{"id":"GPtry0Lj","text":"Нет, режимы взаимоисключающие"},{"id":"8ejdf9sZ","text":"Только меры, связанные с карантином"},{"id":"envgz4dv","text":"Да, ФКЗ прямо это допускает"}]', '["envgz4dv"]', '', 3, 23480, '{"meta":{"article":"Статья 11, ч. 11.4","explanation":"Ч. 11.4.","quote":"в том числе применяя меры и временные ограничения предусмотренные для чрезвычайного положения.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q024~v2', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 11, ч. 11.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q024~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите этапы введения военного положения в порядке, установленном ФКЗ.', '[]', '[]', '', 2, 23490, '{"meta":{"article":"Статья 12, ч. 12.1–12.4","explanation":"Ч. 12.1–12.4.","quote":"12.3. Указ Губернатора Федерального округа Российской Федерации о введении военного положения незамедлительно передается на утверждение Законодательным Собранием Федерального округа.","difficulty":"2"},"items":[{"id":"UgjiHOO","text":"Губернатор ФО издаёт указ о введении военного положения"},{"id":"oahsVqNV","text":"Губернатор незамедлительно сообщает о введении Законодательному Собранию ФО"},{"id":"bVckyYev","text":"Указ незамедлительно передаётся на утверждение Законодательным Собранием ФО"},{"id":"phj6K5rl","text":"Если указ не утверждён — он прекращает действие по истечении 24 часов"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-fkz_rezhimy-q025~v2', NULL, 'medium', 2, 'fkz_rezhimy', 'Статья 12, ч. 12.1–12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q025~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что является иными причинами для введения военного положения?', '[{"id":"ni16gba","text":"ЧС технического характера"},{"id":"ZGPSDbZc","text":"Недостижение целей введения режима ЧП"},{"id":"EkzCUEV","text":"Похищение человека"},{"id":"1j73Q8ux","text":"Попытка совершения государственного переворота"},{"id":"K32daa4U","text":"Угроза жизни высших чинов госструктур, Правительства ФО или Губернатора"},{"id":"ruwtttRt","text":"Участившиеся случаи хищения госимущества"}]', '["ZGPSDbZc","1j73Q8ux","K32daa4U"]', '', 2, 23500, '{"meta":{"article":"Статья 13, ч. 13.2","explanation":"Ч. 13.2 (также п. 3 — повышенная активность криминогенной организации, подрывающая безопасность). Хищения и ЧС — основания ЧП (ст. 3), похищение — КТО.","quote":"1) попытка совершения государственного переворота; 2) угроза жизни высших чинов государственных структур, Правительства Федерального округа или Губернатора Федерального округа Российской Федерации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q028~v2', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 13, ч. 13.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q028~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры применяются на территории военного положения и при этом не названы в перечне мер чрезвычайного положения?', '[{"id":"n4WlgURt","text":"Приостановление деятельности частных организаций"},{"id":"FFuaA16Q","text":"Задержание и арест граждан при нарушении запретов, установленных указами"},{"id":"EURDwPJ","text":"Принудительное и контролируемое перемещение граждан"},{"id":"VUS5qXS6","text":"Введение карантина"},{"id":"Ybhqc37L","text":"Запрещение митингов и забастовок"},{"id":"udmZKZ1m","text":"Ограничение движения транспортных средств и их обыск"},{"id":"W8yB4fjU","text":"Введение военной цензуры"}]', '["FFuaA16Q","EURDwPJ","W8yB4fjU"]', '', 3, 23510, '{"meta":{"article":"Статья 14","explanation":"Пп. 7, 8, 9 ст. 14; остальные варианты есть в ст. 7.","quote":"7) задержание и арест граждан, в случае нарушения запретов и ограничений, установленных указами Губернатора Федерального округа Российской Федерации на территории, на которой введено военное положение;","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-fkz_rezhimy-q029~v2', NULL, 'vp', 3, 'fkz_rezhimy', 'Статья 14', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q029~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Охрана каких объектов усиливается при военном положении?', '[{"id":"OBYIAOKs","text":"Только частных охраняемых объектов"},{"id":"CNAxMLcN","text":"Только объектов Московского Кремля, избирательных участков и частных охраняемых объектов, а также зданий органов местного самоуправления"},{"id":"gtNhdwCD","text":"Только избирательных участков"},{"id":"BIVzZLPt","text":"Военных, важных государственных и специальных объектов, объектов жизнеобеспечения, транспорта, связи, энергетики и повышенной опасности"}]', '["BIVzZLPt"]', '', 2, 23520, '{"meta":{"article":"Статья 14, п. 1","explanation":"П. 1 ст. 14.","quote":"охраны военных, важных государственных и специальных объектов, объектов, обеспечивающих жизнедеятельность населения, функционирование транспорта, коммуникаций и связи, объектов энергетики","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz_rezhimy-q030', NULL, 'full', 2, 'fkz_rezhimy', 'Статья 14, п. 1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz_rezhimy-q030');
