INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к основным обязанностям подразделений ГУ ВП по уставу? Выберите все верные.', '[{"id":"dtPKabKj","text":"Патрулирование и задержание лиц, самовольно покинувших воинскую часть"},{"id":"j3afLDl","text":"Проведение поставок вооружения в адрес других госструктур"},{"id":"Deh5c0F","text":"Выдача военных билетов призывникам и постановка на учёт"},{"id":"XGcEGui","text":"Охрана КПП силами ВП вместо роты охраны и обеспечения"},{"id":"KVb4nhuT","text":"Предотвращение торговли оружием, похищенным со складов ВС РФ"},{"id":"JYbj4UIi","text":"Обыск военнослужащих для обнаружения кражи или вноса запрещённых предметов"}]', '["dtPKabKj","KVb4nhuT","JYbj4UIi"]', '', 2, 23650, '{"meta":{"article":"Внутренний устав, п. 6.51 (ч. III гл. VI)","explanation":"П. 6.51 «а», «в»: патрулирование, задержание самовольно покинувших часть, предотвращение торговли похищенным оружием, обыск военнослужащих.","quote":"проведение патрулирования и задержание лиц, покинувших воинскую часть самовольно, а также предотвращение торговли оружием, похищенным со складов Вооруженных Сил Российской Федерации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-007~v2', 'r6-gu-vp-obyazannosti', 'vp', 2, 'vu', 'Внутренний устав, п. 6.51 (ч. III гл. VI)', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-007~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какое подразделение отвечает за содержание на гауптвахте военнослужащих, подвергнутых дисциплинарному аресту?', '[{"id":"RCTk5CS9","text":"Военная комендатура"},{"id":"58P3eY3L","text":"Рота охраны и обеспечения"},{"id":"gX4Z3tyq","text":"Медицинская рота"},{"id":"aLk1VqOs","text":"Батальон военной полиции"}]', '["RCTk5CS9"]', '', 2, 23660, '{"meta":{"article":"Внутренний устав, п. 6.55 «е»","explanation":"П. 6.55 «е»: Военная комендатура отвечает за содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту.","quote":"содержание военнослужащих на гауптвахте, подвергнутых дисциплинарному аресту","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-008~v2', 'r6-gu-vp-gauptvahta-komendatura', 'vp', 2, 'vu', 'Внутренний устав, п. 6.55 «е»', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-008~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Как 52-ФЗ «Об обороне» определяет право ВС на задержание граждан в мирное время?', '[{"id":"8bqkT1hZ","text":"Задержание в любой точке Федерального округа с последующим арестом и содержанием задержанного силами Вооружённых Сил"},{"id":"nR9iGPqB","text":"Задержание только при введении военного положения"},{"id":"rWKndyQp","text":"Задержание только военнослужащих, гражданские лица задержанию не подлежат"},{"id":"xCUfYm9m","text":"Задержание на подведомственной территории воинской части с дальнейшей передачей задержанных правоохранительным органам"}]', '["xCUfYm9m"]', '', 2, 23670, '{"meta":{"article":"52-ФЗ, статья 12, ч. 12.1, п. 11","explanation":"П. 11 ч. 12.1 ст. 12 52-ФЗ: на подведомственной территории воинской части в мирное время, с передачей правоохранительным органам.","quote":"производить задержания граждан в случаях, предусмотренных действующим законодательством на подведомственной территории воинской части Вооруженных Сил в период мирного времени с дальнейшей передачей задержанных правоохранительным органам","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-009', 'r6-fz52-zaderzhanie-peredacha', 'vp', 2, 'fz_oborona', '52-ФЗ, статья 12, ч. 12.1, п. 11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие права прямо предоставлены Вооружённым Силам законом «Об обороне»? Выберите все верные.', '[{"id":"WYJiCze","text":"Самостоятельно назначать гражданам административные штрафы на территории города и области по КоАП"},{"id":"qLQ5kSkS","text":"Выносить приговоры по уголовным делам в отношении гражданских лиц"},{"id":"vNmrOfyt","text":"Доставлять граждан в служебное помещение правоохранительных органов в целях передачи задержанного"},{"id":"ct4LPvRm","text":"Принимать необходимые меры по охране места совершения предполагаемого преступления до прибытия правоохранительных органов"},{"id":"nhc9kW6e","text":"Обыскивать жилища граждан без ордера на территории города"},{"id":"tG63MYsK","text":"Производить личный обыск граждан в пунктах пропуска на охраняемых важных государственных объектах"}]', '["vNmrOfyt","ct4LPvRm","tG63MYsK"]', '', 3, 23680, '{"meta":{"article":"52-ФЗ, статья 12, ч. 12.1","explanation":"П. 3, 4, 6 ч. 12.1 ст. 12 52-ФЗ. Приговоры и обыск жилищ без ордера не предусмотрены.","quote":"принимать необходимые меры по охране места совершения предполагаемого преступления до прибытия правоохранительными органами … производить личный обыск граждан в пунктах пропуска на охраняемых важных государственных объектах … доставлять граждан в служебное помещение правоохранительных органов в целях передачи задержанного сотрудникам правоохранительных органов","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-010~v2', 'r6-fz52-prava', 'vp', 3, 'fz_oborona', '52-ФЗ, статья 12, ч. 12.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-010~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая территория войсковой части является закрытой для общего пользования и посещения по 86-ФЗ?', '[{"id":"3kPj2DI","text":"Только территория в радиусе 50 метров от казармы"},{"id":"HGZ1RZP","text":"Только здание штаба, склады вооружения и казармы, а также КПП, плац и парковка внутри части"},{"id":"teh8cdzM","text":"Вся территория, огороженная сплошным периметром забора, включая здания, крыши и иные объекты"},{"id":"K1RaaHPI","text":"Только КПП и парковка перед ним"}]', '["teh8cdzM"]', '', 1, 23690, '{"meta":{"article":"86-ФЗ, статья 20, ч. 20.1","explanation":"Ч. 20.1 ст. 20 86-ФЗ: закрыта вся территория внутри сплошного периметра забора.","quote":"Территории войсковых частей, огражденные сплошным периметром забора, то есть вся территория, здания, крыши, иные объекты и пространство в закрытой сплошным периметром забора территории","difficulty":"1"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-011', 'r6-fz86-zakrytaya-vch', 'vp', 1, 'fz_territorii', '86-ФЗ, статья 20, ч. 20.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что относится к охраняемым (а не закрытым) территориям ВС РФ по закону о закрытых и охраняемых территориях? Выберите все верные.', '[{"id":"9Au0nRed","text":"Военные комиссариаты"},{"id":"o09PEerV","text":"Подъездной участок к КПП на территорию Войсковой части №12132"},{"id":"BVPMvTRV","text":"Казарма войсковой части"},{"id":"tw1oux0j","text":"Крыши зданий внутри периметра части и крыши КПП"},{"id":"TNG7ReA1","text":"Плац войсковой части"},{"id":"gPawmkUr","text":"Контрольно-пропускные пункты войсковых частей и парковочные комплексы перед ними"}]', '["9Au0nRed","o09PEerV","gPawmkUr"]', '', 2, 23700, '{"meta":{"article":"86-ФЗ, статья 20, ч. 20.2","explanation":"Ч. 20.2 ст. 20 86-ФЗ. Казарма и крыши внутри периметра — закрытая территория (ч. 20.1).","quote":"1) контрольно-пропускные пункты войсковых частей и парковочные комплексы перед ними; 2) военные комиссариаты; 3) подъездной участок к КПП на территорию Войсковой части №12132.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-012~v2', 'r6-fz86-ohranyaemaya-vs', 'vp', 2, 'fz_territorii', '86-ФЗ, статья 20, ч. 20.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-012~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'На что уполномочены сотрудники, охраняющие территорию с пропускным режимом? Выберите все верные.', '[{"id":"p2wRpleb","text":"При отказе от обыска — сразу арестовать лицо на 30 минут"},{"id":"t1FdYm5","text":"Задерживать отказавшегося от обыска на срок до 60 минут"},{"id":"aXCBNyzT","text":"Проверять документы, удостоверяющие личность"},{"id":"J9dDZ","text":"Изымать паспорт до выхода лица с территории"},{"id":"oaGxoeTb","text":"При отказе от процедур — отказать в посещении или потребовать покинуть территорию"},{"id":"0N9eyjPG","text":"Проводить личный обыск и обыск ТС лица, желающего пройти или уже находящегося на территории"}]', '["aXCBNyzT","oaGxoeTb","0N9eyjPG"]', '', 2, 23710, '{"meta":{"article":"86-ФЗ, статья 31, ч. 31.3","explanation":"Ч. 31.3 ст. 31 86-ФЗ: проверка документов, личный обыск и обыск ТС, при отказе — отказ в посещении или требование покинуть.","quote":"в случае отказа лица от осуществления в отношении него указанных процедур, сотрудники органов государственной власти с пропускным режимом имеют право отказать лицу в посещении таковой территории либо потребовать от него её покинуть","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-015~v2', 'r6-fz86-propusknoy-rezhim-polnomochiya', 'vp', 2, 'fz_territorii', '86-ФЗ, статья 31, ч. 31.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-015~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин у КПП части отказался от обыска перед проходом. Что вправе сделать охрана по 86-ФЗ?', '[{"id":"cgODdyr","text":"Отказать в посещении территории либо потребовать её покинуть"},{"id":"kOKE1gg","text":"Провести обыск принудительно и пропустить"},{"id":"bQ5KuLif","text":"Задержать гражданина на 60 минут"},{"id":"DZ9hH8Ps","text":"Составить протокол о незаконном проникновении и арестовать"}]', '["cgODdyr"]', '', 1, 23720, '{"meta":{"article":"86-ФЗ, статья 31, ч. 31.3, п. 3","explanation":"Отказ от процедур пропускного режима — основание не допустить лицо или потребовать покинуть территорию, а не задержание.","quote":"имеют право отказать лицу в посещении таковой территории либо потребовать от него её покинуть","difficulty":"1"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-016', 'r6-fz86-propusknoy-rezhim-polnomochiya', 'vp', 1, 'fz_territorii', '86-ФЗ, статья 31, ч. 31.3, п. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'На сколько лет лишения свободы (альтернатива штрафу) наказывается незаконное проникновение или нахождение на закрытом объекте воинской части по УК?', '[]', '[]', '', 2, 23730, '{"meta":{"article":"УК, статья 62, ч. 62.3","explanation":"Ч. 3 ст. 62 УК: штраф 80.000 руб. или лишение свободы на срок пяти лет.","quote":"наказываются штрафом в размере восьмидесяти тысяч (80.000) рублей или лишением свободы на срок пяти лет","difficulty":"2"},"answer":5,"tolerance":0,"unit":"лет"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-017~v2', 'r6-uk62-vch', 'vp', 2, 'uk', 'УК, статья 62, ч. 62.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-017~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какая санкция предусмотрена КоАП за нарушение правил поведения на охраняемых территориях?', '[{"id":"iUCMCf4","text":"Лишение свободы на 2 года"},{"id":"SAzbmvEr","text":"Административный арест"},{"id":"ZgUfAgnS","text":"Штраф от 10 000 до 20 000 рублей"},{"id":"kOyLb5TF","text":"Штраф 80 000 рублей или арест"}]', '["ZgUfAgnS"]', '', 3, 23740, '{"meta":{"article":"КоАП, статья 8.11","explanation":"Только штраф — поэтому само по себе это не основание задержания по ч. 1 ст. 7 ПК, требующей ареста или лишения свободы в санкции.","quote":"влечет наложение административного штрафа в размере от десяти тысяч (10.000) до двадцати тысяч (20.000) рублей","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-019~v2', 'r6-koap811-sankciya', 'vp', 3, 'koap', 'КоАП, статья 8.11', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-019~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На каком основании субъекты процессуальных действий проходят на закрытые и охраняемые территории по ПК?', '[{"id":"fDfAyK8y","text":"По законодательству о закрытых и охраняемых территориях на время процессуальных действий"},{"id":"uRE0dakM","text":"Бессрочно, после однократного участия в задержании на этой территории"},{"id":"gz4cCKH","text":"Только с письменного разрешения командира части или начальника объекта"},{"id":"wrX36Xbq","text":"Не вправе проходить ни при каких условиях, ожидают у КПП территории"}]', '["fDfAyK8y"]', '', 2, 23750, '{"meta":{"article":"Статья 11, ч. 11.2","explanation":"Ч. 2 ст. 11 ПК.","quote":"имеют право проходить на закрытые и охраняемые территории в соответствии с законодательством Российской Федерации о закрытых и охраняемых территориях на время проведения процессуальных действий","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-020', 'r6-pk-dopusk-zakrytaya-processualnye', 'vp', 2, 'pk', 'Статья 11, ч. 11.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто по ПК вправе постановлением предоставить право на проникновение на закрытую территорию для производства задержания? Выберите все верные.', '[{"id":"yT6dZoM","text":"Командир батальона военной полиции"},{"id":"WDLp7k5i","text":"Руководитель следственного органа СК России"},{"id":"psZqersk","text":"Начальник регионального подразделения ГИБДД"},{"id":"DcXO73tG","text":"Военный комендант гарнизона"},{"id":"AQDiVUB5","text":"Начальник управления ФСБ по региону"},{"id":"3by99rk0","text":"Прокурор"}]', '["WDLp7k5i","AQDiVUB5","3by99rk0"]', '', 3, 23760, '{"meta":{"article":"Статья 13, ч. 13.9","explanation":"Ч. 9 ст. 13 ПК называет только начальника УФСБ по региону, руководителя следственного органа СК и прокурора.","quote":"Начальник управления Федеральной службой безопасности по региону, руководитель следственного органа Следственного комитета России, прокурор вправе предоставить право на проникновение на закрытую территорию для производства задержания","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-021~v2', 'r6-pk-proniknovenie-postanovlenie', 'vp', 3, 'pk', 'Статья 13, ч. 13.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-021~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'За что отвечает Батальон военной полиции по уставу? Выберите все верные.', '[{"id":"foIOi8q0","text":"Проведение переаттестации военнослужащих"},{"id":"jMJ6DkpC","text":"Содержание на гауптвахте военнослужащих, подвергнутых дисциплинарному аресту"},{"id":"G5Z1ROA","text":"Рассмотрение рапортов на снятие дисциплинарных взысканий"},{"id":"5QkOP7DB","text":"Розыск похищенного (утраченного) военного имущества ВС"},{"id":"iZiz4BCD","text":"Розыск и задержание военнослужащих, самовольно покинувших расположение части"},{"id":"yRiBnMhO","text":"Организацию охраны места преступления и обеспечение сохранности следов"}]', '["5QkOP7DB","iZiz4BCD","yRiBnMhO"]', '', 3, 23770, '{"meta":{"article":"Внутренний устав, п. 6.57 (ч. III гл. VI)","explanation":"П. 6.57 «в», «г», «д». Гауптвахта и рапорты на снятие взысканий — Военная комендатура (п. 6.45), переаттестация — Военный комендант (п. 6.44).","quote":"организацию охраны места преступления, обеспечение сохранности следов совершения преступления … организацию и осуществление мероприятий по розыску похищенного (утраченного) военного имущества Вооруженных Сил … проведение мероприятий по розыску и задержанию военнослужащих, самовольно покинувших расположение части","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-023~v2', 'r6-gu-vp-podrazdeleniya-funkcii', 'vp', 3, 'vu', 'Внутренний устав, п. 6.57 (ч. III гл. VI)', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-023~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Не более скольких минут длится предварительное задержание по ПК?', '[]', '[]', '', 2, 23780, '{"meta":{"article":"Статья 6, ч. 6.3","explanation":"Предварительное задержание — на малый срок, не более 15 минут.","quote":"на малый срок (не более 15 минут) с момента фактического задержания лица","difficulty":"2"},"answer":15,"tolerance":0,"unit":"минут"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-026~v2', 'r6-pk-predvaritelnoe-zaderzhanie', 'vp', 2, 'pk', 'Статья 6, ч. 6.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-026~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто вправе осуществлять предварительное задержание по ПК? Выберите все верные.', '[{"id":"eUsmLJD","text":"Госслужащий, не являющийся сотрудником правоохранительного органа"},{"id":"LV6J2Ni","text":"Сотрудник госоргана, не обладающий правом задержания по иным причинам"},{"id":"UdnDLqsZ","text":"Только сотрудник прокуратуры"},{"id":"IMzJFJay","text":"Только сотрудник правоохранительного органа, находящийся на службе"}]', '["eUsmLJD","LV6J2Ni"]', '', 3, 23790, '{"meta":{"article":"Статья 6, ч. 6.3–6.4","explanation":"Ч. 4 ст. 6: только если он не является сотрудником правоохранительного органа или не обладает правом задержания по иным причинам; далее — передача правоохранительному органу.","quote":"только в случае если он не является сотрудником правоохранительного органа или не обладает правом проведения задержания по иным причинам","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-027', 'r6-pk-predvaritelnoe-zaderzhanie', 'vp', 3, 'pk', 'Статья 6, ч. 6.3–6.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-027');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'За какое правонарушение, по общему правилу ПК, сотрудник правоохранительного органа вправе задержать лицо?', '[{"id":"9B5LMpL0","text":"За которое может быть назначено административный арест или лишение свободы"},{"id":"sPPfYjd","text":"Только за правонарушения в области безопасности дорожного движения"},{"id":"Pn1AtqAY","text":"Только за особо тяжкие преступления против жизни и здоровья"},{"id":"hUcRR62","text":"За любое правонарушение, включая наказуемые только штрафом"}]', '["9B5LMpL0"]', '', 2, 23800, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"Ч. 1 ст. 7 ПК.","quote":"за которое может быть назначено наказание в виде административного ареста или лишения свободы, при наличии одного из следующих оснований","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-028', 'r6-pk-osnovaniya-sankciya', 'vp', 2, 'pk', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-028');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Минимальное количество потерпевших или очевидцев, которые должны указать на лицо, чтобы это стало основанием задержания по ПК?', '[]', '[]', '', 1, 23810, '{"meta":{"article":"Статья 7, ч. 7.1, п. 2","explanation":"«в количестве 3-х и более человек».","quote":"когда потерпевшие или очевидцы в количестве 3-х и более человек укажут на данное лицо как на совершившее правонарушение","difficulty":"1"},"answer":3,"tolerance":0,"unit":"человека"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-029~v2', 'r6-pk-osnovaniya-ochevidcy', 'vp', 1, 'pk', 'Статья 7, ч. 7.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-029~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Двое очевидцев указали на гражданина как на совершившего правонарушение, санкция — лишение свободы. Других оснований нет. Есть ли основание задержания по ПК?', '[{"id":"D9zFxchM","text":"Да, если оба очевидца — военнослужащие"},{"id":"GP4atpu4","text":"Нет, нужно 3 и более потерпевших или очевидцев"},{"id":"CUbWIith","text":"Да, достаточно указания одного потерпевшего"},{"id":"cTjsstL","text":"Да, двух очевидцев достаточно при такой санкции"}]', '["GP4atpu4"]', '', 2, 23820, '{"meta":{"article":"Статья 7, ч. 7.1, п. 2","explanation":"П. 2 ч. 1 ст. 7 требует 3-х и более человек.","quote":"в количестве 3-х и более человек","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-030', 'r6-pk-osnovaniya-ochevidcy', 'vp', 2, 'pk', 'Статья 7, ч. 7.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-030');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'В течение скольких секунд лицо должно оплатить наложенный административный штраф, чтобы не возникло основание задержания по УК?', '[]', '[]', '', 2, 23830, '{"meta":{"article":"Статья 7, ч. 7.1, п. 6","explanation":"П. 6 ч. 1 ст. 7 ПК: 35 секунд после передачи или попытки передачи протокола (постановления).","quote":"в случае если лицо не оплатило наложенный на него административный штраф в течение 35 секунд после непосредственной передачи или попытки передачи протокола (постановления) сотрудником","difficulty":"2"},"answer":35,"tolerance":0,"unit":"секунд"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-031~v2', 'r6-pk-osnovaniya-shtraf-35', 'vp', 2, 'pk', 'Статья 7, ч. 7.1, п. 6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-031~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие из перечисленных обстоятельств прямо названы в ПК как основания для задержания? Выберите все верные.', '[{"id":"LyXuCcca","text":"Наличие ориентировки на лицо или ТС, размещённой по рации госструктур или иным законным образом"},{"id":"nbUFVu","text":"Отказ лица отвечать на вопросы сотрудника"},{"id":"fTXRlCP","text":"Явные следы правонарушения на лице, его одежде, при нём или в жилище"},{"id":"Kha9Qj","text":"Нахождение лица в гражданской одежде рядом с частью"},{"id":"EpwsNqFM","text":"Анонимное сообщение в социальной сети без видео"},{"id":"Z7tXGkbR","text":"Наличие лица в розыске"}]', '["LyXuCcca","fTXRlCP","Z7tXGkbR"]', '', 2, 23840, '{"meta":{"article":"Статья 7, ч. 7.1","explanation":"П. 7, 9, 3 ч. 1 ст. 7 ПК. Отказ отвечать на вопросы — реализация права не свидетельствовать против себя.","quote":"в случае наличия лица в розыске … в случае наличия ориентировки на данное лицо или на транспортное средство, размещенная посредством рации государственных структур или иным законным образом … когда на этом лице или его одежде, при нем или в его жилище будут обнаружены явные следы правонарушения","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-032~v2', 'r6-pk-osnovaniya-perechen', 'vp', 2, 'pk', 'Статья 7, ч. 7.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-032~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда видеозапись правонарушения является основанием задержания по ПК?', '[{"id":"dbTshddw","text":"Только если запись сделана служебной камерой самого сотрудника"},{"id":"4Nfk22EW","text":"Если видео дал очевидец или потерпевший, а санкция — арест или лишение свободы"},{"id":"jHoiQKjN","text":"Никогда — видеозапись не может быть основанием задержания"},{"id":"HVuxTwzx","text":"Если видео опубликовано в СМИ, независимо от санкции правонарушения"}]', '["4Nfk22EW"]', '', 2, 23850, '{"meta":{"article":"Статья 7, ч. 7.1, п. 8","explanation":"П. 8 ч. 1 ст. 7 ПК.","quote":"в случае наличия видеофиксации совершенного правонарушения, санкция которого предполагает наказание в виде административного ареста или лишения свободы, данным лицом, которая предоставлена очевидцем или потерпевшим","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-033', 'r6-pk-osnovaniya-videofiksaciya', 'vp', 2, 'pk', 'Статья 7, ч. 7.1, п. 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-033');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие условия в совокупности требуются для задержания с целью установления личности по ПК? Выберите все верные.', '[{"id":"wZHfoAhY","text":"Лицо отказывается предоставить документ, удостоверяющий личность"},{"id":"dN1zOwOU","text":"Лицо находится на улице в ночное время"},{"id":"TqiDsRFJ","text":"Лицо находится на охраняемой территории"},{"id":"p4ovWuWw","text":"Лицо скрывает лицо"},{"id":"TLK8EmRw","text":"Лицо ранее привлекалось к ответственности"},{"id":"2veIUDuu","text":"Лицо отказывается устранить предмет, мешающий рассмотреть лицо"}]', '["wZHfoAhY","p4ovWuWw","2veIUDuu"]', '', 3, 23860, '{"meta":{"article":"Статья 7, ч. 7.1, п. 5","explanation":"П. 5 ч. 1 ст. 7 ПК — три условия: скрывает лицо, отказывается убрать предмет и отказывается предъявить документ.","quote":"в случае, если личность скрывает лицо и отказывается устранить предмет мешающий рассмотреть лицо и отказывается предоставить документ удостоверяющий личность","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-034~v2', 'r6-pk-ustanovlenie-lichnosti', 'vp', 3, 'pk', 'Статья 7, ч. 7.1, п. 5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-034~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо задержано для установления личности: скрывало лицо и отказалось предъявить документ. Личность установлена, в преступлении с лишением свободы оно не подозревается. Что обязан сделать сотрудник?', '[{"id":"aglVVMwT","text":"Продолжить задержание до 60 минут и доставить лицо в КПЗ до вынесения решения судом"},{"id":"KfvwdNK6","text":"Составить административный протокол, вынести наказание по закону и отпустить лицо"},{"id":"ELN7Iyx5","text":"Передать лицо в ФСБ"},{"id":"TVJkQrKG","text":"Поместить лицо на гауптвахту на 30 минут"}]', '["KfvwdNK6"]', '', 2, 23870, '{"meta":{"article":"Статья 7, ч. 7.2","explanation":"Ч. 2 ст. 7 ПК.","quote":"сотрудник обязан составить административный протокол и вынести наказание в соответствии с федеральным законом, в случае если лицо не подозревается в совершении преступления предусматривающих лишение свободы, сотрудник обязан отпустить задержанное лицо","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-035', 'r6-pk-ustanovlenie-lichnosti-posle', 'vp', 2, 'pk', 'Статья 7, ч. 7.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-035');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте обязательные действия при задержании в последовательности, перечисленной в ПК.', '[]', '[]', '', 2, 23880, '{"meta":{"article":"Статья 10, ч. 10.1","explanation":"П. 1–5 ч. 1 ст. 10: спецсредства → идентификация → оглашение статей → личный обыск → доставление.","quote":"огласить перечень статей, инкриминируемых задержанному","difficulty":"2"},"items":[{"id":"yes0k3Sw","text":"Применить специальные средства"},{"id":"Gh8lo6Dy","text":"Идентифицировать себя"},{"id":"7w8q1lOp","text":"Огласить перечень инкриминируемых статей"},{"id":"8x7EbQgi","text":"Произвести личный обыск"},{"id":"b8N61lFN","text":"Доставить гражданина в орган следствия или дознания, правоохранительный орган"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-036~v2', 'r6-pk-poryadok-st10', 'vp', 2, 'pk', 'Статья 10, ч. 10.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-036~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие действия ПК называет обязательными при задержании? Выберите все верные.', '[{"id":"dN2hnsIi","text":"Сфотографировать задержанного для СМИ"},{"id":"pMoucF5Y","text":"Идентифицировать себя"},{"id":"wjoSrEX4","text":"Получить письменное согласие задержанного"},{"id":"GevWX4eG","text":"Вызвать скорую помощь в каждом случае"},{"id":"Ffyk67Tm","text":"Произвести личный обыск"},{"id":"U4KQHFoM","text":"Огласить перечень инкриминируемых статей"}]', '["pMoucF5Y","Ffyk67Tm","U4KQHFoM"]', '', 1, 23890, '{"meta":{"article":"Статья 10, ч. 10.1","explanation":"Обязательные действия ч. 1 ст. 10: спецсредства, идентификация, оглашение статей, личный обыск, доставление.","quote":"задержание предусматривает следующие обязательные действия","difficulty":"1"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-037~v2', 'r6-pk-poryadok-st10', 'vp', 1, 'pk', 'Статья 10, ч. 10.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-037~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Чем заканчивается процесс задержания после выполнения всех действий ПК, если установлена невиновность?', '[{"id":"tZTuP9P7","text":"Задержание продлевается до решения суда"},{"id":"m63Y8QQ","text":"Лицо помещается в КПЗ до 24 часов"},{"id":"ZVLLQIkz","text":"Лицо передаётся в ФСБ"},{"id":"1iWHIdVz","text":"Сотрудник обязан отпустить лицо"}]', '["1iWHIdVz"]', '', 2, 23900, '{"meta":{"article":"Статья 10, ч. 10.1","explanation":"При вине — переход к аресту, при невиновности — обязан отпустить.","quote":"в случае установления факта невиновности сотрудник обязан отпустить лицо","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-039~v2', 'r6-pk-okonchanie-zaderzhaniya-st10', 'vp', 2, 'pk', 'Статья 10, ч. 10.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-039~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто относится к субъектам процессуальных действий, имеющим свободный проход на место задержания? Выберите все верные.', '[{"id":"NNWsdi5s","text":"Не более одного представителя органов прокуратуры"},{"id":"gTozsRGf","text":"Сотрудник госоргана, передавший задержание"},{"id":"iGFhDzo","text":"Журналисты государственных СМИ с удостоверением"},{"id":"SSsfgC1","text":"Один адвокат, прибывший по вызову сотрудника или задержанного"},{"id":"X1afMnz","text":"Любое число адвокатов, вызванных задержанным"},{"id":"m492hvsF","text":"Любые родственники задержанного по его просьбе"}]', '["NNWsdi5s","gTozsRGf","SSsfgC1"]', '', 2, 23910, '{"meta":{"article":"Статья 11, ч. 11.1","explanation":"П. 3, 5, 9 ч. 1 ст. 11 ПК. Родственники и журналисты субъектами не являются; адвокат — один.","quote":"один адвокат, прибывший по вызову сотрудника или задержанного … не более одного представителя органов прокуратуры … сотрудник государственного органа, передавший задержание в соответствии с настоящим Кодексом имеет право присутствовать и наблюдать за задержанием","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-041~v2', 'r6-pk-subekty-st11', 'vp', 2, 'pk', 'Статья 11, ч. 11.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-041~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Может ли одно и то же лицо на месте задержания одновременно быть и адвокатом, и представителем руководства задержанного?', '[{"id":"cLIq1yI","text":"Да, если такое совмещение разрешил прокурор"},{"id":"WkJNwDCK","text":"Да, без ограничений, если лицо имеет статус адвоката и работает в организации"},{"id":"Eb2ZN3G","text":"Да, если задержанный не возражает против этого"},{"id":"hzCTaqTK","text":"Нет, одно лицо осуществляет полномочия только одного вида субъектов"}]', '["hzCTaqTK"]', '', 3, 23920, '{"meta":{"article":"Статья 11, ч. 11.4","explanation":"Ч. 4 ст. 11 ПК.","quote":"Одно и то же лицо может осуществлять полномочия только одного вида субъектов процессуальных действий.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-042', 'r6-pk-subekty-st11', 'vp', 3, 'pk', 'Статья 11, ч. 11.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-042');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что такое законное требование по ПК?', '[{"id":"gaf4omKA","text":"Требование, подтверждённое двумя свидетелями на месте"},{"id":"zAEsmSaF","text":"Любое требование старшего по званию военнослужащего"},{"id":"2mEDsNF","text":"Только письменное требование, подписанное прокурором или руководителем госоргана"},{"id":"TaBUr5fF","text":"Требование, основанное на нормативных правовых актах, в устной или письменной форме"}]', '["TaBUr5fF"]', '', 1, 23930, '{"meta":{"article":"Статья 21, ч. 21.2","explanation":"Ч. 2 ст. 21 ПК.","quote":"Законное требование или распоряжение - это требование, основанное на нормативных правовых актах, выраженное в устной или письменной форме.","difficulty":"1"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-043', 'r6-pk-zakonnoe-trebovanie', 'vp', 1, 'pk', 'Статья 21, ч. 21.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-043');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Преступник вооружён холодным оружием, явной угрозы жизни пока нет. Что обязан сделать сотрудник перед применением огнестрельного оружия?', '[{"id":"bdERvioC","text":"Получить разрешение прокурора и сообщить об этом в рацию"},{"id":"lBGag5d","text":"Предупредить о намерении открыть огонь на поражение и сделать предупредительный выстрел в воздух"},{"id":"fZO2L4cY","text":"Ничего — при холодном оружии у преступника предупреждать о применении огнестрельного не требуется"},{"id":"sLvpHCJ","text":"Сделать два устных предупреждения и вызвать сотрудников СК"}]', '["lBGag5d"]', '', 2, 23940, '{"meta":{"article":"Статья 25, ч. 25.2","explanation":"Ч. 2 ст. 25 ПК; без предупреждения — только при явной угрозе жизни или здоровью.","quote":"Сотрудник обязан предупредить о намерении открыть огонь на поражение и сделать предупредительный выстрел в воздух.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-045', 'r6-pk-ognestrel-vooruzhennyi', 'vp', 2, 'pk', 'Статья 25, ч. 25.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-045');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие права задержанного прямо перечислены в ПК? Выберите все верные.', '[{"id":"9bkUO20","text":"Требовать немедленного освобождения до решения прокурора"},{"id":"hBYOSUkk","text":"Провести один телефонный звонок любому лицу на выбор"},{"id":"JcRGGzcE","text":"Вызывать адвоката в помещениях СИЗО, КПЗ, КПС"},{"id":"ogtuOBPN","text":"Требовать присутствия журналистов при задержании"},{"id":"IQi3tUmg","text":"Требовать замены сотрудника, проводящего задержание"},{"id":"hQzEBs6A","text":"Не свидетельствовать против себя самого"}]', '["hBYOSUkk","JcRGGzcE","hQzEBs6A"]', '', 1, 23950, '{"meta":{"article":"Статья 8, ч. 8.1","explanation":"Ч. 1 ст. 8: молчать, гос. адвокат, адвокат в СИЗО/КПЗ, конфиденциальная беседа ≤5 мин, звонок ≤2 мин.","quote":"«не свидетельствовать против себя самого» … «вызывать адвоката в помещениях следственного изолятора, исправительного учреждения, камерах предварительного заключения, камерах предварительного содержания» … «требовать предоставить возможность провести один (1) телефонный звонок любому лицу на выбор задержанного»","difficulty":"1"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-049~v2', 'r6-pk-prava-perechen', 'vp', 1, 'pk', 'Статья 8, ч. 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-049~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте право задержанного и ограничение, установленное ПК.', '[]', '[]', '', 2, 23960, '{"meta":{"article":"Статья 8, ч. 8.1","explanation":"П. 2–5 ч. 1 ст. 8 ПК.","quote":"«требовать предоставить возможность провести один (1) телефонный звонок любому лицу на выбор задержанного, не превышающий двух (2) минут» … «требовать предоставить возможность провести конфиденциальную беседу с адвокатом не превышающую 5 минут» … «адвокат обязан в течении пяти (5) минут добраться до места проведения процессуальных действий указанное задержанным, на это время процессуальные действия приостанавливаются»","difficulty":"2"},"pairs":[{"l":{"id":"kwVjyFO","text":"Телефонный звонок"},"r":{"id":"Mhxq0t9","text":"один звонок не более двух минут"}},{"l":{"id":"Zjys9YxC","text":"Конфиденциальная беседа с адвокатом"},"r":{"id":"Pm4Nhpg","text":"не более 5 минут"}},{"l":{"id":"FtjmQXxc","text":"Ожидание адвоката, вызванного задержанным"},"r":{"id":"vK00ImSK","text":"не более 5 минут, действия приостанавливаются"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-050~v2', 'r6-pk-prava-perechen', 'vp', 2, 'pk', 'Статья 8, ч. 8.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-050~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда сотрудник обязан огласить задержанному его права по ПК?', '[{"id":"km08l4zl","text":"Всегда, немедленно в момент применения наручников"},{"id":"nUXdGbW","text":"В случае такого требования от задержанного"},{"id":"RuSMidA","text":"Только после доставления в КПЗ"},{"id":"m2ehgSO9","text":"Только в присутствии прокурора"}]', '["nUXdGbW"]', '', 2, 23970, '{"meta":{"article":"Статья 8, ч. 8.4","explanation":"Ч. 4 ст. 8 ПК: оглашение прав — по требованию задержанного. Термина «правило Миранды» в ПК нет.","quote":"Сотрудник государственного органа обязан огласить задержанному его права, которыми обладает, в случае такого требования от задержанного.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-054~v2', 'r6-pk-oglashenie-prav', 'vp', 2, 'pk', 'Статья 8, ч. 8.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-054~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Задержанный сообщил, что сам вызвал адвоката, но адвокат не прибыл в течение 5 минут. Каковы последствия по ПК?', '[{"id":"aWi70xRq","text":"Сотрудник обязан ждать адвоката ещё 10 минут"},{"id":"ULQvMxA","text":"Сотрудник обязан сам вызвать другого адвоката и ждать его прибытия"},{"id":"ZUUyBtpZ","text":"Задержание прекращается, лицо отпускается"},{"id":"bELF6IRO","text":"Действия возобновляются, право на адвоката считается реализованным"}]', '["bELF6IRO"]', '', 3, 23980, '{"meta":{"article":"Статья 9, ч. 9.5, 9.6","explanation":"Ч. 2 и ч. 5 ст. 9 ПК.","quote":"«процессуальные действия возобновляются по прошествии пяти (5) минут ожидания адвоката, если он не прибыл» … «В случае, если адвокат после вызова в установленном порядке, не прибыл на место проведения процессуальных действий в установленный срок, то право задержанного на предоставление адвоката считается реализованным.»","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-058', 'r6-pk-gos-advokat-ozhidanie', 'vp', 3, 'pk', 'Статья 9, ч. 9.5, 9.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-058');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'С какого момента начинается отсчёт времени телефонного звонка задержанного?', '[{"id":"mINy2ptj","text":"С момента, когда у задержанного отстёгнута от кольца наручника одна рука"},{"id":"GYp8Ut1u","text":"С момента, когда абонент ответил на звонок задержанного по телефону"},{"id":"eAGRgdgQ","text":"С момента набора номера на телефоне задержанным"},{"id":"3XrwtLJs","text":"С момента доставления задержанного в КПЗ или СИЗО"}]', '["mINy2ptj"]', '', 2, 23990, '{"meta":{"article":"Статья 9, ч. 9.3","explanation":"Ч. 3 ст. 9 ПК; время идёт, даже если задержанный никому не звонит.","quote":"Время телефонного звонка начинается с момента, когда у задержанного отстегнута от кольца наручника одна рука.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-059', 'r6-pk-zvonok-poryadok', 'vp', 2, 'pk', 'Статья 9, ч. 9.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-059');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте действия сотрудника при реализации права на телефонный звонок по ПК.', '[]', '[]', '', 3, 24000, '{"meta":{"article":"Статья 9, ч. 9.3","explanation":"Ослабить хват → отстегнуть одно кольцо → пристегнуть его к руке сотрудника/клетке/предмету.","quote":"сотрудник обязан ослабить хват наручников, отстегнуть одно кольцо наручников от задержанного и пристегнуть его (кольцо) к руке самого сотрудника либо к клетке камеры или иного предмета","difficulty":"3"},"items":[{"id":"W2AQDjPo","text":"Ослабить хват наручников"},{"id":"rYhonH5","text":"Отстегнуть одно кольцо наручников от задержанного"},{"id":"q29sKUiF","text":"Пристегнуть освободившееся кольцо к руке сотрудника, клетке камеры или иному предмету"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-060~v2', 'r6-pk-zvonok-poryadok', 'vp', 3, 'pk', 'Статья 9, ч. 9.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-060~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Задержанному освободили руку для звонка, но он две минуты никому не звонил. Как это оценивается по ПК?', '[{"id":"VH2jTby","text":"Это отказ от права только при его письменном заявлении"},{"id":"zDDjurdK","text":"Время звонка шло, право считается использованным по истечении времени"},{"id":"dzpymJbh","text":"Время не шло, так как звонок не был совершён — право сохраняется"},{"id":"9x5vzIqJ","text":"Сотрудник обязан предоставить задержанному ещё одну попытку"}]', '["zDDjurdK"]', '', 3, 24010, '{"meta":{"article":"Статья 9, ч. 9.3","explanation":"Ч. 3 ст. 9 ПК.","quote":"Время телефонного звонка идет даже, если задержанный никому не звонит и не использует телефон.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-061', 'r6-pk-zvonok-poryadok-ne-zvonit', 'vp', 3, 'pk', 'Статья 9, ч. 9.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-061');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Задержанный устно отказался от звонка, а через минуту передумал. Обязан ли сотрудник предоставить звонок?', '[{"id":"LZP5hrax","text":"Да, если с момента отказа прошло меньше 5 минут"},{"id":"7m8XLJGN","text":"Нет, право, от которого задержанный отказался устно, повторно не предоставляется"},{"id":"3q5yq","text":"Да, если на этом настаивает адвокат задержанного"},{"id":"z0UIineU","text":"Да, отказ от права действителен только в письменной форме с подписью задержанного"}]', '["7m8XLJGN"]', '', 2, 24020, '{"meta":{"article":"Статья 9, ч. 9.5","explanation":"Ч. 5 ст. 9 ПК.","quote":"В случае отказа задержанного от предоставления ему какого-либо права, прозвучавшее в устной форме, такое право повторно не предоставляется.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-063', 'r6-pk-otkaz-ot-prava', 'vp', 2, 'pk', 'Статья 9, ч. 9.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-063');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Право на гос. адвоката реализовано, звонок ещё не использован. Может ли задержанный вызвать своего адвоката?', '[{"id":"6xFJXuB","text":"Нет, право на защиту уже реализовано, своего адвоката вызвать уже нельзя"},{"id":"WWBfG1VS","text":"Только с разрешения прокурора, вызванного на место"},{"id":"n0Qs0QYw","text":"Да, и ожидание адвоката ничем не ограничено по времени"},{"id":"4mRnyfgK","text":"Да, через право на телефонный звонок; адвокату даётся 5 минут на прибытие"}]', '["4mRnyfgK"]', '', 3, 24030, '{"meta":{"article":"Статья 9, ч. 9.6","explanation":"Ч. 6 ст. 9 ПК.","quote":"Реализация права задержанного на предоставление государственного адвоката, не лишает задержанного права на вызов адвоката, через реализацию права на осуществление телефонного звонка, если таковое право не было реализовано ранее.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-064', 'r6-pk-svoi-advokat', 'vp', 3, 'pk', 'Статья 9, ч. 9.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-064');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что вправе сделать государственный адвокат в ходе задержания по ПК? Выберите все верные.', '[{"id":"OgAUtR6v","text":"Изъять бодикамеру сотрудника для проверки записи"},{"id":"awvR2Ru0","text":"Вызвать сотрудника СК при достаточных основаниях полагать, что задержание инициировано без оснований"},{"id":"Lbh7sSnN","text":"Вынести решение об освобождении задержанного подзащитного"},{"id":"nFS85pwz","text":"Запросить видеофиксацию действий подзащитного, послуживших основанием задержания"},{"id":"XZLtoUVW","text":"Самостоятельно прекратить задержание при нарушении процессуальных прав своего подзащитного"}]', '["awvR2Ru0","nFS85pwz"]', '', 3, 24040, '{"meta":{"article":"Статья 13, ч. 13.8","explanation":"Ч. 8 ст. 13: запрос видео и вызов СК (ответ 5 мин, прибытие 5 мин, действия останавливаются). Прекратить задержание сам адвокат не вправе.","quote":"Государственный адвокат вправе запросить видеофиксацию совершения своим подзащитным действий … Государственный адвокат вправе осуществить вызов сотрудника органов СК России в случае, если есть достаточные основания полагать, что задержание инициировано без установленных настоящим Кодексом оснований.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-066~v2', 'r6-pk-advokat-vyzov-sk', 'vp', 3, 'pk', 'Статья 13, ч. 13.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-066~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Сколько минут отводится на ответ сотрудника СК, вызванного государственным адвокатом?', '[]', '[]', '', 2, 24050, '{"meta":{"article":"Статья 13, ч. 13.8","explanation":"Ответ — 5 минут, прибытие — 5 минут; на это время процессуальные действия останавливаются.","quote":"Время на ответ сотрудника органов СК России составляет пять (5) минут, время ожидания прибытия составляет пять (5) минут. На время ожидания ответа и прибытия процессуальные действия останавливаются.","difficulty":"2"},"answer":5,"tolerance":0,"unit":"минут"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-067~v2', 'r6-pk-advokat-vyzov-sk', 'vp', 2, 'pk', 'Статья 13, ч. 13.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-067~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'number', 'Каков размер штрафа (в рублях) по УК за отказ от реализации прав задержанного?', '[]', '[]', '', 3, 24060, '{"meta":{"article":"УК, статья 80, ч. 80.4","explanation":"Штраф 1.250.000 рублей или лишение свободы на 3 года (СПРП «★★»).","quote":"наказывается штрафом в размере одного миллиона двухсот пятидесяти тысяч (1.250.000) рублей или лишением свободы на срок в три года","difficulty":"3"},"answer":1250000,"tolerance":0,"unit":"рублей"}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-068~v2', 'r6-uk804-prava', 'vp', 3, 'uk', 'УК, статья 80, ч. 80.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-068~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие действия сотрудника являются ненадлежащей реализацией прав задержанного с точки зрения ПК? Выберите все верные.', '[{"id":"NOz9HNmr","text":"Начать отсчёт звонка до того, как у задержанного освобождена рука"},{"id":"hlZVM0Qd","text":"Предложить задержанному реализовать право на государственного адвоката"},{"id":"lzSI7YVo","text":"Выбрать по своему усмотрению очерёдность реализации прав"},{"id":"4XawaBef","text":"При передаче задержания не сообщить, какие права запрашивались и реализовывались"},{"id":"F2Cj1SVQ","text":"Остаться в помещении во время конфиденциальной беседы с адвокатом"},{"id":"mx0MHa3","text":"Не предоставлять повторно право после устного отказа от него"}]', '["NOz9HNmr","4XawaBef","F2Cj1SVQ"]', '', 3, 24070, '{"meta":{"article":"Статьи 8–9 ПК; ч. 4 ст. 80 УК","explanation":"Звонок отсчитывается с освобождения руки, беседа — после выхода сотрудника, передающий обязан сообщить о правах. Выбор очерёдности и отказ в повторном праве после устного отказа — законны (ч. 1, 5 ст. 9).","quote":"Время телефонного звонка начинается с момента, когда у задержанного отстегнута от кольца наручника одна рука. … сотрудник обязан отвести задержанного в помещение, обеспечивающее конфиденциальную беседу, а затем покинуть его, оставив адвоката наедине с задержанным … передавший сотрудник обязан сообщить какие права запрашивались и какие реализовывались","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-069~v2', 'r6-uk804-prava', 'vp', 3, 'pk', 'Статьи 8–9 ПК; ч. 4 ст. 80 УК', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-069~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях время задержания останавливается по ПК? Выберите все верные.', '[{"id":"aFLIntIq","text":"На время проведения допроса"},{"id":"czKw1T9v","text":"На время, пока сотрудник заполняет рапорт о премии"},{"id":"XpxxT23T","text":"На время ожидания представителя руководства организации"},{"id":"iSOAJUp","text":"На время перерыва сотрудника на обед"},{"id":"hxiDMQSk","text":"На время ожидания адвоката"},{"id":"uzxL3ny","text":"На время личного телефонного разговора сотрудника"}]', '["aFLIntIq","XpxxT23T","hxiDMQSk"]', '', 2, 24080, '{"meta":{"article":"Статья 14, ч. 14.2","explanation":"Ч. 2 ст. 14 ПК; останавливать действия без объективных причин и законного основания нельзя.","quote":"Время задержания останавливается на момент проведения допроса, ожидания адвоката, представителя руководства организации","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-070~v2', 'r6-pk-vremya-ostanovka', 'vp', 2, 'pk', 'Статья 14, ч. 14.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-070~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Требуется ли постановление для личного обыска лица при его задержании?', '[{"id":"uI0bRlYN","text":"Да, всегда требуется постановление следователя или ордер суда на личный обыск"},{"id":"EqfnqKp4","text":"Да, требуется ордер суда на личный обыск"},{"id":"2L8uaFl","text":"Да, требуется письменное согласие прокурора"},{"id":"9fivjq4y","text":"Нет, при задержании или заключении под стражу обыск возможен без постановления"}]', '["9fivjq4y"]', '', 2, 24090, '{"meta":{"article":"Статья 19, ч. 19.1","explanation":"Ч. 1 ст. 19 ПК.","quote":"Личный обыск может быть произведен без соответствующего постановления при задержании лица или заключении его под стражу","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-071', 'r6-pk-lichnyi-obysk-poryadok', 'vp', 2, 'pk', 'Статья 19, ч. 19.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-071');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях проводится личный обыск по ПК? Выберите все верные.', '[{"id":"TMKVSOgF","text":"При задержании"},{"id":"hiiMlhNT","text":"При передаче лицу копии административного протокола"},{"id":"jB1dSDGv","text":"При любой проверке документов на улице"},{"id":"GcQ9ErPl","text":"При аресте"},{"id":"RqhsD5CT","text":"На добровольной основе при проходе на закрытую территорию"},{"id":"mZjM3uYd","text":"По просьбе потерпевшего без иных оснований"}]', '["TMKVSOgF","GcQ9ErPl","RqhsD5CT"]', '', 2, 24100, '{"meta":{"article":"Статья 19, ч. 19.3","explanation":"Ч. 3 ст. 19: при задержании, аресте, по законодательству о ЧП/ВП/КТО, добровольно при проходе на закрытую территорию.","quote":"Личный обыск проводится при задержании, при аресте … Личный обыск также может производиться на добровольной основе при проходе на закрытую территорию лицом.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-072~v2', 'r6-pk-lichnyi-obysk-sluchai', 'vp', 2, 'pk', 'Статья 19, ч. 19.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-072~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Гражданин отказался от добровольного личного обыска при проходе на закрытую территорию. Каковы последствия по ПК?', '[{"id":"d0LIra1h","text":"Лицо задерживается за незаконное проникновение на объект"},{"id":"iw2DoZ7","text":"Лицу вправе отказать в допуске к закрытой территории"},{"id":"5UOmIoVL","text":"Обыск проводится принудительно с применением силы"},{"id":"HbH7EHew","text":"Лицо задерживается на 60 минут для установления личности"}]', '["iw2DoZ7"]', '', 1, 24110, '{"meta":{"article":"Статья 19, ч. 19.3","explanation":"Ч. 3 ст. 19 ПК.","quote":"При отказе от такого добровольного личного обыска лицу вправе отказать в допуске к закрытой территории.","difficulty":"1"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-073', 'r6-pk-obysk-dobrovolnyi-otkaz', 'vp', 1, 'pk', 'Статья 19, ч. 19.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-073');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'match', 'Сопоставьте ситуацию и законную реакцию сотрудника.', '[]', '[]', '', 2, 24120, '{"meta":{"article":"Статья 19, ч. 19.3; 86-ФЗ ст. 31.3","explanation":"Ч. 1 и 3 ст. 19 ПК.","quote":"При отказе от такого добровольного личного обыска лицу вправе отказать в допуске к закрытой территории. … Личный обыск лиц, осуществляющих рыболовную деятельность в речных, озерных, морских водоёмах на водном транспорте или с приспособлением для рыболовной деятельности (с удочкой) проводится уполномоченными сотрудниками полиции.","difficulty":"2"},"pairs":[{"l":{"id":"iL0TqRAq","text":"Лицо отказалось от добровольного обыска при проходе на закрытую территорию"},"r":{"id":"sysXuOZs","text":"Отказать в допуске"}},{"l":{"id":"cYSMVDS7","text":"Лицо задержано по основаниям, предусмотренным ПК"},"r":{"id":"VvcCmkgB","text":"Личный обыск без постановления"}},{"l":{"id":"W0C694MY","text":"Рыболов с удочкой на водоёме"},"r":{"id":"igMk61w","text":"Личный обыск проводят уполномоченные сотрудники полиции"}}],"distractors":[],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-074~v2', 'r6-pk-lichnyi-obysk-poryadok', 'vp', 2, 'pk', 'Статья 19, ч. 19.3; 86-ФЗ ст. 31.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-074~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что разрешается конфисковать при личном обыске по ПК? Выберите все верные.', '[{"id":"MEZkXauU","text":"Компоненты, которые могут быть использованы для производства оружия или боеприпасов"},{"id":"n056G0Zb","text":"Наличные деньги в любой сумме"},{"id":"Ta3sVDMX","text":"Наркосодержащие препараты и вещества"},{"id":"4ToDtG8","text":"Мобильный телефон"},{"id":"9HboUnRt","text":"Оружие, разрешённое к обороту, при наличии лицензии"},{"id":"Pu7ogt9u","text":"Персональные средства защиты в соответствии с законодательством"}]', '["MEZkXauU","Ta3sVDMX","Pu7ogt9u"]', '', 2, 24130, '{"meta":{"article":"Статья 19, ч. 19.2","explanation":"Лицензионное оружие при наличии лицензии не изымается.","quote":"персональных средств защиты в соответствии с действующим законодательством, наркосодержащих препаратов и веществ, компонентов для производства наркосодержащих препаратов и веществ, компонентов, которые могут быть использованы для производства оружия или боеприпасов","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-075~v2', 'r6-pk-konfiskaciya', 'vp', 2, 'pk', 'Статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-075~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'При обыске у задержанного найден пистолет, разрешённый к обороту, и действующая лицензия. Нарушений оборота оружия нет. Как поступить по ПК?', '[{"id":"AqLNumrN","text":"Изъять только патроны"},{"id":"9Iu5CyYI","text":"Изъять как любое огнестрельное оружие"},{"id":"KumRGUKk","text":"Изъять и уничтожить"},{"id":"iuHXGsRs","text":"Не изымать оружие"}]', '["iuHXGsRs"]', '', 2, 24140, '{"meta":{"article":"Статья 19, ч. 19.2","explanation":"Оружие, разрешённое к обороту, при наличии лицензии не изымается.","quote":"не изымается оружие, разрешенное к обороту согласно федеральному закону при наличии соответствующей лицензии","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-076~v2', 'r6-pk-konfiskaciya-licenzia', 'vp', 2, 'pk', 'Статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-076~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязаны сделать сотрудники правоохранительных органов при аннулировании лицензии в связи с нарушением ФЗ «Об оружии»?', '[{"id":"tW8DPKAK","text":"Оставить оружие у владельца до решения суда, изъяв у него только лицензию на хранение и ношение"},{"id":"qfvXIW9I","text":"Передать оружие родственникам"},{"id":"Negz39Y","text":"Изъять оружие, боеприпасы и спецсредства, найденные при обыске личных вещей либо ТС нарушителя"},{"id":"sdkBgiW3","text":"Изъять только лицензию"}]', '["Negz39Y"]', '', 3, 24150, '{"meta":{"article":"34-ФЗ, статья 12, ч. 12.4","explanation":"Ч. 4 ст. 12 34-ФЗ.","quote":"сотрудники правоохранительных органов обязаны изъять оружие, боеприпасы и специальные средства, найденные при обыске личных вещей либо транспортного средства нарушителя","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-077', 'r6-fz34-izyatie', 'vp', 3, 'fz_oruzhie', '34-ФЗ, статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-077');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях обыск транспортного средства не требует ордера? Выберите все верные.', '[{"id":"SqgVnvjf","text":"По устному указанию любого старшего офицера"},{"id":"FvIfr8hD","text":"При совершении нарушения ПДД"},{"id":"JytyCWvm","text":"При проезде на территорию, подлежащую государственной охране"},{"id":"uofBTT9f","text":"При нахождении ТС в зоне совершения преступления"},{"id":"rf9yaUaM","text":"Если ТС припарковано у торгового центра"},{"id":"lJNMoUGg","text":"Если владелец ТС — военнослужащий"}]', '["FvIfr8hD","JytyCWvm","uofBTT9f"]', '', 2, 24160, '{"meta":{"article":"Статья 20, ч. 20.2","explanation":"П. 6, 2, 3 ч. 2 ст. 20 ПК.","quote":"в случае проезда на территорию подлежащую государственной охране … в случае совершения нарушения правил дорожного движения … в случае наличия транспортного средства в зоне совершения преступления","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-078~v2', 'r6-pk-obysk-ts-bez-ordera', 'vp', 2, 'pk', 'Статья 20, ч. 20.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-078~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие меры обеспечения производства по дисциплинарному проступку перечислены в уставе? Выберите все верные.', '[{"id":"LbN2E6hO","text":"Казарменное положение на время служебной проверки"},{"id":"N0rTnmoT","text":"Личный досмотр, досмотр вещей и ТС военнослужащего"},{"id":"4SQnyDUN","text":"Понижение в воинском звании на время проверки"},{"id":"Oju0X74m","text":"Лишение воинского звания до окончания проверки"},{"id":"Ns9ywkKx","text":"Удержание штрафа из денежного довольствия"},{"id":"N5IeGT","text":"Временное отстранение от исполнения служебных обязанностей"}]', '["LbN2E6hO","N0rTnmoT","N5IeGT"]', '', 2, 24170, '{"meta":{"article":"Внутренний устав, п. 5.4","explanation":"П. 5.4 «г», «д», «е». Лишение звания и штраф мерами обеспечения не являются.","quote":"личный досмотр, досмотр вещей, находящихся при военнослужащем, досмотр личного и служебного транспортного средства военнослужащего … временное отстранение от исполнения служебных и должностных обязанностей","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-079~v2', 'r6-ustav-dosmotr', 'vp', 2, 'vu', 'Внутренний устав, п. 5.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-079~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой объём видеофиксации сотрудник обязан предоставить СК или прокуратуре по запросу?', '[{"id":"wiEb8KNN","text":"Полную: противоправные действия, процессуальные действия, ОРМ и порядок задержания"},{"id":"2eK2hg4L","text":"Только момент совершения правонарушения, послужившего основанием"},{"id":"8JwaanNP","text":"Только момент применения специальных средств и физической силы"},{"id":"BQYFNBI2","text":"Только запись оглашения прав и реализации прав задержанного"}]', '["wiEb8KNN"]', '', 3, 24180, '{"meta":{"article":"Статья 15, ч. 15.2","explanation":"Ч. 2 ст. 15 ПК.","quote":"обязан предоставить сотруднику органов СК России, органов прокуратуры полную видеофиксацию совершения лицом противоправных действий, а также дальнейшие совершаемые над задержанным лицом процессуальные действия, оперативно-розыскные мероприятия и порядок задержания","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-083', 'r6-pk-video-sk-prokuratura-obem', 'vp', 3, 'pk', 'Статья 15, ч. 15.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-083');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что допускается в качестве доказательств по УПК? Выберите все верные.', '[{"id":"5cDM5","text":"Предположения о виновности без подтверждающих сведений"},{"id":"mBiVsCP","text":"Личное мнение сотрудника о виновности"},{"id":"b7uVwkx1","text":"Слухи, переданные через третьих лиц без указания источника"},{"id":"ql5bdKWf","text":"Показания подозреваемого, обвиняемого, потерпевшего, свидетеля"},{"id":"kmfjgr0s","text":"Протоколы следственных и судебных действий"},{"id":"JBhdUXy","text":"Вещественные доказательства"}]', '["ql5bdKWf","kmfjgr0s","JBhdUXy"]', '', 2, 24190, '{"meta":{"article":"УПК, статья 19, ч. 19.2","explanation":"Ч. 2 ст. 19 УПК: показания, заключение и показания эксперта, вещественные доказательства, протоколы, иные документы.","quote":"показания подозреваемого, обвиняемого, потерпевшего, свидетеля … вещественные доказательства … протоколы следственных и судебных действий","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-085', 'r6-upk-vidy-dokazatelstv', 'vp', 2, 'upk', 'УПК, статья 19, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-085');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Каково последствие отсутствия протокола и видеозаписи допроса по УПК?', '[{"id":"obinfTxM","text":"Допрос действителен, но требует утверждения прокурором"},{"id":"HYUwI6pp","text":"Допрос признаётся незаконным"},{"id":"8smihSFk","text":"Последствий нет"},{"id":"86ocuV15","text":"Допрос действителен, если есть свидетели"}]', '["HYUwI6pp"]', '', 3, 24200, '{"meta":{"article":"УПК, статья 39, ч. 39.1, 39.8","explanation":"Ст. 39 УПК: протокол и видеозапись обязательны.","quote":"Протокол и видеозапись обязательны. При их отсутствии допрос признается незаконным.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-086', 'r6-upk-dopros-video', 'vp', 3, 'upk', 'УПК, статья 39, ч. 39.1, 39.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-086');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте этапы оформления протокола об административном правонарушении по ПК.', '[]', '[]', '', 1, 24210, '{"meta":{"article":"Статья 62, ч. 62.2","explanation":"Заполнить бланк → подпись → копия по запросу.","quote":"заполнить бланк протокола об административном правонарушении с указанием нарушенных статей","difficulty":"1"},"items":[{"id":"yXXN93d","text":"Заполнить бланк протокола с указанием нарушенных статей"},{"id":"5NXamUUi","text":"Поставить подпись"},{"id":"YytA5El2","text":"Копию протокола передать лицу по его запросу"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-087~v2', 'r6-pk-adm-protokol-poryadok', 'vp', 1, 'pk', 'Статья 62, ч. 62.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-087~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто, по ПК, рассматривает дела об административных правонарушениях, которые не отнесены ПК к ведению суда, прокуратуры, СК, Минюста, ГИБДД и надзора в сфере рыболовства?', '[{"id":"ldphwxvQ","text":"Только суд"},{"id":"AmB6EAv3","text":"Только органы Министерства юстиции"},{"id":"D448yOxF","text":"Любой правоохранительный орган"},{"id":"KYo26k","text":"Только ГИБДД и ЦОДД"}]', '["D448yOxF"]', '', 2, 24220, '{"meta":{"article":"Статья 61, ч. 61.2","explanation":"Ч. 2 ст. 61 ПК — значит, и ВП как правоохранительный орган.","quote":"Иные дела об административных правонарушениях, предусмотренные статьями, не указанными в части 1 настоящей статьи, рассматриваются любым правоохранительным органом.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-089', 'r6-pk-podvedomstvennost-koap', 'vp', 2, 'pk', 'Статья 61, ч. 61.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-089');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расставьте действия при проведении ареста в порядке ПК.', '[]', '[]', '', 2, 24230, '{"meta":{"article":"Статья 18, ч. 18.2","explanation":"Уведомить и разъяснить → личный обыск → арест с заполнением личного дела.","quote":"уведомить лицо подлежащее аресту и иных субъектов задержания об этом и разъяснить причину ареста: назвать статьи, по которым будет произведен арест и кратко их описать","difficulty":"2"},"items":[{"id":"mfuq8kFR","text":"Уведомить лицо и иных субъектов задержания, разъяснить причину ареста (назвать и кратко описать статьи)"},{"id":"xwCqjwRg","text":"Произвести личный обыск с целью обнаружения и конфискации нелегальных предметов"},{"id":"oEydCUJf","text":"Произвести арест на установленный срок, заполнив данные в личном деле"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-091~v2', 'r6-pk-arest-poryadok', 'vp', 2, 'pk', 'Статья 18, ч. 18.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-091~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто по ПК обладает правом задержания адвоката или госслужащего при исполнении должностных обязанностей за преступления из специального перечня? Выберите все верные.', '[{"id":"pQ2APq6n","text":"Представитель руководства задержанного"},{"id":"EqXo0gau","text":"Сотрудники ФСБ России"},{"id":"MgDu6ggF","text":"Сотрудники прокуратуры"},{"id":"fjUv1XC2","text":"Любой сотрудник правоохранительного органа по собственному решению"},{"id":"aBvPGQrj","text":"Военный комендант гарнизона по собственному решению"},{"id":"HI2fr2t2","text":"Сотрудники СК России"},{"id":"YPjhjWOm","text":"Сотрудники правоохранительных органов по решению прокурора"}]', '["EqXo0gau","MgDu6ggF","HI2fr2t2","YPjhjWOm"]', '', 2, 24240, '{"meta":{"article":"Статья 12, ч. 12.1","explanation":"Ч. 1 ст. 12 ПК. Иные сотрудники — только по решению прокурора (кроме исключений ч. 3).","quote":"обладают сотрудники СК России, ФСБ России, сотрудники прокуратуры, сотрудники правоохранительных органов по решению прокурора","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-093~v2', 'r6-pk-gossluzh-kto-zaderzhivaet', 'vp', 2, 'pk', 'Статья 12, ч. 12.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-093~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'В каких случаях любой сотрудник правоохранительного органа (в т.ч. ВП) может задержать работника госоргана при исполнении? Выберите все верные.', '[{"id":"7nvSYoHy","text":"Работник незаконно проник на закрытый объект"},{"id":"hZNpCMBW","text":"Работник открыл огонь по гражданам без веской причины"},{"id":"oNPaOC","text":"Работник отказался предъявить удостоверение гражданину"},{"id":"xNNgrT8Y","text":"Работник применил специальные средства без законных оснований"},{"id":"5nByd76J","text":"Работник совершил любое административное правонарушение"},{"id":"FNEOKJla","text":"Работник совершил захват заложника"}]', '["hZNpCMBW","xNNgrT8Y","FNEOKJla"]', '', 3, 24250, '{"meta":{"article":"Статья 12, ч. 12.3","explanation":"Ч. 3 ст. 12: стрельба без веской причины, незаконные спецсредства, ст. 37, 55, 78 УК — с передачей СК, ФСБ или прокуратуре.","quote":"может быть задержан сотрудником правоохранительного органа в случае, если он открыл огонь по гражданами или иным лицам без веской на то причины, применил специальные средства без законных на то оснований или в случае совершения им хотя бы одного из преступлений, предусмотренных статьями 37, 55, 78 Уголовного Кодекса","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-094~v2', 'r6-pk-gossluzh-isklyuchenie-ch3', 'vp', 3, 'pk', 'Статья 12, ч. 12.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-094~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'ВП задержала работника госоргана при исполнении за стрельбу по гражданам без причины; сотрудников СК, ФСБ и прокуратуры нет. Как действовать по ПК?', '[{"id":"5QTtjq3c","text":"Передать задержанного представителю его руководства под расписку"},{"id":"LXLZ8SY5","text":"Ждать прибытия сотрудников СК без ограничения по времени"},{"id":"V9jLDdcf","text":"Самостоятельно продолжить процессуальные действия с передачей дела в органы СК"},{"id":"OuVJOjm","text":"Немедленно отпустить задержанного, составив рапорт прокурору"}]', '["V9jLDdcf"]', '', 3, 24260, '{"meta":{"article":"Статья 12, ч. 12.3","explanation":"Ч. 3 ст. 12 ПК.","quote":"Если сотрудники органов СК России, органов ФСБ России или органов прокуратуры отсутствуют и передача такого задержанного невозможна, сотрудник вправе самостоятельно продолжить процессуальные действия с передачей уголовного дела (личного дела) в органы СК России.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-095', 'r6-pk-gossluzh-isklyuchenie-ch3', 'vp', 3, 'pk', 'Статья 12, ч. 12.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-095');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник ВП выявил преступление госслужащего при исполнении; оно не входит в перечни, по которым госслужащего задерживают СК, ФСБ, прокуратура или сам сотрудник правоохранительного органа. Что он обязан сделать?', '[{"id":"x6z1w3Qk","text":"Наложить дисциплинарное взыскание через руководство госслужащего и сообщить в прокуратуру"},{"id":"z2h8SyHZ","text":"Составить рапорт с доказательствами прокурору субъекта или руководителю СО СК либо подать иск"},{"id":"nebteSe","text":"Задержать госслужащего на 60 минут до прибытия сотрудников СК"},{"id":"UZvwcqyB","text":"Ничего не делать, так как госслужащий находится при исполнении"}]', '["z2h8SyHZ"]', '', 2, 24270, '{"meta":{"article":"Статья 12, ч. 12.2.1","explanation":"Ч. 2.1 ст. 12 ПК.","quote":"В иных случаях сотрудник правоохранительного органа, выявивший преступления обязан составить рапорт с приложением доказательств на имя прокурора субъекта Российской Федерации, руководителя следственного органа СК России по субъекту или обратиться с исковым заявлением согласно подследственности.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-096', 'r6-pk-gossluzh-raport', 'vp', 2, 'pk', 'Статья 12, ч. 12.2.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-096');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Задержан госслужащий, не находящийся при исполнении. Какая обязанность лежит на сотруднике, производящем задержание?', '[{"id":"6Eo3Ni0e","text":"Продолжать как с обычным гражданином без каких-либо вызовов"},{"id":"Efdo9GjE","text":"Передать его сотрудникам ФСБ России для решения вопроса"},{"id":"iuogCau4","text":"Сверить личные данные с базой госорганизаций и вызвать уполномоченных лиц"},{"id":"8ZbJ6eK4","text":"Немедленно отпустить его, так как он не при исполнении"}]', '["iuogCau4"]', '', 3, 24280, '{"meta":{"article":"Статья 12, ч. 12.4","explanation":"Ч. 4 ст. 12 ПК.","quote":"Сотрудник, производящий задержание обязан сверить личные данные задержанного лица с базой данных государственных организаций или реестром адвокатов.","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-097', 'r6-pk-gossluzh-ne-pri-ispolnenii', 'vp', 3, 'pk', 'Статья 12, ч. 12.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-097');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Задерживается сотрудник госорганизации; вызванные лица не ответили. Расставьте действия по ПК.', '[]', '[]', '', 3, 24290, '{"meta":{"article":"Статья 10, ч. 10.3","explanation":"Вызов → ожидание ответа 5 мин → продолжение действий → передача дела в СК.","quote":"продолжить процессуальные действия в соответствии с настоящим Кодексом и передать дело о преступлении в органы СК России, в случае установления факта невиновности - отпустить лицо","difficulty":"3"},"items":[{"id":"Pa5IBzfx","text":"Вызвать сотрудника СК, прокуратуры, представителя руководства задержанного"},{"id":"sqozcSNi","text":"Ожидать ответа 5 минут"},{"id":"QCZox9K5","text":"Продолжить процессуальные действия по ПК"},{"id":"R0VKHXn","text":"Передать дело о преступлении в органы СК (при невиновности — отпустить)"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-099~v2', 'r6-pk-10-3-ozhidanie', 'vp', 3, 'pk', 'Статья 10, ч. 10.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-099~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто выносит решение в отношении задержанного адвоката, госслужащего, работника госоргана?', '[{"id":"ffyBHtz5","text":"Государственный адвокат, прибывший на место задержания"},{"id":"TVZGN4GN","text":"Представитель руководства организации задержанного"},{"id":"5r3hWtCB","text":"Сотрудник СК России, а при его отсутствии — сотрудник прокуратуры"},{"id":"kjf6JI6f","text":"Сотрудник ВП, проводивший задержание, по итогам проверки"}]', '["5r3hWtCB"]', '', 2, 24300, '{"meta":{"article":"Статья 12, ч. 12.9","explanation":"Ч. 9 ст. 12 ПК; в присутствии прокурора — после его утверждения.","quote":"В отношении адвоката, государственного служащего, работника государственного органа выносит решение сотрудник органов СК России (сотрудник органов прокуратуры в отсутствии представителя органов СК России).","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-100', 'r6-pk-gossluzh-reshenie', 'vp', 2, 'pk', 'Статья 12, ч. 12.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-100');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Прокурор отказал в утверждении решения сотрудника СК в отношении задержанного госслужащего. Что происходит?', '[{"id":"gkqrcVTd","text":"Задержание продлевается на 60 минут, чтобы сотрудник СК вынес новое решение по делу"},{"id":"X8D30RSs","text":"Решение СК вступает в силу без утверждения прокурора"},{"id":"aIreA7xC","text":"Решение по задержанному принимает сотрудник ВП"},{"id":"Y3fi0QZD","text":"Задержание прекращается, сотрудник СК принимает материалы к собственному производству"}]', '["Y3fi0QZD"]', '', 3, 24310, '{"meta":{"article":"Статья 12, ч. 12.12","explanation":"Ч. 12 ст. 12 ПК.","quote":"В случае если сотрудник прокуратуры отказал в утверждении решения сотрудника органов СК России, задержание прекращается","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-101', 'r6-pk-gossluzh-otkaz-prokurora', 'vp', 3, 'pk', 'Статья 12, ч. 12.12', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-101');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'При признаках каких преступлений лицо со статусом неприкосновенности может быть задержано? Выберите все верные.', '[{"id":"0pUKmEc","text":"Неуплата или отказ от уплаты штрафа"},{"id":"9bbjc6cy","text":"Посягательство на жизнь сотрудника правоохранительного органа"},{"id":"bXkO4nhM","text":"Незаконное проникновение на закрытый объект"},{"id":"Dhie8r9o","text":"Убийство"},{"id":"ZhVXJqbI","text":"Неисполнение приказа"},{"id":"7KeUZSvx","text":"Применение насилия в отношении представителя власти"}]', '["9bbjc6cy","Dhie8r9o","7KeUZSvx"]', '', 3, 24320, '{"meta":{"article":"Статья 17, ч. 17.1","explanation":"Перечень ч. 1 ст. 17: ст. 37, 38, 70, 71, 73, 89, 90 УК.","quote":"если отсутствуют признаки совершения им преступления, предусмотренного статьями 37, 38, 70, 71, 73, 89, 90 Уголовного Кодекса Российской Федерации","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-102~v2', 'r6-pk-neprikosnovennost', 'vp', 3, 'pk', 'Статья 17, ч. 17.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-102~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо с неприкосновенностью совершило на глазах ВП преступление, при котором ПК не разрешает его задерживать. Как действовать?', '[{"id":"TLcgg5XN","text":"Меры принуждения не применять; зафиксировать деяние и передать видеофиксацию рапортом в СК или прокурору"},{"id":"LMTB9PXZ","text":"Задержать и поместить на гауптвахту до прибытия сотрудников СК, затем передать им видеозапись"},{"id":"Nowz6H54","text":"Провести личный обыск, изъять запрещённое, затем отпустить лицо и сообщить о нём рапортом прокурору"},{"id":"WzW4WjQR","text":"Задержать на 60 минут и передать сотрудникам ФСБ России"}]', '["TLcgg5XN"]', '', 3, 24330, '{"meta":{"article":"Статья 17, ч. 17.2","explanation":"Ч. 2 ст. 17 ПК.","quote":"сотрудник обязан зафиксировать данное деяние и предоставить полную видеофиксацию с персональной служебной камеры сотрудника","difficulty":"3"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-103', 'r6-pk-neprikosnovennost', 'vp', 3, 'pk', 'Статья 17, ч. 17.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-103');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'По каким статьям УК задержание проводится с дальнейшей передачей задержанного ФСБ? Выберите все верные.', '[{"id":"hpbntp","text":"Разглашение государственной тайны"},{"id":"0yYlogW","text":"Террористический акт"},{"id":"tT0qkhlK","text":"Неисполнение приказа"},{"id":"PsfUE4a","text":"Убийство"},{"id":"VyoDlPT9","text":"Незаконное проникновение на закрытый объект"},{"id":"FMmIbxO","text":"Неуплата или отказ от уплаты штрафа"}]', '["hpbntp","0yYlogW","tT0qkhlK"]', '', 3, 24340, '{"meta":{"article":"Статья 13, ч. 13.3","explanation":"Ч. 3 ст. 13: ст. 53, 55, 72, 73, 74, 75, 78 УК.","quote":"по уголовным делам о преступлениях, предусмотренных статьями 53, 55, 72, 73, 74, 75, 78 Уголовного Кодекса Российской Федерации","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-104~v2', 'r6-pk-peredacha-fsb', 'vp', 3, 'pk', 'Статья 13, ч. 13.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-104~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'ФСБ не ответила на вызов в течение 5 минут при задержании по УК. Как действует сотрудник?', '[{"id":"V6cwfxeC","text":"Обязан ждать сотрудников ФСБ без ограничения по времени"},{"id":"Ky3hiZ96","text":"Передаёт задержанного сотрудникам СК для решения вопроса"},{"id":"afS8Owyv","text":"Вправе продолжить процессуальные действия с передачей дела в ФСБ"},{"id":"kOzaxUI9","text":"Обязан отпустить задержанного и составить рапорт в ФСБ"}]', '["afS8Owyv"]', '', 2, 24350, '{"meta":{"article":"Статья 13, ч. 13.4","explanation":"Ч. 4 ст. 13 ПК.","quote":"В случае отсутствия ответа или не прибытия в указанное время сотрудник правоохранительного органа вправе продолжить процессуальные действия с дальнейшей передачей уголовного дела (личного дела) в органы ФСБ России.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-105', 'r6-pk-peredacha-fsb', 'vp', 2, 'pk', 'Статья 13, ч. 13.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-105');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что обязан сделать сотрудник, который по объективным причинам не может продолжать задержание?', '[{"id":"EXt8IhTi","text":"Передать его уполномоченному сотруднику с изложением обстоятельств и видеоматериалами"},{"id":"oxD9O1JI","text":"Отпустить задержанного, составив рапорт о невозможности задержания"},{"id":"JOi4Aymr","text":"Оставить задержанного в служебном автомобиле до своего возвращения"},{"id":"sfowY8II","text":"Передать задержанного любому гражданскому лицу до прибытия сотрудников"}]', '["EXt8IhTi"]', '', 2, 24360, '{"meta":{"article":"Статья 22","explanation":"Ст. 22 ПК.","quote":"он обязан передать его уполномоченному сотруднику с подробным изложением всех известных ему обстоятельств, передачей видеоматериалов по нарушению задерживаемого","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pkc-106', 'r6-pk-peredacha-st22', 'vp', 2, 'pk', 'Статья 22', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pkc-106');
