INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'text', 'Как сокращённо (аббревиатурой) называется единая система классификации преступлений и правонарушений по их тяжести и опасности, указанная в ПК?', '[]', '[]', '', 3, 24430, '{"meta":{"article":"ПК, ст. 7, ч. 7.3","explanation":"ПК, ч. 7.3: система приоритезации розыска преступников (СПРП).","quote":"7.3. Система приоритезации розыска преступников (также - СПРП) - единая система классификации преступлений и правонарушений, основанная на их тяжести и опасности по отношению к личности, обществу и государству.","difficulty":"3"},"accepted":["СПРП"]}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-t01~v2', NULL, 'vp', 3, 'pk', 'ПК, ст. 7, ч. 7.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-t01~v2');
