INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'blanks_select', 'Заполните пропуски в положении Внутреннего устава об увольнительной.', '[]', '[]', '', 2, 24450, '{"meta":{"article":"ВУ, п. 4.6","explanation":"ВУ, п. 4.6.","quote":"4.6. Военнослужащие с звания Ефрейтор имеют право на увольнительную раз в сутки длительностью 60 минут, за исключением времени начала вечерней поверки, а также за 30 минут до и после неё. Увольнительную допускается разбить на две части по 30 минут.","difficulty":"2"},"content":"Военнослужащие с звания [[*Ефрейтор|Рядовой|Младший сержант|Сержант]] имеют право на увольнительную раз в сутки длительностью [[*60|30|45|90]] минут, за исключением времени начала вечерней поверки, а также за [[*30|15|10|60]] минут до и после неё.","parts":["Военнослужащие с звания ",{"i":0}," имеют право на увольнительную раз в сутки длительностью ",{"i":1}," минут, за исключением времени начала вечерней поверки, а также за ",{"i":2}," минут до и после неё."],"blanks":[{"opts":[{"id":"QcdnUhq","text":"Ефрейтор"},{"id":"SIaQN6Vy","text":"Рядовой"},{"id":"QHGMiPfF","text":"Младший сержант"},{"id":"8AKcvkz8","text":"Сержант"}],"correct":"QcdnUhq"},{"opts":[{"id":"7wz8B6DB","text":"60"},{"id":"A8b6IeQN","text":"30"},{"id":"KWiEXTqI","text":"45"},{"id":"VM0mgJnR","text":"90"}],"correct":"7wz8B6DB"},{"opts":[{"id":"uooEdQOV","text":"30"},{"id":"t2zlylTu","text":"15"},{"id":"llGtKRCd","text":"10"},{"id":"zBwiwKcf","text":"60"}],"correct":"uooEdQOV"}],"partial":true}', 'Переаттестация: Упрощённая', 'question', 0, 1, 'r6-vu-b02~v2', NULL, 'simple', 2, 'vu', 'ВУ, п. 4.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-b02~v2');
