INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'blanks_input', 'Впишите число (цифрой) в ПК.', '[]', '[]', '', 3, 24550, '{"meta":{"article":"ПК, ст. 7, ч. 7.1, п. 2","explanation":"ПК, ч. 7.1, п. 2.","quote":"2) когда потерпевшие или очевидцы в количестве 3-х и более человек укажут на данное лицо как на совершившее правонарушение","difficulty":"3"},"content":"когда потерпевшие или очевидцы в количестве [[3-х|3|трех|трёх|три]] и более человек укажут на данное лицо как на совершившее правонарушение","parts":["когда потерпевшие или очевидцы в количестве ",{"i":0}," и более человек укажут на данное лицо как на совершившее правонарушение"],"blanks":[{"accepted":["3-х","3","трех","трёх","три"]}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-i01~v2', NULL, 'vp', 3, 'pk', 'ПК, ст. 7, ч. 7.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-i01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте КПС найдите и отметьте слова о запрете, связанном с рацией.', '[]', '[]', '', 2, 24560, '{"meta":{"article":"КПС, п. 29","explanation":"КПС, п. 29.","quote":"игнорировать запросы о состоянии поста в рацию; … своевременно не докладывать о состоянии поста;","difficulty":"2"},"content":"29. При несении постовой службы запрещается:\nтерять концентрацию, отвлекаться на телефон, иные электронные средства, на разговоры;\nоставлять вооружение без контроля, убирать его из рук;\n[[игнорировать запросы о состоянии поста в рацию;]]\nсвоевременно не докладывать о состоянии поста;","tokens":[{"t":"29."},{"t":"При"},{"t":"несении"},{"t":"постовой"},{"t":"службы"},{"t":"запрещается:"},{"br":1},{"t":"терять"},{"t":"концентрацию,"},{"t":"отвлекаться"},{"t":"на"},{"t":"телефон,"},{"t":"иные"},{"t":"электронные"},{"t":"средства,"},{"t":"на"},{"t":"разговоры;"},{"br":1},{"t":"оставлять"},{"t":"вооружение"},{"t":"без"},{"t":"контроля,"},{"t":"убирать"},{"t":"его"},{"t":"из"},{"t":"рук;"},{"br":1},{"t":"игнорировать","c":1},{"t":"запросы","c":1},{"t":"о","c":1},{"t":"состоянии","c":1},{"t":"поста","c":1},{"t":"в","c":1},{"t":"рацию;","c":1},{"br":1},{"t":"своевременно"},{"t":"не"},{"t":"докладывать"},{"t":"о"},{"t":"состоянии"},{"t":"поста;"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-kps-f01~v2', NULL, 'medium', 2, 'kps', 'КПС, п. 29', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-kps-f01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте ПК отметьте, что предъявляют сотрудники, личность которых засекречена.', '[]', '[]', '', 3, 24570, '{"meta":{"article":"ПК, ст. 10, ч. 10.1, п. 2","explanation":"ПК, ч. 10.1, п. 2: жетон, его номер и позывной.","quote":"2) идентифицировать себя: сотрудник предоставляет удостоверение, называет должность, звание, фамилию; сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности предоставляют жетон, называют его номер и позывной;","difficulty":"3"},"content":"2) идентифицировать себя: сотрудник предоставляет удостоверение, называет должность, звание, фамилию; сотрудники, находящиеся при исполнении обязанностей, предусматривающих засекречивание своей личности предоставляют [[жетон,]] называют его номер и позывной;","tokens":[{"t":"2)"},{"t":"идентифицировать"},{"t":"себя:"},{"t":"сотрудник"},{"t":"предоставляет"},{"t":"удостоверение,"},{"t":"называет"},{"t":"должность,"},{"t":"звание,"},{"t":"фамилию;"},{"t":"сотрудники,"},{"t":"находящиеся"},{"t":"при"},{"t":"исполнении"},{"t":"обязанностей,"},{"t":"предусматривающих"},{"t":"засекречивание"},{"t":"своей"},{"t":"личности"},{"t":"предоставляют"},{"t":"жетон,","c":1},{"t":"называют"},{"t":"его"},{"t":"номер"},{"t":"и"},{"t":"позывной;"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-pk-f01~v2', NULL, 'vp', 3, 'pk', 'ПК, ст. 10, ч. 10.1, п. 2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-pk-f01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В перечне мер обеспечения производства по дисциплинарному проступку (Внутренний устав) отметьте предельный срок гауптвахты.', '[]', '[]', '', 2, 24580, '{"meta":{"article":"ВУ, п. 5.4 «в»","explanation":"ВУ, п. 5.4, подп. «в».","quote":"в) гауптвахта на срок не более 30 минут","difficulty":"2"},"content":"а) задержание;\nб) доставление;\nв) гауптвахта на срок [[не более 30 минут]] (подозреваемые и обвиняемые военнослужащие содержатся на гауптвахтах в случаях и порядке, которые предусмотрены Процессуальным кодексом Российской Федерации, и иными нормативными правовыми актами Российской Федерации);","tokens":[{"t":"а)"},{"t":"задержание;"},{"br":1},{"t":"б)"},{"t":"доставление;"},{"br":1},{"t":"в)"},{"t":"гауптвахта"},{"t":"на"},{"t":"срок"},{"t":"не","c":1},{"t":"более","c":1},{"t":"30","c":1},{"t":"минут","c":1},{"t":"(подозреваемые"},{"t":"и"},{"t":"обвиняемые"},{"t":"военнослужащие"},{"t":"содержатся"},{"t":"на"},{"t":"гауптвахтах"},{"t":"в"},{"t":"случаях"},{"t":"и"},{"t":"порядке,"},{"t":"которые"},{"t":"предусмотрены"},{"t":"Процессуальным"},{"t":"кодексом"},{"t":"Российской"},{"t":"Федерации,"},{"t":"и"},{"t":"иными"},{"t":"нормативными"},{"t":"правовыми"},{"t":"актами"},{"t":"Российской"},{"t":"Федерации);"}],"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-vu-f01~v2', NULL, 'medium', 2, 'vu', 'ВУ, п. 5.4 «в»', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-vu-f01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте ФКЗ отметьте, чему должны угрожать обстоятельства для введения чрезвычайного положения.', '[]', '[]', '', 2, 24590, '{"meta":{"article":"ФКЗ, ст. 3","explanation":"ФКЗ, ст. 3.","quote":"Чрезвычайное положение вводится лишь при наличии обстоятельств, которые представляют собой непосредственную угрозу жизни и безопасности граждан или конституционному строю Российской Федерации.","difficulty":"2"},"content":"Чрезвычайное положение вводится лишь при наличии обстоятельств, которые представляют собой непосредственную угрозу [[жизни и безопасности граждан]] или [[конституционному строю]] Российской Федерации.","tokens":[{"t":"Чрезвычайное"},{"t":"положение"},{"t":"вводится"},{"t":"лишь"},{"t":"при"},{"t":"наличии"},{"t":"обстоятельств,"},{"t":"которые"},{"t":"представляют"},{"t":"собой"},{"t":"непосредственную"},{"t":"угрозу"},{"t":"жизни","c":1},{"t":"и","c":1},{"t":"безопасности","c":1},{"t":"граждан","c":1},{"t":"или"},{"t":"конституционному","c":1},{"t":"строю","c":1},{"t":"Российской"},{"t":"Федерации."}],"partial":true}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-fkz-f01~v2', NULL, 'full', 2, 'fkz_rezhimy', 'ФКЗ, ст. 3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-fkz-f01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'find', 'В тексте УК отметьте обе формы неосторожности.', '[]', '[]', '', 2, 24600, '{"meta":{"article":"УК, ст. 10-6, ч. 10-6.1","explanation":"УК, ч. 10-6.1.","quote":"10-6.1. Преступлением, совершенным по неосторожности, признается деяние, совершенное по легкомыслию или небрежности.","difficulty":"2"},"content":"Преступлением, совершенным по неосторожности, признается деяние, совершенное по [[легкомыслию]] или [[небрежности.]]","tokens":[{"t":"Преступлением,"},{"t":"совершенным"},{"t":"по"},{"t":"неосторожности,"},{"t":"признается"},{"t":"деяние,"},{"t":"совершенное"},{"t":"по"},{"t":"легкомыслию","c":1},{"t":"или"},{"t":"небрежности.","c":1}],"partial":true}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-uk-f01~v2', NULL, 'full', 2, 'uk', 'УК, ст. 10-6, ч. 10-6.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-uk-f01~v2');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы УПК относит к органам дознания? Выберите все верные.', '[{"id":"w0fG7s9P","text":"Органы военной полиции Вооружённых Сил РФ"},{"id":"cbeAEl98","text":"Органы уголовного розыска органов внутренних дел"},{"id":"75SEfUyw","text":"Органы собственной безопасности войск национальной гвардии"},{"id":"uQ1SkRr2","text":"Командование воинской части, в которой служит подозреваемый"},{"id":"p6PZuhlM","text":"Органы прокуратуры субъекта Российской Федерации"}]', '["w0fG7s9P","cbeAEl98","75SEfUyw"]', '', 2, 24610, '{"meta":{"article":"УПК, ст. 8","quote":"2) органы военной полиции Вооруженных Сил Российской Федерации;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q001', NULL, 'full', 2, 'upk', 'УПК, ст. 8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q001');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В отношении кого орган дознания (например, военная полиция) производит дознание по УПК?', '[{"id":"H4bO3a4u","text":"В отношении любых граждан, задержанных на территории воинской части"},{"id":"FodwTrr8","text":"В отношении сотрудников своего госоргана, в том числе бывших — за деяние в период работы"},{"id":"NNC8NtR","text":"Только в отношении гражданских лиц, совершивших преступление против военнослужащих"},{"id":"mCkRIWc","text":"В отношении любых лиц по преступлениям, совершённым с применением оружия"}]', '["FodwTrr8"]', '', 2, 24620, '{"meta":{"article":"УПК, ч. 26.2","quote":"Дознание производится в отношении действующих сотрудников государственного органа, подразделением которого является орган дознания","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q002', NULL, 'vp', 2, 'upk', 'УПК, ч. 26.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q002');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что УПК называет поводами для возбуждения уголовного дела? Выберите все верные.', '[{"id":"K3GSjQEy","text":"Заявление о преступлении"},{"id":"bWUq5md","text":"Явка с повинной"},{"id":"nmjMQkcz","text":"Обнаружение признаков преступления"},{"id":"UrNFrMBh","text":"Анонимная публикация в СМИ без проверки"},{"id":"E5klnNdW","text":"Устная просьба командира воинской части"}]', '["K3GSjQEy","bWUq5md","nmjMQkcz"]', '', 1, 24630, '{"meta":{"article":"УПК, ч. 22.1","quote":"Поводами для возбуждения уголовного дела служат: … 1) заявление о преступлении; … 2) явка с повинной;","difficulty":"1"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q003', NULL, 'full', 1, 'upk', 'УПК, ч. 22.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q003');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Что является основанием для возбуждения уголовного дела по УПК?', '[{"id":"fCVAp5P","text":"Наличие достаточных данных, указывающих на признаки преступления"},{"id":"PHuSSUxR","text":"Наличие двух и более заявлений от разных граждан об одном событии"},{"id":"pARu34py","text":"Устное указание прокурора, переданное следователю по рации"},{"id":"iZcysHmr","text":"Признание лица в совершении деяния, даже без иных сведений"}]', '["fCVAp5P"]', '', 1, 24640, '{"meta":{"article":"УПК, ч. 22.2","quote":"Основанием для возбуждения уголовного дела является наличие достаточных данных, указывающих на признаки преступления.","difficulty":"1"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-upk-q004', NULL, 'medium', 1, 'upk', 'УПК, ч. 22.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q004');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник принял устное заявление о преступлении и составил протокол, но видеозапись принятия заявления не велась. Каковы последствия по УПК?', '[{"id":"6eT9xI66","text":"Заявление не может являться поводом для возбуждения уголовного дела"},{"id":"3HfxBpce","text":"Заявление действительно, если протокол подписали заявитель и сотрудник"},{"id":"fDZKkviY","text":"Заявление действительно, если его подтвердит второй сотрудник"},{"id":"pd4FtFnJ","text":"Заявление передаётся в прокуратуру для решения вопроса о видеозаписи"}]', '["6eT9xI66"]', '', 2, 24650, '{"meta":{"article":"УПК, ч. 23.4","quote":"В случае отсутствия видеозаписи, данное заявление о совершении преступления не может являться поводом для возбуждения уголовного дела.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q005', NULL, 'vp', 2, 'upk', 'УПК, ч. 23.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q005');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие требования УПК предъявляет к заявлению о преступлении? Выберите все верные.', '[{"id":"tGvpoM","text":"Письменное заявление подписывается заявителем"},{"id":"PpTTopV","text":"Устное заявление заносится в протокол, который подписывают заявитель и принявший"},{"id":"8vsX6ckz","text":"К протоколу прикрепляется видеозапись принятия заявления"},{"id":"z85F110p","text":"Заявление принимается только в письменном виде и только в здании СК"},{"id":"bOSui8eD","text":"Протокол обязательно утверждает прокурор в течение 24 часов"}]', '["tGvpoM","PpTTopV","8vsX6ckz"]', '', 2, 24660, '{"meta":{"article":"УПК, ст. 23","quote":"Устное заявление о преступлении заносится в протокол, который подписывается заявителем и лицом, принявшим данное заявление.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-upk-q006', NULL, 'medium', 2, 'upk', 'УПК, ст. 23', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q006');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какой документ может составить лицо, получившее сообщение о преступлении из иных источников?', '[{"id":"b2d4t80i","text":"Протокол об административном правонарушении"},{"id":"sVOpVadl","text":"Рапорт об обнаружении признаков преступления"},{"id":"cFS9Naf8","text":"Постановление о возбуждении уголовного дела"},{"id":"8qQuW96r","text":"Обвинительное заключение по уголовному делу"}]', '["sVOpVadl"]', '', 1, 24670, '{"meta":{"article":"УПК, ст. 24","quote":"Сообщение о совершенном или готовящемся преступлении, полученное из иных источников, принимается лицом, получившим данное сообщение, о чём может составляется рапорт об обнаружении признаков преступления.","difficulty":"1"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q007', NULL, 'full', 1, 'upk', 'УПК, ст. 24', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q007');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что указывается в постановлении о возбуждении уголовного дела? Выберите все верные.', '[{"id":"1Hu3AIBk","text":"Дата и место его вынесения"},{"id":"4JGAH7Ho","text":"Кем оно вынесено"},{"id":"MiexA4cf","text":"Повод и основание для возбуждения дела"},{"id":"EcL1WG0","text":"Предполагаемый размер наказания"},{"id":"85hq0Fcn","text":"Подписи двух понятых"}]', '["1Hu3AIBk","4JGAH7Ho","MiexA4cf"]', '', 3, 24680, '{"meta":{"article":"УПК, ч. 25.3","quote":"В постановлении о возбуждении уголовного дела указываются: … 1) дата и место его вынесения; … 2) кем оно вынесено; … 3) повод и основание для возбуждения уголовного дела;","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q008', NULL, 'vp', 3, 'upk', 'УПК, ч. 25.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q008');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В какой срок следователь (дознаватель) направляет прокурору копию постановления о возбуждении уголовного дела?', '[{"id":"c2gNyiDR","text":"Не позднее 24 часов с момента вынесения постановления"},{"id":"8iHsZ7Zn","text":"Не позднее 72 часов с момента вынесения постановления"},{"id":"EYTW5bNE","text":"Только после окончания предварительного расследования"},{"id":"zFx8Qvju","text":"В течение недели вместе с обвинительным заключением"}]', '["c2gNyiDR"]', '', 2, 24690, '{"meta":{"article":"УПК, ч. 25.4","quote":"Копия постановления о возбуждении уголовного дела направляется прокурору следователем (или дознавателем) не позднее 24 часов с момента вынесения постановления.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q009', NULL, 'full', 2, 'upk', 'УПК, ч. 25.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q009');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Что УПК допускает в качестве доказательств? Выберите все верные.', '[{"id":"Hhf9kRO","text":"Показания подозреваемого, потерпевшего, свидетеля"},{"id":"UHZK4uQ","text":"Заключение и показания эксперта"},{"id":"r7JfyT6X","text":"Вещественные доказательства"},{"id":"YEVOKs3M","text":"Слухи, источник которых не установлен"},{"id":"k122XsG0","text":"Мнение командира о личности подозреваемого"}]', '["Hhf9kRO","UHZK4uQ","r7JfyT6X"]', '', 2, 24700, '{"meta":{"article":"УПК, ч. 19.2","quote":"В качестве доказательств допускаются: … 1) показания подозреваемого, обвиняемого, потерпевшего, свидетеля; … 2) заключение и показания эксперта; … 3) вещественные доказательства;","difficulty":"2"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q010', NULL, 'vp', 2, 'upk', 'УПК, ч. 19.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q010');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Сотрудник получил доказательство с нарушением требований УПК. Какова его юридическая сила?', '[{"id":"FBCyPvLg","text":"Оно сохраняет силу, если подтверждается другими доказательствами"},{"id":"vkemoJ9","text":"Оно недопустимо и не имеет юридической силы"},{"id":"aNo6OA3q","text":"Оно допустимо, если нарушение допущено по неосторожности"},{"id":"QWfE0J7D","text":"Оно может использоваться только стороной обвинения в суде"}]', '["vkemoJ9"]', '', 2, 24710, '{"meta":{"article":"УПК, ст. 20","quote":"Доказательства, полученные с нарушением требований настоящего Кодекса, являются недопустимыми. Недопустимые доказательства не имеют юридической силы","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-upk-q011', NULL, 'medium', 2, 'upk', 'УПК, ст. 20', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q011');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'С точки зрения чего, по УПК, оценивается каждое доказательство? Выберите все верные.', '[{"id":"c2vhL9es","text":"Относимости"},{"id":"3Nho7e0U","text":"Допустимости"},{"id":"SIa4XoAB","text":"Достоверности"},{"id":"N1tzW0qZ","text":"Популярности"},{"id":"dD2jImk","text":"Давности получения"}]', '["c2vhL9es","3Nho7e0U","SIa4XoAB"]', '', 3, 24720, '{"meta":{"article":"УПК, ч. 21.1","quote":"Каждое доказательство подлежит оценке с точки зрения относимости, допустимости, достоверности, а все собранные доказательства в совокупности — достаточности для разрешения уголовного дела.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q012', NULL, 'full', 3, 'upk', 'УПК, ч. 21.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q012');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'На каком основании производится обыск по УПК и что следователь делает до его начала?', '[{"id":"t2pqAOyN","text":"По постановлению следователя; до начала обыска он предъявляет постановление"},{"id":"42gurLXh","text":"По устному указанию прокурора; постановление оформляется после обыска"},{"id":"2CW5MFMb","text":"По рапорту сотрудника ВП; постановление не требуется вовсе"},{"id":"02qNHXyX","text":"По решению командира части; до начала обыска он вызывает понятых"}]', '["t2pqAOyN"]', '', 2, 24730, '{"meta":{"article":"УПК, ч. 38.2–38.3","quote":"Обыск производится на основании постановления следователя.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q013', NULL, 'vp', 2, 'upk', 'УПК, ч. 38.2–38.3', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q013');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие правила проведения обыска установлены УПК? Выберите все верные.', '[{"id":"KD3eN7ID","text":"До начала обыска предлагается добровольно выдать предметы, подлежащие изъятию"},{"id":"DIrG92x8","text":"Изъятые предметы упаковываются и опечатываются в присутствии участников"},{"id":"BNYNbPsp","text":"Предметы, изъятые из оборота, изымаются во всяком случае"},{"id":"B7s4V4mz","text":"Защитнику и адвокату присутствовать при обыске запрещено"},{"id":"SJcncf2N","text":"Помещения вскрываются только с письменного согласия владельца"}]', '["KD3eN7ID","DIrG92x8","BNYNbPsp"]', '', 2, 24740, '{"meta":{"article":"УПК, ст. 38","quote":"До начала обыска следователь предлагает добровольно выдать подлежащие изъятию предметы, документы и ценности.","difficulty":"2"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q014', NULL, 'full', 2, 'upk', 'УПК, ст. 38', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q014');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Лицо добровольно выдало все подлежащие изъятию предметы, и нет оснований опасаться их сокрытия. Как вправе поступить следователь?', '[{"id":"edgFfWxt","text":"Обязан всё равно провести обыск в полном объёме"},{"id":"Z1446wTt","text":"Вправе не производить обыск"},{"id":"HPrCKNgJ","text":"Обязан задержать лицо до решения суда"},{"id":"aNG7V1x","text":"Должен получить согласие прокурора на отказ от обыска"}]', '["Z1446wTt"]', '', 2, 24750, '{"meta":{"article":"УПК, ч. 38.4","quote":"Если они выданы добровольно и нет оснований опасаться их сокрытия, следователь вправе не производить обыск.","difficulty":"2"}}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-upk-q015', NULL, 'medium', 2, 'upk', 'УПК, ч. 38.4', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q015');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Когда вместо обыска производится выемка?', '[{"id":"wuEUxVPi","text":"Когда предметы нужно найти, но неизвестно, где они находятся"},{"id":"ddZaCLT4","text":"Когда точно известно, где и у кого находятся нужные предметы и документы"},{"id":"yRdSGJ6","text":"Когда обыск проводится ночью или в выходной день"},{"id":"ChjRqtG9","text":"Когда лицо отказалось от добровольного личного обыска на КПП"}]', '["ddZaCLT4"]', '', 2, 24760, '{"meta":{"article":"УПК, ст. 38-1","quote":"При необходимости изъятия определенных предметов и документов, имеющих значение для уголовного дела, и если точно известно, где и у кого они находятся, производится их выемка.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q016', NULL, 'full', 2, 'upk', 'УПК, ст. 38-1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q016');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие требования к допросу установлены УПК? Выберите все верные.', '[{"id":"Jms2BgE","text":"Продолжительность допроса — не более 60 минут"},{"id":"VF6JL87U","text":"Обязательна видеофиксация с персональной служебной камеры"},{"id":"vkdpP43","text":"Госслужащих допрашивают только следователи СК РФ или ФСБ РФ"},{"id":"ggjniUtF","text":"Допрос может длиться без ограничения времени с согласия прокурора"},{"id":"I1OI8l40","text":"Видеозапись допроса ведётся только по просьбе допрашиваемого"}]', '["Jms2BgE","VF6JL87U","vkdpP43"]', '', 3, 24770, '{"meta":{"article":"УПК, ст. 39","quote":"Продолжительность допроса не может превышать шестьдесят (60) минут. Обязательна видеофиксация с персональной служебной камеры.","difficulty":"3"},"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q017', NULL, 'vp', 3, 'upk', 'УПК, ст. 39', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q017');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Кто вправе допрашивать государственного служащего по УПК?', '[{"id":"rN3CAyP","text":"Любой дознаватель органа дознания, в том числе военной полиции"},{"id":"vverrSFh","text":"Только следователи СК РФ или ФСБ РФ"},{"id":"lMkks4wq","text":"Только непосредственный руководитель госслужащего"},{"id":"ywxnPSr","text":"Сотрудник прокуратуры или командир воинской части"}]', '["vverrSFh"]', '', 2, 24780, '{"meta":{"article":"УПК, ч. 39.8","quote":"Государственные служащие допрашиваются только следователями СК РФ или ФСБ РФ.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q018', NULL, 'vp', 2, 'upk', 'УПК, ч. 39.8', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q018');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'Какова предельная продолжительность допроса с задержанием по УПК?', '[{"id":"dYqxoDLn","text":"25 минут"},{"id":"lMEZzjq","text":"60 минут"},{"id":"n4xWj4YX","text":"15 минут"},{"id":"niq5Ous1","text":"45 минут"}]', '["dYqxoDLn"]', '', 2, 24790, '{"meta":{"article":"УПК, ч. 39.9","quote":"Продолжительность допроса с задержанием не может превышать двадцати пяти (25) минут.","difficulty":"2"}}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q019', NULL, 'full', 2, 'upk', 'УПК, ч. 39.9', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q019');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Кто, по УПК, может быть подвергнут приводу при неявке по вызову без уважительных причин? Выберите все верные.', '[{"id":"OiNE5eBZ","text":"Подозреваемый или обвиняемый"},{"id":"kQnBGMDk","text":"Потерпевший"},{"id":"axZGGIIR","text":"Свидетель"},{"id":"AlTJHAgx","text":"Адвокат подозреваемого"},{"id":"jZsz8EO0","text":"Сотрудник прокуратуры"}]', '["OiNE5eBZ","kQnBGMDk","axZGGIIR"]', '', 2, 24800, '{"meta":{"article":"УПК, ч. 39-1.1","quote":"В случае неявки по вызову без уважительных причин подозреваемый, обвиняемый, а также потерпевший, свидетель и лицо, в отношении которого уголовное дело выделено в отдельное производство, могут быть подвергнуты приводу.","difficulty":"2"},"partial":false}', 'Переаттестация: Средняя', 'question', 0, 1, 'r6-upk-q020', NULL, 'medium', 2, 'upk', 'УПК, ч. 39-1.1', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q020');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'single', 'В чём состоит привод по УПК?', '[{"id":"5jeuse6b","text":"В принудительном доставлении лица к дознавателю, следователю или в суд"},{"id":"WbvSUem","text":"В наложении штрафа за неявку и повторном направлении повестки"},{"id":"mlS40KBR","text":"В аресте лица до окончания предварительного расследования"},{"id":"N66nUCR","text":"В передаче материалов дела в прокуратуру для проверки неявки"}]', '["5jeuse6b"]', '', 2, 24810, '{"meta":{"article":"УПК, ч. 39-1.2","quote":"Привод состоит в принудительном доставлении лица к дознавателю, следователю, в орган дознания или следствия или в суд.","difficulty":"2"}}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q021', NULL, 'vp', 2, 'upk', 'УПК, ч. 39-1.2', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q021');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'order', 'Расположите действия сотрудника при задержании лица для привода в порядке, установленном УПК.', '[]', '[]', '', 3, 24820, '{"meta":{"article":"УПК, ч. 39-1.6","quote":"1) Уведомить о производстве привода и вручить постановление о приводе;","difficulty":"3"},"items":[{"id":"GGTGtNOk","text":"Уведомить о производстве привода и вручить постановление о приводе"},{"id":"LWz2Ehvd","text":"Применить специальные средства (при необходимости)"},{"id":"Dn7wcumq","text":"Идентифицировать себя: удостоверение, должность, звание, фамилия"},{"id":"TwURL5xW","text":"Произвести личный обыск задержанного"},{"id":"QN0zz4zD","text":"Доставить гражданина к следователю (дознавателю), вынесшему постановление"}],"partial":false}', 'Переаттестация: Полная ВП', 'question', 0, 1, 'r6-upk-q022', NULL, 'vp', 3, 'upk', 'УПК, ч. 39-1.6', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q022');
INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'multi', 'Какие органы, по УПК, производят привод? Выберите все верные.', '[{"id":"joNskg4v","text":"Органы дознания"},{"id":"cTZsdA4x","text":"Органы Следственного комитета"},{"id":"G31p5KH6","text":"Специальные подразделения органов внутренних дел"},{"id":"G5H3qtSt","text":"Частные охранные организации"},{"id":"kJgAfbWr","text":"Органы местного самоуправления"}]', '["joNskg4v","cTZsdA4x","G31p5KH6"]', '', 3, 24830, '{"meta":{"article":"УПК, ч. 39-1.5","quote":"Привод производится органами дознания, специальными подразделениями органов внутренних дел, войск национальной гвардии и органов государственной безопасности и органами Следственного комитета","difficulty":"3"},"partial":false}', 'Переаттестация: Полная общая', 'question', 0, 1, 'r6-upk-q023', NULL, 'full', 3, 'upk', 'УПК, ч. 39-1.5', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = 0 AND ext_id = 'r6-upk-q023');
