INSERT INTO questions (exam_id, type, text, options, correct, reference, points, position, data, category, kind, easy, active, ext_id, topic, base, difficulty, source_doc, source_ref, created_at, updated_at) SELECT 0, 'case', 'Ситуация: следователь вынес постановление о приводе свидетеля, который без уважительных причин не явился по вызову. Исполнение поручено сотруднику органа дознания.
